INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('carluzh/Alphix-Frontend-Alpha/swap-integration', 'community', 'carluzh', 'Alphix-Frontend-Alpha', 'carluzh/Alphix-Frontend-Alpha', 'swap-integration', 0, 0, 65, '2026-03-04T16:37:24Z', '2026-03-07T04:03:34.409Z', 'f8d029e876121bd01f20344e5616088c74b35085c343abe4e6382aeab6de8de1', '{"id":"carluzh/Alphix-Frontend-Alpha/swap-integration","name":"swap-integration","description":{"en":"The swap-integration skill enables developers to integrate Uniswap swaps into their applications, supporting comprehensive viem/wagmi guidance. It benefits developers familiar with viem basics.","zh":"Swap Integration 是一种将 Uniswap 集成到前端、后端和智能合约中的技术，实现无缝的 swap 功能","ja":"Swap Integration は、Uniswap をフロントエンド、バックエンド、スマートコントラクトに統合する技術です","ko":"Swap Integration은 Uniswap을 프론트엔드, 백엔드, 스마트 계약에 통합하여 swap 기능을 제공하는 기술입니다","es":"La integración de swaps de Uniswap permite a los desarrolladores interactuar con la red de Uniswap de manera segura y eficiente","fr":"L''intégration de swaps Uniswap permet aux développeurs d''interagir avec le réseau Uniswap de manière sécurisée et efficace","de":"Die Integration von Uniswap-Swaps ermöglicht es Entwicklern, mit dem Uniswap-Netzwerk sicher und effizient zu interagieren","pt":"Integre trocas Uniswap em suas aplicações com o plugin uniswap-viem. Aprenda a configurar e utilizar essa habilidade para melhorar suas interações com a blockchain.","ru":"Интегрируйте свопы Uniswap в свои приложения с помощью плагина uniswap-viem. Узнайте, как настроить и использовать эту возможность для улучшения взаимодействия с блокчейном.","ar":"دمج عمليات تبادل Uniswap في تطبيقاتك مع إضافة uniswap-viem. تعلم كيفية إعداد وتشغيل هذه القدرة لتحسين تفاعلك مع سلاسل الكتل"},"seo":{"title":{"en":"swap-integration: Uniswap Swap Setup Guide | AI Agent Skill","zh":"Uniswap 集成指南 - Swap Integration Setup","ja":"Uniswap 統合ガイド - Swap Integration ベストプラクティス","ko":"Uniswap 통합 가이드 - Swap Integration 설정","es":"Guía de configuración para Swap Integration con Uniswap","fr":"Guide d''intégration de Swap avec Uniswap pour les dévelop...","de":"Einrichtungsanleitung für Swap-Integration mit Uniswap","pt":"Guia de Integração de Swap - Configurando Trocas Uniswap","ru":"ИИ Агенты: Руководство по интеграции свопов - Настройка U...","ar":"دليل تكامل البديل - إعداد عمليات تبادل Uniswap"},"description":{"en":"Discover how to integrate Uniswap swaps into your frontends, backends, and smart contracts with the swap-integration skill - get started now!","zh":"了解如何将 Uniswap 集成到前端、后端和智能合约中，实现无缝的 swap 功能","ja":"Uniswap をフロントエンド、バックエンド、スマートコントラクトに統合する方法を学びます","ko":"Uniswap을 프론트엔드, 백엔드, 스마트 계약에 통합하여 swap 기능을 간편하게 사용하십시오","es":"Aprende a integrar swaps de Uniswap en frontends, backends y smart contracts con nuestra guía de configuración","fr":"Découvrez comment intégrer les swaps Uniswap dans vos frontends, backends et smart contracts avec notre guide","de":"Erfahren Sie, wie Sie Uniswap-Swaps in Frontends, Backends und Smart Contracts integrieren können","pt":"Aprenda a integrar trocas Uniswap em frontends, backends e contratos inteligentes com o plugin uniswap-viem","ru":"Интегрируйте свопы Uniswap в фронтенд, бэкенд и смарт-контракты с помощью плагина uniswap-viem","ar":"تعلم كيفية دمج عمليات تبادل Uniswap في الواجهات الأمامية والخلفية والتعاقدات الذكية مع إضافة uniswap-viem"},"definition":{"en":"swap-integration is a skill that integrates Uniswap swaps into frontends, backends, and smart contracts, utilizing the uniswap-viem plugin for viem/wagmi guidance.","zh":"Swap Integration 是一种将 Uniswap 集成到应用中的技术，实现 token 的即时交换","ja":"Swap Integration は、Uniswap をアプリケーションに統合する技術であり、トークンの即時交換を実現します","ko":"Swap Integration은 Uniswap을 애플리케이션에 통합하여 토큰의 즉시 교환을 제공하는 기술입니다","es":"La integración de swaps es la capacidad de interactuar con la red de Uniswap para realizar operaciones de intercambio de tokens","fr":"L''intégration de swaps est la capacité d''interagir avec le réseau Uniswap pour effectuer des opérations d''échange de tokens","de":"Die Swap-Integration ist die Fähigkeit, mit dem Uniswap-Netzwerk zu interagieren, um Token-Tauschoperationen durchzuführen","pt":"A integração de swap é a capacidade de trocar ativos em uma blockchain, permitindo transações eficientes e seguras.","ru":"Интеграция свопов - это возможность обмена активами в блокчейне, обеспечивающая эффективные и безопасные транзакции.","ar":"تكامل البديل هو القدرة على تبادل الأصول في سلاسل الكتل، مما يتيح عمليات معاملات فعالة وأمنة"},"features":{"en":["Installs the uniswap-viem plugin for comprehensive viem/wagmi guidance via `claude plugin add @uniswap/uniswap-viem`","Supports integration of Uniswap swaps into frontends, backends, and smart contracts","Assumes familiarity with viem basics, including client setup, account management, and contract interactions","Provides a quick decision guide for building applications with Uniswap swaps","Utilizes the viem plugin for transaction signing and contract interactions"],"zh":["支持 Uniswap-Viem 插件","提供即时 swap 功能","支持前端、后端和智能合约集成","实现 token 的即时交换","支持多种编程语言"],"ja":["Uniswap-Viem プラグインをサポート","即時 swap 機能を提供","フロントエンド、バックエンド、スマートコントラクトの統合をサポート","トークンの即時交換を実現","多くのプログラミング言語をサポート"],"ko":["Uniswap-Viem 플러그인을 지원","즉시 swap 기능을 제공","프론트엔드, 백엔드, 스마트 계약의 통합을 지원","토큰의 즉시 교환을 제공","다수의 프로그래밍 언어를 지원"],"es":["Integración con Uniswap para realizar operaciones de intercambio de tokens","Compatibilidad con frontends, backends y smart contracts","Uso del plugin uniswap-viem para una guía integral","Interacción segura con la red de Uniswap","Soporte para la gestión de cuentas y firmas de transacciones"],"fr":["Intégration avec Uniswap pour effectuer des opérations d''échange de tokens","Compatibilité avec les frontends, backends et smart contracts","Utilisation du plugin uniswap-viem pour une guidance intégrale","Interaction sécurisée avec le réseau Uniswap","Prise en charge de la gestion de comptes et de signatures de transactions"],"de":["Integration mit Uniswap für den Austausch von Token","Kompatibilität mit Frontends, Backends und Smart Contracts","Verwendung des uniswap-viem-Plugins für eine umfassende Anleitung","Sichere Interaktion mit dem Uniswap-Netzwerk","Unterstützung für die Verwaltung von Konten und Transaktions-Signaturen"],"pt":["Integração com Uniswap","Uso do plugin uniswap-viem","Configuração de contratos inteligentes","Interoperabilidade com frontends e backends","Assinatura de transações seguras"],"ru":["Интеграция с Uniswap","Использование плагина uniswap-viem","Настройка смарт-контрактов","Взаимодействие с фронтендом и бэкендом","Подписание безопасных транзакций"],"ar":["دمج مع Uniswap","استخدام إضافة uniswap-viem","إعداد التعاقدات الذكية","التفاعل مع الواجهات الأمامية والخلفية","التوقيع على المعاملات الآمنة"]},"keywords":{"en":["how to use swap-integration","what is swap-integration","swap-integration alternative","swap-integration vs uniswap","swap-integration install","swap-integration setup guide","uniswap swap integration","viem plugin installation","wagmi guidance for uniswap"],"zh":["Uniswap 集成","Swap Integration","智能合约","前端集成","后端集成","即时 swap","Uniswap-Viem","AI 에이전트"],"ja":["Uniswap 統合","Swap Integration","スマートコントラクト","フロントエンド統合","バックエンド統合","即時 swap","Uniswap-Viem","AI エージェント"],"ko":["Uniswap 통합","Swap Integration","스마트 계약","프론트엔드 통합","백엔드 통합","즉시 swap","Uniswap-Viem","AI 에이전트"],"es":["integración de swaps","Uniswap","tokens","frontends","backends","smart contracts","uniswap-viem","seguridad","gestión de cuentas"],"fr":["intégration de swaps","Uniswap","tokens","frontends","backends","smart contracts","uniswap-viem","sécurité","gestion de comptes"],"de":["Swap-Integration","Uniswap","Token","Frontends","Backends","Smart Contracts","uniswap-viem","Sicherheit","Kontenverwaltung"],"pt":["integração de swap","Uniswap","plugin uniswap-viem","contratos inteligentes","frontends","backends","assinatura de transações","blockchain","desenvolvimento de aplicações"],"ru":["ИИ Агенты","интеграция свопов","Uniswap","плагин uniswap-viem","смарт-контракты","фронтенд","бэкенд","подписание транзакций","блокчейн","разработка приложений"],"ar":["أدوات الذكاء الاصطناعي","تكامل البديل","Uniswap","إضافة uniswap-viem","التعاقدات الذكية","الواجهات الأمامية","الواجهات الخلفية","التوقيع على المعاملات","سلاسل الكتل","تطوير التطبيقات"]}},"owner":"carluzh","repo":"Alphix-Frontend-Alpha","repoPath":"carluzh/Alphix-Frontend-Alpha","stars":0,"forks":0,"updatedAt":"2026-03-04T16:37:24Z","topics":[],"category":"community","skillMd":{"name":"swap-integration","description":"Integrate Uniswap swaps into applications. Use when user says integrate swaps, uniswap, trading api, add swap functionality, build a swap frontend, create a swap script, smart contract swap integration, use Universal Router, Trading API, or mentions swapping tokens via Uniswap.","version":"1.2.0","bodyPreview":"# Swap Integration\n\nIntegrate Uniswap swaps into frontends, backends, and smart contracts.\n\n## Prerequisites\n\nThis skill assumes familiarity with viem basics (client setup, account management, contract interactions, transaction signing). Install the **uniswap-viem** plugin for comprehensive viem/wagmi guidance: `claude plugin add @uniswap/uniswap-viem`\n\n## Quick Decision Guide\n\n| Building...                    | Use This Method               |\n| ------------------------------ | -----------------","body":"# Swap Integration\n\nIntegrate Uniswap swaps into frontends, backends, and smart contracts.\n\n## Prerequisites\n\nThis skill assumes familiarity with viem basics (client setup, account management, contract interactions, transaction signing). Install the **uniswap-viem** plugin for comprehensive viem/wagmi guidance: `claude plugin add @uniswap/uniswap-viem`\n\n## Quick Decision Guide\n\n| Building...                    | Use This Method               |\n| ------------------------------ | ----------------------------- |\n| Frontend with React/Next.js    | Trading API                   |\n| Backend script or bot          | Trading API                   |\n| Smart contract integration     | Universal Router direct calls |\n| Need full control over routing | Universal Router SDK          |\n\n### Routing Types Quick Reference\n\n| Type     | Description                             | Chains                             |\n| -------- | --------------------------------------- | ---------------------------------- |\n| CLASSIC  | Standard AMM swap through Uniswap pools | All supported chains               |\n| DUTCH_V2 | UniswapX Dutch auction V2               | Ethereum, Arbitrum, Base, Unichain |\n| PRIORITY | MEV-protected priority order            | Base, Unichain                     |\n| WRAP     | ETH to WETH conversion                  | All                                |\n| UNWRAP   | WETH to ETH conversion                  | All                                |\n\nSee [Routing Types](#routing-types) for the complete list including DUTCH_V3, DUTCH_LIMIT, LIMIT_ORDER, BRIDGE, and QUICKROUTE.\n\n## Integration Methods\n\n### 1. Trading API (Recommended)\n\nBest for: Frontends, backends, scripts. Handles routing optimization automatically.\n\n**Base URL**: `https://trade-api.gateway.uniswap.org/v1`\n\n**Authentication**: `x-api-key: <your-api-key>` header required\n\n**Getting an API Key**: The Trading API requires an API key for authentication. Visit the [Uniswap Developer Portal](https://developers.uniswap.org/) to register and obtain your API key. Keys are typically available for immediate use after registration. Include it as an `x-api-key` header in all API requests.\n\n**Required Headers** — Include these in ALL Trading API requests:\n\n```text\nContent-Type: application/json\nx-api-key: <your-api-key>\nx-universal-router-version: 2.0\n```\n\n**3-Step Flow**:\n\n```text\n1. POST /check_approval  -> Check if token is approved\n2. POST /quote           -> Get executable quote with routing\n3. POST /swap            -> Get transaction to sign and submit\n```\n\nSee the [Trading API Reference](#trading-api-reference) section below for complete documentation.\n\n### 2. Universal Router SDK\n\nBest for: Direct control over transaction construction.\n\n**Installation**:\n\n```bash\nnpm install @uniswap/universal-router-sdk @uniswap/sdk-core @uniswap/v3-sdk\n```\n\n**Key Pattern**:\n\n```typescript\nimport { SwapRouter } from ''@uniswap/universal-router-sdk'';\n\nconst { calldata, value } = SwapRouter.swapCallParameters(trade, options);\n```\n\nSee the [Universal Router Reference](#universal-router-reference) section below for complete documentation.\n\n### 3. Smart Contract Integration\n\nBest for: On-chain integrations, DeFi composability.\n\n**Interface**: Call `execute()` on Universal Router with encoded commands.\n\nSee the [Universal Router Reference](#universal-router-reference) section below for command encoding.\n\n---\n\n## Trading API Reference\n\n### Step 1: Check Token Approval\n\n```bash\nPOST /check_approval\n```\n\n**Request**:\n\n```json\n{\n  \"walletAddress\": \"0x...\",\n  \"token\": \"0x...\",\n  \"amount\": \"1000000000\",\n  \"chainId\": 1\n}\n```\n\n**Response**:\n\n```json\n{\n  \"approval\": {\n    \"to\": \"0x...\",\n    \"from\": \"0x...\",\n    \"data\": \"0x...\",\n    \"value\": \"0\",\n    \"chainId\": 1\n  }\n}\n```\n\nIf `approval` is `null`, token is already approved.\n\n### Step 2: Get Quote\n\n```bash\nPOST /quote\n```\n\n**Request**:\n\n```json\n{\n  \"swapper\": \"0x...\",\n  \"tokenIn\": \"0x...\",\n  \"tokenOut\": \"0x...\",\n  \"tokenInChainId\": \"1\",\n  \"tokenOutChainId\": \"1\",\n  \"amount\": \"1000000000000000000\",\n  \"type\": \"EXACT_INPUT\",\n  \"slippageTolerance\": 0.5,\n  \"routingPreference\": \"BEST_PRICE\"\n}\n```\n\n> **Note**: `tokenInChainId` and `tokenOutChainId` must be **strings** (e.g., `\"1\"`), not numbers.\n\n**Key Parameters**:\n\n| Parameter           | Description                                                       |\n| ------------------- | ----------------------------------------------------------------- |\n| `type`              | `EXACT_INPUT` or `EXACT_OUTPUT`                                   |\n| `slippageTolerance` | 0-100 percentage                                                  |\n| `protocols`         | Optional: `[\"V2\", \"V3\", \"V4\"]`                                    |\n| `routingPreference` | `BEST_PRICE`, `FASTEST`, `CLASSIC`                                |\n| `autoSlippage`      | `true` to auto-calculate slippage (overrides `slippageTolerance`) |\n| `urgency`           | `normal` or `fast` — affects UniswapX auction timing              |\n\n**Response**:\n\n```json\n{\n  \"routing\": \"CLASSIC\",\n  \"quote\": {\n    \"input\": { \"token\": \"0x...\", \"amount\": \"1000000000000000000\" },\n    \"output\": { \"token\": \"0x...\", \"amount\": \"999000000\" },\n    \"slippage\": 0.5,\n    \"route\": [],\n    \"gasFee\": \"5000000000000000\",\n    \"gasFeeUSD\": \"0.01\",\n    \"gasUseEstimate\": \"150000\"\n  },\n  \"permitData\": {}\n}\n```\n\n> **Display tip**: Use `gasFeeUSD` (a string with the USD value) for gas cost display. Do **not** manually convert `gasFee` (wei) using a hardcoded ETH price — this leads to wildly inaccurate estimates (e.g., ~$87 instead of ~$0.01).\n\n### Step 3: Execute Swap\n\n```bash\nPOST /swap\n```\n\n**Request** - Spread the quote response directly into the body:\n\n```typescript\n// CORRECT: Spread the quote response, strip null fields\nconst quoteResponse = await fetchQuote(params);\n\n// Remove null permitData/permitTransaction (API rejects null values)\nconst { permitData, permitTransaction, ...cleanQuote } = quoteResponse;\n\nconst swapRequest = {\n  ...cleanQuote,\n  // Only include permitData if it''s a valid object (not null)\n  ...(permitData && { permitData }),\n};\n\n// If using Permit2 signature, include BOTH signature and permitData\nif (permit2Signature && permitData) {\n  swapRequest.signature = permit2Signature;\n  swapRequest.permitData = permitData;\n}\n```\n\n**Critical**: Do NOT wrap the quote in `{quote: quoteResponse}`. The API expects the quote response fields spread into the request body.\n\n**Permit2 Rules**:\n\n- `signature` and `permitData` must BOTH be present, or BOTH be absent\n- Never set `permitData: null` - omit the field entirely\n- The quote response often includes `permitData: null` - strip this before sending\n\n**Response** (ready-to-sign transaction):\n\n```json\n{\n  \"swap\": {\n    \"to\": \"0x...\",\n    \"from\": \"0x...\",\n    \"data\": \"0x...\",\n    \"value\": \"0\",\n    \"chainId\": 1,\n    \"gasLimit\": \"250000\"\n  }\n}\n```\n\n**Response Validation** - Always validate before broadcasting:\n\n```typescript\nfunction validateSwapResponse(response: SwapResponse): void {\n  if (!response.swap?.data || response.swap.data === '''' || response.swap.data === ''0x'') {\n    throw new Error(''swap.data is empty - quote may have expired'');\n  }\n  if (!isAddress(response.swap.to) || !isAddress(response.swap.from)) {\n    throw new Error(''Invalid address in swap response'');\n  }\n}\n```\n\n### Supported Chains\n\n| ID   | Chain    | ID      | Chain       |\n| ---- | -------- | ------- | ----------- |\n| 1    | Ethereum | 8453    | Base        |\n| 10   | Optimism | 42161   | Arbitrum    |\n| 56   | BNB      | 42220   | Celo        |\n| 130  | Unichain | 43114   | Avalanche   |\n| 137  | Polygon  | 81457   | Blast       |\n| 196  | X Layer  | 7777777 | Zora        |\n| 324  | zkSync   | 480     | World Chain |\n| 1868 | Soneium  | 143     | Monad       |\n\n### Routing Types\n\n| Type        | Description                                   |\n| ----------- | --------------------------------------------- |\n| CLASSIC     | Standard AMM swap through Uniswap pools       |\n| DUTCH_V2    | UniswapX Dutch auction V2                     |\n| DUTCH_V3    | UniswapX Dutch auction V3                     |\n| PRIORITY    | MEV-protected priority order (Base, Unichain) |\n| DUTCH_LIMIT | UniswapX Dutch limit order                    |\n| LIMIT_ORDER | Limit order                                   |\n| WRAP        | ETH to WETH conversion                        |\n| UNWRAP      | WETH to ETH conversion                        |\n| BRIDGE      | Cross-chain bridge                            |\n| QUICKROUTE  | Fast approximation quote                      |\n\n**UniswapX availability**: UniswapX V2 orders are supported on Ethereum (1), Arbitrum (42161), Base (8453), and Unichain (130). The auction mechanism varies by chain — see [UniswapX Auction Types](#uniswapx-auction-types) below.\n\n---\n\n## Critical Implementation Notes\n\nThese are common pitfalls discovered during real-world Trading API integration. **Follow these rules to avoid on-chain reverts and API errors.**\n\n### 1. Swap Request Body Format\n\nThe `/swap` endpoint expects the quote response **spread into the request body**, not wrapped in a `quote` field.\n\n```typescript\n// WRONG - causes \"quote does not match any of the allowed types\"\nconst badRequest = {\n  quote: quoteResponse, // Don''t wrap!\n  signature: ''0x...'',\n};\n\n// CORRECT - spread the quote response\nconst goodRequest = {\n  ...quoteResponse,\n  signature: ''0x...'', // Only if using Permit2\n};\n```\n\n### 2. Null Field Handling\n\nThe API rejects `permitData: null`. Always strip null fields before sending:\n\n```typescript\nfunction prepareSwapRequest(quoteResponse: QuoteResponse, signature?: string): object {\n  // Strip null values that the API rejects\n  const { permitData, permitTransaction, ...cleanQuote } = quoteResponse;\n\n  const request: Record<string, unknown> = { ...cleanQuote };\n\n  // Only include permitData if it''s a valid object AND we have a signature\n  if (signature && permitData && typeof permitData === ''object'') {\n    request.signature = signature;\n    request.permitData = permitData;\n  }\n\n  return request;\n}\n```\n\n### 3. Permit2 Field Rules\n\nWhen using Permit2 for gasless approvals:\n\n| Scenario                   | `signature` | `permitData` |\n| -------------------------- | ----------- | ------------ |\n| Standard swap (no Permit2) | Omit        | Omit         |\n| Permit2 swap               | Required    | Required     |\n| **Invalid**                | Present     | Missing      |\n| **Invalid**                | Missing     | Present      |\n| **Invalid (API error)**    | Any         | `null`       |\n\n### 4. Pre-Broadcast Validation\n\nAlways validate the swap response before sending to the blockchain:\n\n```typescript\nimport { isAddress, isHex } from ''viem'';\n\nfunction validateSwapBeforeBroadcast(swap: SwapTransaction): void {\n  // 1. data must be non-empty hex\n  if (!swap.data || swap.data === '''' || swap.data === ''0x'') {\n    throw new Error(''swap.data is empty - this will revert on-chain. Re-fetch the quote.'');\n  }\n\n  if (!isHex(swap.data)) {\n    throw new Error(''swap.data is not valid hex'');\n  }\n\n  // 2. Addresses must be valid\n  if (!isAddress(swap.to)) {\n    throw new Error(''swap.to is not a valid address'');\n  }\n\n  if (!isAddress(swap.from)) {\n    throw new Error(''swap.from is not a valid address'');\n  }\n\n  // 3. Value must be present (can be \"0\" for non-ETH swaps)\n  if (swap.value === undefined || swap.value === null) {\n    throw new Error(''swap.value is missing'');\n  }\n}\n```\n\n### 5. Browser Environment Setup\n\nWhen using viem/wagmi in browser environments, you need Node.js polyfills:\n\n**Install buffer polyfill**:\n\n```bash\nnpm install buffer\n```\n\n**Add to your entry file (before other imports)**:\n\n```typescript\n// src/main.tsx or src/index.tsx\nimport { Buffer } from ''buffer'';\nglobalThis.Buffer = Buffer;\n\n// Then your other imports\nimport React from ''react'';\nimport { WagmiProvider } from ''wagmi'';\n// ...\n```\n\n**Vite configuration** (`vite.config.ts`):\n\n```typescript\nexport default defineConfig({\n  define: {\n    global: ''globalThis'',\n  },\n  optimizeDeps: {\n    include: [''buffer''],\n  },\n  resolve: {\n    alias: {\n      buffer: ''buffer'',\n    },\n  },\n});\n```\n\nWithout this setup, you''ll see: `ReferenceError: Buffer is not defined`\n\n#### CORS Proxy Configuration\n\nThe Trading API does not support browser CORS preflight requests — `OPTIONS` requests return `415 Unsupported Media Type`. Direct `fetch()` calls from a browser will always fail. You **must** proxy API requests through your own server or dev server.\n\n**Vite dev proxy** (merge into the same `vite.config.ts` used for the Buffer polyfill above):\n\n```typescript\nexport default defineConfig({\n  server: {\n    proxy: {\n      ''/api/uniswap'': {\n        target: ''https://trade-api.gateway.uniswap.org/v1'',\n        changeOrigin: true,\n        rewrite: (path) => path.replace(/^\\/api\\/uniswap/, ''''),\n      },\n    },\n  },\n});\n```\n\nThen use `/api/uniswap/quote` instead of the full URL in your frontend code.\n\n**Vercel production proxy** (`vercel.json`):\n\n```json\n{\n  \"rewrites\": [\n    {\n      \"source\": \"/api/uniswap/:path*\",\n      \"destination\": \"https://trade-api.gateway.uniswap.org/v1/:path*\"\n    }\n  ]\n}\n```\n\n**Cloudflare Pages** (`public/_redirects`):\n\n```text\n/api/uniswap/* https://trade-api.gateway.uniswap.org/v1/:splat 200\n```\n\n**Next.js** (`next.config.js`):\n\n```javascript\nmodule.exports = {\n  async rewrites() {\n    return [\n      {\n        source: ''/api/uniswap/:path*'',\n        destination: ''https://trade-api.gateway.uniswap.org/v1/:path*'',\n      },\n    ];\n  },\n};\n```\n\nWithout a proxy, you''ll see: `415 Unsupported Media Type` on preflight or CORS errors in the browser console.\n\n### 6. Quote Freshness\n\n- Quotes expire quickly (typically 30 seconds)\n- Always re-fetch if the user takes time to review\n- Use the `deadline` parameter to prevent stale execution\n- If `/swap` returns empty `data`, the quote likely expired\n\n---\n\n## Universal Router Reference\n\nThe Universal Router is a unified interface for swapping across Uniswap v2, v3, and v4.\n\n### Core Function\n\n```solidity\nfunction execute(\n    bytes calldata commands,\n    bytes[] calldata inputs,\n    uint256 deadline\n) external payable;\n```\n\n### Command Encoding\n\nEach command is a single byte:\n\n| Bits | Name     | Purpose                             |\n| ---- | -------- | ----------------------------------- |\n| 0    | flag     | Allow revert (1 = continue on fail) |\n| 1-2  | reserved | Use 0                               |\n| 3-7  | command  | Operation identifier                |\n\n### Swap Commands\n\n| Code | Command           | Description               |\n| ---- | ----------------- | ------------------------- |\n| 0x00 | V3_SWAP_EXACT_IN  | v3 swap with exact input  |\n| 0x01 | V3_SWAP_EXACT_OUT | v3 swap with exact output |\n| 0x08 | V2_SWAP_EXACT_IN  | v2 swap with exact input  |\n| 0x09 | V2_SWAP_EXACT_OUT | v2 swap with exact output |\n| 0x10 | V4_SWAP           | v4 swap                   |\n\n### Token Operations\n\n| Code | Command     | Description                |\n| ---- | ----------- | -------------------------- |\n| 0x04 | SWEEP       | Clear router token balance |\n| 0x05 | TRANSFER    | Send specific amount       |\n| 0x0b | WRAP_ETH    | ETH to WETH                |\n| 0x0c | UNWRAP_WETH | WETH to ETH                |\n\n### Permit2 Commands\n\n| Code | Command               | Description           |\n| ---- | --------------------- | --------------------- |\n| 0x02 | PERMIT2_TRANSFER_FROM | Single token transfer |\n| 0x03 | PERMIT2_PERMIT_BATCH  | Batch approval        |\n| 0x0a | PERMIT2_PERMIT        | Single approval       |\n\n### SDK Usage\n\n```typescript\nimport { SwapRouter, UniswapTrade } from ''@uniswap/universal-router-sdk''\nimport { TradeType } from ''@uniswap/sdk-core''\n\n// Build trade using v3-sdk or router-sdk\nconst trade = new RouterTrade({\n  v3Routes: [...],\n  tradeType: TradeType.EXACT_INPUT\n})\n\n// Get calldata for Universal Router\nconst { calldata, value } = SwapRouter.swapCallParameters(trade, {\n  slippageTolerance: new Percent(50, 10000), // 0.5%\n  recipient: walletAddress,\n  deadline: Math.floor(Date.now() / 1000) + 1200 // 20 min\n})\n\n// Send transaction\nconst tx = await wallet.sendTransaction({\n  to: UNIVERSAL_ROUTER_ADDRESS,\n  data: calldata,\n  value\n})\n```\n\n---\n\n## Permit2 Integration\n\nPermit2 enables signature-based token approvals instead of on-chain approve() calls.\n\n### Approval Target: Permit2 vs Legacy (Direct to Router)\n\nThere are two approval paths. Choose based on your integration type:\n\n| Approach                    | Approve To       | Per-Swap Auth       | Best For                         |\n| --------------------------- | ---------------- | ------------------- | -------------------------------- |\n| **Permit2** (recommended)   | Permit2 contract | EIP-712 signature   | Frontends with user interaction  |\n| **Legacy** (direct approve) | Universal Router | None (pre-approved) | Backend services, smart accounts |\n\n**Permit2 flow** (frontend with user signing):\n\n1. User approves token to Permit2 contract (one-time)\n2. Each swap: user signs an EIP-712 permit message\n3. Universal Router uses the signature to transfer tokens via Permit2\n\n**Legacy flow** (backend services, ERC-4337 smart accounts):\n\n1. Approve token directly to the Universal Router address (one-time)\n2. Each swap: no additional authorization needed\n3. Simpler for automated systems that cannot sign EIP-712 messages\n\nUse the Trading API''s `/check_approval` endpoint — it returns the correct approval target based on the routing type.\n\n### How It Works\n\n1. User approves Permit2 contract once (infinite approval)\n2. For each swap, user signs a message authorizing the transfer\n3. Universal Router uses signature to transfer tokens via Permit2\n\n### Two Modes\n\n| Mode              | Description                                |\n| ----------------- | ------------------------------------------ |\n| SignatureTransfer | One-time signature, no on-chain state      |\n| AllowanceTransfer | Time-limited allowance with on-chain state |\n\n### Integration Pattern\n\n```typescript\nimport { getContract, maxUint256, type Address } from ''viem'';\n\nconst PERMIT2_ADDRESS = ''0x000000000022D473030F116dDEE9F6B43aC78BA3'' as const;\n\n// Check if Permit2 approval exists\nconst allowance = await publicClient.readContract({\n  address: PERMIT2_ADDRESS,\n  abi: permit2Abi,\n  functionName: ''allowance'',\n  args: [userAddress, tokenAddress, spenderAddress],\n});\n\n// If not approved, user must approve Permit2 first\nif (allowance.amount < requiredAmount) {\n  const hash = await walletClient.writeContract({\n    address: tokenAddress,\n    abi: erc20Abi,\n    functionName: ''approve'',\n    args: [PERMIT2_ADDRESS, maxUint256],\n  });\n  await publicClient.waitForTransactionReceipt({ hash });\n}\n\n// Then sign permit for the swap\nconst permitSignature = await signPermit(...);\n```\n\n---\n\n## UniswapX Auction Types\n\nUniswapX routes swaps through off-chain fillers who compete to execute orders at better prices than on-chain AMMs. The auction mechanism varies by chain.\n\n### Exclusive Dutch Auction (Ethereum)\n\n- Starts with an RFQ (Request for Quote) phase where permissioned quoters compete\n- Winning quoter receives **exclusive filling rights** for a set period\n- If the exclusive filler doesn''t execute, falls back to an open Dutch auction where the price decays each block\n- Best for large swaps where MEV protection matters most\n\n**Trading API routing type**: `DUTCH_V2` or `DUTCH_V3`\n\n### Open Dutch Auction (Arbitrum)\n\n- Direct open auction without an RFQ phase\n- Fillers compete on-chain through a descending price mechanism\n- Leverages Arbitrum''s fast 0.25-second block times for rapid price discovery\n- The **Unimind algorithm** sets auction parameters based on historical pair performance\n\n**Trading API routing type**: `DUTCH_V2`\n\n### Priority Gas Auction (Base, Unichain)\n\n- Fillers bid by submitting transactions with varying **priority fees** at a target block\n- Highest priority fee wins the right to fill the order\n- Exploits OP Stack''s priority ordering mechanism\n- Effective on chains where block builders respect priority ordering\n\n**Trading API routing type**: `PRIORITY`\n\n### Key Properties (All Auction Types)\n\n- **Gasless for users** — fillers pay gas fees, incorporated into final pricing\n- **No cost on failure** — if a swap doesn''t fill, the user pays nothing\n- **MEV protection** — auction mechanics prevent frontrunning and sandwich attacks\n- UniswapX V2 is currently supported on Ethereum (1), Arbitrum (42161), Base (8453), and Unichain (130)\n\nFor more detail, see the [UniswapX Auction Types documentation](https://docs.uniswap.org/contracts/uniswapx/auctiontypes).\n\n---\n\n## Direct Universal Router Integration (SDK)\n\nFor direct Universal Router integration without the Trading API, use the SDK''s high-level API.\n\n### Installation\n\n```bash\nnpm install @uniswap/universal-router-sdk @uniswap/router-sdk @uniswap/sdk-core @uniswap/v3-sdk viem\n```\n\n### High-Level Approach (Recommended)\n\nUse `RouterTrade` + `SwapRouter.swapCallParameters()` for automatic command building:\n\n```typescript\nimport { SwapRouter } from ''@uniswap/universal-router-sdk'';\nimport { Trade as RouterTrade } from ''@uniswap/router-sdk'';\nimport { TradeType, Percent } from ''@uniswap/sdk-core'';\nimport { Route as V3Route, Pool } from ''@uniswap/v3-sdk'';\n\n// 1. Fetch pool data (required to construct routes)\n// Using viem to read on-chain pool state:\nconst slot0 = await publicClient.readContract({\n  address: poolAddress,\n  abi: [\n    {\n      name: ''slot0'',\n      type: ''function'',\n      stateMutability: ''view'',\n      inputs: [],\n      outputs: [\n        { name: ''sqrtPriceX96'', type: ''uint160'' },\n        { name: ''tick'', type: ''int24'' },\n        { name: ''observationIndex'', type: ''uint16'' },\n        { name: ''observationCardinality'', type: ''uint16'' },\n        { name: ''observationCardinalityNext'', type: ''uint16'' },\n        { name: ''feeProtocol'', type: ''uint8'' },\n        { name: ''unlocked'', type: ''bool'' },\n      ],\n    },\n  ],\n  functionName: ''slot0'',\n});\nconst liquidity = await publicClient.readContract({\n  address: poolAddress,\n  abi: [\n    {\n      name: ''liquidity'',\n      type: ''function'',\n      stateMutability: ''view'',\n      inputs: [],\n      outputs: [{ type: ''uint128'' }],\n    },\n  ],\n  functionName: ''liquidity'',\n});\n\nconst pool = new Pool(tokenIn, tokenOut, fee, slot0[0].toString(), liquidity.toString(), slot0[1]);\n\n// 2. Build route and trade\nconst route = new V3Route([pool], tokenIn, tokenOut);\nconst trade = RouterTrade.createUncheckedTrade({\n  route,\n  inputAmount: amountIn,\n  outputAmount: expectedOut,\n  tradeType: TradeType.EXACT_INPUT,\n});\n\n// 3. Get calldata\nconst { calldata, value } = SwapRouter.swapCallParameters(trade, {\n  slippageTolerance: new Percent(50, 10000), // 0.5%\n  recipient: walletAddress,\n  deadline: Math.floor(Date.now() / 1000) + 1800,\n});\n\n// 4. Execute with viem\nconst hash = await walletClient.sendTransaction({\n  to: UNIVERSAL_ROUTER_ADDRESS,\n  data: calldata,\n  value: BigInt(value),\n});\n```\n\n### Low-Level Approach (Manual Commands)\n\nFor custom flows (fee collection, complex routing), use `RoutePlanner` directly:\n\n```typescript\nimport { RoutePlanner, CommandType, ROUTER_AS_RECIPIENT } from ''@uniswap/universal-router-sdk'';\nimport { encodeRouteToPath } from ''@uniswap/v3-sdk'';\n\n// Special addresses\nconst MSG_SENDER = ''0x0000000000000000000000000000000000000001'';\nconst ADDRESS_THIS = ''0x0000000000000000000000000000000000000002'';\n```\n\n### Example: V3 Swap with Manual Commands\n\n```typescript\nimport { RoutePlanner, CommandType } from ''@uniswap/universal-router-sdk'';\nimport { encodeRouteToPath, Route } from ''@uniswap/v3-sdk'';\n\nasync function swapV3Manual(route: Route, amountIn: bigint, amountOutMin: bigint) {\n  const planner = new RoutePlanner();\n\n  // Encode V3 path from route\n  const path = encodeRouteToPath(route, false); // false = exactInput\n\n  planner.addCommand(CommandType.V3_SWAP_EXACT_IN, [\n    MSG_SENDER, // recipient\n    amountIn, // amountIn\n    amountOutMin, // amountOutMin\n    path, // encoded path\n    true, // payerIsUser\n  ]);\n\n  return executeRoute(planner);\n}\n```\n\n### Example: ETH to Token (Wrap + Swap)\n\n```typescript\nasync function swapEthToToken(route: Route, amountIn: bigint, amountOutMin: bigint) {\n  const planner = new RoutePlanner();\n  const path = encodeRouteToPath(route, false);\n\n  // 1. Wrap ETH to WETH (keep in router)\n  planner.addCommand(CommandType.WRAP_ETH, [ADDRESS_THIS, amountIn]);\n\n  // 2. Swap WETH → Token (payerIsUser = false since using router''s WETH)\n  planner.addCommand(CommandType.V3_SWAP_EXACT_IN, [\n    MSG_SENDER,\n    amountIn,\n    amountOutMin,\n    path,\n    false,\n  ]);\n\n  return executeRoute(planner, { value: amountIn });\n}\n```\n\n### Example: Token to ETH (Swap + Unwrap)\n\n```typescript\nasync function swapTokenToEth(route: Route, amountIn: bigint, amountOutMin: bigint) {\n  const planner = new RoutePlanner();\n  const path = encodeRouteToPath(route, false);\n\n  // 1. Swap Token → WETH (output to router)\n  planner.addCommand(CommandType.V3_SWAP_EXACT_IN, [\n    ADDRESS_THIS,\n    amountIn,\n    amountOutMin,\n    path,\n    true,\n  ]);\n\n  // 2. Unwrap WETH to ETH\n  planner.addCommand(CommandType.UNWRAP_WETH, [MSG_SENDER, amountOutMin]);\n\n  return executeRoute(planner);\n}\n```\n\n### Example: Fee Collection with PAY_PORTION\n\n```typescript\nasync function swapWithFee(route: Route, amountIn: bigint, feeRecipient: Address, feeBips: number) {\n  const planner = new RoutePlanner();\n  const path = encodeRouteToPath(route, false);\n  const outputToken = route.output.wrapped.address;\n\n  // Swap to router (ADDRESS_THIS)\n  planner.addCommand(CommandType.V3_SWAP_EXACT_IN, [ADDRESS_THIS, amountIn, 0n, path, true]);\n\n  // Pay fee portion (e.g., 30 bips = 0.3%)\n  planner.addCommand(CommandType.PAY_PORTION, [outputToken, feeRecipient, feeBips]);\n\n  // Sweep remainder to user\n  planner.addCommand(CommandType.SWEEP, [outputToken, MSG_SENDER, 0n]);\n\n  return executeRoute(planner);\n}\n```\n\n### Execute Route Helper\n\n```typescript\nimport { UNIVERSAL_ROUTER_ADDRESS } from ''@uniswap/universal-router-sdk'';\n\nconst ROUTER_ABI = [\n  {\n    name: ''execute'',\n    type: ''function'',\n    stateMutability: ''payable'',\n    inputs: [\n      { name: ''commands'', type: ''bytes'' },\n      { name: ''inputs'', type: ''bytes[]'' },\n      { name: ''deadline'', type: ''uint256'' },\n    ],\n    outputs: [],\n  },\n] as const;\n\nasync function executeRoute(planner: RoutePlanner, options?: { value?: bigint }) {\n  const deadline = BigInt(Math.floor(Date.now() / 1000) + 1800);\n  const routerAddress = UNIVERSAL_ROUTER_ADDRESS(''2.0'', 1); // version, chainId\n\n  const { request } = await publicClient.simulateContract({\n    address: routerAddress,\n    abi: ROUTER_ABI,\n    functionName: ''execute'',\n    args: [planner.commands, planner.inputs, deadline],\n    account,\n    value: options?.value ?? 0n,\n  });\n\n  return walletClient.writeContract(request);\n}\n```\n\n### Command Cheat Sheet\n\n| Command           | Parameters                                               |\n| ----------------- | -------------------------------------------------------- |\n| V3_SWAP_EXACT_IN  | (recipient, amountIn, amountOutMin, path, payerIsUser)   |\n| V3_SWAP_EXACT_OUT | (recipient, amountOut, amountInMax, path, payerIsUser)   |\n| V2_SWAP_EXACT_IN  | (recipient, amountIn, amountOutMin, path[], payerIsUser) |\n| V2_SWAP_EXACT_OUT | (recipient, amountOut, amountInMax, path[], payerIsUser) |\n| WRAP_ETH          | (recipient, amount)                                      |\n| UNWRAP_WETH       | (recipient, amountMin)                                   |\n| SWEEP             | (token, recipient, amountMin)                            |\n| TRANSFER          | (token, recipient, amount)                               |\n| PAY_PORTION       | (token, recipient, bips)                                 |\n\n### Fee Tiers\n\n| Tier   | Value | Percentage |\n| ------ | ----- | ---------- |\n| LOWEST | 100   | 0.01%      |\n| LOW    | 500   | 0.05%      |\n| MEDIUM | 3000  | 0.30%      |\n| HIGH   | 10000 | 1.00%      |\n\n---\n\n## Common Integration Patterns\n\n### Frontend Swap Hook (React)\n\n**Note**: Ensure you''ve set up the Buffer polyfill and CORS proxy (see Critical Implementation Notes). For wagmi v2 `useWalletClient()` pitfalls, see [wagmi v2 Integration Pitfalls](#wagmi-v2-integration-pitfalls) below.\n\n```typescript\nimport { isAddress, isHex } from ''viem'';\nimport { useWalletClient } from ''wagmi'';\n\n// In browser apps, use your CORS proxy path instead (see CORS Proxy Configuration)\n// e.g., const API_URL = ''/api/uniswap'';\nconst API_URL = ''https://trade-api.gateway.uniswap.org/v1'';\n\nfunction useSwap() {\n  const { data: walletClient } = useWalletClient();\n  const [quoteResponse, setQuoteResponse] = useState(null);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState(null);\n\n  const getQuote = async (params) => {\n    setLoading(true);\n    setError(null);\n    try {\n      const response = await fetch(`${API_URL}/quote`, {\n        method: ''POST'',\n        headers: {\n          ''Content-Type'': ''application/json'',\n          ''x-api-key'': API_KEY,\n          ''x-universal-router-version'': ''2.0'',\n        },\n        body: JSON.stringify(params),\n      });\n      const data = await response.json();\n      if (!response.ok) throw new Error(data.detail || ''Quote failed'');\n      setQuoteResponse(data); // Store the FULL response, not just data.quote\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const executeSwap = async (permit2Signature?: string) => {\n    if (!quoteResponse) throw new Error(''No quote available'');\n\n    // CRITICAL: Strip null fields and spread quote response into body\n    const { permitData, permitTransaction, ...cleanQuote } = quoteResponse;\n\n    const swapRequest: Record<string, unknown> = {\n      ...cleanQuote,\n    };\n\n    // CRITICAL: Only include permitData if we have BOTH signature and permitData\n    // The API requires both fields to be present or both to be absent\n    if (permit2Signature && permitData && typeof permitData === ''object'') {\n      swapRequest.signature = permit2Signature;\n      swapRequest.permitData = permitData;\n    }\n\n    const swapResponse = await fetch(`${API_URL}/swap`, {\n      method: ''POST'',\n      headers: {\n        ''Content-Type'': ''application/json'',\n        ''x-api-key'': API_KEY,\n        ''x-universal-router-version'': ''2.0'',\n      },\n      body: JSON.stringify(swapRequest),\n    });\n    const data = await swapResponse.json();\n    if (!swapResponse.ok) throw new Error(data.detail || ''Swap failed'');\n\n    // CRITICAL: Validate response before broadcasting\n    if (!data.swap?.data || data.swap.data === '''' || data.swap.data === ''0x'') {\n      throw new Error(''Empty swap data - quote may have expired. Please refresh.'');\n    }\n\n    // Send transaction via wallet (walletClient from useWalletClient())\n    if (!walletClient) throw new Error(''Wallet not connected'');\n    const tx = await walletClient.sendTransaction(data.swap);\n    return tx;\n  };\n\n  return { quote: quoteResponse?.quote, loading, error, getQuote, executeSwap };\n}\n```\n\n### wagmi v2 Integration Pitfalls\n\nThe `useWalletClient()` hook from wagmi v2 can return `undefined` even when the wallet is connected — it resolves asynchronously. This causes \"wallet not connected\" errors at swap time. Additionally, the returned client needs a `chain` for `sendTransaction()` to work.\n\n**Recommended pattern** — use `@wagmi/core` action functions at swap time instead of hooks:\n\n```typescript\nimport { getWalletClient, getPublicClient, switchChain } from ''@wagmi/core'';\nimport type { Config } from ''wagmi'';\n\nasync function executeSwapTransaction(\n  config: Config,\n  chainId: number,\n  swapTx: { to: string; data: string; value: string }\n) {\n  // 1. Ensure the wallet is on the correct chain\n  await switchChain(config, { chainId });\n\n  // 2. Get wallet client with explicit chainId — avoids undefined and missing chain\n  const walletClient = await getWalletClient(config, { chainId });\n\n  // 3. Execute the swap\n  const hash = await walletClient.sendTransaction({\n    to: swapTx.to as `0x${string}`,\n    data: swapTx.data as `0x${string}`,\n    value: BigInt(swapTx.value || ''0''),\n  });\n\n  // 4. Wait for confirmation\n  const publicClient = getPublicClient(config, { chainId });\n  if (!publicClient) throw new Error(`No public client configured for chainId ${chainId}`);\n  return publicClient.waitForTransactionReceipt({ hash });\n}\n```\n\n**Why this matters**:\n\n- `useWalletClient()` hook returns `{ data: undefined }` during async resolution, even after `useAccount()` shows connected\n- `getWalletClient(config, { chainId })` is a promise that resolves only when the client is ready, and includes the chain\n- `switchChain()` prevents \"chain mismatch\" errors when the wallet is on a different network than the swap\n\n### Backend Swap Script (Node.js)\n\n```typescript\nimport { createWalletClient, createPublicClient, http, isAddress, isHex, type Address } from ''viem'';\nimport { privateKeyToAccount } from ''viem/accounts'';\nimport { mainnet } from ''viem/chains'';\n\nconst API_URL = ''https://trade-api.gateway.uniswap.org/v1'';\nconst API_KEY = process.env.UNISWAP_API_KEY!;\n\nconst account = privateKeyToAccount(process.env.PRIVATE_KEY as `0x${string}`);\nconst publicClient = createPublicClient({ chain: mainnet, transport: http() });\nconst walletClient = createWalletClient({ account, chain: mainnet, transport: http() });\n\n// Helper to strip null fields from quote response\nfunction prepareSwapRequest(quoteResponse: Record<string, unknown>, signature?: string): object {\n  const { permitData, permitTransaction, ...cleanQuote } = quoteResponse;\n\n  const request: Record<string, unknown> = { ...cleanQuote };\n\n  // CRITICAL: Only include permitData if we have BOTH signature and permitData\n  // The API requires both fields to be present or both to be absent\n  if (signature && permitData && typeof permitData === ''object'') {\n    request.signature = signature;\n    request.permitData = permitData;\n  }\n\n  return request;\n}\n\n// Validate swap response before broadcasting\nfunction validateSwap(swap: { data?: string; to?: string; from?: string }): void {\n  if (!swap?.data || swap.data === '''' || swap.data === ''0x'') {\n    throw new Error(''swap.data is empty - quote may have expired'');\n  }\n  if (!isHex(swap.data)) {\n    throw new Error(''swap.data is not valid hex'');\n  }\n  if (!swap.to || !isAddress(swap.to) || !swap.from || !isAddress(swap.from)) {\n    throw new Error(''Invalid address in swap response'');\n  }\n}\n\nasync function executeSwap(tokenIn: Address, tokenOut: Address, amount: string, chainId: number) {\n  const ETH_ADDRESS = ''0x0000000000000000000000000000000000000000'';\n\n  // 1. Check approval (for ERC20 tokens, not native ETH)\n  if (tokenIn !== ETH_ADDRESS) {\n    const approvalRes = await fetch(`${API_URL}/check_approval`, {\n      method: ''POST'',\n      headers: {\n        ''x-api-key'': API_KEY,\n        ''Content-Type'': ''application/json'',\n        ''x-universal-router-version'': ''2.0'',\n      },\n      body: JSON.stringify({\n        walletAddress: account.address,\n        token: tokenIn,\n        amount,\n        chainId,\n      }),\n    });\n    const approvalData = await approvalRes.json();\n\n    if (approvalData.approval) {\n      const hash = await walletClient.sendTransaction({\n        to: approvalData.approval.to,\n        data: approvalData.approval.data,\n        value: BigInt(approvalData.approval.value || ''0''),\n      });\n      await publicClient.waitForTransactionReceipt({ hash });\n    }\n  }\n\n  // 2. Get quote\n  const quoteRes = await fetch(`${API_URL}/quote`, {\n    method: ''POST'',\n    headers: {\n      ''x-api-key'': API_KEY,\n      ''Content-Type'': ''application/json'',\n      ''x-universal-router-version'': ''2.0'',\n    },\n    body: JSON.stringify({\n      swapper: account.address,\n      tokenIn,\n      tokenOut,\n      tokenInChainId: String(chainId),\n      tokenOutChainId: String(chainId),\n      amount,\n      type: ''EXACT_INPUT'',\n      slippageTolerance: 0.5,\n    }),\n  });\n  const quoteResponse = await quoteRes.json(); // Store FULL response\n\n  if (!quoteRes.ok) {\n    throw new Error(quoteResponse.detail || ''Quote failed'');\n  }\n\n  // 3. Execute swap - CRITICAL: spread quote response, strip null fields\n  const swapRequest = prepareSwapRequest(quoteResponse);\n\n  const swapRes = await fetch(`${API_URL}/swap`, {\n    method: ''POST'',\n    headers: {\n      ''x-api-key'': API_KEY,\n      ''Content-Type'': ''application/json'',\n      ''x-universal-router-version'': ''2.0'',\n    },\n    body: JSON.stringify(swapRequest),\n  });\n  const swapData = await swapRes.json();\n\n  if (!swapRes.ok) {\n    throw new Error(swapData.detail || ''Swap request failed'');\n  }\n\n  // 4. Validate before broadcasting\n  validateSwap(swapData.swap);\n\n  const hash = await walletClient.sendTransaction({\n    to: swapData.swap.to,\n    data: swapData.swap.data,\n    value: BigInt(swapData.swap.value || ''0''),\n  });\n  return publicClient.waitForTransactionReceipt({ hash });\n}\n```\n\n### Smart Contract Integration (Solidity)\n\n```solidity\n// SPDX-License-Identifier: MIT\npragma solidity ^0.8.0;\n\ninterface IUniversalRouter {\n    function execute(\n        bytes calldata commands,\n        bytes[] calldata inputs,\n        uint256 deadline\n    ) external payable;\n}\n\ninterface IERC20 {\n    function approve(address spender, uint256 amount) external returns (bool);\n}\n\ncontract SwapIntegration {\n    IUniversalRouter public immutable router;\n    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;\n\n    constructor(address _router) {\n        router = IUniversalRouter(_router);\n    }\n\n    function swap(\n        bytes calldata commands,\n        bytes[] calldata inputs,\n        uint256 deadline\n    ) external payable {\n        router.execute{value: msg.value}(commands, inputs, deadline);\n    }\n\n    // Approve token for Permit2 (one-time setup)\n    function approveToken(address token) external {\n        IERC20(token).approve(PERMIT2, type(uint256).max);\n    }\n}\n```\n\n---\n\n## Advanced Patterns\n\n### Smart Account Integration (ERC-4337)\n\nExecute Trading API swaps through ERC-4337 smart accounts with delegation. The pattern:\n\n1. Get swap calldata from Trading API (standard 3-step flow)\n2. Wrap the calldata in a delegation redemption execution\n3. Submit via bundler as a UserOperation\n\n```typescript\n// After getting swap calldata from Trading API:\nconst { to, data, value } = swapResponse.swap;\n\n// Wrap in delegation execution\nconst execution = {\n  target: to, // Universal Router\n  callData: data,\n  value: BigInt(value),\n};\n\n// Submit via bundler\nconst userOpHash = await bundlerClient.sendUserOperation({\n  account: delegateSmartAccount,\n  calls: [\n    {\n      to: delegationManagerAddress,\n      data: encodeFunctionData({\n        abi: delegationManagerAbi,\n        functionName: ''redeemDelegations'',\n        args: [[[signedDelegation]], [0], [[execution]]],\n      }),\n      value: execution.value,\n    },\n  ],\n});\n```\n\n**Key considerations**:\n\n- Use legacy approvals (direct to Universal Router) instead of Permit2 for smart accounts — see [Approval Target](#approval-target-permit2-vs-legacy-direct-to-router)\n- Add 20-30% gas buffer for bundler gas estimation\n- Handle bundler-specific error codes separately from standard transaction errors\n\nSee [Advanced Patterns Reference](./references/advanced-patterns.md#smart-account-integration-erc-4337) for the complete implementation with types and error handling.\n\n### WETH Handling on L2s\n\nOn L2 chains (Base, Optimism, Arbitrum), swaps outputting ETH may deliver WETH instead of native ETH. Always check and unwrap after swaps:\n\n```typescript\nimport { parseAbi, type Address } from ''viem'';\n\nconst WETH_ABI = parseAbi([\n  ''function balanceOf(address) view returns (uint256)'',\n  ''function withdraw(uint256)'',\n]);\n\nconst WETH_ADDRESSES: Record<number, Address> = {\n  1: ''0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2'',\n  10: ''0x4200000000000000000000000000000000000006'',\n  8453: ''0x4200000000000000000000000000000000000006'',\n  42161: ''0x82aF49447D8a07e3bd95BD0d56f35241523fBab1'',\n};\n\n// After swap completes on an L2:\nconst wethAddress = WETH_ADDRESSES[chainId];\nif (wethAddress) {\n  const wethBalance = await publicClient.readContract({\n    address: wethAddress,\n    abi: WETH_ABI,\n    functionName: ''balanceOf'',\n    args: [accountAddress],\n  });\n\n  if (wethBalance > 0n) {\n    const hash = await walletClient.writeContract({\n      address: wethAddress,\n      abi: WETH_ABI,\n      functionName: ''withdraw'',\n      args: [wethBalance],\n    });\n    await publicClient.waitForTransactionReceipt({ hash });\n  }\n}\n```\n\nSee [Advanced Patterns Reference](./references/advanced-patterns.md#weth-handling-on-l2s) for chain-specific WETH addresses and integration details.\n\n### Rate Limiting\n\nThe Trading API enforces rate limits (~10 requests/second per endpoint). For batch operations:\n\n- Add **100-200ms delays** between sequential API calls\n- Implement **exponential backoff with jitter** on 429 responses\n- **Cache approval results** — approvals rarely change between calls\n\n```typescript\n// Exponential backoff for 429 responses\nasync function fetchWithRetry(url: string, init: RequestInit, maxRetries = 5): Promise<Response> {\n  for (let attempt = 0; attempt <= maxRetries; attempt++) {\n    const response = await fetch(url, init);\n    if (response.status !== 429 && response.status < 500) return response;\n    if (attempt === maxRetries) throw new Error(`Failed after ${maxRetries} retries`);\n\n    const delay = Math.min(200 * Math.pow(2, attempt) + Math.random() * 100, 10000);\n    await new Promise((resolve) => setTimeout(resolve, delay));\n  }\n  throw new Error(''Unreachable'');\n}\n```\n\nSee [Advanced Patterns Reference](./references/advanced-patterns.md#rate-limiting-best-practices) for batch operation patterns and full retry implementation.\n\n---\n\n## Key Contract Addresses\n\n### Universal Router (v4)\n\nAddresses are per-chain. The legacy v1 address `0x3fC91A3afd70395Cd496C647d5a6CC9D4B2b7FAD` is deprecated.\n\n| Chain       | ID      | Address                                      |\n| ----------- | ------- | -------------------------------------------- |\n| Ethereum    | 1       | `0x66a9893cc07d91d95644aedd05d03f95e1dba8af` |\n| Unichain    | 130     | `0xef740bf23acae26f6492b10de645d6b98dc8eaf3` |\n| Optimism    | 10      | `0x851116d9223fabed8e56c0e6b8ad0c31d98b3507` |\n| Base        | 8453    | `0x6ff5693b99212da76ad316178a184ab56d299b43` |\n| Arbitrum    | 42161   | `0xa51afafe0263b40edaef0df8781ea9aa03e381a3` |\n| Polygon     | 137     | `0x1095692a6237d83c6a72f3f5efedb9a670c49223` |\n| Blast       | 81457   | `0xeabbcb3e8e415306207ef514f660a3f820025be3` |\n| BNB         | 56      | `0x1906c1d672b88cd1b9ac7593301ca990f94eae07` |\n| Zora        | 7777777 | `0x3315ef7ca28db74abadc6c44570efdf06b04b020` |\n| World Chain | 480     | `0x8ac7bee993bb44dab564ea4bc9ea67bf9eb5e743` |\n| Avalanche   | 43114   | `0x94b75331ae8d42c1b61065089b7d48fe14aa73b7` |\n| Celo        | 42220   | `0xcb695bc5d3aa22cad1e6df07801b061a05a0233a` |\n| Soneium     | 1868    | `0x4cded7edf52c8aa5259a54ec6a3ce7c6d2a455df` |\n| Ink         | 57073   | `0x112908dac86e20e7241b0927479ea3bf935d1fa0` |\n| Monad       | 143     | `0x0d97dc33264bfc1c226207428a79b26757fb9dc3` |\n\nFor testnet addresses, see [Uniswap v4 Deployments](https://docs.uniswap.org/contracts/v4/deployments).\n\n### Permit2\n\n| Chain      | Address                                      |\n| ---------- | -------------------------------------------- |\n| All chains | `0x000000000022D473030F116dDEE9F6B43aC78BA3` |\n\n---\n\n## Troubleshooting\n\n### Common Issues\n\n| Issue                                                  | Solution                                                                                                                                                 |\n| ------------------------------------------------------ | -------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| \"Insufficient allowance\"                               | Call /check_approval first and submit approval tx                                                                                                        |\n| \"Quote expired\"                                        | Increase deadline or re-fetch quote                                                                                                                      |\n| \"Slippage exceeded\"                                    | Increase slippageTolerance or retry                                                                                                                      |\n| \"Insufficient liquidity\"                               | Try smaller amount or different route                                                                                                                    |\n| **\"Buffer is not defined\"**                            | Add Buffer polyfill (see Critical Implementation Notes)                                                                                                  |\n| **On-chain revert with empty data**                    | Validate `swap.data` is non-empty hex before broadcasting                                                                                                |\n| **\"permitData must be of type object\"**                | Strip `permitData: null` from request - omit field entirely                                                                                              |\n| **\"quote does not match any of the allowed types\"**    | Don''t wrap quote in `{quote: ...}` - spread it into request body                                                                                         |\n| **Received WETH instead of ETH on L2**                 | Check and unwrap WETH after swap (see [WETH Handling on L2s](#weth-handling-on-l2s))                                                                     |\n| **429 Too Many Requests**                              | Implement exponential backoff and add delays between batch requests (see [Rate Limiting](#rate-limiting))                                                |\n| **415 on OPTIONS preflight / CORS error**              | Set up a CORS proxy (see [CORS Proxy Configuration](#cors-proxy-configuration) in Browser Environment Setup)                                             |\n| **walletClient is undefined when wallet is connected** | Use `getWalletClient()` from `@wagmi/core` instead of the `useWalletClient()` hook (see [wagmi v2 Integration Pitfalls](#wagmi-v2-integration-pitfalls)) |\n| **\"Please provide a chain with the chain argument\"**   | Pass `chainId` to `getWalletClient(config, { chainId })`                                                                                                 |\n| **Chain mismatch error on swap**                       | Call `switchChain()` before `getWalletClient()` (see [wagmi v2 Integration Pitfalls](#wagmi-v2-integration-pitfalls))                                    |\n\n### API Validation Errors (400)\n\n| Error Message                                     | Cause                                      | Fix                                         |\n| ------------------------------------------------- | ------------------------------------------ | ------------------------------------------- |\n| `\"permitData\" must be of type object`             | Sending `permitData: null`                 | Omit the field entirely when null           |\n| `\"quote\" does not match any of the allowed types` | Wrapping quote in `{quote: quoteResponse}` | Spread quote response: `{...quoteResponse}` |\n| `signature and permitData must both be present`   | Including only one Permit2 field           | Include both or neither                     |\n\n### API Error Codes\n\n| Code | Meaning                                                  |\n| ---- | -------------------------------------------------------- |\n| 400  | Invalid request parameters (see validation errors above) |\n| 401  | Invalid or missing API key                               |\n| 404  | No route found for pair                                  |\n| 429  | Rate limit exceeded                                      |\n| 500  | API error - implement exponential backoff retry          |\n\n### Pre-Broadcast Checklist\n\nBefore sending a swap transaction to the blockchain:\n\n1. **Verify `swap.data`** is non-empty hex (not `''''`, not `''0x''`)\n2. **Verify addresses** - `swap.to` and `swap.from` are valid\n3. **Check quote freshness** - Re-fetch if older than 30 seconds\n4. **Validate gas** - Apply 10-20% buffer to estimates\n5. **Confirm balance** - User has sufficient token balance\n\n---\n\n## Additional Resources\n\n- [Universal Router GitHub](https://github.com/Uniswap/universal-router)\n- [Uniswap Docs](https://docs.uniswap.org)\n- [SDK Monorepo](https://github.com/Uniswap/sdks)\n- [Permit2 Patterns](https://github.com/dragonfly-xyz/useful-solidity-patterns/tree/main/patterns/permit2)\n"},"lastSynced":"2026-03-07T04:03:34.409Z","agentAnalysis":{"suitability":{"en":"Perfect for DeFi Agents needing seamless Uniswap swap integrations into frontends, backends, and smart contracts.","zh":"非常适合需要将Uniswap交换无缝集成到前端、后端和智能合约的DeFi代理。","ja":"DeFiエージェントがフロントエンド、バックエンド、スマートコントラクトにUniswapスワップをシームレスに統合する必要がある場合に最適です。","ko":"DeFi 에이전트가 프론트엔드, 백엔드 및 스마트 계약에 Uniswap 스왑을 무결점으로 통합해야 하는 경우에 적합합니다.","es":"Perfecto para agentes DeFi que necesitan integraciones de intercambio de Uniswap sin problemas en frontends, backends y contratos inteligentes.","fr":"Parfait pour les agents DeFi qui ont besoin d''intégrations d''échange Uniswap sans accroc dans les frontends, backends et contrats intelligents.","de":"Perfekt für DeFi-Agents, die nahtlose Uniswap-Swap-Integrationen in Frontends, Backends und Smart Contracts benötigen.","pt":"Perfeito para Agentes DeFi que precisam de integrações de troca Uniswap sem problemas em frontends, backends e contratos inteligentes.","ru":"Идеально для агентов DeFi, которым необходимы бесперебойные интеграции обмена Uniswap в фронтендах, бэкендах и смарт-контрактах.","ar":"مثالي للوكلاء DeFi الذين يحتاجون إلى تكاملات تبادل Uniswap دون انقطاع في الواجهات الأمامية والخلفية وال عقود الذكية."},"recommendation":{"en":"Empowers agents to integrate Uniswap swaps using viem and wagmi, enabling comprehensive guidance and support for transaction signing and contract interactions via the uniswap-viem plugin.","zh":"赋予代理集成Uniswap交换使用viem和wagmi的能力，实现对交易签名和通过uniswap-viem插件进行合同交互的全面指导和支持。","ja":"viemとwagmiを使用してUniswapスワップを統合するエージェントの能力を付与し、uniswap-viemプラグインを介して取引の署名と契約のやり取りを包括的にガイドおよびサポートします。","ko":"에이전트가 viem 및 wagmi를 사용하여 Uniswap 스왑을 통합할 수 있도록 하여 uniswap-viem 플러그인 통해 거래 서명 및 계약 상호 작용에 대한 포괄적인 가이드 및 지원을 제공합니다.","es":"Habilita a los agentes a integrar intercambios Uniswap utilizando viem y wagmi, lo que permite una orientación y soporte comprehensivos para la firma de transacciones y las interacciones de contrato a través del plugin uniswap-viem.","fr":"Permet aux agents d''intégrer les échanges Uniswap en utilisant viem et wagmi, ce qui permet une guidance et un support complets pour la signature de transactions et les interactions de contrat via le plugin uniswap-viem.","de":"Ermächtigt Agents, Uniswap-Swaps mit Hilfe von viem und wagmi zu integrieren, ermöglicht umfassende Anleitungen und Support für Transaktionsunterschriften und Vertragsinteraktionen über das uniswap-viem-Plugin.","pt":"Habilita os agentes a integrar trocas Uniswap usando viem e wagmi, permitindo orientação abrangente e suporte para assinatura de transações e interações de contrato via plugin uniswap-viem.","ru":"Наделяет агентов возможностью интегрировать обмены Uniswap с помощью viem и wagmi, обеспечивая всестороннее руководство и поддержку для подписи транзакций и взаимодействия с контрактами через плагин uniswap-viem.","ar":"يمنح الوكلاء القدرة على دمج عمليات تبادل Uniswap باستخدام viem و wagmi، مما يتيح إرشادات شاملة ودعمًا لتعيين_Transactions وتفاعلات العقد من خلال البرنامج المساعد uniswap-viem."},"useCases":{"en":["Integrating Uniswap swaps into decentralized applications","Automating transaction signing for Uniswap trades","Debugging smart contract interactions with Uniswap protocol"],"zh":["将Uniswap交换集成到去中心化应用程序中","自动化Uniswap交易的交易签名","调试智能合约与Uniswap协议的交互"],"ja":["分散型アプリケーションにUniswapスワップを統合する","Uniswap取引のトランザクション署名を自動化する","スマートコントラクトとUniswapプロトコルのやり取りをデバッグする"],"ko":["Uniswap 스왑을 분산형 애플리케이션에 통합하는 것","Uniswap 거래의 트랜잭션 서명 자동화","스마트 계약과 Uniswap 프로토콜의 상호 작용 디버깅"],"es":["Integrar intercambios Uniswap en aplicaciones descentralizadas","Automatizar la firma de transacciones para operaciones Uniswap","Depurar interacciones de contratos inteligentes con el protocolo Uniswap"],"fr":["Intégrer les échanges Uniswap dans des applications décentralisées","Automatiser la signature de transactions pour les échanges Uniswap","Déboguer les interactions de contrats intelligents avec le protocole Uniswap"],"de":["Uniswap-Swaps in dezentralisierte Anwendungen integrieren","Transaktionsunterschriften für Uniswap-Handel automatisieren","Smart-Contract-Interaktionen mit dem Uniswap-Protokoll debuggen"],"pt":["Integrar trocas Uniswap em aplicações descentralizadas","Automatizar a assinatura de transações para negociações Uniswap","Depurar interações de contrato inteligente com protocolo Uniswap"],"ru":["Интегрировать обмены Uniswap в децентрализованные приложения","Автоматизировать подпись транзакций для торговли Uniswap","Отлаживать взаимодействия смарт-контракта с протоколом Uniswap"],"ar":["دمج عمليات تبادل Uniswap في التطبيقات اللامركزية","تأتمة توقيع المعاملات للتجارة Uniswap","تصحيح أخطاء تفاعلات العقد الذكية مع بروتوكول Uniswap"]},"limitations":{"en":["Requires familiarity with viem basics","Needs uniswap-viem plugin installation","Limited to Uniswap protocol support"],"zh":["需要熟悉viem基础知识","需要安装uniswap-viem插件","仅限Uniswap协议支持"],"ja":["viemの基礎知識に精通している必要がある","uniswap-viemプラグインのインストールが必要","Uniswapプロトコルのみをサポート"],"ko":["viem 기본 지식에 익숙해야 함","uniswap-viem 플러그인 설치 필요","Uniswap 프로토콜 지원만 제한"],"es":["Requiere familiaridad con los conceptos básicos de viem","Necesita la instalación del plugin uniswap-viem","Limitado al soporte del protocolo Uniswap"],"fr":["Nécessite une connaissance de base de viem","Nécessite l''installation du plugin uniswap-viem","Limité au support du protocole Uniswap"],"de":["Benötigt Vertrautheit mit den Grundlagen von viem","Benötigt die Installation des uniswap-viem-Plugins","Begrenzt auf die Unterstützung des Uniswap-Protokolls"],"pt":["Exige familiaridade com bases de viem","Necessita instalação do plugin uniswap-viem","Limitado ao suporte do protocolo Uniswap"],"ru":["Требует знакомства с основами viem","Требует установки плагина uniswap-viem","Ограничен поддержкой протокола Uniswap"],"ar":["يتطلب دراية بأساسيات viem","يتطلب تثبيت البرنامج المساعد uniswap-viem","محدود بدعم بروتوكول Uniswap"]},"version":4},"contentHash":"f8d029e876121bd01f20344e5616088c74b35085c343abe4e6382aeab6de8de1","qualityScore":65}');
DELETE FROM skills_fts WHERE id = 'carluzh/Alphix-Frontend-Alpha/swap-integration';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('carluzh/Alphix-Frontend-Alpha/swap-integration', 'swap-integration', 'carluzh', 'Alphix-Frontend-Alpha', 'community', 'swap-integration carluzh Alphix-Frontend-Alpha community The swap-integration skill enables developers to integrate Uniswap swaps into their applications, supporting comprehensive viem/wagmi guidance. It benefits developers familiar with viem basics. Swap Integration 是一种将 Uniswap 集成到前端、后端和智能合约中的技术，实现无缝的 swap 功能 Swap Integration は、Uniswap をフロントエンド、バックエンド、スマートコントラクトに統合する技術です Swap Integration은 Uniswap을 프론트엔드, 백엔드, 스마트 계약에 통합하여 swap 기능을 제공하는 기술입니다 La integración de swaps de Uniswap permite a los desarrolladores interactuar con la red de Uniswap de manera segura y eficiente L''intégration de swaps Uniswap permet aux développeurs d''interagir avec le réseau Uniswap de manière sécurisée et efficace Die Integration von Uniswap-Swaps ermöglicht es Entwicklern, mit dem Uniswap-Netzwerk sicher und effizient zu interagieren Integre trocas Uniswap em suas aplicações com o plugin uniswap-viem. Aprenda a configurar e utilizar essa habilidade para melhorar suas interações com a blockchain. Интегрируйте свопы Uniswap в свои приложения с помощью плагина uniswap-viem. Узнайте, как настроить и использовать эту возможность для улучшения взаимодействия с блокчейном. دمج عمليات تبادل Uniswap في تطبيقاتك مع إضافة uniswap-viem. تعلم كيفية إعداد وتشغيل هذه القدرة لتحسين تفاعلك مع سلاسل الكتل how to use swap-integration what is swap-integration swap-integration alternative swap-integration vs uniswap swap-integration install swap-integration setup guide uniswap swap integration viem plugin installation wagmi guidance for uniswap Uniswap 集成 Swap Integration 智能合约 前端集成 后端集成 即时 swap Uniswap-Viem AI 에이전트 Installs the uniswap-viem plugin for comprehensive viem/wagmi guidance via `claude plugin add @uniswap/uniswap-viem` Supports integration of Uniswap swaps into frontends, backends, and smart contracts Assumes familiarity with viem basics, including client setup, account management, and contract interactions Provides a quick decision guide for building applications with Uniswap swaps Utilizes the viem plugin for transaction signing and contract interactions swap-integration is a skill that integrates Uniswap swaps into frontends, backends, and smart contracts, utilizing the uniswap-viem plugin for viem/wagmi guidance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('acedergren/oci-self-service-portal/firecrawl', 'community', 'acedergren', 'oci-self-service-portal', 'acedergren/oci-self-service-portal', 'firecrawl', 0, 0, 65, '2026-03-03T09:46:57Z', '2026-03-07T04:03:57.485Z', '04721607ce1b10eea258568dca54fa8870e8e9d8b988d080bf21219547bf8097', '{"id":"acedergren/oci-self-service-portal/firecrawl","name":"firecrawl","description":{"en":"firecrawl is an OCI Self-Service Portal with AI-powered chat and 60+ OCI tools, ideal for developers needing efficient web scraping solutions. It offers a decision framework for scale assessment and parallelization.","zh":"Firecrawl是OCI Self-Service Portal的AI-powered chat和60+ OCI工具，用于Web抓取","ja":"Firecrawlは、OCI Self-Service PortalのAIエージェントと60以上のOCIツールを備えたWebスクレイピングツール","ko":"Firecrawl은 OCI Self-Service Portal의 AI 툴과 60가지 이상의 OCI 도구를 갖춘 웹 스크레이핑 전문가","es":"firecrawl es una herramienta de scraping web con capacidades de AI que permite la automatización de tareas de contenido web","fr":"firecrawl est un outil de scraping web avec des capacités d''IA qui permet l''automatisation des tâches de contenu web","de":"firecrawl ist ein Web-Scraping-Tool mit KI-Fähigkeiten, das die Automatisierung von Webinhaltsaufgaben ermöglicht","pt":"O Firecrawl é uma ferramenta de web scraping com IA que permite extrair dados da web de forma eficiente, com suporte a paralelização e concorrência","ru":"Firecrawl - это инструмент веб-скрапинга с ИИ, который позволяет эффективно извлекать данные из сети, с поддержкой параллелизации и конкурентности","ar":"Firecrawl هو أداة爬虫 الويب بالذكاء الاصطناعي التي تمكنك من استخراج البيانات من الويب بفعالية، مع دعم للتوازي والتنافس"},"seo":{"title":{"en":"firecrawl: Web Scraping Expert Setup Guide | AI Agent Skill","zh":"Firecrawl Setup Guide - AI工具 CLI 网页抓取专家","ja":"Firecrawlベストプラクティス - AIエージェントによるWeb Scraping","ko":"Firecrawl 사용법 - AI 툴 CLI 웹 스크레이핑 전문가","es":"Guía de configuración de firecrawl: Herramienta de scrapi...","fr":"Guide de mise en place de firecrawl: Outil de scraping we...","de":"Einrichtungsleitfaden für firecrawl: Web-Scraping-Tool mi...","pt":"Guia de Configuração do Firecrawl - Ferramenta de Web Scr...","ru":"Настройка Firecrawl - Инструмент веб-скрапинга с ИИ Агентами","ar":"دليل إعداد Firecrawl - أداة爬虫 الويب بالذكاء الاصطناعي"},"description":{"en":"Unlock efficient web content tasks with firecrawl. Learn how to prioritize firecrawl over WebFetch/WebSearch and master its CLI for optimal results.","zh":"了解Firecrawl的优点和技术细节，优化您的Web抓取任务","ja":"Firecrawlの機能と使い方をマスターして、Webスクレイピングを最適化する","ko":"Firecrawl의 기능과 사용법을 익혀 웹 스크레이핑을 최적화하세요","es":"Aprende a utilizar firecrawl, una herramienta de scraping web con capacidades de AI para tareas de contenido web","fr":"Découvrez comment utiliser firecrawl, un outil de scraping web avec des capacités d''IA pour les tâches de contenu web","de":"Erfahren Sie, wie Sie firecrawl verwenden, ein Web-Scraping-Tool mit KI-Fähigkeiten für Webinhaltsaufgaben","pt":"Aprenda a utilizar o Firecrawl, uma ferramenta de web scraping com IA, para extrair dados da web de forma eficiente","ru":"Узнайте, как использовать Firecrawl, инструмент веб-скрапинга с ИИ, для эффективного извлечения данных из сети","ar":"تعرف على كيفية استخدام Firecrawl، أداة爬虫 الويب بالذكاء الاصطناعي، لاستخراج البيانات من الويب بفعالية"},"definition":{"en":"firecrawl is a web scraping expert tool that utilizes a CLI for efficient web content tasks, prioritized over WebFetch/WebSearch.","zh":"Firecrawl是用于Web抓取的CLI工具，具有AI-powered chat和OCI工具集","ja":"Firecrawlは、Webスクレイピング用のCLIツールであり、AIエージェントとOCIツールを備えている","ko":"Firecrawl은 웹 스크레이핑용 CLI 도구로 AI 툴과 OCI 도구를 갖추고 있다","es":"firecrawl es una herramienta de scraping web con AI que utiliza la línea de comandos para extraer contenido web","fr":"firecrawl est un outil de scraping web avec IA qui utilise la ligne de commande pour extraire le contenu web","de":"firecrawl ist ein Web-Scraping-Tool mit KI, das die Kommandozeile zur Extraktion von Webinhalten verwendet","pt":"O Firecrawl é uma ferramenta de web scraping com IA que utiliza comandos CLI para extrair dados da web","ru":"Firecrawl - это инструмент веб-скрапинга с ИИ, который использует команды CLI для извлечения данных из сети","ar":"Firecrawl هو أداة爬虫 الويب بالذكاء الاصطناعي التي تستخدم أوامر CLI لاستخراج البيانات من الويب"},"features":{"en":["Utilizes a decision framework for scale assessment","Supports parallelization using `&` and `wait` for 6-50 pages","Employs `xargs -P` for concurrent processing of 50+ pages","Allows manual commands for one-time tasks","Enables simple serial execution with the `-o` flag for 1-5 pages"],"zh":["优化的Web抓取功能","支持parallelization和concurrency limits","提供-xargs -P选项用于大规模抓取","支持one-time和recurring抓取任务","具有AI-powered chat功能","集成了60+ OCI工具"],"ja":["最適化されたWebスクレイピング機能","parallelizationとconcurrency limitsのサポート","大規模スクレイピング用の-xargs -Pオプション","one-timeとrecurringスクレイピングタスクのサポート","AIエージェントによるチャット機能","60以上のOCIツールの統合"],"ko":["최적화된 웹 스크레이핑 기능","parallelization과 concurrency limits 지원","대규모 스크레이핑을 위한 -xargs -P 옵션","one-time과 recurring 스크레이핑 작업 지원","AI 툴을 통한 채팅 기능","60가지 이상의 OCI 도구 통합"],"es":["Soporte para tareas de contenido web con AI","Capacidad de scraping web en paralelo con ''&'' y ''wait''","Opción de usar ''xargs -P'' para concurrencia limitada","Compatibilidad con tareas de una sola vez o recurrentes","Uso de la línea de comandos para la extracción de contenido web","Integración con OCI Self-Service Portal"],"fr":["Prise en charge des tâches de contenu web avec IA","Capacité de scraping web en parallèle avec ''&'' et ''wait''","Option d''utiliser ''xargs -P'' pour une concurrence limitée","Compatibilité avec les tâches ponctuelles ou récurrentes","Utilisation de la ligne de commande pour l''extraction de contenu web","Intégration avec le portail de self-service OCI"],"de":["Unterstützung für Webinhaltsaufgaben mit KI","Fähigkeit zum parallelen Web-Scraping mit ''&'' und ''wait''","Option, ''xargs -P'' für eine begrenzte Konkurrenz zu verwenden","Kompatibilität mit Einmal- oder wiederkehrenden Aufgaben","Verwendung der Kommandozeile zur Extraktion von Webinhalten","Integration mit dem OCI-Self-Service-Portal"],"pt":["Suporte a paralelização com `&` e `wait`","Concorrência com `xargs -P`","Comandos CLI para extração de dados","Escala de extração de 1 a 50+ páginas","Suporte a extração de dados em tempo real"],"ru":["Поддержка параллелизации с `&` и `wait`","Конкурентность с `xargs -P`","Команды CLI для извлечения данных","Масштаб извлечения от 1 до 50+ страниц","Поддержка извлечения данных в реальном времени"],"ar":["دعم للتوازي مع `&` و `wait`","تنافس مع `xargs -P`","أوامر CLI لاستخراج البيانات","مقياس استخراج من 1 إلى 50+ صفحة","دعم لاستخراج البيانات في الوقت الحقيقي"]},"keywords":{"en":["how to use firecrawl","firecrawl alternative","firecrawl vs WebFetch","firecrawl install","firecrawl setup guide","what is firecrawl","firecrawl CLI","web scraping with firecrawl"],"zh":["Firecrawl","AI工具","Web抓取","CLI","OCI Self-Service Portal","AI-powered chat","parallelization","concurrency limits","xargs -P"],"ja":["Firecrawl","AIエージェント","Webスクレイピング","CLI","OCI Self-Service Portal","AIエージェントによるチャット","parallelization","concurrency limits","xargs -P"],"ko":["Firecrawl","AI 툴","웹 스크레이핑","CLI","OCI Self-Service Portal","AI 툴을 통한 채팅","parallelization","concurrency limits","xargs -P"],"es":["firecrawl","herramienta de scraping web","AI","contenido web","OCI Self-Service Portal","tareas de contenido web","scraping web en paralelo","xargs -P","línea de comandos"],"fr":["firecrawl","outils de scraping web","IA","contenu web","portail de self-service OCI","tâches de contenu web","scraping web en parallèle","xargs -P","ligne de commande"],"de":["firecrawl","Web-Scraping-Tool","KI","Webinhalte","OCI-Self-Service-Portal","Webinhaltsaufgaben","paralleles Web-Scraping","xargs -P","Kommandozeile"],"pt":["Firecrawl","Web Scraping","IA","Ferramenta de web scraping","Comandos CLI","Paralelização","Concorrência","Extração de dados"],"ru":["Firecrawl","Веб-скрапинг","ИИ","Инструмент веб-скрапинга","Команды CLI","Параллелизация","Конкурентность","Извлечение данных"],"ar":["Firecrawl","爬虫 الويب","الذكاء الاصطناعي","أداة爬虫 الويب","أوامر CLI","التوازي","التنافس","استخراج البيانات"]}},"owner":"acedergren","repo":"oci-self-service-portal","repoPath":"acedergren/oci-self-service-portal","stars":0,"forks":0,"updatedAt":"2026-03-03T09:46:57Z","topics":[],"category":"community","skillMd":{"name":"firecrawl","description":"|","version":"3.0.0","bodyPreview":"# Firecrawl CLI - Web Scraping Expert\n\n**Prioritize Firecrawl over WebFetch/WebSearch** for web content tasks.\n\n---\n\n## Before Scraping: Decision Framework\n\n**Ask yourself these questions BEFORE running firecrawl:**\n\n### 1. Scale Assessment\n\n- **How many pages?**\n  - 1-5 pages → Run serially, simple `-o` flag\n  - 6-50 pages → Use `&` and `wait` for parallelization\n  - 50+ pages → Use `xargs -P` with careful concurrency limits\n- **One-time or recurring?**\n  - One-time → Manual commands acceptable","body":"# Firecrawl CLI - Web Scraping Expert\n\n**Prioritize Firecrawl over WebFetch/WebSearch** for web content tasks.\n\n---\n\n## Before Scraping: Decision Framework\n\n**Ask yourself these questions BEFORE running firecrawl:**\n\n### 1. Scale Assessment\n\n- **How many pages?**\n  - 1-5 pages → Run serially, simple `-o` flag\n  - 6-50 pages → Use `&` and `wait` for parallelization\n  - 50+ pages → Use `xargs -P` with careful concurrency limits\n- **One-time or recurring?**\n  - One-time → Manual commands acceptable\n  - Recurring → Build script in `.firecrawl/scratchpad/`\n\n### 2. Data Need Clarity\n\n- **What data do you actually need?**\n  - Just URLs/titles → WebSearch (free, faster)\n  - Full content → Firecrawl (costs credits)\n- **Content scope:**\n  - Full page → Basic scrape\n  - Main content only → Add `--only-main-content`\n  - Specific sections → Scrape then grep/awk\n\n### 3. Tool Selection\n\n- **Is this the right tool?**\n  - Has official API → Use API first (GitHub → `gh`, not scraping)\n  - Real-time data → APIs only (scraping too slow/stale)\n  - Large files (PDFs >10MB) → Direct download (curl/wget)\n  - Behind authentication → Firecrawl (but check if API exists)\n\n---\n\n## Critical Decision: Which Tool to Use?\n\n```\nUser needs web content?\n│\n├─ Single known URL\n│   ├─ Public page, simple HTML → WebFetch (faster, no auth needed)\n│   ├─ JS-rendered/SPA (React, Vue, etc.) → Firecrawl (executes JavaScript)\n│   ├─ Need structured data (links, headings, tables) → Firecrawl (markdown output)\n│   └─ Behind auth/paywall → Firecrawl (handles authentication)\n│\n├─ Search + scrape workflow\n│   ├─ Need top 5-10 results with content → Firecrawl search --scrape\n│   ├─ Just need URLs/titles → WebSearch (lighter weight, faster)\n│   └─ Deep research (20+ sources) → Firecrawl (parallelized scraping)\n│\n├─ Entire site mapping (discover all pages)\n│   └─ Use Firecrawl map (returns all URLs on domain)\n│\n└─ Real-time data (stock prices, sports scores)\n    └─ Use direct API if available (NOT scraping - too slow/unreliable)\n```\n\n---\n\n## Anti-Patterns (NEVER Do This)\n\n### ❌ #1: Sequential Scraping\n\n**Problem**: Scraping sites one-by-one wastes time.\n\n```bash\n# WRONG - sequential (10 sites = 50+ seconds)\nfor url in site1 site2 site3 site4 site5; do\n  firecrawl scrape \"$url\" -o \".firecrawl/$url.md\"\ndone\n\n# CORRECT - parallel (10 sites = 5-8 seconds)\nfirecrawl scrape site1 -o .firecrawl/1.md &\nfirecrawl scrape site2 -o .firecrawl/2.md &\nfirecrawl scrape site3 -o .firecrawl/3.md &\nwait\n\n# BEST - xargs parallelization\ncat urls.txt | xargs -P 10 -I {} sh -c ''firecrawl scrape \"{}\" -o \".firecrawl/$(echo {} | md5).md\"''\n```\n\n**Why**: Firecrawl supports up to 100 parallel jobs (check `firecrawl --status`). Use them.\n\n**Why this is deceptively hard to debug**: Operations complete successfully—just slowly. No error messages indicate the problem. When scraping 20 sites takes 2 minutes instead of 10 seconds, it''s not obvious the bottleneck is sequential execution rather than network speed. Profiling reveals the issue: 90% of time is spent waiting, not processing. Takes 10-15 minutes to realize parallelization is the fix.\n\n### ❌ #2: Reading Full Output into Context\n\n**Problem**: Firecrawl results often exceed 1000+ lines. Reading entire files floods context.\n\n```bash\n# WRONG - reads 5000-line file into context\nRead(.firecrawl/result.md)\n\n# CORRECT - preview first, then targeted extraction\nwc -l .firecrawl/result.md  # Check size: 5243 lines\nhead -100 .firecrawl/result.md  # Preview structure\ngrep -A 10 \"keyword\" .firecrawl/result.md  # Extract relevant sections\n```\n\n**Why**: Context is precious. Use bash tools (grep, head, tail, awk) to extract what you need.\n\n**Why this is deceptively hard to debug**: No error message appears—file loads successfully into context. The agent thinks \"I''ll just read the file\" without checking size first. You only discover the problem 30+ messages later when context limits hit, or responses become sluggish. File explorers don''t show line counts by default. Terminal shows \"success\" but you''ve silently wasted 4000+ tokens. Takes 15-20 minutes to realize incremental reading with grep/head would have been 20x more efficient.\n\n### ❌ #3: Using Firecrawl for Wrong Tasks\n\n**NEVER use Firecrawl for:**\n\n- **Authenticated pages without proper setup** → Run `firecrawl login --browser` first\n- **Real-time data (sports scores, stock prices)** → Use direct APIs (scraping is too slow)\n- **Large binary files (PDFs > 10MB, videos)** → Download directly via curl/wget\n- **APIs with official SDKs** → Use the SDK (GitHub API → use `gh` CLI)\n\n**Why this is deceptively hard to debug**: Wrong tool choice doesn''t produce errors—it produces slow, unreliable results. Scraping real-time data \"works\" but is 10 seconds behind and costs credits per request. Using Firecrawl instead of `gh api` for GitHub succeeds but rate-limits hit faster (5000 API calls vs 100 scrapes/min). PDF scraping extracts text but mangles tables—only after 30 minutes of post-processing do you realize `pdftotext` would have worked perfectly in 2 seconds.\n\n### ❌ #4: Ignoring Output Organization\n\n**Problem**: Dumping all results in working directory creates mess.\n\n```bash\n# WRONG - pollutes working directory\nfirecrawl scrape https://example.com\n\n# CORRECT - organized structure\nfirecrawl scrape https://example.com -o .firecrawl/example.com.md\nfirecrawl search \"AI news\" -o .firecrawl/search-ai-news.json\nfirecrawl map https://docs.site.com -o .firecrawl/docs-sitemap.txt\n```\n\n**Why**: `.firecrawl/` directory keeps workspace clean, add to `.gitignore`.\n\n**Why this is deceptively hard to debug**: No error—files just accumulate in root directory. After 10-15 scrapes, `ls` output becomes unreadable. Worse: firecrawl''s default output to stdout means results appear in terminal but aren''t saved, requiring re-scraping (wasting credits). Only after losing data twice do you realize `-o` flag is mandatory for persistence. Git commits accidentally include scraped data before `.gitignore` is updated.\n\n---\n\n## Authentication Setup\n\n**Before first use**, check auth status:\n\n```bash\nfirecrawl --status\n```\n\n**If not authenticated**:\n\n```bash\nfirecrawl login --browser  # Opens browser automatically\n```\n\nThe `--browser` flag auto-opens authentication page without prompting. Don''t ask user to run manually—execute and let browser handle auth.\n\n---\n\n## Core Operations (Quick Reference)\n\n### Search the Web\n\n```bash\n# Basic search\nfirecrawl search \"your query\" -o .firecrawl/search-query.json --json\n\n# Search + scrape content from results\nfirecrawl search \"firecrawl tutorials\" --scrape -o .firecrawl/search-scraped.json --json\n\n# Time-filtered search\nfirecrawl search \"AI announcements\" --tbs qdr:d -o .firecrawl/today.json --json  # Past day\nfirecrawl search \"tech news\" --tbs qdr:w -o .firecrawl/week.json --json          # Past week\n```\n\n### Scrape Single Page\n\n```bash\n# Get clean markdown\nfirecrawl scrape https://example.com -o .firecrawl/example.md\n\n# Main content only (removes nav, footer, ads)\nfirecrawl scrape https://example.com --only-main-content -o .firecrawl/clean.md\n\n# Wait for JS to render (SPAs)\nfirecrawl scrape https://spa-app.com --wait-for 3000 -o .firecrawl/spa.md\n```\n\n### Map Entire Site\n\n```bash\n# Discover all URLs\nfirecrawl map https://example.com -o .firecrawl/urls.txt\n\n# Filter for specific pages\nfirecrawl map https://example.com --search \"blog\" -o .firecrawl/blog-urls.txt\n```\n\n---\n\n## Expert Pattern: Parallel Bulk Scraping\n\n**Check concurrency limit first**:\n\n```bash\nfirecrawl --status\n# Output: Concurrency: 0/100 jobs\n```\n\n**Run up to limit**:\n\n```bash\n# For list of URLs in file\ncat urls.txt | xargs -P 10 -I {} sh -c ''firecrawl scrape \"{}\" -o \".firecrawl/$(basename {}).md\"''\n\n# For generated URLs\nfor i in {1..20}; do\n  firecrawl scrape \"https://site.com/page/$i\" -o \".firecrawl/page-$i.md\" &\ndone\nwait\n```\n\n**Extract data after bulk scrape**:\n\n```bash\n# Extract all H1 headings from scraped pages\ngrep \"^# \" .firecrawl/*.md\n\n# Find pages mentioning keyword\ngrep -l \"keyword\" .firecrawl/*.md\n\n# Process with jq (if JSON output)\njq -r ''.data.web[].title'' .firecrawl/*.json\n```\n\n---\n\n## When to Load Full CLI Reference\n\n**MANDATORY - READ ENTIRE FILE**: `references/cli-options.md` when:\n\n- Error mentions 3+ unknown flags (e.g., \"--sitemap\", \"--include-tags\", \"--exclude-tags\")\n- Need 5+ advanced options for a single command\n- Troubleshooting header injection, cookie handling, or sitemap modes\n- Setting up custom user-agents or location-based scraping parameters\n\n**MANDATORY - READ ENTIRE FILE**: `references/output-processing.md` when:\n\n- Building pipeline with 3+ transformation steps (firecrawl | jq | awk | ...)\n- Parsing nested JSON structures from search results (accessing .data.web[].metadata)\n- Need to combine outputs from 10+ scraped files into single dataset\n- Implementing deduplication or merging logic across multiple firecrawl results\n\n**Do NOT load references** for basic search/scrape/map operations with standard flags (--json, -o, --limit, --scrape).\n\n---\n\n## Error Recovery Procedures\n\n### When \"Not authenticated\" Error Occurs\n\n**Recovery steps**:\n\n1. Check current auth status: `firecrawl --status`\n2. Run authentication: `firecrawl login --browser` (auto-opens browser)\n3. Verify success: `firecrawl --status` should show \"Authenticated via FIRECRAWL_API_KEY\"\n4. **Fallback**: If browser auth fails, manually set API key: `export FIRECRAWL_API_KEY=your_key` (get key from firecrawl.dev dashboard)\n\n### When \"Concurrency limit reached\" Error Occurs\n\n**Recovery steps**:\n\n1. Check current usage: `firecrawl --status` (shows X/100 jobs)\n2. Wait for running jobs: `wait` (if using `&` background jobs)\n3. Verify capacity freed: `firecrawl --status` should show lower usage\n4. **Fallback**: If jobs are stuck, reduce parallelization (e.g., `xargs -P 5` instead of `-P 10`) and retry. Jobs auto-timeout after 5 minutes.\n\n### When \"Page failed to load\" Error Occurs\n\n**Recovery steps**:\n\n1. Test basic connectivity: `curl -I URL` (verify site is accessible)\n2. Increase JS wait time: `firecrawl scrape URL --wait-for 5000 -o output.md`\n3. Verify output has content: `wc -l output.md` (should be >10 lines)\n4. **Fallback**: If still empty after 10s wait, page may be fully client-rendered → try `--format html` to check raw HTML, or use alternate approach (curl + cheerio, or try WebFetch if JS not critical)\n\n### When \"Output file is empty\" Error Occurs\n\n**Recovery steps**:\n\n1. Check if content exists: `head -20 output.md` (see what was captured)\n2. Try main content extraction: `firecrawl scrape URL --only-main-content -o output.md`\n3. Verify improvement: `wc -l output.md` (should increase significantly)\n4. **Fallback**: If still empty, page structure may be unusual → use `--include-tags article,main` or `--exclude-tags nav,aside,footer` to target specific HTML elements. If that fails, page may have no scrapeable text (images only, canvas-based, etc.).\n\n---\n\n## Resources\n\n- **CLI Help**: `firecrawl --help` or `firecrawl <command> --help`\n- **Status Check**: `firecrawl --status` (shows auth, credits, concurrency)\n- **This Skill**: Decision trees, anti-patterns, expert parallelization patterns\n"},"lastSynced":"2026-03-07T04:03:57.485Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Scraping Agents needing efficient web content extraction with OCI tools and AI-powered chat","zh":"非常适合需要使用OCI工具和AI驱动聊天的Web Scraping Agents进行高效的网页内容提取","ja":"Web Scraping AgentsがOCIツールやAIを利用したWebコンテンツ抽出を効率的に行うのに最適","ko":"OCI 도구 및 AI聊天을 사용하여 효율적인 웹 콘텐츠 추출을进行하는 웹 스크래핑 에이전트에 적합","es":"Perfecto para agentes de Scraping Web que necesitan una extracción eficiente de contenido web con herramientas de OCI y chat con inteligencia artificial","fr":"Parfait pour les agents de Scraping Web ayant besoin d''une extraction efficace de contenu Web avec des outils OCI et un chat alimenté par l''IA","de":"Perfekt für Web Scraping Agenten, die eine effiziente Webinhaltsextraktion mit OCI-Tools und künstlicher Intelligenz-basiertem Chat benötigen","pt":"Perfeito para Agentes de Scraping da Web que precisam de extração eficiente de conteúdo da web com ferramentas OCI e chat impulsionado por IA","ru":"Идеально для Веб-скрейпинговых агентов, которым требуется эффективная экстракция веб-контента с помощью инструментов OCI и чата, работающего на ИИ","ar":"مثالي لعمليات حشر صراصير الويب التي تحتاج إلى استخراج محتوى ويب فعال مع أدوات OCI و دردشة مدعومة بالذكاء الاصطناعي"},"recommendation":{"en":"Empowers agents to perform scalable web scraping tasks using firecrawl''s decision framework for scale assessment and parallelization, leveraging OCI Self-Service Portal with 60+ OCI tools and supporting protocols like serial and parallel execution with `&` and `wait` or `xargs -P` for concurrency control","zh":"赋予代理执行可扩展的Web抓取任务的能力，使用firecrawl的决策框架进行规模评估和并行化，利用OCI自助服务门户和60+ OCI工具，支持诸如串行和并行执行的协议，使用`&`和`wait`或`xargs -P`进行并发控制","ja":"エージェントがfirecrawlの意思決定フレームワークを使用してスケーラブルなWebスクレイピングタスクを実行できるようにし、OCIセルフサービスポータルと60以上のOCIツールを利用し、シリアルおよびパラレル実行などのプロトコルをサポートし、`&`および`wait`または`xargs -P`を使用した並行制御","ko":"에이전트가 확장 가능한 웹 스크래핑 작업을 수행할 수 있도록 하며, firecrawl의 의사 결정 프레임워크를 사용하여 규모 평가 및 병렬화를 수행하고, OCI 셀프 서비스 포털 및 60개 이상의 OCI 도구를 활용하고, 직렬 및 병렬 실행 등의 프로토콜을 지원하며, `&` 및 `wait` 또는 `xargs -P`를 사용한 병렬 제어","es":"Habilita a los agentes a realizar tareas de scraping web escalables utilizando el marco de decisión de firecrawl para la evaluación de escalabilidad y paralelización, aprovechando el Portal de autoservicio de OCI con más de 60 herramientas de OCI y protocolos de支持 como la ejecución serie y paralela con `&` y `wait` o `xargs -P` para el control de concurrencia","fr":"Permet aux agents d''exécuter des tâches de scraping Web escalables en utilisant le cadre de décision de firecrawl pour l''évaluation de l''échelle et la parallélisation, en exploitant le Portail d''auto-service d''OCI avec plus de 60 outils d''OCI et en prenant en charge des protocoles tels que l''exécution série et parallèle avec `&` et `wait` ou `xargs -P` pour le contrôle de la concurrence","de":"Ermächtigt Agenten, skalierbare Web-Scraping-Aufgaben mit firecrawls Entscheidungsframework für Skaleneinschätzung und Parallelisierung durchzuführen, indem es das OCI-Selbstbedienungsportal mit über 60 OCI-Tools und unterstützten Protokollen wie serieller und paralleler Ausführung mit `&` und `wait` oder `xargs -P` für Konkurrenzkontrolle nutzt","pt":"Habilita os agentes a realizar tarefas de scraping da web escaláveis usando o framework de decisão do firecrawl para avaliação de escala e parallelização, aproveitando o Portal de Autoatendimento da OCI com 60+ ferramentas da OCI e suportando protocolos como execução serial e paralela com `&` e `wait` ou `xargs -P` para controle de concorrência","ru":"Наделяет агентов возможностью выполнять масштабируемые задачи веб-скрейпинга с помощью фреймворка принятия решений firecrawl для оценки масштаба и параллелизации, используя Портал самообслуживания OCI с 60+ инструментами OCI и поддерживая протоколы, такие как последовательная и параллельная выполнение с `&` и `wait` или `xargs -P` для управления конкурентностью","ar":"يمكّن الوكيل من أداء مهام حشر صراصير الويب القابلة للتوسيع باستخدام إطار تصمیم firecrawl لتقييم النطاق والتسلسل الهرمي ، والاستفادة من بوابة الخدمة الذاتية لشركة OCI مع أكثر من 60 أداة من أدوات شركة OCI ودعم بروتوكولات مثل التنفيذ المتسلسل والمتوازي مع `&` و `wait` أو `xargs -P` للسيطرة على الت конкурسية"},"useCases":{"en":["Automating web content extraction for large-scale datasets","Optimizing web scraping tasks with parallelization using `xargs -P`","Debugging web scraping issues with firecrawl''s CLI and decision framework"],"zh":["自动化大规模数据集的网页内容提取","使用`xargs -P`进行并行化的网页抓取任务优化","使用firecrawl的CLI和决策框架调试网页抓取问题"],"ja":["大規模データセットのWebコンテンツ抽出を自動化する","`xargs -P`を使用した並列化によるWebスクレイピングタスクの最適化","firecrawlのCLIおよび意思決定フレームワークを使用したWebスクレイピングの問題のデバッグ"],"ko":["대규모 데이터셋의 웹 콘텐츠 추출 자동화","`xargs -P`를 사용한 병렬화를 통한 웹 스크래핑 작업 최적화","firecrawl의 CLI 및 의사 결정 프레임워크를 사용한 웹 스크래핑 문제 디버깅"],"es":["Automatizar la extracción de contenido web para grandes conjuntos de datos","Optimizar tareas de scraping web con paralelización utilizando `xargs -P`","Depurar problemas de scraping web con la CLI y el marco de decisión de firecrawl"],"fr":["Automatiser l''extraction de contenu Web pour de grands ensembles de données","Optimiser les tâches de scraping Web avec une parallélisation en utilisant `xargs -P`","Déboguer les problèmes de scraping Web avec la CLI et le cadre de décision de firecrawl"],"de":["Automatisieren der Webinhaltsextraktion für große Datensätze","Optimieren von Web-Scraping-Aufgaben mit Parallelisierung unter Verwendung von `xargs -P`","Fehlerbehebung bei Web-Scraping-Problemen mit der CLI und dem Entscheidungsframework von firecrawl"],"pt":["Automatizar a extração de conteúdo da web para conjuntos de dados em larga escala","Otimizar tarefas de scraping da web com parallelização usando `xargs -P`","Depurar problemas de scraping da web com o CLI e o framework de decisão do firecrawl"],"ru":["Автоматизировать извлечение веб-контента для больших наборов данных","Оптимизировать задачи веб-скрейпинга с параллелизацией с помощью `xargs -P`","Отлаживать проблемы веб-скрейпинга с помощью CLI и фреймворка принятия решений firecrawl"],"ar":["تأتميم استخراج محتوى الويب ل مجموعات البيانات على نطاق واسع","تحسين مهام حشر صراصير الويب بالتزامن باستخدام `xargs -P`","تصحيح أخطاء حشر صراصير الويب باستخدام CLI و إطار تصمیم firecrawl"]},"limitations":{"en":["Requires careful concurrency limits for large-scale scraping tasks","Ideal for 6-50 pages with `&` and `wait` for parallelization","Recommended for one-time or recurring web content tasks with manual commands or automated workflows"],"zh":["需要对大规模抓取任务进行仔细的并发限制","适用于使用`&`和`wait`进行并行化的6-50页","推荐用于一次性或定期的网页内容任务，使用手动命令或自动化工作流"],"ja":["大規模なスクレイピングタスクには注意深い並行制限が必要","`&`および`wait`を使用した並列化の場合、6〜50ページが適している","手動コマンドまたは自動化されたワークフローを使用した一時的な、または定期的なWebコンテンツタスクに推奨"],"ko":["대규모 스크래핑 작업에는 신중한 병렬 제한이 필요","`&` 및 `wait`를 사용한 병렬화의 경우 6-50페이지가 적합","수동 명령 또는 자동화된 워크플로를 사용한 일회성 또는 정기적인 웹 콘텐츠 작업에 권장"],"es":["Requiere límites de concurrencia cuidadosos para tareas de scraping a gran escala","Ideal para 6-50 páginas con `&` y `wait` para paralelización","Recomendado para tareas de contenido web de un solo uso o recurrentes con comandos manuales o flujos de trabajo automatizados"],"fr":["Nécessite des limites de concurrence soigneuses pour les tâches de scraping à grande échelle","Idéal pour 6-50 pages avec `&` et `wait` pour la parallélisation","Recommandé pour les tâches de contenu Web à usage unique ou récurrent avec des commandes manuelles ou des flux de travail automatisés"],"de":["Benötigt sorgfältige Konkurrenzlimits für groß angelegte Scraping-Aufgaben","Ideal für 6-50 Seiten mit `&` und `wait` für Parallelisierung","Empfohlen für Einmal- oder wiederkehrende Webinhaltsaufgaben mit manuellen Befehlen oder automatisierten Workflows"],"pt":["Exige limites de concorrência cuidadosos para tarefas de scraping da web em larga escala","Ideal para 6-50 páginas com `&` e `wait` para parallelização","Recomendado para tarefas de extração de conteúdo da web de uma vez ou recorrentes com comandos manuais ou fluxos de trabalho automatizados"],"ru":["Требует тщательных ограничений конкурентности для задач веб-скрейпинга в большом масштабе","Идеально для 6-50 страниц с `&` и `wait` для параллелизации","Рекомендуется для одноразовых или повторяющихся задач извлечения веб-контента с ручными командами или автоматизированными рабочими процессами"],"ar":["يتطلب حدود تزامن دقيق ل مهام حشر صراصير الويب على نطاق واسع","مثالي ل 6-50 صفحة مع `&` و `wait` للتشغيل المتوازي","موصى به للقيام بمهام استخراج محتوى الويب لمرة واحدة أو متكررة مع أوامر يدوية أو سير عمل آلي"]},"version":4},"contentHash":"04721607ce1b10eea258568dca54fa8870e8e9d8b988d080bf21219547bf8097","qualityScore":65}');
