INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('acedergren/oci-self-service-portal/firecrawl', 'firecrawl', 'acedergren', 'oci-self-service-portal', 'community', 'firecrawl acedergren oci-self-service-portal community firecrawl is an OCI Self-Service Portal with AI-powered chat and 60+ OCI tools, ideal for developers needing efficient web scraping solutions. It offers a decision framework for scale assessment and parallelization. Firecrawl是OCI Self-Service Portal的AI-powered chat和60+ OCI工具，用于Web抓取 Firecrawlは、OCI Self-Service PortalのAIエージェントと60以上のOCIツールを備えたWebスクレイピングツール Firecrawl은 OCI Self-Service Portal의 AI 툴과 60가지 이상의 OCI 도구를 갖춘 웹 스크레이핑 전문가 firecrawl es una herramienta de scraping web con capacidades de AI que permite la automatización de tareas de contenido web firecrawl est un outil de scraping web avec des capacités d''IA qui permet l''automatisation des tâches de contenu web firecrawl ist ein Web-Scraping-Tool mit KI-Fähigkeiten, das die Automatisierung von Webinhaltsaufgaben ermöglicht O Firecrawl é uma ferramenta de web scraping com IA que permite extrair dados da web de forma eficiente, com suporte a paralelização e concorrência Firecrawl - это инструмент веб-скрапинга с ИИ, который позволяет эффективно извлекать данные из сети, с поддержкой параллелизации и конкурентности Firecrawl هو أداة爬虫 الويب بالذكاء الاصطناعي التي تمكنك من استخراج البيانات من الويب بفعالية، مع دعم للتوازي والتنافس how to use firecrawl firecrawl alternative firecrawl vs WebFetch firecrawl install firecrawl setup guide what is firecrawl firecrawl CLI web scraping with firecrawl Firecrawl AI工具 Web抓取 CLI OCI Self-Service Portal AI-powered chat parallelization concurrency limits xargs -P Utilizes a decision framework for scale assessment Supports parallelization using `&` and `wait` for 6-50 pages Employs `xargs -P` for concurrent processing of 50+ pages Allows manual commands for one-time tasks Enables simple serial execution with the `-o` flag for 1-5 pages firecrawl is a web scraping expert tool that utilizes a CLI for efficient web content tasks, prioritized over WebFetch/WebSearch.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('refly-ai/refly-skills/exa', 'community', 'refly-ai', 'refly-skills', 'refly-ai/refly-skills', 'exa', 0, 0, 65, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:09.903Z', 'dcf47b7cd8f817a99470bc08f29bbe2c12097431f9ef50783aaebccb02276b1a', '{"id":"refly-ai/refly-skills/exa","name":"exa","description":{"en":"The exa skill performs semantic search using Exa AI, enabling developers to find content by meaning, discover similar documents, and perform neural web searches. It benefits developers needing to explore topics using semantic search.","zh":"Exa AI技能提供了基于语义搜索的内容发现功能，帮助开发者找到相关内容、类似文档和神经网络搜索结果。","ja":"Exa AIエージェントは、意味による検索を使用してコンテンツを発見する機能を提供し、開発者が関連コンテンツ、類似ドキュメント、ニューラルネットワーク検索結果を見つけるのを支援します。","ko":"Exa AI 에이전트는 의미 검색을 사용하여 콘텐츠를 발견하는 기능을 제공하여 개발자가 관련 콘텐츠, 유사 문서 및 신경망 검색 결과를 찾을 수 있도록 도와줍니다.","es":"Exa es una habilidad que permite realizar búsquedas semánticas y descubrir documentos similares utilizando técnicas de inteligencia artificial","fr":"Exa est une compétence qui permet d''effectuer des recherches sémantiques et de découvrir des documents similaires en utilisant des techniques d''intelligence artificielle","de":"Exa ist eine Fähigkeit, die semantische Suchen und das Auffinden ähnlicher Dokumente mithilfe von KI-Techniken ermöglicht","pt":"O Exa é uma ferramenta de IA que realiza buscas semânticas avançadas, permitindo encontrar conteúdo por significado e não por palavras-chave.","ru":"Exa - это инструмент ИИ, выполняющий семантические поиски, позволяющий найти контент по смыслу, а не по ключевым словам.","ar":"Exa هو أداة الإي إيه التي تقوم بالبحث الدلالي المتقدم، مما يسمح بالعثور على المحتوى من خلال المعنى وليس الكلمات الرئيسية."},"seo":{"title":{"en":"exa: Semantic Search Setup Guide | AI Agent Skill","zh":"Exa AI技能设置指南 - 基于语义搜索的内容发现","ja":"Exa AIエージェントの設定方法 - 意味による検索でコンテンツを発見","ko":"Exa AI 에이전트 설정 가이드 - 의미 검색을 통한 콘텐츠 발견","es":"Guía de configuración de Exa para búsqueda semántica","fr":"Guide de mise en place d''Exa pour la recherche sémantique","de":"Exa Einrichtungsleitfaden für semantische Suche","pt":"Guia de Configuração do Exa: Busca Semântica Avançada com...","ru":"Настройка Exa: Руководство по семантическому поиску с пом...","ar":"إعداد Exa: دليل البحث الدلالي المتقدم باستخدام أدوات الإي..."},"description":{"en":"Unlock the power of semantic search with exa. Discover how to find content by meaning, not keywords, and perform neural web searches with this AI agent skill.","zh":"了解Exa AI技能，实现语义搜索、类似文档发现和神经网络搜索。查看设置指南和技术细节。","ja":"Exa AIエージェントについて学び、意味による検索、類似ドキュメントの発見、ニューラルネットワーク検索を実現します。設定方法と技術的な詳細を確認してください。","ko":"Exa AI 에이전트에 대해 알아보고 의미 검색, 유사 문서 발견 및 신경망 검색을 구현하세요. 설정 가이드 및 기술 세부 사항을 확인하세요.","es":"Aprende a utilizar Exa para realizar búsquedas semánticas y descubrir documentos similares con nuestra guía paso a paso","fr":"Découvrez comment utiliser Exa pour effectuer des recherches sémantiques et trouver des documents similaires avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Exa für semantische Suchen und das Auffinden ähnlicher Dokumente verwenden können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o Exa para realizar buscas semânticas avançadas e descubra documentos semelhantes com essa ferramenta de IA","ru":"Узнайте, как настроить Exa для выполнения семантических поисков и открытия подобных документов с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Exa لأداء عمليات بحث دلالي متقدم واكتشاف مستندات مشابهة باستخدام أدوات الإي إيه"},"definition":{"en":"exa is a semantic search skill using Exa AI to find content by meaning, not keywords, and perform neural web searches.","zh":"Exa AI技能是一种基于语义搜索的AI工具，用于发现相关内容和类似文档。","ja":"Exa AIエージェントは、意味による検索を使用して関連コンテンツと類似ドキュメントを発見するAIエージェントです。","ko":"Exa AI 에이전트는 의미 검색을 사용하여 관련 콘텐츠와 유사 문서를 발견하는 AI 에이전트입니다.","es":"Exa es una herramienta de búsqueda semántica que utiliza inteligencia artificial para encontrar contenido por significado y no por palabras clave","fr":"Exa est un outil de recherche sémantique qui utilise l''intelligence artificielle pour trouver du contenu par signification et non par mots clés","de":"Exa ist ein Tool für semantische Suche, das KI verwendet, um Inhalte nach Bedeutung und nicht nach Schlüsselwörtern zu finden","pt":"O que é Exa? É uma ferramenta de IA que executa buscas semânticas para encontrar conteúdo relevante.","ru":"Что такое Exa? Это инструмент ИИ, который выполняет семантические поиски для нахождения релевантного контента.","ar":"ما هو Exa؟ إنه أداة الإي إيه التي تقوم بالبحث الدلالي للعثور على المحتوى ذي الصلة."},"features":{"en":["Performs semantic search using Exa AI","Finds content by meaning, not keywords","Discovers similar documents","Performs neural web searches","Accepts input as JSON with search query and num results","Executes using refly skill command"],"zh":["基于语义搜索的内容发现","类似文档发现","神经网络搜索","JSON输入支持","多结果检索"],"ja":["意味による検索を使用したコンテンツの発見","類似ドキュメントの発見","ニューラルネットワーク検索","JSON入力のサポート","複数結果の取得"],"ko":["의미 검색을 통한 콘텐츠 발견","유사 문서 발견","신경망 검색","JSON 입력 지원","다중 결과 조회"],"es":["Búsqueda semántica utilizando inteligencia artificial","Descubrimiento de documentos similares","Búsqueda neurológica en la web","Compatibilidad con formato JSON para entrada y salida","Ejecución mediante línea de comandos con CLI"],"fr":["Recherche sémantique utilisant l''intelligence artificielle","Découverte de documents similaires","Recherche neurale sur le web","Compatibilité avec le format JSON pour l''entrée et la sortie","Exécution via la ligne de commande avec CLI"],"de":["Semantische Suche mit KI","Auffinden ähnlicher Dokumente","Neuronale Suche im Web","Kompatibilität mit JSON-Format für Ein- und Ausgabe","Ausführung über die Kommandozeile mit CLI"],"pt":["Realiza buscas semânticas avançadas","Encontra conteúdo por significado e não por palavras-chave","Descobre documentos semelhantes","Executa buscas neurais na web","Recebe resultados em formato JSON"],"ru":["Выполняет семантические поиски","Находит контент по смыслу, а не по ключевым словам","Открывает подобные документы","Выполняет нейронные поиски в сети","Получает результаты в формате JSON"],"ar":["يقوم بالبحث الدلالي المتقدم","يجد المحتوى من خلال المعنى وليس الكلمات الرئيسية","يكتشف المستندات المشابهة","يقوم بالبحث العصبي على الويب","يستلم النتائج بتنسيق JSON"]},"keywords":{"en":["how to use exa","what is exa","exa alternative","exa vs semantic search tools","exa install","exa setup guide","exa AI agent","semantic search with exa","neural web search with exa"],"zh":["Exa AI技能","语义搜索","类似文档发现","神经网络搜索","AI工具","内容发现","JSON输入","开发者工具"],"ja":["Exa AIエージェント","意味による検索","類似ドキュメントの発見","ニューラルネットワーク検索","AIエージェント","コンテンツの発見","JSON入力","開発者ツール"],"ko":["Exa AI 에이전트","의미 검색","유사 문서 발견","신경망 검색","AI 에이전트","콘텐츠 발견","JSON 입력","개발자 도구"],"es":["exa","búsqueda semántica","inteligencia artificial","descubrimiento de documentos","búsqueda neurológica","JSON","CLI","herramientas de AI","agentes de AI"],"fr":["exa","recherche sémantique","intelligence artificielle","découverte de documents","recherche neurale","JSON","CLI","outils d''IA","agents d''IA"],"de":["exa","semantische Suche","Künstliche Intelligenz","Auffinden von Dokumenten","neuronale Suche","JSON","CLI","KI-Tools","KI-Agents"],"pt":["Exa","busca semântica","ferramentas de IA","busca avançada","documentos semelhantes","JSON","desenvolvedores","programação"],"ru":["Exa","семантический поиск","ИИ Агенты","расширенный поиск","podobные документы","JSON","разработчики","программирование"],"ar":["Exa","البحث الدلالي","أدوات الإي إيه","البحث المتقدم","مستندات مشابهة","JSON","مطوّرون","برمجة"]}},"owner":"refly-ai","repo":"refly-skills","repoPath":"refly-ai/refly-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"exa","description":"Perform semantic search using Exa AI. Use when you need to: (1) find content by meaning not keywords, (2) discover similar documents, or (3) perform neural web searches.","version":"1.0.0","bodyPreview":"# Exa\n\nPerform semantic search using Exa AI. Use when you need to: (1) find content by meaning not keywords, (2) discover similar documents, or (3) perform neural web searches.\n\n## Input\n\nProvide input as JSON:\n\n```json\n{\n  \"search_query\": \"The search query or topic you want to explore using semantic search\",\n  \"num_results\": \"Number of search results to retrieve (e.g., 5, 10, 20)\"\n}\n```\n\n## Execution (Pattern B: Text/Data)\n\n### Step 1: Run the Skill and Get Run ID\n\n```bash\nRESULT=$(refly skill","body":"# Exa\n\nPerform semantic search using Exa AI. Use when you need to: (1) find content by meaning not keywords, (2) discover similar documents, or (3) perform neural web searches.\n\n## Input\n\nProvide input as JSON:\n\n```json\n{\n  \"search_query\": \"The search query or topic you want to explore using semantic search\",\n  \"num_results\": \"Number of search results to retrieve (e.g., 5, 10, 20)\"\n}\n```\n\n## Execution (Pattern B: Text/Data)\n\n### Step 1: Run the Skill and Get Run ID\n\n```bash\nRESULT=$(refly skill run --id skpi-j39cg6h58kgt89qy41chi1ay --input ''{\n  \"query\": \"latest developments in artificial intelligence\",\n  \"num_results\": \"10\"\n}'')\nRUN_ID=$(echo \"$RESULT\" | jq -r ''.payload.workflowExecutions[0].id'')\n# RUN_ID is we-xxx format, use this for workflow commands\n```\n\n### Step 2: Open Workflow in Browser and Wait for Completion\n\n```bash\nopen \"https://refly.ai/workflow/c-eptydufr83h9gket8xdjbnan\"\nrefly workflow status \"$RUN_ID\" --watch --interval 30000\n```\n\n### Step 3: Extract Text Content\n\n```bash\n# Get text content from toolcalls\nCONTENT=$(refly workflow toolcalls \"$RUN_ID\" --files --latest | jq -r ''.payload.nodes[].content'')\necho \"$CONTENT\"\n```\n\n## Expected Output\n\n- **Type**: Text content\n- **Format**: Semantic search results\n- **Action**: Display content to user\n\n## Rules\n\nFollow base skill workflow: `~/.claude/skills/refly/SKILL.md`\n"},"lastSynced":"2026-03-08T02:00:09.903Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced semantic search capabilities using Exa AI.","zh":"适合需要使用Exa AI进行高级语义搜索的AI代理。","ja":"Exa AIを使用した高度なセマンティック検索機能を必要とするAIエージェントに適しています。","ko":"Exa AI를 사용하여 고급 의미 검색 기능이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan capacidades de búsqueda semántica avanzadas utilizando Exa AI.","fr":"Parfait pour les agents IA nécessitant des capacités de recherche sémantique avancées utilisant Exa AI.","de":"Perfekt für KI-Agenten, die erweiterte semantische Suchfunktionen mit Exa AI benötigen.","pt":"Perfeito para Agentes de IA que necessitam de capacidades de busca semântica avançadas usando Exa AI.","ru":"Идеально для агентов ИИ, которым необходимы продвинутые возможности семантического поиска с помощью Exa AI.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى قدرات بحث دلالية متقدمة باستخدام Exa AI."},"recommendation":{"en":"Empowers agents to perform neural web searches, discover similar documents, and find content by meaning using semantic search, leveraging JSON input for search queries and result customization.","zh":"赋予代理执行神经网络搜索、发现类似文档和通过语义搜索按意义查找内容的能力，利用JSON输入进行搜索查询和结果自定义。","ja":"エージェントに、ニューラルネットワーク検索の実行、類似ドキュメントの発見、セマンティック検索による意味によるコンテンツの検索を行う能力を与え、JSON入力を使用して検索クエリと結果のカスタマイズを行います。","ko":"에이전트가 신경망 검색을 수행하고, 의미에 따라 유사한 문서를 발견하며, 의미 검색을 통해 의미에 따라 콘텐츠를 찾을 수 있는 기능을 제공하고, JSON 입력을 사용하여 검색 쿼리와 결과를 사용자 지정합니다.","es":"Habilita a los agentes a realizar búsquedas web neuronales, descubrir documentos similares y encontrar contenido por significado utilizando la búsqueda semántica, aprovechando la entrada JSON para consultas de búsqueda y personalización de resultados.","fr":"Permet aux agents d''effectuer des recherches web neuronales, de découvrir des documents similaires et de trouver du contenu par signification en utilisant la recherche sémantique, en exploitant l''entrée JSON pour les requêtes de recherche et la personnalisation des résultats.","de":"Ermöglicht es Agenten, neuronale Websuchen durchzuführen, ähnliche Dokumente zu entdecken und Inhalte anhand ihrer Bedeutung zu finden, indem sie die semantische Suche nutzen und JSON-Eingaben für Suchanfragen und Ergebnispersonalisierung verwenden.","pt":"Habilita os agentes a realizar buscas na web neurais, descobrir documentos semelhantes e encontrar conteúdo por significado usando busca semântica, aproveitando a entrada JSON para consultas de busca e personalização de resultados.","ru":"Наделяет агентов возможностью выполнять нейронные веб-поиски, обнаруживать подобные документы и находить контент по смыслу с помощью семантического поиска, используя входные данные JSON для запросов поиска и настройки результатов.","ar":"يمنح الوكلاء القدرة على إجراء عمليات بحث شبكية عصبية، واكتشاف مستندات مشابهة، وإيجاد المحتوى بالمعني باستخدام البحث الدلالي، واستخدام المدخلات JSON لاستفسارات البحث وتخصيص النتائج."},"useCases":{"en":["Performing semantic searches for topic exploration","Discovering similar documents based on meaning","Executing neural web searches for specific information"],"zh":["进行语义搜索以探索主题","根据意义发现类似文档","执行神经网络搜索以获取特定信息"],"ja":["トピックの探索のためにセマンティック検索を行う","意味に基づいて類似ドキュメントを発見する","特定の情報を取得するためにニューラルネットワーク検索を実行する"],"ko":["주제를 탐색하기 위한 의미 검색 수행","의미에 따라 유사한 문서를 발견하는こと","특정 정보를 검색하기 위한 신경망 검색 실행"],"es":["Realizar búsquedas semánticas para la exploración de temas","Descubrir documentos similares en función de su significado","Ejecutar búsquedas web neuronales para obtener información específica"],"fr":["Effectuer des recherches sémantiques pour l''exploration de sujets","Découvrir des documents similaires en fonction de leur signification","Exécuter des recherches web neuronales pour obtenir des informations spécifiques"],"de":["Durchführen semantischer Suchen zur Themenexploration","Entdecken ähnlicher Dokumente basierend auf ihrer Bedeutung","Ausführen neuronaler Websuchen für spezifische Informationen"],"pt":["Realizar buscas semânticas para exploração de tópicos","Descobrir documentos semelhantes com base no significado","Executar buscas na web neurais para informações específicas"],"ru":["Выполнение семантических поисков для исследования тем","Обнаружение подобных документов на основе смысла","Выполнение нейронных веб-поисков для конкретной информации"],"ar":["إجراء عمليات بحث دلالية لاستكشاف المواضيع","اكتشاف مستندات مشابهة بالاعتماد على المعني","تنفيذ عمليات بحث شبكية عصبية لمعلومات محددة"]},"limitations":{"en":["Requires Exa AI integration","Input must be in JSON format","Dependent on quality of search query for accurate results"],"zh":["需要Exa AI集成","输入必须为JSON格式","依赖于搜索查询质量以获取准确的结果"],"ja":["Exa AIの統合が必要","入力はJSON形式でなければならない","検索クエリの品質に依存して正確な結果を取得する"],"ko":["Exa AI 통합이 필요합니다.","입력이 JSON 형식이어야 합니다.","정확한 결과를 얻기 위해 검색 쿼리의 품질에 의존합니다."],"es":["Requiere integración con Exa AI","La entrada debe estar en formato JSON","Depende de la calidad de la consulta de búsqueda para obtener resultados precisos"],"fr":["Nécessite une intégration avec Exa AI","L''entrée doit être au format JSON","Dépend de la qualité de la requête de recherche pour obtenir des résultats précis"],"de":["Benötigt Exa AI-Integration","Eingabe muss im JSON-Format sein","Hängt von der Qualität der Suchanfrage für genaue Ergebnisse ab"],"pt":["Requer integração com Exa AI","A entrada deve estar no formato JSON","Dependente da qualidade da consulta de busca para resultados precisos"],"ru":["Требует интеграции с Exa AI","Входные данные должны быть в формате JSON","Зависит от качества запроса поиска для точных результатов"],"ar":["يتطلب تكاملًا مع Exa AI","يجب أن تكون المدخلات بصيغة JSON","يعتمد على جودة استفسار البحث للحصول على نتائج دقيقة"]},"version":4},"contentHash":"dcf47b7cd8f817a99470bc08f29bbe2c12097431f9ef50783aaebccb02276b1a","qualityScore":65}');
