INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('refly-ai/refly-skills/exa', 'exa', 'refly-ai', 'refly-skills', 'community', 'exa refly-ai refly-skills community The exa skill performs semantic search using Exa AI, enabling developers to find content by meaning, discover similar documents, and perform neural web searches. It benefits developers needing to explore topics using semantic search. Exa AI技能提供了基于语义搜索的内容发现功能，帮助开发者找到相关内容、类似文档和神经网络搜索结果。 Exa AIエージェントは、意味による検索を使用してコンテンツを発見する機能を提供し、開発者が関連コンテンツ、類似ドキュメント、ニューラルネットワーク検索結果を見つけるのを支援します。 Exa AI 에이전트는 의미 검색을 사용하여 콘텐츠를 발견하는 기능을 제공하여 개발자가 관련 콘텐츠, 유사 문서 및 신경망 검색 결과를 찾을 수 있도록 도와줍니다. Exa es una habilidad que permite realizar búsquedas semánticas y descubrir documentos similares utilizando técnicas de inteligencia artificial Exa est une compétence qui permet d''effectuer des recherches sémantiques et de découvrir des documents similaires en utilisant des techniques d''intelligence artificielle Exa ist eine Fähigkeit, die semantische Suchen und das Auffinden ähnlicher Dokumente mithilfe von KI-Techniken ermöglicht O Exa é uma ferramenta de IA que realiza buscas semânticas avançadas, permitindo encontrar conteúdo por significado e não por palavras-chave. Exa - это инструмент ИИ, выполняющий семантические поиски, позволяющий найти контент по смыслу, а не по ключевым словам. Exa هو أداة الإي إيه التي تقوم بالبحث الدلالي المتقدم، مما يسمح بالعثور على المحتوى من خلال المعنى وليس الكلمات الرئيسية. how to use exa what is exa exa alternative exa vs semantic search tools exa install exa setup guide exa AI agent semantic search with exa neural web search with exa Exa AI技能 语义搜索 类似文档发现 神经网络搜索 AI工具 内容发现 JSON输入 开发者工具 Performs semantic search using Exa AI Finds content by meaning, not keywords Discovers similar documents Performs neural web searches Accepts input as JSON with search query and num results Executes using refly skill command exa is a semantic search skill using Exa AI to find content by meaning, not keywords, and perform neural web searches.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('IceWhaleTech/ToolFS/toolfs', 'community', 'IceWhaleTech', 'ToolFS', 'IceWhaleTech/ToolFS', 'toolfs', 0, 0, 65, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:24.492Z', '3c72a49f5ebcf59374531ca6f5691f7867fe048a9872d8ae8d65796800ab8ab3', '{"id":"IceWhaleTech/ToolFS/toolfs","name":"toolfs","description":{"en":"ToolFS provides a unified virtual filesystem framework for LLM agents, accessing files, memory, RAG systems, skills, and snapshots. It benefits AI agent developers by integrating multiple data sources and operations.","zh":"ToolFS是一个统一的虚拟文件系统框架，为LLM代理提供访问文件、内存、RAG系统、技能和快照的方式","ja":"ToolFSは、ファイル、メモリ、RAGシステム、スキル、スナップショットへのアクセスを提供する、LLMエージェントのための統一された仮想ファイルシステムフレームワークです","ko":"ToolFS는 파일, 메모리, RAG 시스템, 스킬 및 스냅샷에 대한 액세스를 제공하는 LLM 에이전트를 위한 통합 가상 파일 시스템 프레임워크입니다","es":"ToolFS es un sistema de archivos virtuales unificado para Agentes de IA que proporciona acceso a archivos, memoria y sistemas RAG a través de un namespace único","fr":"ToolFS est un système de fichiers virtuels unifié pour les Agents d''IA qui fournit un accès aux fichiers, à la mémoire et aux systèmes RAG via un namespace unique","de":"ToolFS ist ein einheitliches virtuelles Dateisystem für KI-Agenten, das Zugriff auf Dateien, Speicher und RAG-Systeme über einen einzigen Namespace bietet","pt":"O ToolFS é um sistema de arquivos virtuais unificado para agentes de IA, que fornece acesso a arquivos, memória, RAG e habilidades através de um namespace único","ru":"ToolFS - это унифицированная виртуальная файловая система для ИИ Агентов, обеспечивающая доступ к файлам, памяти, RAG и навыкам через единое пространство имен","ar":"ToolFS هو نظام ملفات افتراضي موحد للوكلاء الذكاء الاصطناعي، يوفر الوصول إلى الملفات والذاكرة والبحث الدلالي والمهارات من خلال مساحة اسم واحدة"},"seo":{"title":{"en":"ToolFS: Unified Virtual Filesystem Setup Guide | AI Agent...","zh":"ToolFS_SETUP_GUIDE","ja":"ToolFS_BEST_PRACTICES_FOR_AIエージェント","ko":"ToolFS_SETUP_FOR_AI_TOOLS","es":"Guía de configuración de ToolFS para Agentes de IA","fr":"Guide de mise en place de ToolFS pour les Agents d''IA","de":"ToolFS Einrichtungsleitfaden für KI-Agenten","pt":"Guia de Configuração do ToolFS: Integração de Memória e RAG","ru":"Руководство по настройке ToolFS: объединение памяти и ИИ ...","ar":"دليل إعداد ToolFS: دمج الذاكرة والوكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how ToolFS integrates memory, RAG, and local data access. Learn to set up and utilize this scalable plugin system for AI agents today!","zh":"ToolFS虚拟文件系统框架为LLM代理提供访问文件、内存、RAG系统、技能和快照的统一方式","ja":"ToolFSはAIエージェントのための統一された仮想ファイルシステムフレームワークで、ファイル、メモリ、RAGシステム、スキル、スナップショットへのアクセスを提供します","ko":"ToolFS는 LLM 에이전트를 위한 통합 가상 파일 시스템 프레임워크로 파일, 메모리, RAG 시스템, 스킬 및 스냅샷에 대한 액세스를 제공합니다","es":"Descubre cómo ToolFS integra memoria, RAG y acceso a datos locales para Agentes de IA con una arquitectura de plugins escalable","fr":"Découvrez comment ToolFS intègre la mémoire, RAG et l''accès aux données locales pour les Agents d''IA avec une architecture de plugins évolutives","de":"Erfahren Sie, wie ToolFS Speicher, RAG und lokalen Datenzugriff für KI-Agenten mit einer skalierbaren Plugin-Architektur integriert","pt":"Aprenda a configurar o ToolFS, um sistema de arquivos virtuais para agentes de IA, e descubra como integrar memória, RAG e acesso a dados locais","ru":"Узнайте, как настроить ToolFS, виртуальную файловую систему для ИИ Агентов, и объединить память, RAG и доступ к локальным данным","ar":"تعرف على كيفية إعداد ToolFS، نظام ملفات افتراضي للوكلاء الذكاء الاصطناعي، وتعلم دمج الذاكرة والبحث الدلالي والوصول إلى البيانات المحلية"},"definition":{"en":"ToolFS is a FUSE virtual filesystem for AI agents, integrating memory, RAG, and local data access with flexible tool chaining and a scalable plugin system","zh":"ToolFS是一种虚拟文件系统框架，提供访问文件、内存、RAG系统、技能和快照的统一方式","ja":"ToolFSは、ファイル、メモリ、RAGシステム、スキル、スナップショットへのアクセスを提供する仮想ファイルシステムフレームワークです","ko":"ToolFS는 파일, 메모리, RAG 시스템, 스킬 및 스냅샷에 대한 액세스를 제공하는 가상 파일 시스템 프레임워크입니다","es":"ToolFS es un sistema de archivos virtuales que integra memoria, RAG y acceso a datos locales para Agentes de IA","fr":"ToolFS est un système de fichiers virtuels qui intègre la mémoire, RAG et l''accès aux données locales pour les Agents d''IA","de":"ToolFS ist ein virtuelles Dateisystem, das Speicher, RAG und lokalen Datenzugriff für KI-Agenten integriert","pt":"O ToolFS é um sistema de arquivos virtuais que integra memória, RAG e acesso a dados locais para agentes de IA","ru":"ToolFS - это виртуальная файловая система, объединяющая память, RAG и доступ к локальным данным для ИИ Агентов","ar":"ToolFS هو نظام ملفات افتراضي يدمج الذاكرة والبحث الدلالي والوصول إلى البيانات المحلية للوكلاء الذكاء الاصطناعي"},"features":{"en":["Integrates persistent key-value storage for session data and context via memory","Provides semantic search over vector databases for document retrieval via RAG","Offers access to mounted local directories through a unified virtual filesystem","Supports skills and snapshots through a single /toolfs namespace","Features a scalable plugin system for flexible MCP/tool chaining"],"zh":["提供访问文件、内存、RAG系统、技能和快照的统一方式","支持FUSE虚拟文件系统","提供灵活的MCP/工具链","支持可扩展的插件系统"],"ja":["ファイル、メモリ、RAGシステム、スキル、スナップショットへのアクセスを提供する","FUSE仮想ファイルシステムをサポート","柔軟なMCP/ツールチェーンを提供","スケーラブルなプラグインシステムをサポート"],"ko":["파일, 메모리, RAG 시스템, 스킬 및 스냅샷에 대한 액세스를 제공하는","FUSE 가상 파일 시스템을 지원","유연한 MCP/도구 체인을 제공","확장 가능한 플러그인 시스템을 지원"],"es":["Integración de memoria y RAG para Agentes de IA","Acceso a datos locales a través de un namespace único","Arquitectura de plugins escalable para extensiones personalizadas","Soporte para sistemas de archivos montados localmente","Acceso a habilidades y instantáneas a través del namespace /toolfs"],"fr":["Intégration de la mémoire et RAG pour les Agents d''IA","Accès aux données locales via un namespace unique","Architecture de plugins évolutives pour extensions personnalisées","Support pour les systèmes de fichiers montés localement","Accès aux compétences et aux instantanés via le namespace /toolfs"],"de":["Integration von Speicher und RAG für KI-Agenten","Zugriff auf lokale Daten über einen einzigen Namespace","Skalierbare Plugin-Architektur für benutzerdefinierte Erweiterungen","Unterstützung für lokal montierte Dateisysteme","Zugriff auf Fähigkeiten und Snapshots über den Namespace /toolfs"],"pt":["Integração de memória para armazenamento de dados de sessão e contexto","Acesso a RAG para busca semântica em bancos de dados vetoriais","Acesso a arquivos em diretórios locais montados","Suporte a habilidades e snapshots","Sistema de plugins escalável"],"ru":["Объединение памяти для хранения данных сессии и контекста","Доступ к RAG для семантического поиска в векторных базах данных","Доступ к файлам в смонтированных локальных директориях","Поддержка навыков и снимков","Масштабируемая система плагинов"],"ar":["دمج الذاكرة لتخزين بيانات الجلسة والسياق","الوصول إلى البحث الدلالي في قواعد البيانات المتجهة","الوصول إلى الملفات في الدلائل المحلية المثبتة","دعم المهارات والصور","نظام الإضافات القابل للتوسيع"]},"keywords":{"en":["how to use toolfs","what is toolfs","toolfs alternative","toolfs vs fuse","toolfs install","toolfs setup guide","toolfs for ai agents","toolfs plugin system","toolfs virtual filesystem"],"zh":["ToolFS","LLM代理","虚拟文件系统","FUSE","MCP","RAG系统","技能","快照","AI工具"],"ja":["ToolFS","AIエージェント","仮想ファイルシステム","FUSE","MCP","RAGシステム","スキル","スナップショット","AIツール"],"ko":["ToolFS","LLM 에이전트","가상 파일 시스템","FUSE","MCP","RAG 시스템","스킬","스냅샷","AI 도구"],"es":["Agentes de IA","sistemas de archivos virtuales","RAG","acceso a datos locales","arquitectura de plugins","inteligencia artificial","desarrollo de software","integración de sistemas"],"fr":["Agents d''IA","systèmes de fichiers virtuels","RAG","accès aux données locales","architecture de plugins","intelligence artificielle","développement de logiciels","intégration de systèmes"],"de":["KI-Agenten","virtuelle Dateisysteme","RAG","Zugriff auf lokale Daten","Plugin-Architektur","künstliche Intelligenz","Software-Entwicklung","Systemintegration"],"pt":["ToolFS","agentes de IA","sistema de arquivos virtuais","integração de memória","RAG","acesso a dados locais","habilidades","snapshots","plugins"],"ru":["ToolFS","ИИ Агенты","виртуальная файловая система","объединение памяти","RAG","доступ к локальным данным","навыки","снимки","плагины"],"ar":["ToolFS","الوكلاء الذكاء الاصطناعي","نظام ملفات افتراضي","دمج الذاكرة","البحث الدلالي","الوصول إلى البيانات المحلية","المهارات","الصور","الإضافات"]}},"owner":"IceWhaleTech","repo":"ToolFS","repoPath":"IceWhaleTech/ToolFS","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.272Z","topics":[],"category":"community","skillMd":{"name":"toolfs","description":"Unified virtual filesystem framework for LLM agents. Provides access to files, memory, RAG, skills, and snapshots through a single interface. Use this skill when the user requests file operations, memory storage, semantic search, skill execution, or state management tasks.","version":"1.0.0","bodyPreview":"# ToolFS\n\nToolFS is a unified virtual filesystem framework for LLM agents that provides access to files, memory, RAG systems, skills, and snapshots through a single `/toolfs` namespace.\n\n## Overview\n\nToolFS integrates multiple data sources and operations into one virtual filesystem:\n\n- **Memory**: Persistent key-value storage for session data and context\n- **RAG**: Semantic search over vector databases for document retrieval  \n- **Filesystem**: Access to mounted local directories\n- **Skills**: E","body":"# ToolFS\n\nToolFS is a unified virtual filesystem framework for LLM agents that provides access to files, memory, RAG systems, skills, and snapshots through a single `/toolfs` namespace.\n\n## Overview\n\nToolFS integrates multiple data sources and operations into one virtual filesystem:\n\n- **Memory**: Persistent key-value storage for session data and context\n- **RAG**: Semantic search over vector databases for document retrieval  \n- **Filesystem**: Access to mounted local directories\n- **Skills**: Execute WASM-based skills mounted to virtual paths\n- **Snapshots**: Create point-in-time snapshots and restore previous states\n\nAll operations respect session isolation, permission control, and audit logging for safe execution in sandboxed environments.\n\n## Available Skills\n\nToolFS is organized into functional modules. Each module provides specific capabilities:\n\n| Module | Path | Description | Documentation |\n|--------|------|-------------|---------------|\n| **Memory** | `/toolfs/memory` | Persistent storage for session data and context | [Memory Skill](memory/SKILL.md) |\n| **RAG** | `/toolfs/rag` | Semantic search over vector databases | [RAG Skill](rag/SKILL.md) |\n| **Filesystem** | `/toolfs/<mount>` | Access to mounted local directories | [Filesystem Skill](filesystem/SKILL.md) |\n| **Code** | `/toolfs/<skill>` | Execute WASM or native skills | [Code Skill](code/SKILL.md) |\n| **Snapshots** | `/toolfs/snapshots` | Filesystem state snapshots and rollback | [Snapshot Skill](snapshot/SKILL.md) |\n\n## Quick Start\n\n### Memory Operations\n```bash\n# Read memory entry\nGET /toolfs/memory/<entry_id>\n\n# Write memory entry  \nPUT /toolfs/memory/<entry_id>\n\n# List memory entries\nLIST /toolfs/memory\n```\n\nSee [Memory Skill](memory/SKILL.md) for details.\n\n### RAG Search\n```bash\n# Semantic search\nGET /toolfs/rag/query?text=<query>&top_k=<number>\n```\n\nSee [RAG Skill](rag/SKILL.md) for details.\n\n### Filesystem Access\n```bash\n# Read file\nGET /toolfs/<mount_point>/<relative_path>\n\n# Write file\nPUT /toolfs/<mount_point>/<relative_path>\n\n# List directory\nLIST /toolfs/<mount_point>/<relative_path>\n```\n\nSee [Filesystem Skill](filesystem/SKILL.md) for details.\n\n### Skill Execution\n```bash\n# Execute skill\nGET /toolfs/<skill_mount_path>?text=<query>\n```\n\nSee [Skill Skill](skill/SKILL.md) for details.\n\n### Snapshot Management\n```bash\n# Create snapshot\nPOST /toolfs/snapshots/create\n\n# Rollback snapshot\nPOST /toolfs/snapshots/rollback\n\n# List snapshots\nGET /toolfs/snapshots\n```\n\nSee [Snapshot Skill](snapshot/SKILL.md) for details.\n\n## Skill API (Chained Operations)\n\nChain multiple operations in a single request:\n\n```json\nPOST /toolfs/skills/chain\nContent-Type: application/json\n\n{\n  \"operations\": [\n    {\n      \"type\": \"search_memory\",\n      \"query\": \"user preferences\"\n    },\n    {\n      \"type\": \"search_rag\",\n      \"query\": \"ToolFS configuration\",\n      \"top_k\": 5\n    },\n    {\n      \"type\": \"read_file\",\n      \"path\": \"/toolfs/data/config/settings.json\"\n    }\n  ]\n}\n```\n\n## Common Use Cases\n\n- **File Operations**: \"Read the config file from the project directory\"\n- **Memory Persistence**: \"Store this conversation summary in memory\"\n- **Semantic Search**: \"Search documents for information about X\"\n- **Skill Execution**: \"Execute the RAG skill to find relevant content\"\n- **State Management**: \"Create a snapshot before making changes\"\n- **Recovery**: \"Restore the previous state\"\n\n## Output Format\n\nAll operations return standardized result structures:\n\n```json\n{\n  \"type\": \"memory|rag|file|skill|snapshot\",\n  \"source\": \"identifier (ID, path, command, skill_name)\",\n  \"content\": \"string content or data\",\n  \"metadata\": {},\n  \"success\": true|false,\n  \"error\": \"error message if failed\"\n}\n```\n\n## Error Handling\n\nErrors are returned with structured responses:\n\n```json\n{\n  \"success\": false,\n  \"error\": \"Detailed error message\",\n  \"type\": \"error_type\",\n  \"source\": \"operation_identifier\"\n}\n```\n\nCommon error types:\n- `access_denied`: Session does not have permission\n- `not_found`: Resource not found\n- `skill_error`: Skill execution failed\n- `validation_error`: Invalid input parameters\n- `filesystem_error`: Filesystem operation failed\n\n## Best Practices\n\n1. **Use Sessions**: Always create sessions with appropriate `allowed_paths` for security\n2. **Chain Operations**: Use `ChainOperations` to minimize round trips\n3. **Snapshot Before Changes**: Create snapshots before major filesystem modifications\n4. **Handle Errors**: Check `success` field in results and provide fallback strategies\n5. **Leverage Metadata**: Use metadata fields to pass context between operations\n\n## Module Documentation\n\nFor detailed information about each module, see:\n\n- [Memory Skill](memory/SKILL.md) - Persistent storage operations\n- [RAG Skill](rag/SKILL.md) - Semantic search operations\n- [Filesystem Skill](filesystem/SKILL.md) - File and directory operations\n- [Skill Skill](skill/SKILL.md) - Skill execution and management\n- [Snapshot Skill](snapshot/SKILL.md) - State management operations\n\n---\n\n*This documentation describes ToolFS version 1.0.0. Each module has its own detailed SKILL.md for specific operations.*\n"},"lastSynced":"2026-03-08T02:00:24.492Z","agentAnalysis":{"suitability":{"en":"Ideal for LLM Agents requiring unified access to files, memory, RAG systems, skills, and snapshots through a single virtual filesystem namespace","zh":"适用于需要通过单一虚拟文件系统命名空间访问文件、内存、RAG系统、技能和快照的LLM代理","ja":"LLMエージェントがファイル、メモリ、RAGシステム、スキル、スナップショットに統一されたアクセスを必要とする場合に適しています","ko":"파일, 메모리, RAG 시스템, 스킬 및 스냅샷에 대한統一된 액세스를 필요로하는 LLM 에이전트에 적합합니다","es":"Ideal para agentes LLM que requieren acceso unificado a archivos, memoria, sistemas RAG, habilidades y instantáneas a través de un único espacio de nombres de sistema de archivos virtual","fr":"Idéal pour les agents LLM nécessitant un accès unifié aux fichiers, à la mémoire, aux systèmes RAG, aux compétences et aux instantanés via un seul espace de noms de système de fichiers virtuel","de":"Ideal für LLM-Agents, die einen einheitlichen Zugriff auf Dateien, Speicher, RAG-Systeme, Fähigkeiten und Snapshots über einen einzigen virtuellen Dateisystem-Namensraum benötigen","pt":"Ideal para agentes LLM que requerem acesso unificado a arquivos, memória, sistemas RAG, habilidades e instantâneos por meio de um único namespace de sistema de arquivos virtual","ru":"Идеально для агентов LLM, требующих унифицированного доступа к файлам, памяти, системам RAG, навыкам и снимкам через единое виртуальное пространство имен файловой системы","ar":"مثالي لعميل LLM الذي يتطلب الوصول الموحد إلى الملفات والذاكرة وأنظمة RAG والمهارات وال لحظات من خلال مساحة اسم ملف افتراضي واحدة"},"recommendation":{"en":"Empowers agents to integrate multiple data sources and operations, providing access to persistent key-value storage, semantic search over vector databases, and mounted local directories through protocols like ToolFS, enhancing their capabilities with RAG systems and skills management","zh":"赋予代理集成多个数据源和操作的能力，提供对持久键值存储、向量数据库上的语义搜索以及通过ToolFS等协议挂载的本地目录的访问，同时增强其使用RAG系统和技能管理的能力","ja":"エージェントに複数のデータソースと操作を統合する能力を与え、ToolFSなどのプロトコルを介した永続的なキー値ストレージ、ベクトルデータベース上のセマンティック検索、およびローカルディレクトリへのアクセスを提供し、RAGシステムおよびスキル管理機能を強化する","ko":"에이전트가 여러 데이터 소스와 작업을 통합할 수 있는 능력을 부여하고, ToolFS와 같은 프로토콜을 통해 지속적인 키-값 저장소, 벡터 데이터베이스上的 의미 검색 및 로컬 디렉토리에 대한 액세스를 제공하여 RAG 시스템 및 스킬 관리 기능을 강화합니다","es":"Permite a los agentes integrar múltiples fuentes de datos y operaciones, proporcionando acceso a un almacenamiento de clave-valor persistente, búsqueda semántica sobre bases de datos vectoriales y directorios locales montados a través de protocolos como ToolFS, mejorando sus capacidades con sistemas RAG y administración de habilidades","fr":"Permet aux agents d''intégrer plusieurs sources de données et opérations, fournissant un accès à un stockage de clés-valeurs persistant, une recherche sémantique sur des bases de données vectorielles et des répertoires locaux montés via des protocoles comme ToolFS, améliorant leurs capacités avec les systèmes RAG et la gestion des compétences","de":"Ermöglicht es Agents, mehrere Datenquellen und Operationen zu integrieren, indem sie Zugriff auf persistenten Schlüssel-Wert-Speicher, semantische Suche über Vektor-Datenbanken und lokale Verzeichnisse bieten, die über Protokolle wie ToolFS montiert werden, und ihre Fähigkeiten mit RAG-Systemen und Fähigkeitsmanagement erweitern","pt":"Habilita os agentes a integrar várias fontes de dados e operações, fornecendo acesso a armazenamento de chave-valor persistente, busca semântica sobre bancos de dados de vetores e diretórios locais montados por meio de protocolos como ToolFS, melhorando suas capacidades com sistemas RAG e gerenciamento de habilidades","ru":"Наделяет агентов возможностью интегрировать несколько источников данных и операций, обеспечивая доступ к постоянному хранилищу ключ-значение, семантическому поиску по базам данных векторов и монтированию локальных каталогов по протоколам seperti ToolFS, расширяя их возможности за счет систем RAG и управления навыками","ar":"تمكّن الوكيل من دمج مصادر بيانات وعمليات متعددة، ويوفر الوصول إلى تخزين قيمة المفتاح المستدام والبحث الدلالي عبر قواعد بيانات المتجهات والمجلدات المحلية المثبتة عبر بروتوكولات مثل ToolFS، وتحسين قابليته من خلال أنظمة RAG وإدارة المهارات"},"useCases":{"en":["Accessing session data and context through memory","Performing semantic search over vector databases for document retrieval","Mounting local directories for file access","Managing skills and snapshots through a unified interface"],"zh":["通过内存访问会话数据和上下文","在向量数据库上执行语义搜索以检索文档","通过ToolFS等协议挂载本地目录以访问文件","通过统一接口管理技能和快照"],"ja":["メモリを介してセッションデータとコンテキストにアクセスする","ベクトルデータベース上でセマンティック検索を実行してドキュメントを取得する","ToolFSなどのプロトコルを介してローカルディレクトリをマウントしてファイルにアクセスする","統一されたインターフェースを介してスキルとスナップショットを管理する"],"ko":["메모리를 통해 세션 데이터 및 컨텍스트에 액세스하기","벡터 데이터베이스에서 의미 검색을 수행하여 문서를 검색하기","ToolFS와 같은 프로토콜을 통해 로컬 디렉토리를 마운트하여 파일에 액세스하기","통합 인터페이스를 통해 스킬 및 스냅샷 관리하기"],"es":["Acceder a datos de sesión y contexto a través de la memoria","Realizar búsquedas semánticas sobre bases de datos vectoriales para la recuperación de documentos","Montar directorios locales para el acceso a archivos","Administrar habilidades y instantáneas a través de una interfaz unificada"],"fr":["Accéder aux données de session et au contexte via la mémoire","Effectuer des recherches sémantiques sur des bases de données vectorielles pour la récupération de documents","Monter des répertoires locaux pour l''accès aux fichiers","Gérer les compétences et les instantanés via une interface unifiée"],"de":["Auf Sitzungsdaten und Kontext über den Speicher zugreifen","Semantische Suche über Vektor-Datenbanken für die Dokumentenrückgewinnung durchführen","Lokale Verzeichnisse für den Dateizugriff einbinden","Fähigkeiten und Snapshots über eine einheitliche Schnittstelle verwalten"],"pt":["Acessando dados de sessão e contexto por meio da memória","Realizando busca semântica sobre bancos de dados de vetores para recuperação de documentos","Montando diretórios locais para acesso a arquivos","Gerenciando habilidades e instantâneos por meio de uma interface unificada"],"ru":["Доступ к данным сеанса и контексту через память","Выполнение семантического поиска по базам данных векторов для извлечения документов","Монтирование локальных каталогов для доступа к файлам","Управление навыками и снимками через унифицированный интерфейс"],"ar":["الوصول إلى بيانات الجلسة والسياق من خلال الذاكرة","إجراء بحث دلالي عبر قواعد بيانات المتجهات لاسترجاع الوثائق","تركيب المجلدات المحلية للوصول إلى الملفات","إدارة المهارات وال لحظات من خلال واجهة موحدة"]},"limitations":{"en":["Requires ToolFS namespace setup","Limited to LLM agents","Dependent on underlying filesystem and RAG system infrastructure"],"zh":["需要设置ToolFS命名空间","仅限LLM代理","依赖于底层文件系统和RAG系统基础设施"],"ja":["ToolFS名前空間の設定が必要","LLMエージェントのみ","基礎となるファイルシステムとRAGシステムのインフラストラクチャに依存する"],"ko":["ToolFS 이름공간 설정이 필요합니다","LLM 에이전트만 해당","하위 파일 시스템 및 RAG 시스템 인프라에 종속"],"es":["Requiere la configuración del espacio de nombres de ToolFS","Limitado a agentes LLM","Dependiente de la infraestructura subyacente del sistema de archivos y del sistema RAG"],"fr":["Nécessite la configuration de l''espace de noms ToolFS","Limité aux agents LLM","Dépendant de l''infrastructure sous-jacente du système de fichiers et du système RAG"],"de":["Benötigt die Einrichtung des ToolFS-Namensraums","Begrenzt auf LLM-Agents","Abhängig von der zugrunde liegenden Infrastruktur des Dateisystems und des RAG-Systems"],"pt":["Requer configuração do namespace ToolFS","Limitado a agentes LLM","Dependente da infraestrutura do sistema de arquivos subjacente e do sistema RAG"],"ru":["Требует настройки пространства имен ToolFS","Ограничен агентами LLM","Зависит от инфраструктуры базового файлового системы и системы RAG"],"ar":["يتطلب إعداد مساحة اسم ToolFS","محدود لوكيل LLM","يعتمد على بنية تحتية لنظام الملفات وتحت نظام RAG"]},"version":4},"contentHash":"3c72a49f5ebcf59374531ca6f5691f7867fe048a9872d8ae8d65796800ab8ab3","qualityScore":65}');
