INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('IceWhaleTech/ToolFS/toolfs', 'toolfs', 'IceWhaleTech', 'ToolFS', 'community', 'toolfs IceWhaleTech ToolFS community ToolFS provides a unified virtual filesystem framework for LLM agents, accessing files, memory, RAG systems, skills, and snapshots. It benefits AI agent developers by integrating multiple data sources and operations. ToolFS是一个统一的虚拟文件系统框架，为LLM代理提供访问文件、内存、RAG系统、技能和快照的方式 ToolFSは、ファイル、メモリ、RAGシステム、スキル、スナップショットへのアクセスを提供する、LLMエージェントのための統一された仮想ファイルシステムフレームワークです ToolFS는 파일, 메모리, RAG 시스템, 스킬 및 스냅샷에 대한 액세스를 제공하는 LLM 에이전트를 위한 통합 가상 파일 시스템 프레임워크입니다 ToolFS es un sistema de archivos virtuales unificado para Agentes de IA que proporciona acceso a archivos, memoria y sistemas RAG a través de un namespace único ToolFS est un système de fichiers virtuels unifié pour les Agents d''IA qui fournit un accès aux fichiers, à la mémoire et aux systèmes RAG via un namespace unique ToolFS ist ein einheitliches virtuelles Dateisystem für KI-Agenten, das Zugriff auf Dateien, Speicher und RAG-Systeme über einen einzigen Namespace bietet O ToolFS é um sistema de arquivos virtuais unificado para agentes de IA, que fornece acesso a arquivos, memória, RAG e habilidades através de um namespace único ToolFS - это унифицированная виртуальная файловая система для ИИ Агентов, обеспечивающая доступ к файлам, памяти, RAG и навыкам через единое пространство имен ToolFS هو نظام ملفات افتراضي موحد للوكلاء الذكاء الاصطناعي، يوفر الوصول إلى الملفات والذاكرة والبحث الدلالي والمهارات من خلال مساحة اسم واحدة how to use toolfs what is toolfs toolfs alternative toolfs vs fuse toolfs install toolfs setup guide toolfs for ai agents toolfs plugin system toolfs virtual filesystem ToolFS LLM代理 虚拟文件系统 FUSE MCP RAG系统 技能 快照 AI工具 Integrates persistent key-value storage for session data and context via memory Provides semantic search over vector databases for document retrieval via RAG Offers access to mounted local directories through a unified virtual filesystem Supports skills and snapshots through a single /toolfs namespace Features a scalable plugin system for flexible MCP/tool chaining ToolFS is a FUSE virtual filesystem for AI agents, integrating memory, RAG, and local data access with flexible tool chaining and a scalable plugin system');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('robertogogoni/claude-cross-machine-sync/tool-discovery', 'community', 'robertogogoni', 'claude-cross-machine-sync', 'robertogogoni/claude-cross-machine-sync', 'tool-discovery', 0, 0, 65, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:27.205Z', '07dee57b840dfd674cf88ee90186bbb136d3cbc9ab54ec65b76a6369578d88c2', '{"id":"robertogogoni/claude-cross-machine-sync/tool-discovery","name":"tool-discovery","description":{"en":"The tool-discovery skill enables AI agents to discover available tools, MCP servers, and plugins, and automatically searches for solutions when a tool doesn''t exist locally. This benefits developers working with AI agents, particularly when users inquire about capabilities or tools.","zh":"工具发现技能帮助您发现可用工具和MCP服务器，自动搜索解决方案","ja":"ツール発見スキルは、利用可能なツールとMCPサーバーを発見し、自動検索ソリューションを実行するのに役立ちます","ko":"도구 발견 기능은 사용 가능한 도구와 MCP 서버를 발견하고 자동 검색 솔루션을 실행하는 데 도움이 됩니다","es":"El skill tool-discovery permite a los Agentes de IA descubrir herramientas y plugins disponibles. Ayuda a los desarrolladores a encontrar soluciones para tareas específicas.","fr":"Le skill tool-discovery permet aux Agents IA de découvrir les outils et les plugins disponibles. Il aide les développeurs à trouver des solutions pour des tâches spécifiques.","de":"Der tool-discovery-Skill ermöglicht es KI-Agenten, verfügbare Tools und Plugins zu entdecken. Er hilft Entwicklern bei der Suche nach Lösungen für spezifische Aufgaben.","pt":"O tool-discovery é uma habilidade que permite a descoberta de ferramentas disponíveis, sincronização de código e memória.","ru":"Tool-discovery - это навык, который позволяет обнаруживать доступные инструменты, синхронизировать код и память.","ar":"tool-discovery هو مهارة يسمح باكتشاف أدوات متاحة وتنسيق الكود والذاكرة."},"seo":{"title":{"en":"tool-discovery: Cross-Machine Sync Setup Guide | AI Agent...","zh":"工具发现设置指南 - Claude Code 同步","ja":"ツール発見のベストプラクティス - Claude Code 同期","ko":"도구 발견 설정 가이드 - Claude Code 동기화","es":"Guía de Configuración de tool-discovery para Agentes de IA","fr":"Configurer tool-discovery pour les Agents IA : Guide Étap...","de":"tool-discovery Einrichtungsleitfaden für KI-Agenten","pt":"Guia de Configuração do tool-discovery: Descoberta de Fer...","ru":"Настройка tool-discovery: Руководство по обнаружению ИИ А...","ar":"دليل إعداد tool-discovery: اكتشاف أدوات الإيجنت الذكية"},"description":{"en":"Unlock seamless tool discovery across machines. Learn how to setup and utilize the tool-discovery skill for efficient AI agent development","zh":"了解工具发现技能，自动搜索解决方案，发现可用工具和MCP服务器","ja":"ツール発見スキルについて学び、自動検索ソリューションを実行して利用可能なツールとMCPサーバーを発見する","ko":"도구 발견 기능에 대해 알아보고 자동 검색 솔루션을 실행하여 사용 가능한 도구와 MCP 서버를 발견하십시오","es":"Descubre cómo configurar tool-discovery para mejorar la búsqueda de herramientas y plugins en tus Agentes de IA. Obtén más información sobre este skill.","fr":"Découvrez comment configurer tool-discovery pour améliorer la recherche d''outils et de plugins pour vos Agents IA. En savoir plus sur ce skill.","de":"Erfahren Sie, wie Sie tool-discovery einrichten, um die Suche nach Tools und Plugins für Ihre KI-Agenten zu verbessern. Weitere Informationen zu diesem Skill.","pt":"Descubra como configurar o tool-discovery para sincronizar código e encontrar soluções de ferramentas AI","ru":"Узнайте, как настроить tool-discovery для синхронизации кода и поиска решений ИИ Агентов","ar":"اكتشف كيفية إعداد tool-discovery لتنسيق الكود و البحث عن حلول أدوات الإيجنت الذكية"},"definition":{"en":"tool-discovery is a skill that facilitates the discovery of available tools, MCP servers, and plugins across machines, enabling efficient AI agent development and user support","zh":"工具发现是一种帮助用户发现可用工具和MCP服务器的AI技能","ja":"ツール発見は、利用可能なツールとMCPサーバーを発見するのに役立つAIスキルです","ko":"도구 발견은 사용 가능한 도구와 MCP 서버를 발견하는 데 도움이 되는 AI 기능입니다","es":"tool-discovery es un skill que permite a los Agentes de IA buscar y descubrir herramientas y plugins disponibles.","fr":"tool-discovery est un skill qui permet aux Agents IA de rechercher et de découvrir les outils et les plugins disponibles.","de":"tool-discovery ist ein Skill, der es KI-Agenten ermöglicht, verfügbare Tools und Plugins zu suchen und zu entdecken.","pt":"O que é tool-discovery? É uma habilidade de descoberta de ferramentas AI que sincroniza código e memória.","ru":"Что такое tool-discovery? Это навык обнаружения ИИ Агентов, который синхронизирует код и память.","ar":"ما هو tool-discovery؟ هو مهارة لاكتشاف أدوات الإيجنت الذكية التي تزامن الكود والذاكرة."},"features":{"en":["Enables cross-machine Claude Code sync for settings, memory, skills, and episodic memory","Automatically searches for solutions when a tool doesn''t exist locally","Supports discovery of MCP servers and plugins","Activates when users ask about available tools or capabilities","Facilitates user inquiries about tool availability and capabilities"],"zh":["自动搜索解决方案","发现可用工具和MCP服务器","支持Claude Code同步","跨机器搜索","支持技能和插件发现"],"ja":["自動検索ソリューション","利用可能なツールとMCPサーバーの発見","Claude Code同期のサポート","マシン間の検索","スキルとプラグインの発見のサポート"],"ko":["자동 검색 솔루션","사용 가능한 도구와 MCP 서버의 발견","Claude Code 동기화 지원","머신 간 검색","기능과 플러그인의 발견 지원"],"es":["Búsqueda automática de soluciones","Compatibilidad con MCP y plugins","Integración con la memoria episódica","Soporte para la búsqueda de herramientas y capacidades","Funcionalidad de sincronización de código"],"fr":["Recherche automatique de solutions","Compatibilité avec MCP et les plugins","Intégration avec la mémoire épisodique","Prise en charge de la recherche d''outils et de capacités","Fonctionnalité de synchronisation de code"],"de":["Automatische Lösungssuche","Kompatibilität mit MCP und Plugins","Integration mit der episodischen Speicher","Unterstützung für die Suche nach Tools und Fähigkeiten","Code-Synchronisierungsfunktion"],"pt":["Sincronização de código entre máquinas","Descoberta de ferramentas disponíveis","Suporte a MCP servers e plugins","Busca automática de soluções","Sincronização de memória e habilidades"],"ru":["Синхронизация кода между машинами","Обнаружение доступных инструментов","Поддержка MCP серверов и плагинов","Автоматический поиск решений","Синхронизация памяти и навыков"],"ar":["تنسيق الكود بين الآلات","اكتشاف أدوات متاحة","دعم خوادم وملحقات MCP","البحث التلقائي عن حلول","تنسيق الذاكرة والمهارات"]},"keywords":{"en":["how to use tool-discovery","what is tool-discovery","tool-discovery alternative","tool-discovery setup guide","tool-discovery install","cross-machine sync for AI agents","Claude Code sync","MCP server discovery"],"zh":["AI工具发现","工具搜索","MCP服务器","Claude Code同步","自动搜索解决方案","跨机器搜索","技能发现","插件发现"],"ja":["AIエージェント","ツール発見","ツール検索","MCPサーバー","Claude Code同期","自動検索ソリューション","マシン間の検索","スキル発見","プラグイン発見"],"ko":["AI 에이전트","도구 발견","도구 검색","MCP 서버","Claude Code 동기화","자동 검색 솔루션","머신 간 검색","기능 발견","플러그인 발견"],"es":["Agentes de IA","tool-discovery","búsqueda de herramientas","plugins para Agentes de IA","MCP","desarrollo de Agentes de IA","soluciones de IA","herramientas de desarrollo de IA","integración de herramientas de IA"],"fr":["Agents IA","tool-discovery","recherche d''outils","plugins pour Agents IA","MCP","développement d''Agents IA","solutions IA","outils de développement IA","intégration d''outils IA"],"de":["KI-Agenten","tool-discovery","Tool-Suche","Plugins für KI-Agenten","MCP","Entwicklung von KI-Agenten","KI-Lösungen","KI-Entwicklungstools","KI-Tool-Integration"],"pt":["tool-discovery","ferramentas AI","sincronização de código","descoberta de ferramentas","MCP servers","plugins","busca automática de soluções","desenvolvimento de software"],"ru":["tool-discovery","ИИ Агенты","синхронизация кода","обнаружение инструментов","MCP серверы","плагины","автоматический поиск решений","разработка программного обеспечения"],"ar":["tool-discovery","أدوات الإيجنت الذكية","تنسيق الكود","اكتشاف أدوات","خوادم وملحقات MCP","البحث التلقائي عن حلول","تطوير البرمجيات"]}},"owner":"robertogogoni","repo":"claude-cross-machine-sync","repoPath":"robertogogoni/claude-cross-machine-sync","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"tool-discovery","description":"Use when user asks what tools are available?, is there a tool for..., can Claude do..., how can I..., mentions MCP servers, wants to discover capabilities, or seems uncertain about available integrations. Helps discover and search for tools, MCP servers, and plugins.","version":"1.0.0","bodyPreview":"# Tool Discovery & Search\n\nThis skill helps you discover available tools, MCP servers, and plugins. If a tool doesn''t exist locally, it automatically searches for solutions.\n\n## When This Skill Applies\n\nActivate this skill when:\n- User asks about available tools or capabilities\n- User wants to know if Claude can do something\n- User mentions \"MCP\", \"plugin\", \"integration\", or \"tool\"\n- User seems uncertain about how to accomplish a task\n- User asks \"is there a way to...\" or \"can you...\"\n\n## Curren","body":"# Tool Discovery & Search\n\nThis skill helps you discover available tools, MCP servers, and plugins. If a tool doesn''t exist locally, it automatically searches for solutions.\n\n## When This Skill Applies\n\nActivate this skill when:\n- User asks about available tools or capabilities\n- User wants to know if Claude can do something\n- User mentions \"MCP\", \"plugin\", \"integration\", or \"tool\"\n- User seems uncertain about how to accomplish a task\n- User asks \"is there a way to...\" or \"can you...\"\n\n## Current Available Tools\n\n### Core Claude Code Tools\nAlways available without configuration:\n- **Bash**: Execute shell commands, run scripts, system operations\n- **Read**: Read file contents, view code, examine configurations\n- **Edit**: Modify existing files with precise edits\n- **Write**: Create new files, overwrite existing ones\n- **Glob**: Find files by pattern (e.g., `**/*.js`)\n- **Grep**: Search code for patterns, find text across files\n- **WebSearch**: Search the web for information\n- **WebFetch**: Fetch and read web page content\n- **LSP**: Language server features (go to definition, find references, hover info)\n- **NotebookEdit**: Edit Jupyter notebooks\n- **Skill**: Invoke other skills\n- **Task**: Spawn specialized agents for complex tasks\n- **TodoWrite**: Create and manage task lists\n- **AskUserQuestion**: Ask clarifying questions with options\n\n### Connected MCP Servers\n\nYour currently configured MCP servers:\n\n#### **Beeper** (messaging & chat)\n- **Tool**: `mcp__beeper__search_chats`\n- **Purpose**: Search and interact with chat messages across platforms\n- **Use when**: Working with messages, chat history, or messaging platforms\n\n#### **Claude in Chrome** (browser automation)\nTools available:\n- `mcp__claude-in-chrome__javascript_tool`: Execute JavaScript in browser\n- `mcp__claude-in-chrome__read_page`: Read page accessibility tree\n- `mcp__claude-in-chrome__find`: Find elements on page\n- `mcp__claude-in-chrome__form_input`: Fill form fields\n- `mcp__claude-in-chrome__computer`: Mouse/keyboard control\n- `mcp__claude-in-chrome__navigate`: Navigate URLs\n- `mcp__claude-in-chrome__screenshot`: Take screenshots\n- `mcp__claude-in-chrome__gif_creator`: Record browser actions as GIF\n- `mcp__claude-in-chrome__upload_image`: Upload images to pages\n- `mcp__claude-in-chrome__get_page_text`: Extract page text\n- `mcp__claude-in-chrome__tabs_*`: Manage browser tabs\n- `mcp__claude-in-chrome__read_console_messages`: Debug JavaScript\n- `mcp__claude-in-chrome__read_network_requests`: Monitor network activity\n- `mcp__claude-in-chrome__shortcuts_*`: Use browser shortcuts/workflows\n\n**Use when**: Web scraping, browser automation, testing web apps, form filling, web interaction\n\n#### **Episodic Memory** (conversation history)\n- **Tool**: `mcp__plugin_episodic-memory_episodic-memory__search`\n- **Purpose**: Search previous Claude Code conversations\n- **Use when**: Recalling past decisions, finding previous solutions, remembering context\n\n### Installed Plugins\n\nYour currently enabled plugins:\n- **superpowers@superpowers-marketplace**: Advanced development workflows\n- **episodic-memory@superpowers-marketplace**: Cross-session memory\n\n## Tool Discovery Process\n\nWhen a user needs a tool that isn''t currently available:\n\n### Step 1: Understand the Need\nAsk clarifying questions:\n- What specific task are you trying to accomplish?\n- What data/services do you need to interact with?\n- What format is the input/output?\n\n### Step 2: Search Existing Resources\n\nCheck these locations for potential solutions:\n\n1. **MCP Registry** - Search official MCP servers:\n   ```bash\n   # Search the MCP registry on GitHub\n   gh search repos \"mcp server\" topic:mcp\n   ```\n\n2. **Claude Plugins Marketplace**:\n   ```bash\n   # Check official plugins\n   ls ~/.claude/plugins/marketplaces/claude-plugins-official/plugins/\n   ls ~/.claude/plugins/marketplaces/claude-plugins-official/external_plugins/\n   ```\n\n3. **Awesome MCP Servers**: Search https://github.com/punkpeye/awesome-mcp-servers\n\n4. **NPM/PyPI for MCP**:\n   ```bash\n   # Search npm for MCP servers\n   npm search mcp-server\n\n   # Search PyPI\n   pip search mcp\n   ```\n\n### Step 3: Present Options\n\nOnce you find relevant tools:\n\n1. **Describe the tool**: What it does and how it helps\n2. **Installation method**: How to install it\n3. **Configuration needed**: What setup is required\n4. **Example usage**: Show how it would solve the user''s problem\n\n### Step 4: Offer Installation Assistance\n\nAsk the user:\n- \"I found [tool name] that can [capability]. Would you like me to help install it?\"\n- Provide installation commands\n- Help configure `.mcp.json` or plugin settings\n\n## Common Tool Categories & Solutions\n\n### Database Access\n- **PostgreSQL**: `@modelcontextprotocol/server-postgres`\n- **SQLite**: `@modelcontextprotocol/server-sqlite`\n- **MySQL**: Search npm for `mcp-server-mysql`\n\n### API Integrations\n- **GitHub**: `@modelcontextprotocol/server-github`\n- **GitLab**: Available in official plugins\n- **Slack**: Available in official plugins\n- **Linear**: Available in official plugins\n- **Stripe**: Available in official plugins\n\n### Development Tools\n- **Playwright**: Browser testing (official plugin)\n- **Firebase**: Firebase integration (official plugin)\n- **Docker**: Search for MCP docker servers\n- **Kubernetes**: Search for MCP k8s servers\n\n### Productivity\n- **Google Drive**: Search MCP registry\n- **Notion**: Search MCP registry\n- **Calendar**: Search MCP registry\n\n### AI & Data\n- **Sentry**: Error tracking\n- **Memory/RAG**: Episodic memory (already installed!)\n- **Vector DBs**: Search for Pinecone, Weaviate MCP servers\n\n## How to Install New MCP Servers\n\n### Method 1: NPM-based MCP Server\n```bash\n# Install globally\nnpm install -g @modelcontextprotocol/server-NAME\n\n# Add to ~/.claude.json\n```\n\nThen add configuration to `~/.claude.json`:\n```json\n{\n  \"mcpServers\": {\n    \"server-name\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@modelcontextprotocol/server-NAME\"],\n      \"env\": {\n        \"API_KEY\": \"your-key-here\"\n      }\n    }\n  }\n}\n```\n\n### Method 2: Python MCP Server\n```bash\n# Install with pip\npip install mcp-server-NAME\n\n# Add to ~/.claude.json\n```\n\nConfiguration:\n```json\n{\n  \"mcpServers\": {\n    \"server-name\": {\n      \"command\": \"python\",\n      \"args\": [\"-m\", \"mcp_server_name\"],\n      \"env\": {\n        \"API_KEY\": \"your-key-here\"\n      }\n    }\n  }\n}\n```\n\n### Method 3: Custom MCP Server\n```bash\n# Clone repository\ngit clone https://github.com/org/mcp-server-name\ncd mcp-server-name\nnpm install\n\n# Add to ~/.claude.json with full path\n```\n\n## Search Strategy\n\nWhen searching for a tool:\n\n1. **Start broad**: \"mcp server for [use case]\"\n2. **Check official sources**: Anthropic''s MCP registry, official plugins\n3. **Search GitHub**: `gh search repos \"mcp [service name]\"`\n4. **Check awesome lists**: awesome-mcp-servers, awesome-claude\n5. **Search package managers**: npm, PyPI, crates.io\n\n## Example Interactions\n\n### User: \"Can Claude access my Google Calendar?\"\nResponse pattern:\n1. \"Let me search for a Google Calendar MCP server...\"\n2. Use WebSearch or gh search to find options\n3. Present findings: \"I found [X] MCP server that provides Google Calendar integration\"\n4. Explain installation and configuration\n5. Offer to help set it up\n\n### User: \"Is there a way to interact with Docker?\"\nResponse pattern:\n1. Check if docker MCP exists\n2. Search GitHub/npm for docker MCP servers\n3. Present options with pros/cons\n4. Guide installation if user wants to proceed\n\n### User: \"What tools do I have?\"\nResponse pattern:\n1. List core tools\n2. List connected MCP servers with their capabilities\n3. List installed plugins\n4. Mention discovery capabilities: \"I can also search for new tools if you need something specific\"\n\n## Proactive Discovery\n\nWhen you notice the user struggling with a task:\n- Suggest: \"This task might be easier with [tool]. Would you like me to search for an MCP server that can help?\"\n- Offer: \"I can search the MCP registry for solutions if you''d like\"\n\n## Important Notes\n\n- Always verify tool compatibility before suggesting installation\n- Check if tools require API keys or authentication\n- Warn about security implications of tools that access sensitive data\n- Prioritize official Anthropic MCP servers when available\n- Test that installed tools work before declaring success\n\n## Quick Reference Commands\n\n```bash\n# Search MCP registry\ngh search repos topic:mcp \"keyword\"\n\n# List installed MCP servers\ncat ~/.claude.json | grep -A 5 mcpServers\n\n# List available plugins\nls ~/.claude/plugins/marketplaces/\n\n# Check skill availability\nls ~/.claude/skills/\n\n# Search npm for MCP\nnpm search mcp-server\n```\n\n## When to Use This Skill\n\n✅ User asks \"what can Claude do?\"\n✅ User wants to know available integrations\n✅ User needs a capability that might require a new tool\n✅ User mentions a service/API by name\n✅ User seems uncertain about how to proceed\n\n❌ User has a clear plan and knows what tools to use\n❌ Task is straightforward with existing tools\n❌ User is already using a specific tool successfully\n"},"lastSynced":"2026-03-08T02:00:27.205Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced AI Agents like AutoGPT and LangChain needing automated tool and plugin discovery capabilities.","zh":"适用于像 AutoGPT 和 LangChain 这样的高级 AI 代理，它们需要自动化工具和插件发现功能。","ja":"AutoGPTやLangChainなどの高度なAIエージェントに適しており、自動ツールおよびプラグイン発見機能が必要です。","ko":"AutoGPT 및 LangChain과 같은 고급 AI 에이전트에게 적합하며 자동화된 도구 및 플러그인 검색 기능이 필요합니다.","es":"Ideal para agentes de IA avanzados como AutoGPT y LangChain que necesitan capacidades de descubrimiento de herramientas y plugins automatizadas.","fr":"Idéal pour les agents d''IA avancés comme AutoGPT et LangChain nécessitant des capacités de découverte d''outils et de plugins automatisées.","de":"Ideal für fortschrittliche KI-Agents wie AutoGPT und LangChain, die automatisierte Werkzeug- und Plugin-Entdeckungsfunktionen benötigen.","pt":"Ideal para Agentes de IA Avançados como AutoGPT e LangChain que necessitam de capacidades de descoberta de ferramentas e plugins automatizadas.","ru":"Идеально подходит для продвинутых агентов ИИ, таких как AutoGPT и LangChain, требующих автоматизированных возможностей обнаружения инструментов и плагинов.","ar":"مثالي لوكلاء الذكاء الاصطناعي المتقدمين مثل AutoGPT و LangChain الذين يحتاجون إلى قدرات اكتشاف أدوات وملحقات آلية."},"recommendation":{"en":"Empowers agents to automatically search for tools, MCP servers, and plugins, leveraging keywords like ''MCP'', ''plugin'', and ''integration'' to provide seamless user experiences through efficient solution discovery using protocols and libraries.","zh":"赋予代理自动搜索工具、MCP服务器和插件的能力，利用像''MCP''、''插件''和''集成''这样的关键词，通过高效的解决方案发现提供无缝的用户体验，使用协议和库。","ja":"エージェントにツール、MCPサーバー、プラグインを自動検索する能力を付与し、''MCP''、''プラグイン''、''統合''などのキーワードを使用して、プロトコルやライブラリを使用した効率的なソリューション発見によりシームレスなユーザーエクスペリエンスを提供します。","ko":"에이전트에게 자동으로 도구, MCP 서버 및 플러그인을 검색할 수 있는 능력을 부여하며 ''MCP'', ''플러그인'', ''통합''과 같은 키워드를 사용하여 프로토콜 및 라이브러리를 사용한 효율적인 솔루션 검색을 통해 무결점의 사용자 경험을 제공합니다.","es":"Habilita a los agentes a buscar automáticamente herramientas, servidores MCP y plugins, aprovechando palabras clave como ''MCP'', ''plugin'' e ''integración'' para proporcionar experiencias de usuario sin problemas a través de la descubierta eficiente de soluciones utilizando protocolos y bibliotecas.","fr":"Permet aux agents de rechercher automatiquement des outils, des serveurs MCP et des plugins, en exploitant des mots clés comme ''MCP'', ''plugin'' et ''intégration'' pour fournir des expériences utilisateur sans problème à travers la découverte efficace de solutions en utilisant des protocoles et des bibliothèques.","de":"Ermöglicht es den Agents, automatisch nach Tools, MCP-Servern und Plugins zu suchen, indem Schlüsselwörter wie ''MCP'', ''Plugin'' und ''Integration'' genutzt werden, um eine nahtlose Benutzererfahrung durch effiziente Lösungsentdeckung unter Verwendung von Protokollen und Bibliotheken bereitzustellen.","pt":"Habilita os agentes a buscar automaticamente ferramentas, servidores MCP e plugins, utilizando palavras-chave como ''MCP'', ''plugin'' e ''integração'' para fornecer experiências de usuário sem interrupções através da descoberta eficiente de soluções usando protocolos e bibliotecas.","ru":"Наделяет агентов возможностью автоматически искать инструменты, серверы MCP и плагины, используя ключевые слова như ''MCP'', ''плагин'' и ''интеграция'' для обеспечения бесперебойного пользовательского опыта посредством эффективного обнаружения решений с использованием протоколов и библиотек.","ar":"تمكين الوكلاء من البحث تلقائيًا عن أدوات وخادمات MCP وملحقات باستخدام كلمات مفتاحية مثل ''MCP'' و ''ملحق'' و ''تكامل'' لتوفير تجارب مستخدم لامعة من خلال اكتشاف حلول فعال باستخدام بروتوكولات ومكتبات."},"useCases":{"en":["Automating tool discovery for user inquiries","Generating plugin recommendations for tasks","Debugging integration issues with MCP servers"],"zh":["自动化工具发现用于用户查询","为任务生成插件推荐","调试与MCP服务器集成的问题"],"ja":["ユーザーの問い合わせに対するツールの自動発見","タスク用のプラグインの推奨","MCPサーバーとの統合の問題のデバッグ"],"ko":["사용자 요청에 대한 도구 자동 검색","작업을 위한 플러그인 추천 생성","MCP 서버와의 통합 문제 디버깅"],"es":["Automatizar el descubrimiento de herramientas para consultas de usuarios","Generar recomendaciones de plugins para tareas","Depurar problemas de integración con servidores MCP"],"fr":["Automatiser la découverte d''outils pour les requêtes des utilisateurs","Générer des recommandations de plugins pour les tâches","Déboguer les problèmes d''intégration avec les serveurs MCP"],"de":["Automatisieren der Werkzeugentdeckung für Benutzeranfragen","Erzeugen von Plugin-Empfehlungen für Aufgaben","Beheben von Integrationsproblemen mit MCP-Servern"],"pt":["Automatizar a descoberta de ferramentas para consultas de usuário","Gerar recomendações de plugins para tarefas","Depurar problemas de integração com servidores MCP"],"ru":["Автоматизировать обнаружение инструментов для запросов пользователей","Генерировать рекомендации плагинов для задач","Отлаживать проблемы интеграции с серверами MCP"],"ar":["تأتميم اكتشاف أدوات لاستفسارات المستخدم","توليد توجيهات ملحقات للمهام","تصحيح مشاكل التكامل مع خادمات MCP"]},"limitations":{"en":["Requires access to external repositories or databases for tool discovery","Dependent on user input for effective search"],"zh":["需要访问外部存储库或数据库以进行工具发现","依赖于用户输入以进行有效搜索"],"ja":["ツールの発見には外部リポジトリまたはデータベースへのアクセスが必要","有効な検索にはユーザーの入力に依存します"],"ko":["도구 검색을 위해 외부 저장소 또는 데이터베이스에 접근할 필요가 있음","유효한 검색을 위해 사용자 입력에 의존"],"es":["Requiere acceso a repositorios o bases de datos externos para la descubierta de herramientas","Depende de la entrada del usuario para una búsqueda efectiva"],"fr":["Nécessite un accès à des référentiels ou des bases de données externes pour la découverte d''outils","Dépend de la saisie de l''utilisateur pour une recherche efficace"],"de":["Benötigt Zugriff auf externe Repositorys oder Datenbanken für die Werkzeugentdeckung","Hängt von der Benutzereingabe für eine effektive Suche ab"],"pt":["Requer acesso a repositórios ou bases de dados externas para descoberta de ferramentas","Depende da entrada do usuário para busca eficaz"],"ru":["Требует доступа к внешним репозиториям или базам данных для обнаружения инструментов","Зависит от ввода пользователя для эффективного поиска"],"ar":["يتطلب الوصول إلى مستودعات أو قواعد بيانات خارجية لاكتشاف الأدوات","يعتمد على إدخال المستخدم للبحث الفعال"]},"version":4},"contentHash":"07dee57b840dfd674cf88ee90186bbb136d3cbc9ab54ec65b76a6369578d88c2","qualityScore":65}');
