INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('robertogogoni/claude-cross-machine-sync/tool-discovery', 'tool-discovery', 'robertogogoni', 'claude-cross-machine-sync', 'community', 'tool-discovery robertogogoni claude-cross-machine-sync community The tool-discovery skill enables AI agents to discover available tools, MCP servers, and plugins, and automatically searches for solutions when a tool doesn''t exist locally. This benefits developers working with AI agents, particularly when users inquire about capabilities or tools. 工具发现技能帮助您发现可用工具和MCP服务器，自动搜索解决方案 ツール発見スキルは、利用可能なツールとMCPサーバーを発見し、自動検索ソリューションを実行するのに役立ちます 도구 발견 기능은 사용 가능한 도구와 MCP 서버를 발견하고 자동 검색 솔루션을 실행하는 데 도움이 됩니다 El skill tool-discovery permite a los Agentes de IA descubrir herramientas y plugins disponibles. Ayuda a los desarrolladores a encontrar soluciones para tareas específicas. Le skill tool-discovery permet aux Agents IA de découvrir les outils et les plugins disponibles. Il aide les développeurs à trouver des solutions pour des tâches spécifiques. Der tool-discovery-Skill ermöglicht es KI-Agenten, verfügbare Tools und Plugins zu entdecken. Er hilft Entwicklern bei der Suche nach Lösungen für spezifische Aufgaben. O tool-discovery é uma habilidade que permite a descoberta de ferramentas disponíveis, sincronização de código e memória. Tool-discovery - это навык, который позволяет обнаруживать доступные инструменты, синхронизировать код и память. tool-discovery هو مهارة يسمح باكتشاف أدوات متاحة وتنسيق الكود والذاكرة. how to use tool-discovery what is tool-discovery tool-discovery alternative tool-discovery setup guide tool-discovery install cross-machine sync for AI agents Claude Code sync MCP server discovery AI工具发现 工具搜索 MCP服务器 Claude Code同步 自动搜索解决方案 跨机器搜索 技能发现 插件发现 Enables cross-machine Claude Code sync for settings, memory, skills, and episodic memory Automatically searches for solutions when a tool doesn''t exist locally Supports discovery of MCP servers and plugins Activates when users ask about available tools or capabilities Facilitates user inquiries about tool availability and capabilities tool-discovery is a skill that facilitates the discovery of available tools, MCP servers, and plugins across machines, enabling efficient AI agent development and user support');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Galaxy-Dawn/claude-scholar/ui-ux-pro-max', 'community', 'Galaxy-Dawn', 'claude-scholar', 'Galaxy-Dawn/claude-scholar', 'ui-ux-pro-max', 0, 0, 65, '2026-03-08T01:57:15.276Z', '2026-03-08T02:00:40.634Z', 'd34ca9a7ec3104f60ae1cfabccb6bfa7f0a62e6c52cfe26327756a13cbeaab70', '{"id":"Galaxy-Dawn/claude-scholar/ui-ux-pro-max","name":"ui-ux-pro-max","description":{"en":"ui-ux-pro-max streamlines the research workflow for data science, AI research, and academic writing. It provides a comprehensive design guide for web and mobile applications.","zh":"UI/UX Pro Max 是一个全面的设计指南，包含 50+ 样式、97 色板、57 字体对和 99 UX 指南，适用于数据科学、AI 研究和学术写作","ja":"UI/UX Pro Max は、データサイエンス、AI 研究、学術文章作成のための包括的な設計ガイドです。50以上のスタイル、97のカラーパレット、57のフォントペア、99のUXガイドラインを含みます","ko":"UI/UX Pro Max는 데이터 과학, AI 연구 및 학술 저술을 위한 종합적인 디자인 가이드로, 50개 이상의 스타일, 97개의 색상 팔레트, 57개의 글꼴 조합 및 99개의 UX 가이드라인을 제공합니다","es":"ui-ux-pro-max es una guía de diseño integral para aplicaciones web y móviles con 50+ estilos y 97 paletas de colores","fr":"ui-ux-pro-max est un guide de design complet pour les applications web et mobiles avec 50+ styles et 97 palettes de couleurs","de":"ui-ux-pro-max ist ein umfassender Designleitfaden für Web- und Mobile-Anwendungen mit 50+ Stilen und 97 Farbpaletten","pt":"O UI/UX Pro Max é um guia de design abrangente para aplicações web e móveis, contendo 50+ estilos e 97 paletas de cores","ru":"UI/UX Pro Max - это комплексное руководство по дизайну для веб- и мобильных приложений, содержащее 50+ стилей и 97 цветовых палитр","ar":"UI/UX Pro Max هو دليل التصميم الشامل لتطبيقات الويب والموبايل، الذي يحتوي على 50+ نمطًا و97 لوحة ألوان"},"seo":{"title":{"en":"ui-ux-pro-max: Comprehensive Design Guide for AI Agents |...","zh":"UI/UX Pro Max 设计指南：AI 工具集成和开发最佳实践","ja":"UI/UX Pro Max 設計ガイド：AI エージェントを活用した開発のベストプラクティス","ko":"UI/UX Pro Max 디자인 가이드: AI 에이전트와의 통합 및 개발 