INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Galaxy-Dawn/claude-scholar/ui-ux-pro-max', 'ui-ux-pro-max', 'Galaxy-Dawn', 'claude-scholar', 'community', 'ui-ux-pro-max Galaxy-Dawn claude-scholar community ui-ux-pro-max streamlines the research workflow for data science, AI research, and academic writing. It provides a comprehensive design guide for web and mobile applications. UI/UX Pro Max 是一个全面的设计指南，包含 50+ 样式、97 色板、57 字体对和 99 UX 指南，适用于数据科学、AI 研究和学术写作 UI/UX Pro Max は、データサイエンス、AI 研究、学術文章作成のための包括的な設計ガイドです。50以上のスタイル、97のカラーパレット、57のフォントペア、99のUXガイドラインを含みます UI/UX Pro Max는 데이터 과학, AI 연구 및 학술 저술을 위한 종합적인 디자인 가이드로, 50개 이상의 스타일, 97개의 색상 팔레트, 57개의 글꼴 조합 및 99개의 UX 가이드라인을 제공합니다 ui-ux-pro-max es una guía de diseño integral para aplicaciones web y móviles con 50+ estilos y 97 paletas de colores ui-ux-pro-max est un guide de design complet pour les applications web et mobiles avec 50+ styles et 97 palettes de couleurs ui-ux-pro-max ist ein umfassender Designleitfaden für Web- und Mobile-Anwendungen mit 50+ Stilen und 97 Farbpaletten O UI/UX Pro Max é um guia de design abrangente para aplicações web e móveis, contendo 50+ estilos e 97 paletas de cores UI/UX Pro Max - это комплексное руководство по дизайну для веб- и мобильных приложений, содержащее 50+ стилей и 97 цветовых палитр UI/UX Pro Max هو دليل التصميم الشامل لتطبيقات الويب والموبايل، الذي يحتوي على 50+ نمطًا و97 لوحة ألوان how to use ui-ux-pro-max ui-ux-pro-max alternative ui-ux-pro-max setup guide what is ui-ux-pro-max ui-ux-pro-max vs competitors ui-ux-pro-max install ui-ux-pro-max for AI research ui-ux-pro-max for data science ui-ux-pro-max for academic writing UI/UX 设计 AI 工具 数据科学 学术写作 Claude Code 设计指南 开发最佳实践 AI 集成 UX 指南 Contains 50+ styles for web and mobile applications Includes 97 color palettes for customizable design Offers 57 font pairings for enhanced typography Provides 99 UX guidelines for improved user experience Features 25 chart types across 9 technology stacks Includes a searchable database with priority-based recommendations ui-ux-pro-max is a Claude Code configuration for data science and AI research, offering a comprehensive design guide with 50+ styles, 97 color palettes, and 99 UX guidelines');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mjunaidca/robolearn/ros2-launch-system', 'community', 'mjunaidca', 'robolearn', 'mjunaidca/robolearn', 'ros2-launch-system', 0, 0, 65, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:18.625Z', '1d79309c4e7e0f961c03bdf238a3cbcf0862abbd7056572c16d8fcd2f43438b1', '{"id":"mjunaidca/robolearn/ros2-launch-system","name":"ros2-launch-system","description":{"en":"ros2-launch-system is a tool for generating ROS 2 Python launch files and multi-node configurations following official ROS 2 Humble patterns","zh":"ros2-launch-system 是一个用于生成 ROS 2 Python 启动文件和多节点配置的工具，遵循官方 ROS 2 Humble 模式","ja":"ros2-launch-system は、公式の ROS 2 Humble パターンに従った ROS 2 Python 起動ファイルとマルチノード構成を生成するツールです","ko":"ros2-launch-system는 공식 ROS 2 Humble 패턴을 따르는 ROS 2 Python 시작 파일과 多 노드 구성 생성을 위한 도구입니다","es":"ros2-launch-system es una habilidad que permite generar archivos de lanzamiento de ROS 2 Python y configuraciones de multi-nodos siguiendo patrones oficiales de ROS 2 Humble","fr":"ros2-launch-system est une compétence qui permet de générer des fichiers de lancement ROS 2 Python et des configurations de multi-nœuds suivant les modèles officiels de ROS 2 Humble","de":"ros2-launch-system ist eine Fähigkeit, die die Erstellung von ROS 2 Python-Startdateien und Multi-Node-Konfigurationen nach offiziellen ROS 2 Humble-Mustern ermöglicht","pt":"O ROS 2 Launch System é uma habilidade que gera arquivos de lançamento Python precisos para o ROS 2, seguindo os padrões oficiais do ROS 2 Humble.","ru":"ROS 2 Launch System - это навык, который генерирует точные файлы запуска Python для ROS 2, следуя официальным стандартам ROS 2 Humble.","ar":"نظام إطلاق ROS 2 هو مهارة تنتج ملفات إطلاق Python دقيقة للROS 2، وتتبع معايير ROS 2 Humble الرسمية."},"seo":{"title":{"en":"ROS 2 Launch System Setup Guide - ros2-launch-system","zh":"ROS 2 启动系统设置指南 - ros2-launch-system","ja"