INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mjunaidca/robolearn/ros2-launch-system', 'ros2-launch-system', 'mjunaidca', 'robolearn', 'community', 'ros2-launch-system mjunaidca robolearn community ros2-launch-system is a tool for generating ROS 2 Python launch files and multi-node configurations following official ROS 2 Humble patterns ros2-launch-system 是一个用于生成 ROS 2 Python 启动文件和多节点配置的工具，遵循官方 ROS 2 Humble 模式 ros2-launch-system は、公式の ROS 2 Humble パターンに従った ROS 2 Python 起動ファイルとマルチノード構成を生成するツールです ros2-launch-system는 공식 ROS 2 Humble 패턴을 따르는 ROS 2 Python 시작 파일과 多 노드 구성 생성을 위한 도구입니다 ros2-launch-system es una habilidad que permite generar archivos de lanzamiento de ROS 2 Python y configuraciones de multi-nodos siguiendo patrones oficiales de ROS 2 Humble ros2-launch-system est une compétence qui permet de générer des fichiers de lancement ROS 2 Python et des configurations de multi-nœuds suivant les modèles officiels de ROS 2 Humble ros2-launch-system ist eine Fähigkeit, die die Erstellung von ROS 2 Python-Startdateien und Multi-Node-Konfigurationen nach offiziellen ROS 2 Humble-Mustern ermöglicht O ROS 2 Launch System é uma habilidade que gera arquivos de lançamento Python precisos para o ROS 2, seguindo os padrões oficiais do ROS 2 Humble. ROS 2 Launch System - это навык, который генерирует точные файлы запуска Python для ROS 2, следуя официальным стандартам ROS 2 Humble. نظام إطلاق ROS 2 هو مهارة تنتج ملفات إطلاق Python دقيقة للROS 2، وتتبع معايير ROS 2 Humble الرسمية. ROS 2 Python launch files multi-node configurations physical AI textbooks lesson creation exercises AI agents ROS 2 Python 启动文件 多节点配置 物理 AI 教科书 课程创建 练习 AIエージェント Generate accurate ROS 2 Python launch files Support multi-node configurations Follow official ROS 2 Humble patterns Used for creating lessons in physical AI textbooks Used for writing multi-node deployment exercises Used for generating worked examples ros2-launch-system is a tool for generating ROS 2 launch files and multi-node configurations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huydepzai121/skill/ffmpeg', 'community', 'huydepzai121', 'skill', 'huydepzai121/skill', 'ffmpeg', 0, 0, 65, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:18.959Z', '6e597ecb0fbe9c1bb76549ce47060fcc4003a6514abffb2600142de216ad4936', '{"id":"huydepzai121/skill/ffmpeg","name":"ffmpeg","description":{"en":"ffmpeg is a multimedia framework for handling video, audio, and streams. It benefits developers who need to convert media files, encode/decode video, and process audio","zh":"FFmpeg 是一个全面的开源多媒体框架，用于处理视频、音频和其他多媒体文件和流媒体。它提供了命令行工具和库用于记录、转换和流媒体音频和视频","ja":"FFmpeg は、ビデオ、オーディオ、その他のマルチメディア ファイルとストリームを处理するための包括的なオープンソース マルチメディア フレームワークです。コマンドライン ツールとライブラリを提供して、オーディオとビデオを記録、変換、ストリーミングします","ko":"FFmpeg는 비디오, 오디오 및 기타 멀티미디어 파일 및 스트림을 처리하기 위한 포괄적인 오픈소스 멀티미디어 프레임워크입니다. 오디오 및 비디오를 기록, 변환 및 스트리밍하기 위한 명령줄 도구 및 라이브러리를 제공합니다","es":"ffmpeg es un framework de multimedia de código abierto que maneja archivos y flujos de video, audio y otros medios. Proporciona herramientas de línea de comandos y bibliotecas para grabar, convertir y transmitir audio y video.","fr":"ffmpeg est un framework multimédia open-source qui gère les fichiers et les flux de vidéo, d''audio et d''autres médias. Il fournit des outils de ligne de commande et des bibliothèques pour enregistrer, convertir et diffuser de l''audio et de la vidéo.","de":"ffmpeg ist ein Open-Source-Multimedia-Framework, das Video-, Audio- und andere Mediadateien und -streams verarbeitet. Es bietet Kommandozeilen-Tools und Bibliotheken zum Aufzeichnen, Konvertieren und Übertragen von Audio und Video.","pt":"O FFmpeg é uma estrutura de mídia de código aberto que lida com arquivos e fluxos de vídeo, áudio e outros tipos de mídia. Ele fornece ferramentas de linha de comando e bibliotecas para gravar, converter e transmitir áudio e vídeo.","ru":"FFmpeg - это комплексная открытая мультимедиа-фреймворк, которая обрабатывает видео, аудио и другие мультимедиа файлы и потоки. Он предоставляет командную строку и библиотеки для записи, конвертации и потоковой передачи аудио и видео.","ar":"FFmpeg هو إطار مفتوح المصدر لملفات الوسائط المتعددة التي تتعامل مع ملفات الفيديو والصوت وغيرها من أنواع الوسائط المتعددة. يقدم أدوات سطر الأوامر والمكتبات لتسجيل وتحويل وبث الصوت والفيديو."},"seo":{"title":{"en":"ffmpeg: Comprehensive Media Processing Setup Guide | AI A...","zh":"FFmpeg Setup Guide: 视频和音频处理最佳实践","ja":"FFmpeg を使ったマルチメディア処理のベストプラクティス","ko":"FFmpeg 설정 가이드: 비디오 및 오디오 처리 전문가","es":"Guía de configuración de ffmpeg para desarrolladores","fr":"Guide de mise en route de ffmpeg pour les développeurs","de":"ffmpeg-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração do FFmpeg para Desenvolvedores","ru":"Настройка FFmpeg: Лучшие Практики для ИИ Агентов","ar":"دليل إعداد FFmpeg للتحكم في الوسائط المتعددة"},"description":{"en":"Unlock the full potential of ffmpeg for media file conversions, encoding, and live streaming. Discover how to harness its command-line tools and libraries fo...","zh":"了解如何使用 FFmpeg 处理视频和音频文件，包括格式转换、编码和解码、流媒体处理等","ja":"FFmpeg を使用してマルチメディアファイルを処理する方法について学びます。形式変換、エンコード/デコード、ストリーミングなど","ko":"FFmpeg를 사용하여 비디오 및 오디오 파일을 처리하는 방법을 알아보세요. 형식 변환, 인코딩/디코딩, 스트리밍 등","es":"Aprende a utilizar ffmpeg para convertir, codificar y transmitir archivos de medios. Descubre sus características clave y beneficios para desarrolladores.","fr":"Découvrez comment utiliser ffmpeg pour convertir, encoder et diffuser des fichiers multimédias. Explorez ses fonctionnalités clés et avantages pour les dével...","de":"Erfahren Sie, wie Sie ffmpeg für die Konvertierung, Kodierung und Übertragung von Mediadateien verwenden. Entdecken Sie seine wichtigsten Funktionen und Vort...","pt":"Aprenda a usar o FFmpeg para converter, codificar e transmitir arquivos de mídia. Descubra como integrar essa ferramenta poderosa em seus projetos de desenvo...","ru":"Узнайте, как использовать FFmpeg для конвертации, кодирования и потоковой передачи мультимедиа. Откройте для себя, как интегрировать эту мощную инструмент в ...","ar":"تعرف على كيفية استخدام FFmpeg لتحويل وتشفير و بث الملفات الإعلامية. اكتشف كيفية دمج هذه الأداة القوية في مشاريع التطوير الخاصة بك."},"definition":{"en":"ffmpeg is a comprehensive open-source multimedia framework for recording, converting, and streaming audio and video","zh":"FFmpeg 是一个开源的多媒体处理框架，用于处理视频、音频和其他多媒体文件","ja":"FFmpeg は、ビデオ、オーディオ、その他のマルチメディア ファイルを处理するためのオープンソース マルチメディア フレームワークです","ko":"FFmpeg는 비디오, 오디오 및 기타 멀티미디어 파일을 처리하기 위한 오픈소스 멀티미디어 프레임워크입니다","es":"ffmpeg es un framework de multimedia de código abierto que permite la grabación, conversión y transmisión de archivos de medios.","fr":"ffmpeg est un framework multimédia open-source qui permet l''enregistrement, la conversion et la diffusion de fichiers multimédias.","de":"ffmpeg ist ein Open-Source-Multimedia-Framework, das die Aufzeichnung, Konvertierung und Übertragung von Mediadateien ermöglicht.","pt":"O que é FFmpeg? É uma ferramenta de código aberto para processar arquivos de mídia.","ru":"Что такое FFmpeg? Это открытая инструмент для обработки мультимедиа файлов.","ar":"ما هو FFmpeg؟ هو أداة مفتوحة المصدر لمعالجة ملفات الوسائط المتعددة."},"features":{"en":["Converts media files between formats like MP4, MKV, WebM, and AVI","Encodes/decodes video with codecs such as H.264, H.265, VP9, and AV1","Processes audio files with formats like AAC, MP3, FLAC, and Opus","Supports live streaming for real-time multimedia applications"],"zh":["支持多种视频格式（MP4、MKV、WebM、AVI 等）","支持不同视频编码（H.264、H.265、VP9、AV1）","支持音频文件处理（AAC、MP3、FLAC、Opus）","支持实时流媒体处理"],"ja":["複数のビデオ形式（MP4、MKV、WebM、AVI など）をサポート","異なるビデオエンコード（H.264、H.265、VP9、AV1）をサポート","オーディオファイル処理（AAC、MP3、FLAC、Opus）をサポート","リアルタイムストリーミング処理をサポート"],"ko":["여러 비디오 형식（MP4, MKV, WebM, AVI 등）을 지원","다른 비디오 인코딩（H.264, H.265, VP9, AV1）을 지원","오디오 파일 처리（AAC, MP3, FLAC, Opus）을 지원","실시간 스트리밍 처리를 지원"],"es":["Conversión de archivos de medios entre formatos (MP4, MKV, WebM, AVI, etc.)","Codificación y decodificación de video con diferentes codecs (H.264, H.265, VP9, AV1)","Procesamiento de archivos de audio (AAC, MP3, FLAC, Opus)","Transmisión en vivo","Herramientas de línea de comandos y bibliotecas para grabar y convertir audio y video"],"fr":["Conversion de fichiers multimédias entre formats (MP4, MKV, WebM, AVI, etc.)","Encodage et décodage de la vidéo avec différents codecs (H.264, H.265, VP9, AV1)","Traitement de fichiers audio (AAC, MP3, FLAC, Opus)","Diffusion en direct","Outils de ligne de commande et bibliothèques pour enregistrer et convertir de l''audio et de la vidéo"],"de":["Konvertierung von Mediadateien zwischen Formaten (MP4, MKV, WebM, AVI, etc.)","Kodierung und Dekodierung von Video mit verschiedenen Codecs (H.264, H.265, VP9, AV1)","Verarbeitung von Audiodateien (AAC, MP3, FLAC, Opus)","Live-Übertragung","Kommandozeilen-Tools und Bibliotheken zum Aufzeichnen und Konvertieren von Audio und Video"],"pt":["Conversão de arquivos de mídia entre formatos (MP4, MKV, WebM, AVI, etc.)","Codificação/decodificação de vídeo com diferentes codecs (H.264, H.265, VP9, AV1)","Processamento de arquivos de áudio (AAC, MP3, FLAC, Opus)","Transmissão ao vivo","Gravação de áudio e vídeo","Bibliotecas para desenvolvimento de aplicativos"],"ru":["Конвертация мультимедиа файлов между форматами (MP4, MKV, WebM, AVI и т.д.)","Кодирование/декодирование видео с разными кодеками (H.264, H.265, VP9, AV1)","Обработка аудио файлов (AAC, MP3, FLAC, Opus)","Потоковая передача в режиме реального времени","Запись аудио и видео","Библиотеки для разработки приложений"],"ar":["تحويل ملفات الوسائط المتعددة بين الصيغ (MP4, MKV, WebM, AVI, etc.)","تشفير/فك تشفير الفيديو باستخدام كوديكات مختلفة (H.264, H.265, VP9, AV1)","معالجة ملفات الصوت (AAC, MP3, FLAC, Opus)","بث مباشر","تسجيل الصوت والفيديو","مكتبات لتطوير التطبيقات"]},"keywords":{"en":["how to use ffmpeg","ffmpeg alternative","ffmpeg install","ffmpeg vs FFprobe","what is ffmpeg","ffmpeg setup guide","ffmpeg command-line tools","ffmpeg video encoding","ffmpeg audio processing"],"zh":["FFmpeg","视频处理","音频处理","多媒体框架","命令行工具","流媒体处理","视频格式转换","音频编码"],"ja":["FFmpeg","ビデオ処理","オーディオ処理","マルチメディアフレームワーク","コマンドラインツール","ストリーミング処理","ビデオ形式変換","オーディオエンコード"],"ko":["FFmpeg","비디오 처리","오디오 처리","멀티미디어 프레임워크","명령줄 도구","스트리밍 처리","비디오 형식 변환","오디오 인코딩"],"es":["ffmpeg","conversión de video","codificación de video","transmisión en vivo","procesamiento de audio","herramientas de línea de comandos","bibliotecas de multimedia","desarrollo de aplicaciones de medios","framework de multimedia"],"fr":["ffmpeg","conversion de vidéo","encodage de vidéo","diffusion en direct","traitement d''audio","outils de ligne de commande","bibliothèques multimédia","développement d''applications de médias","framework multimédia"],"de":["ffmpeg","Konvertierung von Video","Kodierung von Video","Live-Übertragung","Verarbeitung von Audio","Kommandozeilen-Tools","Multimedia-Bibliotheken","Entwicklung von Medienanwendungen","Multimedia-Framework"],"pt":["FFmpeg","conversão de mídia","codificação de vídeo","processamento de áudio","transmissão ao vivo","gravação de áudio e vídeo","desenvolvimento de aplicativos","bibliotecas de mídia"],"ru":["FFmpeg","конвертация мультимедиа","кодирование видео","обработка аудио","потоковая передача","запись аудио и видео","разработка приложений","библиотеки мультимедиа"],"ar":["FFmpeg","تحويل الوسائط المتعددة","تشفير الفيديو","معالجة الصوت","بث مباشر","تسجيل الصوت والفيديو","تطوير التطبيقات","مكتبات الوسائط المتعددة"]}},"owner":"huydepzai121","repo":"skill","repoPath":"huydepzai121/skill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"ffmpeg","description":"Guide for using FFmpeg - a comprehensive multimedia framework for video/audio encoding, conversion, streaming, and filtering. Use when processing media files, converting formats, extracting audio, creating streams, applying filters, or optimizing video/audio quality.","version":"1.0.0","bodyPreview":"# FFmpeg Skill\n\nFFmpeg is a comprehensive open-source multimedia framework that handles video, audio, and other multimedia files and streams. It provides command-line tools and libraries for recording, converting, and streaming audio and video.\n\n## When to Use This Skill\n\nUse this skill when:\n- Converting media files between formats (MP4, MKV, WebM, AVI, etc.)\n- Encoding/decoding video with different codecs (H.264, H.265, VP9, AV1)\n- Processing audio files (AAC, MP3, FLAC, Opus)\n- Live streaming","body":"# FFmpeg Skill\n\nFFmpeg is a comprehensive open-source multimedia framework that handles video, audio, and other multimedia files and streams. It provides command-line tools and libraries for recording, converting, and streaming audio and video.\n\n## When to Use This Skill\n\nUse this skill when:\n- Converting media files between formats (MP4, MKV, WebM, AVI, etc.)\n- Encoding/decoding video with different codecs (H.264, H.265, VP9, AV1)\n- Processing audio files (AAC, MP3, FLAC, Opus)\n- Live streaming to platforms (Twitch, YouTube, RTMP servers)\n- Creating HLS/DASH adaptive streams\n- Extracting audio from video files\n- Applying video/audio filters (scale, crop, denoise, volume)\n- Screen recording and capture\n- Optimizing video quality and file size\n- Batch processing media files\n- Analyzing media file properties\n\n## Core Components\n\n### Command-Line Tools\n\n**ffmpeg**: Primary tool for transcoding, conversion, and streaming\n**ffprobe**: Media analysis and inspection tool\n**ffplay**: Minimalist multimedia player for testing\n\n### Libraries\n\n- **libavcodec**: Encoding/decoding codecs\n- **libavformat**: Container formats and I/O\n- **libavfilter**: Audio/video filtering framework\n- **libavutil**: Utility functions\n- **libswscale**: Video scaling and color conversion\n- **libswresample**: Audio resampling and mixing\n\n## Common Video Codecs\n\n### Modern Codecs\n\n**H.264 (libx264)**: Most widely supported, excellent compression/quality balance\n- Best for: Universal compatibility, streaming, web video\n- Quality range: CRF 17-28 (lower = better quality)\n\n**H.265/HEVC (libx265)**: 25-50% better compression than H.264\n- Best for: 4K video, file size reduction\n- Slower encoding, limited browser support\n\n**VP9**: Royalty-free, WebM format\n- Best for: YouTube, open-source projects\n- Good quality/compression, Chrome/Firefox support\n\n**AV1 (libaom-av1, libsvtav1)**: Next-generation codec, best compression\n- Best for: Future-proofing, ultimate quality/size ratio\n- Very slow encoding (improving with SVT-AV1)\n\n### Legacy Codecs\n- MPEG-4 (Xvid/DivX)\n- MPEG-2\n- VP8\n\n## Common Audio Codecs\n\n**AAC**: Industry standard, excellent quality\n**MP3**: Universal compatibility, good quality\n**Opus**: Best quality at low bitrates, ideal for voice/streaming\n**FLAC**: Lossless compression, archival quality\n**Vorbis**: Open-source, good quality\n**AC-3/DTS**: Surround sound formats\n\n## Container Formats\n\n**MP4**: Universal compatibility, streaming-friendly\n**MKV (Matroska)**: Feature-rich, supports multiple tracks/subtitles\n**WebM**: Web-optimized (VP8/VP9 + Vorbis/Opus)\n**AVI**: Legacy format, broad compatibility\n**MOV**: Apple QuickTime format\n**TS**: Transport stream for broadcasting\n**FLV**: Flash video (legacy streaming)\n\n## Basic Operations\n\n### Format Conversion\n\nSimple format conversion without re-encoding:\n```bash\nffmpeg -i input.mkv -c copy output.mp4\n```\n\nConvert with specific codecs:\n```bash\nffmpeg -i input.avi -c:v libx264 -c:a aac output.mp4\n```\n\n### Quality-Based Encoding (CRF)\n\nConstant Rate Factor - best for quality-focused encoding:\n\n```bash\n# H.264 encoding (CRF 23 = default, 17-28 recommended range)\nffmpeg -i input.mkv -c:v libx264 -preset slow -crf 22 -c:a copy output.mp4\n\n# H.265 encoding (higher compression)\nffmpeg -i input.mkv -c:v libx265 -preset medium -crf 24 -c:a copy output.mp4\n\n# VP9 encoding (WebM)\nffmpeg -i input.mkv -c:v libvpx-vp9 -crf 30 -b:v 0 -c:a libopus output.webm\n```\n\n**CRF Scale:**\n- 0 = Lossless (huge file size)\n- 17-18 = Visually lossless\n- 20-23 = High quality (recommended)\n- 24-28 = Medium quality\n- 30+ = Low quality\n- 51 = Worst quality\n\n**Presets** (speed vs compression):\n- ultrafast, superfast, veryfast, faster, fast\n- medium (default)\n- slow, slower, veryslow (better compression)\n- placebo (not recommended - minimal gains)\n\n### Bitrate-Based Encoding (Two-Pass)\n\nFor targeting specific file sizes:\n\n```bash\n# Pass 1 (analysis)\nffmpeg -y -i input.mkv -c:v libx264 -b:v 2600k -pass 1 -an -f null /dev/null\n\n# Pass 2 (encoding)\nffmpeg -i input.mkv -c:v libx264 -b:v 2600k -pass 2 -c:a aac -b:a 128k output.mp4\n```\n\n### Audio Extraction\n\nExtract audio without re-encoding:\n```bash\nffmpeg -i video.mp4 -vn -c:a copy audio.m4a\n```\n\nExtract and convert to MP3:\n```bash\nffmpeg -i video.mp4 -vn -q:a 0 audio.mp3\n```\n\nExtract with specific bitrate:\n```bash\nffmpeg -i video.mp4 -vn -c:a libmp3lame -b:a 192k audio.mp3\n```\n\n### Video Scaling/Resizing\n\nScale to specific dimensions:\n```bash\nffmpeg -i input.mp4 -vf scale=1280:720 output.mp4\n```\n\nScale maintaining aspect ratio:\n```bash\n# Width 1280, height auto-calculated\nffmpeg -i input.mp4 -vf scale=1280:-1 output.mp4\n\n# Height 720, width auto-calculated\nffmpeg -i input.mp4 -vf scale=-1:720 output.mp4\n```\n\nScale to half resolution:\n```bash\nffmpeg -i input.mp4 -vf scale=iw/2:ih/2 output.mp4\n```\n\n### Trimming/Cutting Video\n\nCut without re-encoding (fast but less precise):\n```bash\nffmpeg -i input.mp4 -ss 00:01:30 -to 00:03:00 -c copy output.mp4\n```\n\nCut with re-encoding (precise):\n```bash\nffmpeg -i input.mp4 -ss 00:01:30 -t 00:01:30 -c:v libx264 -c:a aac output.mp4\n```\n\nParameters:\n- `-ss`: Start time (HH:MM:SS or seconds)\n- `-to`: End time\n- `-t`: Duration (instead of end time)\n\n### Concatenation\n\n**Method 1: Concat demuxer (same codec/format)**\n\nCreate `concat.txt`:\n```\nfile ''input1.mp4''\nfile ''input2.mp4''\nfile ''input3.mp4''\n```\n\nRun:\n```bash\nffmpeg -f concat -safe 0 -i concat.txt -c copy output.mp4\n```\n\n**Method 2: Concat filter (different formats)**\n```bash\nffmpeg -i input1.mp4 -i input2.mp4 -i input3.mp4 \\\n  -filter_complex \"[0:v][0:a][1:v][1:a][2:v][2:a]concat=n=3:v=1:a=1[v][a]\" \\\n  -map \"[v]\" -map \"[a]\" output.mp4\n```\n\n## Advanced Filtering\n\n### Video Filters\n\n**Multiple filters (chain with comma):**\n```bash\nffmpeg -i input.mp4 -vf \"scale=1280:720,hqdn3d\" output.mp4\n```\n\n**Denoise:**\n```bash\nffmpeg -i input.mp4 -vf hqdn3d output.mp4\n```\n\n**Deinterlace:**\n```bash\nffmpeg -i input.mp4 -vf yadif output.mp4\n```\n\n**Crop:**\n```bash\n# Crop to 1280x720 from top-left (0,0)\nffmpeg -i input.mp4 -vf \"crop=1280:720:0:0\" output.mp4\n\n# Auto-detect and remove black borders\nffmpeg -i input.mp4 -vf \"cropdetect\" output.mp4\n```\n\n**Rotate:**\n```bash\n# Rotate 90 degrees clockwise\nffmpeg -i input.mp4 -vf \"transpose=1\" output.mp4\n\n# Rotate 180 degrees\nffmpeg -i input.mp4 -vf \"transpose=1,transpose=1\" output.mp4\n```\n\n**Watermark/Logo:**\n```bash\nffmpeg -i video.mp4 -i logo.png \\\n  -filter_complex \"overlay=10:10\" output.mp4\n```\n\n**Speed adjustment:**\n```bash\n# 2x speed\nffmpeg -i input.mp4 -vf \"setpts=0.5*PTS\" -af \"atempo=2.0\" output.mp4\n\n# 0.5x speed (slow motion)\nffmpeg -i input.mp4 -vf \"setpts=2.0*PTS\" -af \"atempo=0.5\" output.mp4\n```\n\n### Audio Filters\n\n**Volume adjustment:**\n```bash\n# Increase volume by 10dB\nffmpeg -i input.mp4 -af \"volume=10dB\" output.mp4\n\n# Set to 50% volume\nffmpeg -i input.mp4 -af \"volume=0.5\" output.mp4\n```\n\n**Normalize audio:**\n```bash\nffmpeg -i input.mp4 -af loudnorm output.mp4\n```\n\n**Crossfade between audio:**\n```bash\nffmpeg -i audio1.mp3 -i audio2.mp3 \\\n  -filter_complex \"[0][1]acrossfade=d=5\" output.mp3\n```\n\n**Mix multiple audio tracks:**\n```bash\nffmpeg -i input1.mp3 -i input2.mp3 \\\n  -filter_complex \"[0:a][1:a]amix=inputs=2:duration=longest\" output.mp3\n```\n\n## Streaming\n\n### RTMP Streaming (Twitch/YouTube)\n\n**Basic stream:**\n```bash\nffmpeg -re -i input.mp4 -c:v libx264 -preset veryfast \\\n  -maxrate 3000k -bufsize 6000k -pix_fmt yuv420p -g 50 \\\n  -c:a aac -b:a 128k -ar 44100 \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Screen capture + stream (Linux):**\n```bash\nffmpeg -f x11grab -s 1920x1080 -framerate 30 -i :0.0 \\\n  -f pulse -ac 2 -i default \\\n  -c:v libx264 -preset veryfast -tune zerolatency \\\n  -maxrate 2500k -bufsize 5000k -pix_fmt yuv420p \\\n  -c:a aac -b:a 128k -ar 44100 \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Screen capture (Windows DirectShow):**\n```bash\nffmpeg -f dshow -i video=\"screen-capture-recorder\":audio=\"Stereo Mix\" \\\n  -c:v libx264 -preset ultrafast -tune zerolatency \\\n  -maxrate 750k -bufsize 3000k \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Important streaming parameters:**\n- `-re`: Read input at native frame rate (real-time)\n- `-tune zerolatency`: Optimize for low latency\n- `-g 50`: Keyframe every 50 frames (2 seconds @ 25fps)\n- `-maxrate`: Maximum bitrate\n- `-bufsize`: Rate control buffer (typically 2x maxrate)\n\n### HLS Streaming\n\nGenerate adaptive HLS stream:\n```bash\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset fast -crf 22 -g 48 -sc_threshold 0 \\\n  -c:a aac -b:a 128k \\\n  -f hls -hls_time 6 -hls_playlist_type vod \\\n  -hls_segment_filename \"segment_%03d.ts\" \\\n  playlist.m3u8\n```\n\n**Multi-bitrate HLS:**\n```bash\nffmpeg -i input.mp4 \\\n  -map 0:v -map 0:a -map 0:v -map 0:a \\\n  -c:v libx264 -crf 22 -c:a aac -b:a 128k \\\n  -b:v:0 2000k -s:v:0 1280x720 -b:v:1 5000k -s:v:1 1920x1080 \\\n  -var_stream_map \"v:0,a:0 v:1,a:1\" \\\n  -master_pl_name master.m3u8 \\\n  -f hls -hls_time 6 -hls_list_size 0 \\\n  stream_%v/index.m3u8\n```\n\n### UDP/RTP Streaming\n\n**UDP stream:**\n```bash\nffmpeg -re -i input.mp4 -c copy -f mpegts udp://192.168.1.100:1234\n```\n\n**RTP audio stream:**\n```bash\nffmpeg -re -i audio.mp3 -c:a libopus -f rtp rtp://192.168.1.100:5004\n```\n\n## Hardware Acceleration\n\n### NVIDIA NVENC\n\n```bash\n# H.264 with NVENC\nffmpeg -hwaccel cuda -i input.mp4 -c:v h264_nvenc -preset fast -crf 22 output.mp4\n\n# H.265 with NVENC\nffmpeg -hwaccel cuda -i input.mp4 -c:v hevc_nvenc -preset fast -crf 24 output.mp4\n```\n\n### Intel QuickSync (QSV)\n\n```bash\nffmpeg -hwaccel qsv -c:v h264_qsv -i input.mp4 \\\n  -c:v h264_qsv -preset fast -global_quality 22 output.mp4\n```\n\n### AMD VCE\n\n```bash\nffmpeg -hwaccel auto -i input.mp4 \\\n  -c:v h264_amf -quality balanced -rc cqp -qp 22 output.mp4\n```\n\n## Media Analysis\n\n### Inspect media file\n\n```bash\n# Detailed information\nffprobe -v quiet -print_format json -show_format -show_streams input.mp4\n\n# Human-readable format\nffprobe input.mp4\n\n# Get duration\nffprobe -v error -show_entries format=duration \\\n  -of default=noprint_wrappers=1:nokey=1 input.mp4\n\n# Get resolution\nffprobe -v error -select_streams v:0 \\\n  -show_entries stream=width,height \\\n  -of csv=s=x:p=0 input.mp4\n\n# Get bitrate\nffprobe -v error -show_entries format=bit_rate \\\n  -of default=noprint_wrappers=1:nokey=1 input.mp4\n```\n\n## Batch Processing\n\n### Bash loop for batch conversion\n\n```bash\n# Convert all MKV files to MP4\nfor file in *.mkv; do\n  ffmpeg -i \"$file\" -c:v libx264 -crf 22 -c:a aac \"${file%.mkv}.mp4\"\ndone\n\n# Resize all videos to 720p\nfor file in *.mp4; do\n  ffmpeg -i \"$file\" -vf scale=-1:720 \"720p_${file}\"\ndone\n```\n\n### Parallel processing with GNU Parallel\n\n```bash\n# Install: sudo apt-get install parallel\n\n# Process multiple files in parallel\nls *.mkv | parallel ffmpeg -i {} -c:v libx264 -crf 22 -c:a aac {.}.mp4\n```\n\n## Common Patterns\n\n### Create GIF from video\n\n```bash\n# High quality GIF\nffmpeg -i input.mp4 -vf \"fps=15,scale=640:-1:flags=lanczos,split[s0][s1];[s0]palettegen[p];[s1][p]paletteuse\" output.gif\n\n# Simple GIF\nffmpeg -i input.mp4 -vf \"fps=10,scale=320:-1\" output.gif\n```\n\n### Extract frames as images\n\n```bash\n# Extract all frames\nffmpeg -i input.mp4 frame_%04d.png\n\n# Extract 1 frame per second\nffmpeg -i input.mp4 -vf fps=1 frame_%04d.png\n\n# Extract single frame at 5 seconds\nffmpeg -ss 00:00:05 -i input.mp4 -frames:v 1 frame.png\n```\n\n### Create video from images\n\n```bash\n# From numbered images\nffmpeg -framerate 30 -i frame_%04d.png -c:v libx264 -crf 22 -pix_fmt yuv420p output.mp4\n\n# From pattern\nffmpeg -framerate 24 -pattern_type glob -i ''*.png'' -c:v libx264 output.mp4\n```\n\n### Add subtitles\n\n```bash\n# Burn subtitles into video\nffmpeg -i video.mp4 -vf subtitles=subtitles.srt output.mp4\n\n# Embed subtitle track (soft subtitles)\nffmpeg -i video.mp4 -i subtitles.srt -c copy -c:s mov_text output.mp4\n```\n\n### Remove audio\n\n```bash\nffmpeg -i input.mp4 -an -c:v copy output.mp4\n```\n\n### Replace audio\n\n```bash\nffmpeg -i video.mp4 -i audio.mp3 -c:v copy -c:a aac -map 0:v:0 -map 1:a:0 output.mp4\n```\n\n### Create thumbnail\n\n```bash\n# Single thumbnail at 5 seconds\nffmpeg -i input.mp4 -ss 00:00:05 -vframes 1 -vf scale=320:-1 thumb.jpg\n\n# Multiple thumbnails (one per minute)\nffmpeg -i input.mp4 -vf fps=1/60,scale=320:-1 thumb_%03d.jpg\n```\n\n## Performance Optimization\n\n### Speed vs Quality Trade-offs\n\n**Fast encoding (real-time processing):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset ultrafast -crf 23 output.mp4\n```\n\n**Balanced (default):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset medium -crf 22 output.mp4\n```\n\n**High quality (archival):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset veryslow -crf 18 output.mp4\n```\n\n### Multi-threading\n\nFFmpeg automatically uses multiple CPU cores. Override with:\n```bash\nffmpeg -threads 8 -i input.mp4 -c:v libx264 output.mp4\n```\n\n## Best Practices\n\n1. **Use CRF for quality-focused encoding** - Better than bitrate for most use cases\n2. **Two-pass for size targets** - When file size is critical\n3. **Copy streams when possible** - Use `-c copy` to avoid re-encoding\n4. **Choose appropriate presets** - Balance speed vs compression\n5. **Match output to source** - Don''t upscale or use higher quality than source\n6. **Test short clips first** - Verify settings before batch processing\n7. **Hardware acceleration** - Use GPU encoding for faster processing\n8. **Audio matters** - Don''t neglect audio codec/bitrate choices\n9. **Use filters efficiently** - Chain multiple filters with commas\n10. **Verify output** - Always check quality after encoding\n\n## Common Parameters Reference\n\n### Video Parameters\n- `-c:v` or `-vcodec`: Video codec\n- `-b:v`: Video bitrate (e.g., `2M`, `2500k`)\n- `-crf`: Constant Rate Factor (0-51)\n- `-preset`: Encoding speed/quality (ultrafast to veryslow)\n- `-tune`: Encoding optimization (film, animation, zerolatency)\n- `-pix_fmt`: Pixel format (yuv420p for compatibility)\n- `-r`: Frame rate (e.g., `30`, `60`)\n- `-g`: GOP size (keyframe interval)\n\n### Audio Parameters\n- `-c:a` or `-acodec`: Audio codec\n- `-b:a`: Audio bitrate (e.g., `128k`, `192k`)\n- `-ar`: Audio sample rate (e.g., `44100`, `48000`)\n- `-ac`: Audio channels (1=mono, 2=stereo)\n- `-q:a`: Audio quality for VBR (0=best for MP3)\n\n### General Parameters\n- `-i`: Input file\n- `-y`: Overwrite output without asking\n- `-n`: Never overwrite output\n- `-t`: Duration to encode\n- `-ss`: Start time offset\n- `-to`: End time\n- `-vf`: Video filters\n- `-af`: Audio filters\n- `-map`: Stream selection\n- `-metadata`: Set metadata\n- `-f`: Force format\n\n## Troubleshooting\n\n### \"Unknown encoder\" errors\nInstall codec libraries:\n```bash\n# Ubuntu/Debian\nsudo apt-get install ffmpeg libx264-dev libx265-dev libvpx-dev\n\n# Check available encoders\nffmpeg -encoders\n```\n\n### Output compatibility issues\nUse safe defaults for maximum compatibility:\n```bash\nffmpeg -i input.mkv -c:v libx264 -profile:v high -level 4.0 \\\n  -pix_fmt yuv420p -c:a aac -b:a 128k output.mp4\n```\n\n### Performance issues\n- Use hardware acceleration (`-hwaccel`)\n- Choose faster presets (`-preset fast`)\n- Reduce resolution with scale filter\n- Use multiple threads explicitly\n\n### Quality issues\n- Lower CRF value (18-22 for high quality)\n- Use slower preset (`-preset slow`)\n- Use two-pass encoding for better bitrate distribution\n- Match or exceed source bitrate\n\n## Resources\n\n- Official Documentation: https://ffmpeg.org/documentation.html\n- FFmpeg Wiki: https://trac.ffmpeg.org/\n- Codec Guides: https://trac.ffmpeg.org/wiki/Encode\n- Filter Documentation: https://ffmpeg.org/ffmpeg-filters.html\n- GitHub Repository: https://github.com/ffmpeg/ffmpeg\n- Community Examples: https://trac.ffmpeg.org/wiki/\n\n## Implementation Checklist\n\nWhen using FFmpeg:\n\n- [ ] Verify FFmpeg installation (`ffmpeg -version`)\n- [ ] Check available codecs for your use case\n- [ ] Test encoding settings on short clip first\n- [ ] Choose appropriate codec for target platform\n- [ ] Set quality level (CRF or bitrate)\n- [ ] Configure audio codec and bitrate\n- [ ] Apply necessary filters (scale, crop, etc.)\n- [ ] Consider hardware acceleration if available\n- [ ] Verify output quality and file size\n- [ ] Test output compatibility on target devices\n- [ ] Document settings for reproducibility\n- [ ] Create batch scripts for repetitive tasks\n"},"lastSynced":"2026-03-08T02:01:18.959Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Processing Agents needing advanced video and audio conversion capabilities.","zh":"适合需要高级视频和音频转换功能的媒体处理代理。","ja":"高度なビデオとオーディオの変換機能を必要とするメディア処理エージェントに適しています。","ko":"고급 비디오 및 오디오 변환 기능을 필요로 하는 미디어 처리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Procesamiento de Medios que necesitan capacidades avanzadas de conversión de video y audio.","fr":"Parfait pour les Agents de Traitement des Médias ayant besoin de capacités avancées de conversion vidéo et audio.","de":"Perfekt für Medienverarbeitungsagenten, die erweiterte Video- und Audio-Konvertierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Processamento de Mídia que necessitam de capacidades avançadas de conversão de vídeo e áudio.","ru":"Идеально для агентов обработки медиа, требующих продвинутых возможностей преобразования видео и аудио.","ar":"مثالي لعميل معالجة الوسائط التي تحتاج إلى قدرات متقدمة لتحويل الفيديو والصوت."},"recommendation":{"en":"Empowers agents to convert media files between formats like MP4, MKV, and WebM, encode and decode video with codecs such as H.264 and H.265, and process audio files in formats like AAC and MP3, enabling seamless live streaming and multimedia handling.","zh":"赋予代理转换媒体文件的格式，如MP4、MKV和WebM，使用H.264和H.265等编解码器对视频进行编码和解码，并处理AAC和MP3等格式的音频文件，使得直播和多媒体处理变得无缝。","ja":"エージェントがMP4、MKV、WebMなどの形式でメディアファイルを変換し、H.264やH.265などのコーデックを使用してビデオをエンコードおよびデコードし、AACやMP3などの形式のオーディオファイルを処理することを可能にし、ライブストリーミングやマルチメディアの処理を無断に実行できるようにします。","ko":"에이전트가 MP4, MKV, WebM 등의 형식으로 미디어 파일을 변환하고 H.264 및 H.265 등의 코덱을 사용하여 비디오를 인코딩 및 디코딩하며 AAC 및 MP3 등의 형식의 오디오 파일을 처리하여 라이브 스트리밍 및 멀티미디어 처리를 무중단으로 실행할 수 있도록 합니다.","es":"Habilita a los agentes a convertir archivos de medios entre formatos como MP4, MKV y WebM, codificar y decodificar video con codecs como H.264 y H.265, y procesar archivos de audio en formatos como AAC y MP3, lo que permite una transmisión en vivo y un manejo de multimedia sin problemas.","fr":"Permet aux agents de convertir des fichiers multimédias entre des formats tels que MP4, MKV et WebM, de coder et de decoder la vidéo avec des codecs tels que H.264 et H.265, et de traiter des fichiers audio dans des formats tels que AAC et MP3, ce qui permet une diffusion en direct et une gestion multimédia sans problème.","de":"Ermöglicht es Agenten, Mediadateien zwischen Formaten wie MP4, MKV und WebM zu konvertieren, Video mit Codecs wie H.264 und H.265 zu encodieren und zu decodieren und Audiodateien in Formaten wie AAC und MP3 zu verarbeiten, wodurch ein nahtloses Live-Streaming und eine Multimedia-Bearbeitung ermöglicht werden.","pt":"Habilita os agentes a converter arquivos de mídia entre formatos como MP4, MKV e WebM, codificar e decodificar vídeo com codecs como H.264 e H.265, e processar arquivos de áudio em formatos como AAC e MP3, permitindo transmissão ao vivo e manipulação de multimídia sem problemas.","ru":"Наделяет агентов возможностью конвертировать медиафайлы между форматами, такими как MP4, MKV и WebM, кодировать и декодировать видео с кодеками, такими как H.264 и H.265, и обрабатывать аудиофайлы в форматах, таких как AAC и MP3, обеспечивая бесперебойную трансляцию и обработку мультимедиа.","ar":"يمنح الوكلاء khảية تحويل ملفات الوسائط بين صيغ مثل MP4 و MKV و WebM ، وتشفير وفك تشفير الفيديو باستخدام ترميزات مثل H.264 و H.265 ، ومعالجة ملفات الصوت في صيغ مثل AAC و MP3 ، مما يتيح البث المباشر ومعالجة الوسائط المتعددة دون انقطاع."},"useCases":{"en":["Converting video files for cross-platform compatibility","Encoding audio streams for live broadcasting","Processing multimedia files for web-based applications"],"zh":["为跨平台兼容性而转换视频文件","为直播广播而编码音频流","为基于Web的应用程序而处理多媒体文件"],"ja":["クロスプラットフォームの互換性のためにビデオファイルを変換する","ライブ放送のためにオーディオストリームをエンコードする","Webベースのアプリケーションのためにマルチメディアファイルを処理する"],"ko":["크로스 플랫폼 호환성을 위해 비디오 파일을 변환하는 것","라이브 방송을 위해 오디오 스트림을 인코딩하는 것","웹 기반 애플리케이션을 위해 멀티미디어 파일을 처리하는 것"],"es":["Conversión de archivos de video para la compatibilidad entre plataformas","Codificación de flujos de audio para la transmisión en vivo","Procesamiento de archivos multimedia para aplicaciones web"],"fr":["Conversion de fichiers vidéo pour la compatibilité multiplateforme","Codage de flux audio pour la diffusion en direct","Traitement de fichiers multimédia pour les applications Web"],"de":["Konvertierung von Videodateien für die Kompatibilität zwischen Plattformen","Codierung von Audio-Streams für das Live-Broadcasting","Verarbeitung von Multimedia-Dateien für webbasierte Anwendungen"],"pt":["Conversão de arquivos de vídeo para compatibilidade entre plataformas","Codificação de transmissões de áudio para transmissão ao vivo","Processamento de arquivos de multimídia para aplicações baseadas na web"],"ru":["Преобразование видеофайлов для совместимости между платформами","Кодирование аудиопотоков для прямой трансляции","Обработка мультимедиа-файлов для веб-приложений"],"ar":["تحويل ملفات الفيديو لتوافق بين المنصات","تشفير تيارات الصوت للبث المباشر","معالجة ملفات الوسائط المتعددة لالتطبيقات المستندة إلى الويب"]},"limitations":{"en":["Requires command-line interface access","Dependent on system resources for processing power"],"zh":["需要命令行接口访问","依赖系统资源用于处理能力"],"ja":["コマンドラインインターフェースへのアクセスが必要","処理能力にシステムリソースに依存している"],"ko":["명령줄 인터페이스 액세스가 필요함","처리 능력에 시스템 리소스에 의존함"],"es":["Requiere acceso a la interfaz de línea de comandos","Depende de los recursos del sistema para la potencia de procesamiento"],"fr":["Nécessite un accès à l''interface de ligne de commande","Dépend des ressources du système pour la puissance de traitement"],"de":["Benötigt Zugriff auf die Kommandozeilenoberfläche","Hängt von den Systemressourcen für die Verarbeitungsleistung ab"],"pt":["Requer acesso à interface de linha de comando","Dependente de recursos do sistema para processamento"],"ru":["Требует доступа к командной строке","Зависит от системных ресурсов для обработки"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر","يعتمد على موارد النظام لمعالجة"]},"version":4},"contentHash":"6e597ecb0fbe9c1bb76549ce47060fcc4003a6514abffb2600142de216ad4936","qualityScore":65}');
