INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huydepzai121/skill/ffmpeg', 'ffmpeg', 'huydepzai121', 'skill', 'community', 'ffmpeg huydepzai121 skill community ffmpeg is a multimedia framework for handling video, audio, and streams. It benefits developers who need to convert media files, encode/decode video, and process audio FFmpeg 是一个全面的开源多媒体框架，用于处理视频、音频和其他多媒体文件和流媒体。它提供了命令行工具和库用于记录、转换和流媒体音频和视频 FFmpeg は、ビデオ、オーディオ、その他のマルチメディア ファイルとストリームを处理するための包括的なオープンソース マルチメディア フレームワークです。コマンドライン ツールとライブラリを提供して、オーディオとビデオを記録、変換、ストリーミングします FFmpeg는 비디오, 오디오 및 기타 멀티미디어 파일 및 스트림을 처리하기 위한 포괄적인 오픈소스 멀티미디어 프레임워크입니다. 오디오 및 비디오를 기록, 변환 및 스트리밍하기 위한 명령줄 도구 및 라이브러리를 제공합니다 ffmpeg es un framework de multimedia de código abierto que maneja archivos y flujos de video, audio y otros medios. Proporciona herramientas de línea de comandos y bibliotecas para grabar, convertir y transmitir audio y video. ffmpeg est un framework multimédia open-source qui gère les fichiers et les flux de vidéo, d''audio et d''autres médias. Il fournit des outils de ligne de commande et des bibliothèques pour enregistrer, convertir et diffuser de l''audio et de la vidéo. ffmpeg ist ein Open-Source-Multimedia-Framework, das Video-, Audio- und andere Mediadateien und -streams verarbeitet. Es bietet Kommandozeilen-Tools und Bibliotheken zum Aufzeichnen, Konvertieren und Übertragen von Audio und Video. O FFmpeg é uma estrutura de mídia de código aberto que lida com arquivos e fluxos de vídeo, áudio e outros tipos de mídia. Ele fornece ferramentas de linha de comando e bibliotecas para gravar, converter e transmitir áudio e vídeo. FFmpeg - это комплексная открытая мультимедиа-фреймворк, которая обрабатывает видео, аудио и другие мультимедиа файлы и потоки. Он предоставляет командную строку и библиотеки для записи, конвертации и потоковой передачи аудио и видео. FFmpeg هو إطار مفتوح المصدر لملفات الوسائط المتعددة التي تتعامل مع ملفات الفيديو والصوت وغيرها من أنواع الوسائط المتعددة. يقدم أدوات سطر الأوامر والمكتبات لتسجيل وتحويل وبث الصوت والفيديو. how to use ffmpeg ffmpeg alternative ffmpeg install ffmpeg vs FFprobe what is ffmpeg ffmpeg setup guide ffmpeg command-line tools ffmpeg video encoding ffmpeg audio processing FFmpeg 视频处理 音频处理 多媒体框架 命令行工具 流媒体处理 视频格式转换 音频编码 Converts media files between formats like MP4, MKV, WebM, and AVI Encodes/decodes video with codecs such as H.264, H.265, VP9, and AV1 Processes audio files with formats like AAC, MP3, FLAC, and Opus Supports live streaming for real-time multimedia applications ffmpeg is a comprehensive open-source multimedia framework for recording, converting, and streaming audio and video');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LeighAtkins/OpenPaint/Writing Hookify Rules', 'community', 'LeighAtkins', 'OpenPaint', 'LeighAtkins/OpenPaint', 'Writing Hookify Rules', 0, 0, 65, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:47.796Z', 'cf7a6a0b92092f44c6532bd9af7189748a9c3b4d044005418230b08cc99ac55c', '{"id":"LeighAtkins/OpenPaint/Writing Hookify Rules","name":"Writing Hookify Rules","description":{"en":"Writing Hookify Rules is a skill for creating markdown files with YAML frontmatter to define patterns and messages. It benefits developers working with AI agents and Claude.","zh":"Hookify 规则用于定义模式和消息，存储在 `.claude/hookify.{rule-name}.local.md` 文件中","ja":"Hookify ルールは、パターンとメッセージを定義し、`.claude/hookify.{rule-name}.local.md` ファイルに保存されます","ko":"Hookify 규칙은 패턴과 메시지를 정의하며 `.claude/hookify.{rule-name}.local.md` 파일에 저장됩니다","es":"Las reglas Hookify son archivos markdown con frontmatter YAML que definen patrones y mensajes personalizados para mejorar la productividad del desarrollador","fr":"Les règles Hookify sont des fichiers markdown avec frontmatter YAML qui définissent des modèles et des messages personnalisés pour améliorer la productivité des développeurs","de":"Hookify-Regeln sind markdown-Dateien mit YAML-Frontmatter, die Muster und benutzerdefinierte Nachrichten definieren, um die Produktivität der Entwickler zu verbessern","pt":"As regras Hookify são arquivos markdown com frontmatter YAML que definem padrões e mensagens para serem exibidas quando esses padrões são detectados.","ru":"Правила Hookify представляют собой файлы markdown с YAML-заголовком, определяющие шаблоны и сообщения, отображаемые при совпадении этих шаблонов.","ar":"قواعد Hookify هي ملفات markdown مع YAML- заголовок التي تحدد أنماطاً ورسائل لتعرض عند مطابقة هذه الأنماط."},"seo":{"title":{"en":"Writing Hookify Rules: Setup Guide for AI Agents","zh":"Hookify 规则编写最佳实践","ja":"Hookify ルールの設定ガイド - AIエージェント","ko":"Hookify 규칙 작성 가이드 - AI 도구","es":"Guía de configuración de reglas Hookify para desarrolladores","fr":"Guide de mise en place des règles Hookify pour les dévelo...","de":"Einrichtungsleitfaden für Hookify-Regeln für Entwickler","pt":"Guia de Configuração de Regras Hookify para Desenvolvedores","ru":"Настройка Правил Hookify: Лучшие Практики для Разработчик...","ar":"دليل إعداد قواعد Hookify لمنشئي التطبيقات الذكية"},"description":{"en":"Discover how to create custom Hookify rules with YAML frontmatter and regex patterns. Learn to trigger messages with markdown formatting and warnings.","zh":"学习如何编写 Hookify 规则以定义模式和消息。了解规则文件格式和 YAML 前置内容","ja":"Hookify ルールを書く方法を学び、パターンとメッセージを定義しよう。ルールファイル形式と YAML フロントマターについて","ko":"Hookify 규칙을 작성하여 패턴과 메시지를 정의하는 방법을 배워보세요. 규칙 파일 형식과 YAML 전면 물질에 대해 알아보세요","es":"Aprende a crear reglas Hookify personalizadas con YAML y markdown para mejorar la productividad del desarrollador","fr":"Découvrez comment créer des règles Hookify personnalisées avec YAML et markdown pour améliorer la productivité des développeurs","de":"Erfahren Sie, wie Sie benutzerdefinierte Hookify-Regeln mit YAML und markdown erstellen, um die Produktivität der Entwickler zu verbessern","pt":"Aprenda a criar regras Hookify personalizadas com markdown e YAML para automatizar tarefas e melhorar a produtividade","ru":"Откройте для себя возможности правил Hookify: автоматизируйте задачи и повышайте производительность с помощью markdown и YAML","ar":"اكتشف كيفية إنشاء قواعد Hookify المخصصة باستخدام markdown و YAML لتحسين الإنتاجية وتحقيق التutomatização"},"definition":{"en":"Writing Hookify Rules is a technique for defining patterns to watch for and messages to show when those patterns match using markdown files with YAML frontmatter.","zh":"Hookify 规则是带有 YAML 前置内容的 markdown 文件，用于定义模式和消息","ja":"Hookify ルールは、YAML フロントマターを持つ Markdown ファイルで、パターンとメッセージを定義します","ko":"Hookify 규칙은 YAML 전면 물질을 갖는 마크다운 파일로 패턴과 메시지를 정의합니다","es":"Una regla Hookify es un archivo markdown con frontmatter YAML que define patrones y mensajes para mejorar la productividad","fr":"Une règle Hookify est un fichier markdown avec frontmatter YAML qui définit des modèles et des messages pour améliorer la productivité","de":"Eine Hookify-Regel ist eine markdown-Datei mit YAML-Frontmatter, die Muster und Nachrichten definiert, um die Produktivität zu verbessern","pt":"Regras Hookify são arquivos markdown que definem padrões e ações para automatizar tarefas","ru":"Правила Hookify - это файлы markdown, определяющие шаблоны и действия для автоматизации задач","ar":"قواعد Hookify هي ملفات markdown التي تحدد أنماطاً وإجراءات لتautomatização المهام"},"features":{"en":["Supports YAML frontmatter for rule definition","Utilizes regex patterns for matching","Triggers messages with markdown formatting and warnings","Stores rules in .claude/hookify.{rule-name}.local.md files","Allows for event specification using bash, file, stop, prompt, or all"],"zh":["支持 YAML 前置内容","定义模式和消息","存储在 `.claude/hookify.{rule-name}.local.md` 文件中","支持正则表达式模式","支持 markdown 格式的消息"],"ja":["YAML フロントマターをサポート","パターンとメッセージを定義","`.claude/hookify.{rule-name}.local.md` ファイルに保存","正規表現パターンをサポート","Markdown 形式のメッセージをサポート"],"ko":["YAML 전면 물질 지원","패턴과 메시지를 정의","`.claude/hookify.{rule-name}.local.md` 파일에 저장","정규 표현식 패턴 지원","마크다운 형식의 메시지를 지원"],"es":["Archivos markdown con frontmatter YAML","Patrones personalizados con expresiones regulares","Mensajes personalizados con formato markdown","Compatibilidad con eventos como bash, file, stop y prompt","Almacenamiento de reglas en archivos `.claude/hookify.{rule-name}.local.md`"],"fr":["Fichiers markdown avec frontmatter YAML","Modèles personnalisés avec expressions régulières","Messages personnalisés avec format markdown","Compatibilité avec des événements tels que bash, file, stop et prompt","Stockage des règles dans des fichiers `.claude/hookify.{rule-name}.local.md`"],"de":["Markdown-Dateien mit YAML-Frontmatter","Benutzerdefinierte Muster mit regulären Ausdrücken","Benutzerdefinierte Nachrichten mit markdown-Format","Kompatibilität mit Ereignissen wie bash, file, stop und prompt","Speicherung von Regeln in Dateien `.claude/hookify.{rule-name}.local.md`"],"pt":["Criação de regras personalizadas com markdown e YAML","Definição de padrões e mensagens para serem exibidas","Armazenamento de regras em arquivos `.claude/hookify.{rule-name}.local.md`","Suporte a regex para padrões complexos","Integração com eventos como bash, file, stop, prompt e all"],"ru":["Создание пользовательских правил с помощью markdown и YAML","Определение шаблонов и сообщений для отображения","Хранение правил в файлах `.claude/hookify.{rule-name}.local.md`","Поддержка regex для сложных шаблонов","Интеграция с событиями như bash, file, stop, prompt и all"],"ar":["إنشاء قواعد مخصصة باستخدام markdown و YAML","تحديد أنماط ورسائل لتعرض","تخزين القواعد في ملفات `.claude/hookify.{rule-name}.local.md`","دعم regex لأنماط معقدة","تكامل مع أحداث مثل bash و file و stop و prompt و all"]},"keywords":{"en":["how to use Writing Hookify Rules","what is Writing Hookify Rules","Writing Hookify Rules alternative","Writing Hookify Rules setup guide","Writing Hookify Rules install","yaml frontmatter tutorial","regex pattern matching examples"],"zh":["Hookify 规则","AI 工具","YAML 前置内容","markdown 文件","正则表达式模式","消息定义","规则文件格式"],"ja":["Hookify ルール","AIエージェント","YAML フロントマター","Markdown ファイル","正規表現パターン","メッセージ定義","ルールファイル形式"],"ko":["Hookify 규칙","AI 도구","YAML 전면 물질","마크다운 파일","정규 표현식 패턴","메시지 정의","규칙 파일 형식"],"es":["reglas Hookify","desarrollo de reglas Hookify","yaml frontmatter","markdown para desarrolladores","expresiones regulares en Hookify","Herramientas de productividad para desarrolladores","Integración de AI en el desarrollo"],"fr":["règles Hookify","développement de règles Hookify","frontmatter yaml","markdown pour les développeurs","expressions régulières dans Hookify","Outils de productivité pour les développeurs","Intégration de l''IA dans le développement"],"de":["Hookify-Regeln","Entwicklung von Hookify-Regeln","yaml-Frontmatter","markdown für Entwickler","reguläre Ausdrücke in Hookify","Produktivitätstools für Entwickler","Integration von KI in der Entwicklung"],"pt":["regras hookify","markdown","yaml","automatização de tarefas","desenvolvimento de aplicativos","integração com eventos","regex","programação","desenvolvedores"],"ru":["правила hookify","markdown","yaml","автоматизация задач","разработка приложений","интеграция с событиями","regex","программирование","разработчики","ИИ Агенты"],"ar":["قواعد hookify","markdown","yaml","تautomatização المهام","تنمية التطبيقات","تكامل مع الأحداث","regex","برمجة","مطورون","وكلاء الذكاء الاصطناعي"]}},"owner":"LeighAtkins","repo":"OpenPaint","repoPath":"LeighAtkins/OpenPaint","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"Writing Hookify Rules","description":"This skill should be used when the user asks to create a hookify rule, write a hook rule, configure hookify, add a hookify rule, or needs guidance on hookify rule syntax and patterns.","version":"0.1.0","bodyPreview":"# Writing Hookify Rules\n\n## Overview\n\nHookify rules are markdown files with YAML frontmatter that define patterns to watch for and messages to show when those patterns match. Rules are stored in `.claude/hookify.{rule-name}.local.md` files.\n\n## Rule File Format\n\n### Basic Structure\n\n```markdown\n---\nname: rule-identifier\nenabled: true\nevent: bash|file|stop|prompt|all\npattern: regex-pattern-here\n---\n\nMessage to show Claude when this rule triggers.\nCan include markdown formatting, warnings, suggest","body":"# Writing Hookify Rules\n\n## Overview\n\nHookify rules are markdown files with YAML frontmatter that define patterns to watch for and messages to show when those patterns match. Rules are stored in `.claude/hookify.{rule-name}.local.md` files.\n\n## Rule File Format\n\n### Basic Structure\n\n```markdown\n---\nname: rule-identifier\nenabled: true\nevent: bash|file|stop|prompt|all\npattern: regex-pattern-here\n---\n\nMessage to show Claude when this rule triggers.\nCan include markdown formatting, warnings, suggestions, etc.\n```\n\n### Frontmatter Fields\n\n**name** (required): Unique identifier for the rule\n- Use kebab-case: `warn-dangerous-rm`, `block-console-log`\n- Be descriptive and action-oriented\n- Start with verb: warn, prevent, block, require, check\n\n**enabled** (required): Boolean to activate/deactivate\n- `true`: Rule is active\n- `false`: Rule is disabled (won''t trigger)\n- Can toggle without deleting rule\n\n**event** (required): Which hook event to trigger on\n- `bash`: Bash tool commands\n- `file`: Edit, Write, MultiEdit tools\n- `stop`: When agent wants to stop\n- `prompt`: When user submits a prompt\n- `all`: All events\n\n**action** (optional): What to do when rule matches\n- `warn`: Show message but allow operation (default)\n- `block`: Prevent operation (PreToolUse) or stop session (Stop events)\n- If omitted, defaults to `warn`\n\n**pattern** (simple format): Regex pattern to match\n- Used for simple single-condition rules\n- Matches against command (bash) or new_text (file)\n- Python regex syntax\n\n**Example:**\n```yaml\nevent: bash\npattern: rm\\s+-rf\n```\n\n### Advanced Format (Multiple Conditions)\n\nFor complex rules with multiple conditions:\n\n```markdown\n---\nname: warn-env-file-edits\nenabled: true\nevent: file\nconditions:\n  - field: file_path\n    operator: regex_match\n    pattern: \\.env$\n  - field: new_text\n    operator: contains\n    pattern: API_KEY\n---\n\nYou''re adding an API key to a .env file. Ensure this file is in .gitignore!\n```\n\n**Condition fields:**\n- `field`: Which field to check\n  - For bash: `command`\n  - For file: `file_path`, `new_text`, `old_text`, `content`\n- `operator`: How to match\n  - `regex_match`: Regex pattern matching\n  - `contains`: Substring check\n  - `equals`: Exact match\n  - `not_contains`: Substring must NOT be present\n  - `starts_with`: Prefix check\n  - `ends_with`: Suffix check\n- `pattern`: Pattern or string to match\n\n**All conditions must match for rule to trigger.**\n\n## Message Body\n\nThe markdown content after frontmatter is shown to Claude when the rule triggers.\n\n**Good messages:**\n- Explain what was detected\n- Explain why it''s problematic\n- Suggest alternatives or best practices\n- Use formatting for clarity (bold, lists, etc.)\n\n**Example:**\n```markdown\n⚠️ **Console.log detected!**\n\nYou''re adding console.log to production code.\n\n**Why this matters:**\n- Debug logs shouldn''t ship to production\n- Console.log can expose sensitive data\n- Impacts browser performance\n\n**Alternatives:**\n- Use a proper logging library\n- Remove before committing\n- Use conditional debug builds\n```\n\n## Event Type Guide\n\n### bash Events\n\nMatch Bash command patterns:\n\n```markdown\n---\nevent: bash\npattern: sudo\\s+|rm\\s+-rf|chmod\\s+777\n---\n\nDangerous command detected!\n```\n\n**Common patterns:**\n- Dangerous commands: `rm\\s+-rf`, `dd\\s+if=`, `mkfs`\n- Privilege escalation: `sudo\\s+`, `su\\s+`\n- Permission issues: `chmod\\s+777`, `chown\\s+root`\n\n### file Events\n\nMatch Edit/Write/MultiEdit operations:\n\n```markdown\n---\nevent: file\npattern: console\\.log\\(|eval\\(|innerHTML\\s*=\n---\n\nPotentially problematic code pattern detected!\n```\n\n**Match on different fields:**\n```markdown\n---\nevent: file\nconditions:\n  - field: file_path\n    operator: regex_match\n    pattern: \\.tsx?$\n  - field: new_text\n    operator: regex_match\n    pattern: console\\.log\\(\n---\n\nConsole.log in TypeScript file!\n```\n\n**Common patterns:**\n- Debug code: `console\\.log\\(`, `debugger`, `print\\(`\n- Security risks: `eval\\(`, `innerHTML\\s*=`, `dangerouslySetInnerHTML`\n- Sensitive files: `\\.env$`, `credentials`, `\\.pem$`\n- Generated files: `node_modules/`, `dist/`, `build/`\n\n### stop Events\n\nMatch when agent wants to stop (completion checks):\n\n```markdown\n---\nevent: stop\npattern: .*\n---\n\nBefore stopping, verify:\n- [ ] Tests were run\n- [ ] Build succeeded\n- [ ] Documentation updated\n```\n\n**Use for:**\n- Reminders about required steps\n- Completion checklists\n- Process enforcement\n\n### prompt Events\n\nMatch user prompt content (advanced):\n\n```markdown\n---\nevent: prompt\nconditions:\n  - field: user_prompt\n    operator: contains\n    pattern: deploy to production\n---\n\nProduction deployment checklist:\n- [ ] Tests passing?\n- [ ] Reviewed by team?\n- [ ] Monitoring ready?\n```\n\n## Pattern Writing Tips\n\n### Regex Basics\n\n**Literal characters:** Most characters match themselves\n- `rm` matches \"rm\"\n- `console.log` matches \"console.log\"\n\n**Special characters need escaping:**\n- `.` (any char) → `\\.` (literal dot)\n- `(` `)` → `\\(` `\\)` (literal parens)\n- `[` `]` → `\\[` `\\]` (literal brackets)\n\n**Common metacharacters:**\n- `\\s` - whitespace (space, tab, newline)\n- `\\d` - digit (0-9)\n- `\\w` - word character (a-z, A-Z, 0-9, _)\n- `.` - any character\n- `+` - one or more\n- `*` - zero or more\n- `?` - zero or one\n- `|` - OR\n\n**Examples:**\n```\nrm\\s+-rf         Matches: rm -rf, rm  -rf\nconsole\\.log\\(   Matches: console.log(\n(eval|exec)\\(    Matches: eval( or exec(\nchmod\\s+777      Matches: chmod 777, chmod  777\nAPI_KEY\\s*=      Matches: API_KEY=, API_KEY =\n```\n\n### Testing Patterns\n\nTest regex patterns before using:\n\n```bash\npython3 -c \"import re; print(re.search(r''your_pattern'', ''test text''))\"\n```\n\nOr use online regex testers (regex101.com with Python flavor).\n\n### Common Pitfalls\n\n**Too broad:**\n```yaml\npattern: log    # Matches \"log\", \"login\", \"dialog\", \"catalog\"\n```\nBetter: `console\\.log\\(|logger\\.`\n\n**Too specific:**\n```yaml\npattern: rm -rf /tmp  # Only matches exact path\n```\nBetter: `rm\\s+-rf`\n\n**Escaping issues:**\n- YAML quoted strings: `\"pattern\"` requires double backslashes `\\\\s`\n- YAML unquoted: `pattern: \\s` works as-is\n- **Recommendation**: Use unquoted patterns in YAML\n\n## File Organization\n\n**Location:** All rules in `.claude/` directory\n**Naming:** `.claude/hookify.{descriptive-name}.local.md`\n**Gitignore:** Add `.claude/*.local.md` to `.gitignore`\n\n**Good names:**\n- `hookify.dangerous-rm.local.md`\n- `hookify.console-log.local.md`\n- `hookify.require-tests.local.md`\n- `hookify.sensitive-files.local.md`\n\n**Bad names:**\n- `hookify.rule1.local.md` (not descriptive)\n- `hookify.md` (missing .local)\n- `danger.local.md` (missing hookify prefix)\n\n## Workflow\n\n### Creating a Rule\n\n1. Identify unwanted behavior\n2. Determine which tool is involved (Bash, Edit, etc.)\n3. Choose event type (bash, file, stop, etc.)\n4. Write regex pattern\n5. Create `.claude/hookify.{name}.local.md` file in project root\n6. Test immediately - rules are read dynamically on next tool use\n\n### Refining a Rule\n\n1. Edit the `.local.md` file\n2. Adjust pattern or message\n3. Test immediately - changes take effect on next tool use\n\n### Disabling a Rule\n\n**Temporary:** Set `enabled: false` in frontmatter\n**Permanent:** Delete the `.local.md` file\n\n## Examples\n\nSee `${CLAUDE_PLUGIN_ROOT}/examples/` for complete examples:\n- `dangerous-rm.local.md` - Block dangerous rm commands\n- `console-log-warning.local.md` - Warn about console.log\n- `sensitive-files-warning.local.md` - Warn about editing .env files\n\n## Quick Reference\n\n**Minimum viable rule:**\n```markdown\n---\nname: my-rule\nenabled: true\nevent: bash\npattern: dangerous_command\n---\n\nWarning message here\n```\n\n**Rule with conditions:**\n```markdown\n---\nname: my-rule\nenabled: true\nevent: file\nconditions:\n  - field: file_path\n    operator: regex_match\n    pattern: \\.ts$\n  - field: new_text\n    operator: contains\n    pattern: any\n---\n\nWarning message\n```\n\n**Event types:**\n- `bash` - Bash commands\n- `file` - File edits\n- `stop` - Completion checks\n- `prompt` - User input\n- `all` - All events\n\n**Field options:**\n- Bash: `command`\n- File: `file_path`, `new_text`, `old_text`, `content`\n- Prompt: `user_prompt`\n\n**Operators:**\n- `regex_match`, `contains`, `equals`, `not_contains`, `starts_with`, `ends_with`\n"},"lastSynced":"2026-03-08T02:01:47.796Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude, AutoGPT, and LangChain needing customized pattern detection and response capabilities.","zh":"非常适合需要自定义模式检测和响应能力的AI代理，如Claude、AutoGPT和LangChain。","ja":"Claude、AutoGPT、LangChainなどのカスタマイズされたパターン検出および応答機能を必要とするAIエージェントに最適です。","ko":"Claude, AutoGPT, LangChain 등의 맞춤형 패턴 감지 및 응답 기능이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA como Claude, AutoGPT y LangChain que necesitan capacidades de detección y respuesta de patrones personalizados.","fr":"Parfait pour les agents IA comme Claude, AutoGPT et LangChain nécessitant des capacités de détection et de réponse de modèles personnalisés.","de":"Perfekt für KI-Agents wie Claude, AutoGPT und LangChain, die benutzerdefinierte Mustererkennungs- und Reaktionsfähigkeiten benötigen.","pt":"Perfeito para Agentes de IA como Claude, AutoGPT e LangChain que necessitam de capacidades de detecção e resposta de padrões personalizados.","ru":"Идеально для агентов ИИ, таких как Claude, AutoGPT и LangChain, которые требуют настраиваемых возможностей обнаружения и реагирования на шаблоны.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude و AutoGPT و LangChain الذين يحتاجون إلى قدرات الكشف عن الأنماط والاستجابة المخصصة."},"recommendation":{"en":"Empowers agents to define custom patterns using regex and trigger informative messages with markdown formatting, enhancing user interaction with features like YAML frontmatter and event-based triggers such as bash, file, stop, prompt, or all events.","zh":"赋予代理定义使用正则表达式的自定义模式，并使用Markdown格式触发信息消息，通过YAML前置内容和基于事件的触发器（如bash、文件、停止、提示或所有事件）等功能增强用户交互。","ja":"エージェントが正規表現を使用してカスタムパターンを定義し、Markdownフォーマットで情報メッセージをトリガーすることを可能にし、YAMLフロントマターとbash、ファイル、停止、プロンプト、またはすべてのイベントなどのイベントベースのトリガーなどの機能でユーザーとのやり取りを強化します。","ko":"에이전트가 정규식을 사용하여 사용자 지정 패턴을 정의하고 Markdown 형식으로 정보 메시지를 트리거하는 것을 가능하게 하며, YAML 프론트매터와 bash, 파일, 중지, 프롬프트 또는 모든 이벤트와 같은 이벤트 기반 트리거와 같은 기능으로 사용자 상호 작용을 향상시킵니다.","es":"Habilita a los agentes a definir patrones personalizados utilizando regex y desencadenar mensajes informativos con formato markdown, mejorando la interacción del usuario con características como YAML frontmatter y desencadenadores basados en eventos como bash, archivo, detener, prompt o todos los eventos.","fr":"Permet aux agents de définir des modèles personnalisés en utilisant regex et de déclencher des messages informatifs avec une mise en forme markdown, améliorant l''interaction utilisateur avec des fonctionnalités comme YAML frontmatter et des déclencheurs basés sur des événements tels que bash, fichier, arrêter, invite ou tous les événements.","de":"Ermöglicht es Agents, benutzerdefinierte Muster mit regex zu definieren und informative Nachrichten mit markdown-Formatierung auszulösen, wodurch die Benutzerinteraktion mit Funktionen wie YAML-Frontmatter und ereignisbasierten Auslösern wie bash, Datei, Stop, Prompt oder allen Ereignissen verbessert wird.","pt":"Habilita os agentes a definir padrões personalizados usando regex e acionar mensagens informativas com formatação markdown, melhorando a interação do usuário com recursos como YAML frontmatter e gatilhos baseados em eventos, como bash, arquivo, parar, prompt ou todos os eventos.","ru":"Позволяет агентам определять пользовательские шаблоны с помощью regex и запускать информативные сообщения с форматированием markdown, улучшая взаимодействие пользователя с функциями, такими как YAML frontmatter и событийные триггеры, такие как bash, файл, остановка, запрос или все события.","ar":"يمكن العميل من تعريف الأنماط المخصصة باستخدام regex وتفعيل رسائل إعلامية ذات تنسيق markdown، مما يعزز تفاعل المستخدم مع الميزات مثل YAML frontmatter والمتغيرات القائمة على الأحداث مثل bash وملف وايقاف وطلب أو جميع الأحداث."},"useCases":{"en":["Defining custom regex patterns for event triggers","Generating informative messages with markdown support","Customizing agent responses based on specific event types"],"zh":["为事件触发器定义自定义正则表达式模式","生成支持Markdown的信息消息","根据特定事件类型自定义代理响应"],"ja":["イベントトリガー用のカスタム正規表現パターンを定義する","Markdownをサポートする情報メッセージを生成する","特定のイベントタイプに基づいてエージェントの応答をカスタマイズする"],"ko":["이벤트 트리거를 위한 사용자 지정 정규식 패턴 정의","Markdown을 지원하는 정보 메시지 생성","특정 이벤트 유형에 따라 에이전트 응답 사용자 지정"],"es":["Definir patrones de regex personalizados para desencadenadores de eventos","Generar mensajes informativos con soporte de markdown","Personalizar respuestas de agentes en función de tipos de eventos específicos"],"fr":["Définir des modèles regex personnalisés pour les déclencheurs d''événements","Générer des messages informatifs avec une prise en charge de markdown","Personnaliser les réponses des agents en fonction de types d''événements spécifiques"],"de":["Benutzerdefinierte regex-Muster für Ereignis-Trigger definieren","Informative Nachrichten mit markdown-Unterstützung generieren","Agenten-Antworten anhand spezifischer Ereignistypen anpassen"],"pt":["Definir padrões regex personalizados para gatilhos de eventos","Gerar mensagens informativas com suporte a markdown","Personalizar respostas do agente com base em tipos de eventos específicos"],"ru":["Определение пользовательских шаблонов regex для триггеров событий","Генерация информативных сообщений с поддержкой markdown","Настройка ответов агента на основе конкретных типов событий"],"ar":["تعريف أنماط regex مخصصة لمتغيرات الأحداث","توليد رسائل إعلامية مدعومة بتنسيق markdown","تخصيص استجابات العميل بناءً على أنواع الأحداث المحددة"]},"limitations":{"en":["Requires markdown file creation with YAML frontmatter","Dependent on Claude or similar AI agent infrastructure"],"zh":["需要创建带有YAML前置内容的Markdown文件","依赖于Claude或类似的AI代理基础设施"],"ja":["YAMLフロントマターを含むMarkdownファイルの作成が必要","Claudeまたは同等のAIエージェントインフラストラクチャに依存する"],"ko":["YAML 프론트매터를 포함하는 Markdown 파일 생성이 필요","Claude 또는 유사한 AI 에이전트 인프라에 의존"],"es":["Requiere la creación de un archivo markdown con YAML frontmatter","Dependiente de la infraestructura de agentes de IA como Claude o similar"],"fr":["Nécessite la création d''un fichier markdown avec YAML frontmatter","Dépendante de l''infrastructure d''agents IA tels que Claude ou similaire"],"de":["Erfordert die Erstellung einer markdown-Datei mit YAML-Frontmatter","Abhängig von der Infrastruktur von KI-Agents wie Claude oder ähnlich"],"pt":["Exige a criação de arquivos markdown com YAML frontmatter","Dependente da infraestrutura do agente de IA Claude ou similar"],"ru":["Требует создания файлов markdown с YAML frontmatter","Зависит от инфраструктуры агента ИИ Claude или аналогичной"],"ar":["يتطلب إنشاء ملفات markdown مع YAML frontmatter","يعتمد على بنية تحتية للعميل الذكاء الاصطناعي Claude أو مشابهة"]},"version":4},"contentHash":"cf7a6a0b92092f44c6532bd9af7189748a9c3b4d044005418230b08cc99ac55c","qualityScore":65}');
