INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LeighAtkins/OpenPaint/Writing Hookify Rules', 'Writing Hookify Rules', 'LeighAtkins', 'OpenPaint', 'community', 'Writing Hookify Rules LeighAtkins OpenPaint community Writing Hookify Rules is a skill for creating markdown files with YAML frontmatter to define patterns and messages. It benefits developers working with AI agents and Claude. Hookify 规则用于定义模式和消息，存储在 `.claude/hookify.{rule-name}.local.md` 文件中 Hookify ルールは、パターンとメッセージを定義し、`.claude/hookify.{rule-name}.local.md` ファイルに保存されます Hookify 규칙은 패턴과 메시지를 정의하며 `.claude/hookify.{rule-name}.local.md` 파일에 저장됩니다 Las reglas Hookify son archivos markdown con frontmatter YAML que definen patrones y mensajes personalizados para mejorar la productividad del desarrollador Les règles Hookify sont des fichiers markdown avec frontmatter YAML qui définissent des modèles et des messages personnalisés pour améliorer la productivité des développeurs Hookify-Regeln sind markdown-Dateien mit YAML-Frontmatter, die Muster und benutzerdefinierte Nachrichten definieren, um die Produktivität der Entwickler zu verbessern As regras Hookify são arquivos markdown com frontmatter YAML que definem padrões e mensagens para serem exibidas quando esses padrões são detectados. Правила Hookify представляют собой файлы markdown с YAML-заголовком, определяющие шаблоны и сообщения, отображаемые при совпадении этих шаблонов. قواعد Hookify هي ملفات markdown مع YAML- заголовок التي تحدد أنماطاً ورسائل لتعرض عند مطابقة هذه الأنماط. how to use Writing Hookify Rules what is Writing Hookify Rules Writing Hookify Rules alternative Writing Hookify Rules setup guide Writing Hookify Rules install yaml frontmatter tutorial regex pattern matching examples Hookify 规则 AI 工具 YAML 前置内容 markdown 文件 正则表达式模式 消息定义 规则文件格式 Supports YAML frontmatter for rule definition Utilizes regex patterns for matching Triggers messages with markdown formatting and warnings Stores rules in .claude/hookify.{rule-name}.local.md files Allows for event specification using bash, file, stop, prompt, or all Writing Hookify Rules is a technique for defining patterns to watch for and messages to show when those patterns match using markdown files with YAML frontmatter.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('avvale/aurora-back/aurora-tools-scripts', 'community', 'avvale', 'aurora-back', 'avvale/aurora-back', 'aurora-tools-scripts', 0, 0, 65, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:51.736Z', 'acf3f5addc4461596c12ea733111594180133540c1162af9598b4035fb592178', '{"id":"avvale/aurora-back/aurora-tools-scripts","name":"aurora-tools-scripts","description":{"en":"The aurora-tools-scripts skill helps developers manage database schema modifications, such as ALTER TABLE and CREATE/DROP INDEX, in conjunction with the postgresql skill.","zh":"Aurora Tools Scripts是一个用于数据库迁移和schema变化的技能，需要与postgresql技能一起使用","ja":"Aurora Tools Scriptsはデータベーススキーマ変更用のスキルで、postgresqlスキルと組み合わせて使用する必要があります","ko":"Aurora Tools Scripts는 데이터베이스 마이그레이션과 스키마 변경을 위한 스킬로, postgresql 스킬과 함께 사용되어야 합니다","es":"aurora-tools-scripts es una habilidad que define dónde colocar el código para modificaciones de esquema de base de datos y procedimientos con PostgreSQL","fr":"aurora-tools-scripts est une compétence qui définit où placer le code pour les modifications de schéma de base de données et les procédures avec PostgreSQL","de":"aurora-tools-scripts ist eine Fähigkeit, die bestimmt, wo der Code für Datenbankschemamodifikationen und Prozeduren mit PostgreSQL platziert werden soll","pt":"O aurora-tools-scripts é uma ferramenta para gerenciar migrações de banco de dados com o postgresql. Use para alterar esquemas de banco de dados de forma eficiente","ru":"ИИ Агенты aurora-tools-scripts - это инструмент для управления миграциями базы данных с помощью postgresql. Используйте для эффективного изменения схем базы данных","ar":"أدوات aurora-tools-scripts هي أداة لإدارة مهاجرة قواعد البيانات مع postgresql. استخدمها لتعديل مخططات قواعد البيانات بفعالية"},"seo":{"title":{"en":"aurora-tools-scripts: Database Schema Management Setup Gu...","zh":"Aurora Tools Scripts Setup Guide - AIエージェント数据库迁移","ja":"Aurora Tools Scripts ベストプラクティス - AIエージェントを使用したデータベーススキーマ変更","ko":"Aurora Tools Scripts 사용법 - AI 에이전트를 이용한 데이터베이스 마이그레이션","es":"Guía de configuración de aurora-tools-scripts para desarr...","fr":"Guide de mise en place d''aurora-tools-scripts pour les dé...","de":"Einrichtungsleitfaden für aurora-tools-scripts-Entwickler","pt":"Guia de Configuração do aurora-tools-scripts para Migraçõ...","ru":"Настройка ИИ Агентов aurora-tools-scripts для Базы Данных","ar":"دليل إعداد أدوات aurora-tools-scripts لمهاجرة قواعد البيانات"},"description":{"en":"Discover how to use aurora-tools-scripts with postgresql for efficient database schema modifications - learn more and get started today!","zh":"了解Aurora Tools Scripts的技术细节，包括数据库迁移和schema变化，使用postgresql技能进行SQL编写","ja":"Aurora Tools Scriptsの機能とベストプラクティスを学び、postgresqlスキルと組み合わせてデータベーススキーマ変更を実現","ko":"Aurora Tools Scripts의 기능과 사용법을 익히고, postgresql 스킬을 활용하여 데이터베이스 마이그레이션을 수행하십시오","es":"Aprende a utilizar aurora-tools-scripts con PostgreSQL para modificaciones de esquema de base de datos y procedimientos","fr":"Découvrez comment utiliser aurora-tools-scripts avec PostgreSQL pour les modifications de schéma de base de données et les procédures","de":"Erfahren Sie, wie Sie aurora-tools-scripts mit PostgreSQL für Datenbankschemamodifikationen und Prozeduren verwenden","pt":"Aprenda a usar o aurora-tools-scripts com o skill postgresql para modificar esquemas de banco de dados de forma eficiente","ru":"Используйте ИИ Агенты aurora-tools-scripts с навыком postgresql для эффективного изменения схем базы данных","ar":"تعلم كيفية استخدام أدوات aurora-tools-scripts مع مهارة postgresql لتعديل مخططات قواعد البيانات بفعالية"},"definition":{"en":"aurora-tools-scripts is a skill that defines where to put database code, such as migrations.ts vs procedures.ts, for efficient schema changes.","zh":"Aurora Tools Scripts是一种AIエージェント技能，用于定义数据库迁移和schema变化的代码位置","ja":"Aurora Tools ScriptsはAIエージェントのスキルで、データベーススキーマ変更用のコードの位置を定義するために使用されます","ko":"Aurora Tools Scripts는 AI 에이전트의 스킬로, 데이터베이스 마이그레이션과 스키마 변경을 위한 코드의 위치를 정의하는 데 사용됩니다","es":"aurora-tools-scripts es una herramienta de inteligencia artificial que ayuda a los desarrolladores a gestionar modificaciones de esquema de base de datos","fr":"aurora-tools-scripts est un outil d''intelligence artificielle qui aide les développeurs à gérer les modifications de schéma de base de données","de":"aurora-tools-scripts ist ein KI-Tool, das Entwicklern hilft, Datenbankschemamodifikationen zu verwalten","pt":"O que é aurora-tools-scripts? É uma ferramenta para gerenciar migrações de banco de dados com o postgresql","ru":"Что такое ИИ Агенты aurora-tools-scripts? Это инструмент для управления миграциями базы данных с помощью postgresql","ar":"ما هي أدوات aurora-tools-scripts؟ هي أداة لإدارة مهاجرة قواعد البيانات مع postgresql"},"features":{"en":["Defines WHERE to put code for database schema modifications","Works in conjunction with the postgresql skill for SQL statement writing","Supports migrations.ts for schema changes, including ALTER TABLE and CREATE/DROP INDEX","Requires companion use with the postgresql skill for optimal functionality","Helps with database schema modifications, such as adding or dropping columns","Uses migrations.ts and procedures.ts for organized code management"],"zh":["定义数据库迁移和schema变化的代码位置","与postgresql技能一起使用，进行SQL编写","支持ALTER TABLE、CREATE/DROP INDEX等数据库操作","用于migrations.ts和procedures.ts代码的管理"],"ja":["データベーススキーマ変更用のコードの位置を定義","postgresqlスキルと組み合わせてSQLを書く","ALTER TABLE、CREATE/DROP INDEXなどのデータベース操作をサポート","migrations.tsとprocedures.tsコードの管理に使用"],"ko":["데이터베이스 마이그레이션과 스키마 변경을 위한 코드의 위치를 정의","postgresql 스킬과 함께 사용하여 SQL을 작성","ALTER TABLE, CREATE/DROP INDEX 등의 데이터베이스 연산을 지원","migrations.ts와 procedures.ts 코드의 관리에 사용"],"es":["Definición de ubicación de código para modificaciones de esquema de base de datos","Compatibilidad con PostgreSQL para procedimientos y migraciones","Soporte para ALTER TABLE, CREATE/DROP INDEX y otros comandos DDL","Integración con la habilidad de PostgreSQL para escribir declaraciones SQL","Uso de migrations.ts para modificaciones de esquema de base de datos","Uso de procedures.ts para procedimientos de base de datos"],"fr":["Définition de l''emplacement du code pour les modifications de schéma de base de données","Compatibilité avec PostgreSQL pour les procédures et les migrations","Prise en charge de ALTER TABLE, CREATE/DROP INDEX et d''autres commandes DDL","Intégration avec la compétence PostgreSQL pour écrire des instructions SQL","Utilisation de migrations.ts pour les modifications de schéma de base de données","Utilisation de procedures.ts pour les procédures de base de données"],"de":["Definition der Codeposition für Datenbankschemamodifikationen","Unterstützung für PostgreSQL für Prozeduren und Migrationen","Unterstützung für ALTER TABLE, CREATE/DROP INDEX und andere DDL-Befehle","Integration mit der PostgreSQL-Fähigkeit zum Schreiben von SQL-Anweisungen","Verwendung von migrations.ts für Datenbankschemamodifikationen","Verwendung von procedures.ts für Datenbankprozeduren"],"pt":["Gerenciamento de migrações de banco de dados com o postgresql","Alteração de esquemas de banco de dados com migrations.ts","Criação e exclusão de índices com CREATE/DROP INDEX","Adição e remoção de colunas com ALTER TABLE","Integração com o skill postgresql para escrever declarações SQL"],"ru":["Управление миграциями базы данных с помощью postgresql","Изменение схем базы данных с помощью migrations.ts","Создание и удаление индексов с помощью CREATE/DROP INDEX","Добавление и удаление столбцов с помощью ALTER TABLE","Интеграция с навыком postgresql для написания операторов SQL"],"ar":["إدارة مهاجرة قواعد البيانات مع postgresql","تعديل مخططات قواعد البيانات مع migrations.ts","إنشاء وحذف الفهارس مع CREATE/DROP INDEX","إضافة وحذف الأعمدة مع ALTER TABLE","التكامل مع مهارة postgresql لكتابة عبارات SQL"]},"keywords":{"en":["how to use aurora-tools-scripts","aurora-tools-scripts setup guide","aurora-tools-scripts and postgresql","database schema management with aurora-tools-scripts","aurora-tools-scripts alternative","aurora-tools-scripts vs other database management tools","installing aurora-tools-scripts","aurora-tools-scripts tutorial","aurora-tools-scripts best practices"],"zh":["Aurora Tools Scripts","AIエージェント","数据库迁移","schema变化","postgresql技能","SQL编写","migrations.ts","procedures.ts"],"ja":["Aurora Tools Scripts","AIエージェント","データベーススキーマ変更","postgresqlスキル","SQL書き方","migrations.ts","procedures.ts"],"ko":["Aurora Tools Scripts","AI 에이전트","데이터베이스 마이그레이션","스키마 변경","postgresql 스킬","SQL 작성","migrations.ts","procedures.ts"],"es":["aurora-tools-scripts","herramientas de inteligencia artificial para desarrolladores","postgresql","modificaciones de esquema de base de datos","procedimientos de base de datos","migraciones de base de datos","DDL","ALTER TABLE","CREATE/DROP INDEX"],"fr":["aurora-tools-scripts","outils d''intelligence artificielle pour les développeurs","postgresql","modifications de schéma de base de données","procédures de base de données","migrations de base de données","DDL","ALTER TABLE","CREATE/DROP INDEX"],"de":["aurora-tools-scripts","KI-Tools für Entwickler","postgresql","Datenbankschemamodifikationen","Datenbankprozeduren","Datenbankmigrationen","DDL","ALTER TABLE","CREATE/DROP INDEX"],"pt":["aurora-tools-scripts","postgresql","migrações de banco de dados","gerenciamento de esquemas","ALTER TABLE","CREATE/DROP INDEX","migrations.ts","desenvolvimento de banco de dados"],"ru":["ИИ Агенты aurora-tools-scripts","postgresql","миграции базы данных","управление схемами","ALTER TABLE","CREATE/DROP INDEX","migrations.ts","разработка базы данных"],"ar":["أدوات aurora-tools-scripts","postgresql","مهاجرة قواعد البيانات","إدارة مخططات","ALTER TABLE","CREATE/DROP INDEX","migrations.ts","تطوير قواعد البيانات"]}},"owner":"avvale","repo":"aurora-back","repoPath":"avvale/aurora-back","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"aurora-tools-scripts","description":">","version":"1.0","bodyPreview":"## Required Companion Skill\n\n> **IMPORTANT**: Always use this skill together with `postgresql` skill.\n>\n> - This skill defines **WHERE** to put the code (migrations.ts vs procedures.ts)\n> - The `postgresql` skill defines **HOW** to write the SQL statements\n>\n> Read `.claude/skills/postgresql/SKILL.md` before writing any SQL.\n\n---\n\n## When to Use\n\n### migrations.ts - Schema Changes (DDL)\n\nUse for **database schema modifications**:\n\n- ALTER TABLE (add/drop/modify columns)\n- CREATE/DROP INDEX\n- Add","body":"## Required Companion Skill\n\n> **IMPORTANT**: Always use this skill together with `postgresql` skill.\n>\n> - This skill defines **WHERE** to put the code (migrations.ts vs procedures.ts)\n> - The `postgresql` skill defines **HOW** to write the SQL statements\n>\n> Read `.claude/skills/postgresql/SKILL.md` before writing any SQL.\n\n---\n\n## When to Use\n\n### migrations.ts - Schema Changes (DDL)\n\nUse for **database schema modifications**:\n\n- ALTER TABLE (add/drop/modify columns)\n- CREATE/DROP INDEX\n- Add constraints (UNIQUE, FOREIGN KEY, CHECK)\n- Add rowId pattern to existing tables\n- Any structural change to tables\n\n### procedures.ts - Programmable Objects\n\nUse for **stored logic and automation**:\n\n- Stored procedures (PROCEDURE)\n- Functions (FUNCTION)\n- Triggers (TRIGGER)\n- Sequences (via FUNCTION that creates them)\n\n---\n\n## Critical Patterns\n\n### File Structure\n\n| File                             | Purpose                                                     |\n| -------------------------------- | ----------------------------------------------------------- |\n| `src/assets/tools/migrations.ts` | **Schema changes only**: ALTER TABLE, CREATE INDEX, DDL     |\n| `src/assets/tools/procedures.ts` | **Programmable objects**: procedures, functions, triggers   |\n| `src/@api/graphql.ts`            | Types and ToolsProcedureType enum                           |\n\n### Migration Object Structure\n\n```typescript\n{\n  id: ''UUID'',           // Generate with crypto.randomUUID()\n  name: string,         // English description: \"Verb + Object + Table\"\n  version: string,      // Semver matching package.json, e.g., ''0.0.7''\n  sort: number,         // Execution order within version\n  upScript: `SQL`,      // Pure PostgreSQL SQL in template literal\n  downScript: `SQL`,    // Exact inverse of upScript\n}\n```\n\n### Procedure Object Structure\n\n```typescript\n{\n  id: ''UUID'',\n  name: string,                    // Descriptive name\n  type: ToolsProcedureType,        // PROCEDURE | FUNCTION | TRIGGER\n  version: string,\n  sort: number,\n  upScript: `SQL`,                 // Pure SQL: CREATE OR REPLACE...\n  downScript: `SQL`,               // Pure SQL: DROP...\n}\n```\n\n### SQL Conventions\n\n| Rule                           | Example              |\n| ------------------------------ | -------------------- |\n| Table names use double quotes  | `\"TableName\"`        |\n| Always prefix with schema      | `public.\"TableName\"` |\n| Use IF EXISTS/IF NOT EXISTS    | Idempotent scripts   |\n| Environment vars interpolation | `${process.env.VAR}` |\n\n### Naming Conventions\n\n| Element    | Pattern                | Example                   |\n| ---------- | ---------------------- | ------------------------- |\n| Functions  | `set_{entity}_{field}` | `set_load_order_code`     |\n| Triggers   | `trg_{function_name}`  | `trg_set_load_order_code` |\n| Sequences  | `{purpose}_seq`        | `load_order_code_seq`     |\n| Indexes    | `{table_snake}_{col}`  | `message_outbox_row_id`   |\n| Local vars | `v_` prefix            | `v_code`                  |\n| Counters   | `t_` prefix            | `t_counter`               |\n\n### Decision Tree\n\n```\nWhat do you need?\n│\n├─ Schema/Structure change (DDL)?\n│   └─ YES → migrations.ts\n│       ├─ ALTER TABLE (add/drop/modify columns)\n│       ├─ CREATE/DROP INDEX\n│       ├─ ADD CONSTRAINT\n│       └─ Any table structure change\n│\n└─ Programmable logic?\n    └─ YES → procedures.ts\n        ├─ Stored procedure (no return)     → type: PROCEDURE\n        ├─ Function (returns value/table)   → type: FUNCTION\n        ├─ Trigger + trigger function       → type: TRIGGER\n        └─ Sequence (created via function)  → type: FUNCTION\n```\n\n---\n\n## Code Examples\n\n### Migration: Add Column\n\n```typescript\n{\n  id: ''98978f96-b617-469f-b80c-2a30c5516f47'',\n  name: ''Add defaultRedirection to IamRole'',\n  version: ''0.0.6'',\n  sort: 8,\n  upScript: `\n    ALTER TABLE public.\"IamRole\" ADD COLUMN \"defaultRedirection\" VARCHAR(2046) NULL;\n  `,\n  downScript: `\n    ALTER TABLE public.\"IamRole\" DROP COLUMN IF EXISTS \"defaultRedirection\";\n  `,\n}\n```\n\n### Migration: Add rowId (Aurora Standard Pattern)\n\n```typescript\n{\n  id: ''bf177b46-6671-410b-bf49-4ce97c29884e'',\n  name: ''Add rowId to MessageOutbox'',\n  version: ''0.0.5'',\n  sort: 5,\n  upScript: `\n    ALTER TABLE public.\"MessageOutbox\" ADD COLUMN \"rowId\" BIGINT GENERATED BY DEFAULT AS IDENTITY;\n    WITH ordered AS (\n        SELECT id AS uuid_pk, ROW_NUMBER() OVER (ORDER BY \"createdAt\", id) AS rn FROM public.\"MessageOutbox\"\n    )\n    UPDATE public.\"MessageOutbox\" t\n        SET \"rowId\" = o.rn\n    FROM ordered o\n        WHERE t.id = o.uuid_pk\n            AND t.\"rowId\" IS NULL;\n\n    SELECT setval(pg_get_serial_sequence(''public.\"MessageOutbox\"'',''rowId''), (SELECT MAX(\"rowId\") FROM public.\"MessageOutbox\"), true);\n\n    ALTER TABLE public.\"MessageOutbox\" ALTER COLUMN \"rowId\" SET NOT NULL;\n    CREATE UNIQUE INDEX message_outbox_row_id ON public.\"MessageOutbox\" USING btree (\"rowId\");\n  `,\n  downScript: `\n    DROP INDEX IF EXISTS \"message_outbox_row_id\";\n    ALTER TABLE public.\"MessageOutbox\" DROP COLUMN IF EXISTS \"rowId\";\n  `,\n}\n```\n\n### Procedure: Basic\n\n```typescript\n{\n  id: ''1cd0c79e-b83b-4ebf-b112-063669703cdc'',\n  name: ''insert_user'',\n  type: ToolsProcedureType.PROCEDURE,\n  version: ''0.0.1'',\n  sort: 1,\n  upScript: `\nCREATE OR REPLACE PROCEDURE insert_user(name_input VARCHAR, age_input INTEGER)\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    INSERT INTO users (name, age) VALUES (name_input, age_input);\nEND;\n$$;\n  `,\n  downScript: `DROP PROCEDURE IF EXISTS insert_user(VARCHAR, INTEGER);`,\n}\n```\n\n---\n\n## Commands\n\n```bash\n# Generate UUID for new entry\nuuidgen | tr ''[:upper:]'' ''[:lower:]''\n\n# Or in Node.js\nnode -e \"console.log(crypto.randomUUID())\"\n\n# Check current package version\njq -r ''.version'' package.json\n```\n\n---\n\n## Resources\n\n- **Templates**: See [assets/templates.ts](assets/templates.ts) for copy-paste\n  templates\n- **Migrations**: See `src/assets/tools/migrations.ts` for real examples\n- **Procedures**: See `src/assets/tools/procedures.ts` for procedure examples\n"},"lastSynced":"2026-03-08T02:01:51.736Z","agentAnalysis":{"suitability":{"en":"Ideal for Database Management Agents requiring streamlined schema modification and index management in PostgreSQL environments.","zh":"适用于需要在PostgreSQL环境中简化模式修改和索引管理的数据库管理代理。","ja":"PostgreSQL環境におけるスキーマの変更とインデックス管理をストリームライン化する必要があるデータベース管理エージェントに適しています。","ko":"PostgreSQL 환경에서 스키마 수정 및 인덱스 관리를 간소화해야 하는 데이터베이스 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Administración de Base de Datos que requieren una modificación de esquema y gestión de índices optimizadas en entornos PostgreSQL.","fr":"Idéal pour les Agents de Gestion de Base de Données nécessitant une modification de schéma et une gestion d''index rationalisées dans des environnements PostgreSQL.","de":"Ideal für Datenbank-Verwaltungsagenten, die eine optimierte Schema-Modifizierung und Index-Verwaltung in PostgreSQL-Umgebungen erfordern.","pt":"Ideal para Agentes de Gerenciamento de Banco de Dados que exigem modificação de esquema e gerenciamento de índice simplificados em ambientes PostgreSQL.","ru":"Идеально подходит для агентов управления базами данных, требующих упрощенного изменения схемы и управления индексами в средах PostgreSQL.","ar":"مثالي للوكلاء إدارة قواعد البيانات التي تتطلب تعديل مخطط مبسط وإدارة الفهارس في بيئات PostgreSQL."},"recommendation":{"en":"Empowers agents to manage database schema modifications, including ALTER TABLE and CREATE/DROP INDEX operations, in conjunction with the postgresql skill, utilizing migrations.ts for schema changes and procedures.ts for stored procedures, while adhering to SQL statement guidelines defined by the postgresql skill.","zh":"赋予代理管理数据库模式修改的能力，包括ALTER TABLE和CREATE/DROP INDEX操作，结合postgresql技能，使用migrations.ts进行模式更改，使用procedures.ts进行存储过程，而遵循由postgresql技能定义的SQL语句指南。","ja":"エージェントがデータベーススキーマの変更を管理できるようにすることで、ALTER TABLEおよびCREATE/DROP INDEX操作を実行し、postgresqlスキルと連携して、migrations.tsを使用してスキーマの変更を、procedures.tsを使用してストアドプロシージャを実行し、postgresqlスキルで定義されたSQLステートメントのガイドラインに従います。","ko":"에이전트가 데이터베이스 스키마 수정을 관리할 수 있도록 하여 ALTER TABLE 및 CREATE/DROP INDEX 연산을 수행하며, postgresql 기술과 함께 migrations.ts를 사용하여 스키마 변경을 수행하고 procedures.ts를 사용하여 저장 프로시저를 수행하고, postgresql 기술에서 정의한 SQL 문 가이드라인을 따릅니다.","es":"Habilita a los agentes a gestionar las modificaciones del esquema de la base de datos, incluidas las operaciones ALTER TABLE y CREATE/DROP INDEX, en conjunto con la habilidad postgresql, utilizando migrations.ts para los cambios de esquema y procedures.ts para los procedimientos almacenados, mientras se adhiere a las pautas de instrucciones SQL definidas por la habilidad postgresql.","fr":"Permet aux agents de gérer les modifications du schéma de base de données, y compris les opérations ALTER TABLE et CREATE/DROP INDEX, en conjonction avec la compétence postgresql, en utilisant migrations.ts pour les modifications de schéma et procedures.ts pour les procédures stockées, tout en respectant les directives d''instructions SQL définies par la compétence postgresql.","de":"Ermächtigt die Agenten, Änderungen am Datenbankschema zu verwalten, einschließlich ALTER TABLE- und CREATE/DROP INDEX-Operationen, in Verbindung mit der postgresql-Fähigkeit, unter Verwendung von migrations.ts für Schemaänderungen und procedures.ts für gespeicherte Prozeduren, während die SQL-Anweisungsrichtlinien der postgresql-Fähigkeit eingehalten werden.","pt":"Habilita os agentes a gerenciar modificações de esquema de banco de dados, incluindo operações ALTER TABLE e CREATE/DROP INDEX, em conjunto com a habilidade postgresql, utilizando migrations.ts para alterações de esquema e procedures.ts para procedimentos armazenados, enquanto adere às diretrizes de instruções SQL definidas pela habilidade postgresql.","ru":"Наделяет агентов возможностью управлять изменениями схемы базы данных, включая операции ALTER TABLE и CREATE/DROP INDEX, в сочетании с навыком postgresql, используя migrations.ts для изменений схемы и procedures.ts для хранимых процедур, при этом соблюдая руководящие принципы инструкций SQL, определенные навыком postgresql.","ar":"تمكين الوكلاء من إدارة تعديلات مخطط قاعدة البيانات، بما في ذلك عمليات ALTER TABLE و CREATE/DROP INDEX، بالاشتراك مع مهارة postgresql، باستخدام migrations.ts لتحديثات المخطط وprocedures.ts للإجراءات المخزنة، مع اتباع إرشادات العبارات SQL المحددة من قبل مهارة postgresql."},"useCases":{"en":["Automating database schema updates with migrations.ts","Optimizing database performance by creating and dropping indexes","Modifying table structures with ALTER TABLE operations"],"zh":["使用migrations.ts自动执行数据库模式更新","通过创建和删除索引来优化数据库性能","使用ALTER TABLE操作修改表结构"],"ja":["migrations.tsを使用してデータベーススキーマの更新を自動化する","インデックスの作成と削除によってデータベースのパフォーマンスを最適化する","ALTER TABLE操作を使用してテーブル構造を変更する"],"ko":["migrations.ts를 사용하여 데이터베이스 스키마 업데이트를 자동화하는 것","인덱스를 생성 및 삭제하여 데이터베이스 성능을 최적화하는 것","ALTER TABLE 연산을 사용하여 테이블 구조를 수정하는 것"],"es":["Automatizar las actualizaciones del esquema de base de datos con migrations.ts","Optimizar el rendimiento de la base de datos mediante la creación y eliminación de índices","Modificar las estructuras de tabla con operaciones ALTER TABLE"],"fr":["Automatiser les mises à jour du schéma de base de données avec migrations.ts","Optimiser les performances de la base de données en créant et en supprimant des index","Modifier les structures de table avec des opérations ALTER TABLE"],"de":["Automatisieren von Datenbankschema-Updates mit migrations.ts","Optimieren der Datenbankleistung durch Erstellen und Löschen von Indizes","Ändern der Tabellenstrukturen mit ALTER TABLE-Operationen"],"pt":["Automatizar atualizações de esquema de banco de dados com migrations.ts","Otimizar o desempenho do banco de dados criando e removendo índices","Modificar estruturas de tabela com operações ALTER TABLE"],"ru":["Автоматизировать обновления схемы базы данных с помощью migrations.ts","Оптимизировать производительность базы данных, создавая и удаляя индексы","Изменять структуры таблиц с помощью операций ALTER TABLE"],"ar":["تحديث مخطط قاعدة البيانات تلقائيًا باستخدام migrations.ts","تحسين أداء قاعدة البيانات من خلال إنشاء و حذف الفهارس","تعديل هياكل الجداول باستخدام عمليات ALTER TABLE"]},"limitations":{"en":["Requires companion postgresql skill for SQL statement generation","Limited to PostgreSQL database management"],"zh":["需要伴随postgresql技能来生成SQL语句","仅限PostgreSQL数据库管理"],"ja":["SQLステートメントの生成には、postgresqlスキルが必要","PostgreSQLデータベース管理に限定される"],"ko":["SQL 문 생성을 위해 postgresql 기술이 필요함","PostgreSQL 데이터베이스 관리에만 제한됨"],"es":["Requiere la habilidad postgresql companion para la generación de instrucciones SQL","Limitado a la administración de bases de datos PostgreSQL"],"fr":["Nécessite la compétence postgresql pour la génération d''instructions SQL","Limité à la gestion de bases de données PostgreSQL"],"de":["Benötigt die Begleitfähigkeit postgresql für die Generierung von SQL-Anweisungen","Begrenzt auf die Verwaltung von PostgreSQL-Datenbanken"],"pt":["Exige a habilidade postgresql companion para geração de instruções SQL","Limitado ao gerenciamento de banco de dados PostgreSQL"],"ru":["Требует сопутствующего навыка postgresql для генерации инструкций SQL","Ограничен только управлением базой данных PostgreSQL"],"ar":["يتطلب مهارة postgresql المرافقة لتوليد عبارات SQL","محدود بإدارة قاعدة البيانات PostgreSQL فقط"]},"version":4},"contentHash":"acf3f5addc4461596c12ea733111594180133540c1162af9598b4035fb592178","qualityScore":65}');
