INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dolsoon/my-awesome-project/moai-foundation-specs', 'moai-foundation-specs', 'dolsoon', 'my-awesome-project', 'community', 'moai-foundation-specs dolsoon my-awesome-project community The moai-foundation-specs skill provides comprehensive guidance on SPEC lifecycle management, version control, and approval workflows for AI agents. It benefits developers working with MoAI-ADK development pipelines. moai-foundation-specs 提供了综合的 SPEC 生命周期管理、版本控制和审批工作流功能 moai-foundation-specs は、SPEC ライフサイクル管理、バージョン管理、承認ワークフローなどの機能を提供します moai-foundation-specs는 SPEC 生命周期 관리, 버전 관리, 승인 워크플로우 등의 기능을 제공합니다 Moai-foundation-specs es una habilidad para la gestión de ciclo de vida de SPEC, que incluye versiones, flujos de aprobación y trazabilidad. Proporciona orientaciónintegral sobre la gestión del ciclo de vida SPEC. Moai-foundation-specs est une compétence pour la gestion du cycle de vie SPEC, qui comprend les versions, les flux d''approbation et la traçabilité. Fournit des conseils complets sur la gestion du cycle de vie SPEC. Moai-foundation-specs ist eine Fähigkeit für das SPEC-Lebenszyklus-Management, die Versionen, Genehmigungsworkflows und Nachverfolgbarkeit umfasst. Bietet umfassende Anleitung zur SPEC-Lebenszyklus-Verwaltung. O Moai-Foundation-Specs é uma habilidade que fornece orientação abrangente sobre gerenciamento de ciclo de vida de SPEC, controle de versão e integração com o pipeline de desenvolvimento MoAI-ADK. Moai-Foundation-Specs - это навык, который предоставляет комплексное руководство по управлению жизненным циклом SPEC, контролю версий и интеграции с конвейером разработки MoAI-ADK. Moai-Foundation-Specs هو مهارة توفر إرشادات شاملة لإدارة دورة حياة SPEC وإدارة الإصدارات والتكامل مع خط أنابيب التطوير MoAI-ADK. how to use moai-foundation-specs moai-foundation-specs setup guide SPEC lifecycle management moai-foundation-specs vs traditional development methods moai-foundation-specs install moai-foundation-specs tutorial for AI agents moai-foundation-specs SPEC 生命周期管理 版本控制 AI エージェント MoAI-ADK 开发流程 语义版本 Manages 4 SPEC lifecycle states: Draft, Active, Deprecated, and Archived Supports semantic versioning (major.minor.patch) for version management Provides approval workflows for SPEC documents Enables traceability and integration with MoAI-ADK development pipelines moai-foundation-specs is a skill that provides expert-level SPEC lifecycle management, including version control, approval workflows, and integration with MoAI-ADK development pipelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gadievron/raptor/github-archive', 'community', 'gadievron', 'raptor', 'gadievron/raptor', 'github-archive', 0, 0, 65, '2026-03-08T01:57:15.309Z', '2026-03-08T02:02:25.066Z', '93845cfe196ea94184f53dad44e5743ebb376c8d3f3fba60a4ff3988b7652132', '{"id":"gadievron/raptor/github-archive","name":"github-archive","description":{"en":"The github-archive skill enables AI agents to query immutable GitHub event history via BigQuery for security investigations and threat actor attribution. It benefits security researchers and incident responders","zh":"github-archive 是一个用于查询 GitHub 事件历史的 AI 代理技能，通过 BigQuery 获取tamper-proof 的_forensic 证据","ja":"github-archive は、BigQuery を使用して GitHub イベント履歴を取得し、セキュリティ調査とフォレンジック分析を行う AI エージェント スキルです","ko":"github-archive는 BigQuery를 사용하여 GitHub 이벤트 기록을 조회하고 보안 조사 및 포렌식 분석을 수행하는 AI 에이전트 스킬입니다","es":"github-archive es una habilidad que permite consultar la historia de eventos inmutable de GitHub a través de BigQuery para obtener pruebas forenses para investigaciones de seguridad","fr":"github-archive est une compétence qui permet d''interroger l''historique des événements immutable de GitHub via BigQuery pour obtenir des preuves forenses pour les enquêtes de sécurité","de":"github-archive ist eine Fähigkeit, die es ermöglicht, die unveränderliche Ereignishistorie von GitHub über BigQuery abzufragen, um forensische Beweise für Sicherheitsuntersuchungen zu erhalten","pt":"O github-archive é uma habilidade que permite queryar a história imutável de eventos do GitHub via BigQuery para obter evidências forenses para investigações de segurança.","ru":"ИИ Агент github-archive предназначен для запроса неизменяемой истории событий GitHub через BigQuery для получения неоспоримых доказательств для расследований безопасности.","ar":"يكون github-archive مهارة تسمح بالاستعلام عن سجل الأحداث غير القابل للتغ