INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gadievron/raptor/github-archive', 'github-archive', 'gadievron', 'raptor', 'community', 'github-archive gadievron raptor community The github-archive skill enables AI agents to query immutable GitHub event history via BigQuery for security investigations and threat actor attribution. It benefits security researchers and incident responders github-archive 是一个用于查询 GitHub 事件历史的 AI 代理技能，通过 BigQuery 获取tamper-proof 的_forensic 证据 github-archive は、BigQuery を使用して GitHub イベント履歴を取得し、セキュリティ調査とフォレンジック分析を行う AI エージェント スキルです github-archive는 BigQuery를 사용하여 GitHub 이벤트 기록을 조회하고 보안 조사 및 포렌식 분석을 수행하는 AI 에이전트 스킬입니다 github-archive es una habilidad que permite consultar la historia de eventos inmutable de GitHub a través de BigQuery para obtener pruebas forenses para investigaciones de seguridad github-archive est une compétence qui permet d''interroger l''historique des événements immutable de GitHub via BigQuery pour obtenir des preuves forenses pour les enquêtes de sécurité github-archive ist eine Fähigkeit, die es ermöglicht, die unveränderliche Ereignishistorie von GitHub über BigQuery abzufragen, um forensische Beweise für Sicherheitsuntersuchungen zu erhalten O github-archive é uma habilidade que permite queryar a história imutável de eventos do GitHub via BigQuery para obter evidências forenses para investigações de segurança. ИИ Агент github-archive предназначен для запроса неизменяемой истории событий GitHub через BigQuery для получения неоспоримых доказательств для расследований безопасности. يكون github-archive مهارة تسمح بالاستعلام عن سجل الأحداث غير القابل للتغيير على GitHub من خلال BigQuery للحصول على أدلة أمنية محكمة للتحقيقات الأمنية. how to use github-archive github-archive setup guide github-archive alternative github-archive vs BigQuery github-archive install github-archive for security investigations github-archive for threat actor attribution what is github-archive github-archive tutorial github-archive BigQuery GitHub 事件历史 安全调查 取证分析 AI 代理技能 github-archive Setup Guide Queries immutable GitHub event history via BigQuery Obtains tamper-proof forensic evidence for security investigations Supports building threat actor attribution profiles Verifies claims about repository activity using definitive timestamps Reconstructs attack timelines with BigQuery data Detects supply chain compromises using automation system data github-archive is a skill that queries BigQuery to obtain tamper-proof forensic evidence for security investigations involving GitHub repositories');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mc-zuri/mineflayer-bedrock/skill-builder', 'community', 'mc-zuri', 'mineflayer-bedrock', 'mc-zuri/mineflayer-bedrock', 'skill-builder', 0, 0, 65, '2026-03-08T01:57:15.314Z', '2026-03-08T02:02:43.692Z', '746a9e95e82207c57fd0c384f7d64c339398c5561cb15c4884f0e21d6ccc8ae5', '{"id":"mc-zuri/mineflayer-bedrock/skill-builder","name":"skill-builder","description":{"en":"The skill-builder enables developers to create well-structured Claude Code skills that follow best practices and the Agent Skills specification, streamlining AI agent development","zh":"Skill Builder 是一个用于创建结构化的 Claude Code 技能的工具，帮助开发者遵循最佳实践和 Agent Skills 规范","ja":"Skill Builder は、ベストプラクティスと Agent Skills の仕様に従った構造化された Claude Code スキルを作成するためのツールです","ko":"Skill Builder는 구조화된 Claude Code 스킬을 생성하고 개발자에게 최고의 실践과 에이전트 스킬 규격을 따르도록 도와주는 툴입니다","es":"El skill-builder te permite crear habilidades de Claude Code siguiendo las mejores prácticas y la especificación de habilidades de Agentes de IA. Crea habilidades bien estructuradas con este conjunto de herramientas","fr":"Le skill-builder vous permet de créer des compétences de Claude Code en suivant les meilleures pratiques et la spécification des compétences des Outils d''IA. Créez des compétences bien structurées avec cet ensemble d''outils","de":"Der skill-builder ermöglicht es Ihnen, KI-Agents-Fähigkeiten zu erstellen, die den Best Practices und der Spezifikation entsprechen. Erstellen Sie gut strukturierte Fähigkeiten mit diesem Satz von Tools","pt":"O Skill Builder é uma ferramenta para criar habilidades bem estruturadas para Ferramentas de IA. Ele oferece um modelo para criar habilidades que seguem as melhores práticas.","ru":"Skill Builder - это инструмент для создания хорошо структурированных навыков для ИИ Агентов. Он предоставляет шаблон для создания навыков, которые следуют лучшим практикам.","ar":"