INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mc-zuri/mineflayer-bedrock/skill-builder', 'skill-builder', 'mc-zuri', 'mineflayer-bedrock', 'community', 'skill-builder mc-zuri mineflayer-bedrock community The skill-builder enables developers to create well-structured Claude Code skills that follow best practices and the Agent Skills specification, streamlining AI agent development Skill Builder 是一个用于创建结构化的 Claude Code 技能的工具，帮助开发者遵循最佳实践和 Agent Skills 规范 Skill Builder は、ベストプラクティスと Agent Skills の仕様に従った構造化された Claude Code スキルを作成するためのツールです Skill Builder는 구조화된 Claude Code 스킬을 생성하고 개발자에게 최고의 실践과 에이전트 스킬 규격을 따르도록 도와주는 툴입니다 El skill-builder te permite crear habilidades de Claude Code siguiendo las mejores prácticas y la especificación de habilidades de Agentes de IA. Crea habilidades bien estructuradas con este conjunto de herramientas Le skill-builder vous permet de créer des compétences de Claude Code en suivant les meilleures pratiques et la spécification des compétences des Outils d''IA. Créez des compétences bien structurées avec cet ensemble d''outils Der skill-builder ermöglicht es Ihnen, KI-Agents-Fähigkeiten zu erstellen, die den Best Practices und der Spezifikation entsprechen. Erstellen Sie gut strukturierte Fähigkeiten mit diesem Satz von Tools O Skill Builder é uma ferramenta para criar habilidades bem estruturadas para Ferramentas de IA. Ele oferece um modelo para criar habilidades que seguem as melhores práticas. Skill Builder - это инструмент для создания хорошо структурированных навыков для ИИ Агентов. Он предоставляет шаблон для создания навыков, которые следуют лучшим практикам. Skill Builder هو أداة لإنشاء مهارات متقنة للوكلاء الذكاء الاصطناعي. يقدم نموذجًا لإنشاء مهارات تتبع أفضل الممارسات. how to use skill-builder what is skill-builder skill-builder alternative skill-builder vs Claude Code skill-builder install skill-builder setup guide Claude Code skills development AI agent skills creation Agent Skills specification AI工具 Skill Builder Claude Code Agent Skills 最佳实践 开发效率 快速入门 SKILL.md 脚本 引用 资产文件 Creates well-structured Claude Code skills in .claude/skills/ or ~/.claude/skills/ directories Generates SKILL.md files using a predefined template Supports addition of supporting files such as scripts, references, and assets Enables testing of skills by asking Claude to perform matching tasks Follows the Agent Skills specification for consistency and compatibility skill-builder is a tool for creating and managing Claude Code skills, following the Agent Skills specification');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HR-AR/Project-Conductor/validation-expert', 'community', 'HR-AR', 'Project-Conductor', 'HR-AR/Project-Conductor', 'validation-expert', 0, 0, 65, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:49.418Z', '473410285e8ab972535d9dcb6cd815e54752673422d926712ed09b3ec936a057', '{"id":"HR-AR/Project-Conductor/validation-expert","name":"validation-expert","description":{"en":"The validation-expert skill provides deep research-driven validation for Project Conductor''s architecture, benefiting developers who need to ensure quality and production readiness. It supports Node.js 20+ with TypeScript 5.2.2.","zh":"validation-expert 是一个深度研究驱动的验证技能，专门为 Project Conductor 的架构设计。它支持 Node.js 20+ 和 TypeScript 5.2.2","ja":"validation-expert は、Project Conductor のアーキテクチャ向けに設計された深度検証スキルです。Node.js 20+ と TypeScript 5.2.2 をサポート","ko":"validation-expert는 Project Conductor의 아키텍처를 위한 심층 검증 스킬로, Node.js 20+와 TypeScript 5.2.2를 지원","es":"Validation Expert es una habilidad de validación avanzada para Project Conductor, diseñada para trabajar con Node.js 20+ y TypeScript 5.2.2.","fr":"Validation Expert est une compétence de validation avancée pour Project Conductor, conçue pour fonctionner avec Node.js 20+ et TypeScript 5.2.2.","de":"Validation Expert ist eine erweiterte Validierungsfähigkeit für Project Conductor, die für die Zusammenarbeit mit Node.js 20+ und TypeScript 5.2.2 konzipiert wurde.","pt":"O Validation Expert é uma habilidade de validação profunda para arquiteturas de Projeto Conductor, utilizando Node.js e TypeScript.","ru":"Validation Expert - это навык глубокой валидации для архитектур Project Conductor, использующий Node.js и TypeScript.","ar":"Validation Expert هو مهارة التحقق من الصحة العميق لمعماريات مشروع Conductor، باستخدام Node.js و TypeScript."},"seo":{"title":{"en":"validation-expert: Deep Research-Driven Validation Setup ...","zh":"validation-expert 设置指南 - 基于 Node.js 的深度验证","ja":"validation-expert 導入ガイド - AIエージェントによる深度検証","ko":"validation-expert 설정 가이드 - Node.js 기반의 심층 검증","es":"Guía de configuración de Validation Expert para Project C...","fr":"Guide de mise en place de Validation Expert pour Project ...","de":"Einrichtungsleitfaden für Validation Expert in Project Co...","pt":"Guia de Configuração do Validation Expert para Desenvolve...","ru":"Настройка Validation Expert: Лучшие Практики для Разработ...","ar":"دليل إعداد Validation Expert لتقنيات الفهرسة الإلكترونية"},"description":{"en":"Unlock efficient validation with validation-expert. Learn how to invoke this skill for pre-deployment checks, quality issue detection, and production readine...","zh":"了解 validation-expert 的技术细节和使用场景，优化您的项目质量和部署流程","ja":"validation-expert の技術的詳細と使用シーンを学び、プロジェクトの品質とデプロイプロセスを最適化","ko":"validation-expert의 기술적 세부 사항과 사용 시나리오를 학습하여 프로젝트 품질과 배포 프로세스를 최적화","es":"Aprende a utilizar Validation Expert para Project Conductor con Node.js 20+ y TypeScript 5.2.2. Mejora la calidad de tu código con nuestra guía","fr":"Découvrez comment utiliser Validation Expert pour Project Conductor avec Node.js 20+ et TypeScript 5.2.2. Améliorez la qualité de votre code avec notre guide","de":"Erfahren Sie, wie Sie Validation Expert für Project Conductor mit Node.js 20+ und TypeScript 5.2.2 verwenden. Verbessern Sie die Qualität Ihres Codes mit uns...","pt":"Aprenda a configurar o Validation Expert para melhorar a qualidade do código com Node.js e TypeScript","ru":"Узнайте, как настроить Validation Expert для повышения качества кода с помощью Node.js и TypeScript в ИИ Агентах","ar":"اكتشف كيفية إعداد Validation Expert لتحسين جودة الكود باستخدام Node.js و TypeScript في أدوات الفهرسة الإلكترونية"},"definition":{"en":"validation-expert is a deep research-driven validation skill specifically designed for Project Conductor''s architecture, facilitating thorough checks and reviews.","zh":"validation-expert 是一种 AI 驱动的验证工具，用于检查和验证项目代码的质量和完整性","ja":"validation-expert は、プロジェクトのコードの品質と完全性を検証する AI エージェントによる検証ツール","ko":"validation-expert는 프로젝트 코드의 품질과 完整性를 검증하는 AI 에이전트 기반의 검증 도구","es":"Validation Expert es una habilidad de validación que verifica la calidad del código en Project Conductor","fr":"Validation Expert est une compétence de validation qui vérifie la qualité du code dans Project Conductor","de":"Validation Expert ist eine Validierungsfähigkeit, die die Qualität des Codes in Project Conductor überprüft","pt":"Validation Expert é uma habilidade de validação que verifica a qualidade do código antes da implantação.","ru":"Validation Expert - это навык валидации, который проверяет качество кода перед развертыванием.","ar":"Validation Expert هو مهارة التحقق من الصحة التي تحقق من جودة الكود قبل النشر."},"features":{"en":["Invokes validation on user mentions of ''validate'', ''check'', ''review'', or ''test''","Supports pre-deployment checks to staging/production environments","Performs quality issue detection after major feature implementation","Assesses production readiness before creating a pull request","Integrates with Node.js 20+ and TypeScript 5.2.2 for seamless validation"],"zh":["支持 Node.js 20+ 和 TypeScript 5.2.2","深度研究驱动的验证技能","用于检查和验证项目代码的质量和完整性","可用于项目部署前、主要功能实现后和质量问题疑似时","支持 pull request 前的代码检查"],"ja":["Node.js 20+ と TypeScript 5.2.2 をサポート","深度検証スキル","プロジェクトのコードの品質と完全性を検証","プロジェクトのデプロイ前、主な機能の実装後、品質の問題が疑われる場合に使用","プルリクエスト前のコードチェックをサポート"],"ko":["Node.js 20+와 TypeScript 5.2.2를 지원","심층 검증 스킬","프로젝트 코드의 품질과 完整性를 검증","프로젝트 배포 전, 주요 기능 구현 후, 품질 문제가 의심되는 경우 사용","풀 리퀘스트前的 코드 체크를 지원"],"es":["Validación de código con Node.js 20+","Compatibilidad con TypeScript 5.2.2","Detección de problemas de calidad antes de la implementación","Verificación de la preparación para la producción","Integración con el flujo de trabajo de Project Conductor"],"fr":["Validation de code avec Node.js 20+","Compatibilité avec TypeScript 5.2.2","Détection des problèmes de qualité avant la mise en production","Vérification de la préparation pour la production","Intégration avec le flux de travail de Project Conductor"],"de":["Code-Validierung mit Node.js 20+","Kompatibilität mit TypeScript 5.2.2","Erkennung von Qualitätsproblemen vor der Implementierung","Überprüfung der Produktionsbereitschaft","Integration in den Arbeitsablauf von Project Conductor"],"pt":["Validação de código com Node.js 20+","Suporte a TypeScript 5.2.2","Verificação de qualidade antes da implantação","Detecção de problemas de qualidade","Integração com o ciclo de vida do Projeto Conductor"],"ru":["Валидация кода с помощью Node.js 20+","Поддержка TypeScript 5.2.2","Проверка качества перед развертыванием","Обнаружение проблем качества","Интеграция с жизненным циклом Project Conductor"],"ar":["التحقق من صحة الكود باستخدام Node.js 20+","دعم TypeScript 5.2.2","التحقق من جودة الكود قبل النشر","اكتشاف مشاكل الجودة","التكامل مع دورة حياة مشروع Conductor"]},"keywords":{"en":["how to use validation-expert","validation-expert setup guide","validation-expert alternative","validation-expert vs Project Conductor","validation-expert install","what is validation-expert","validation-expert for Node.js","validation-expert for TypeScript","validation-expert best practices"],"zh":["validation-expert","AI 驱动的验证","Node.js","TypeScript","项目代码质量","代码检查","部署前检查","pull request 检查"],"ja":["validation-expert","AIエージェントによる検証","Node.js","TypeScript","プロジェクトのコードの品質","コードチェック","デプロイ前のチェック","プルリクエストのチェック"],"ko":["validation-expert","AI 에이전트 기반의 검증","Node.js","TypeScript","프로젝트 코드의 품질","코드 체크","배포 전 체크","풀 리퀘스트 체크"],"es":["Validation Expert","Project Conductor","Node.js 20+","TypeScript 5.2.2","validación de código","calidad del código","preparación para la producción","herramientas de desarrollo","Herramientas de AI para desarrolladores"],"fr":["Validation Expert","Project Conductor","Node.js 20+","TypeScript 5.2.2","validation de code","qualité du code","préparation pour la production","outils de développement","Outils d''IA pour les développeurs"],"de":["Validation Expert","Project Conductor","Node.js 20+","TypeScript 5.2.2","Code-Validierung","Code-Qualität","Produktionsbereitschaft","Entwicklungstools","KI-Tools für Entwickler"],"pt":["Validation Expert","Node.js","TypeScript","validação de código","qualidade de código","Projeto Conductor","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Validation Expert","Node.js","TypeScript","валидация кода","качество кода","Project Conductor","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["Validation Expert","Node.js","TypeScript","التحقق من صحة الكود","جودة الكود","مشروع Conductor","تطوير البرمجيات","أدوات التطوير","أدوات الفهرسة الإلكترونية"]}},"owner":"HR-AR","repo":"Project-Conductor","repoPath":"HR-AR/Project-Conductor","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.316Z","topics":[],"category":"community","skillMd":{"name":"validation-expert","description":"Comprehensive validation for Project Conductor using deep research for best practices. Use when user mentions validate, check quality, review code, test coverage, or before deployment.","version":"1.0.0","bodyPreview":"# Validation Expert (Project Conductor)\n\n**Deep research-driven validation skill specific to Project Conductor''s architecture.**\n\n## When to Use\n\nInvoke this skill when:\n- User mentions: \"validate\", \"check\", \"review\", \"test\"\n- Before deployment to staging/production\n- After major feature implementation\n- When quality issues are suspected\n- Before creating a pull request\n- When user asks \"is this production ready?\"\n\n## Project Conductor Context\n\n**Tech Stack:**\n- Node.js 20+ with TypeScript 5.2.2","body":"# Validation Expert (Project Conductor)\n\n**Deep research-driven validation skill specific to Project Conductor''s architecture.**\n\n## When to Use\n\nInvoke this skill when:\n- User mentions: \"validate\", \"check\", \"review\", \"test\"\n- Before deployment to staging/production\n- After major feature implementation\n- When quality issues are suspected\n- Before creating a pull request\n- When user asks \"is this production ready?\"\n\n## Project Conductor Context\n\n**Tech Stack:**\n- Node.js 20+ with TypeScript 5.2.2\n- Express.js 4.18.2\n- Socket.io 4.7.2 (real-time)\n- PostgreSQL 15 (database)\n- Redis 7 (caching)\n- Jest 29.6.4 (testing)\n\n**Architecture:**\n- 7-module workflow (Onboarding → BRD → PRD → Design → Conflicts → Implementation → History)\n- RESTful APIs (12 major APIs, 100+ endpoints)\n- Real-time collaboration (WebSocket)\n- Document-centric (Markdown + YAML frontmatter)\n\n## Validation Methodology\n\n### Step 1: Quick Health Check\n\n```bash\n# Run immediate checks\nnpm run build          # TypeScript compilation\nnpm run lint          # ESLint\nnpm test              # Jest test suite\nnpm run typecheck     # TypeScript strict checks\n\n# Check docker services\ndocker-compose ps     # PostgreSQL, Redis status\n```\n\n### Step 2: Launch Deep Research for Best Practices\n\n**Use codex-deep-research agent** to validate against industry standards:\n\n```markdown\nInvoke Task tool with subagent_type=\"codex-deep-research\"\n\nPrompt:\n\"Research the best practices, validation techniques, and quality standards for a production-ready TypeScript + Express.js + PostgreSQL application similar to Project Conductor.\n\nProject Conductor is a requirements management and workflow orchestration platform with:\n- 12 RESTful APIs\n- Real-time WebSocket collaboration\n- PostgreSQL database with complex queries\n- Redis caching\n- 7-module workflow system\n- Document-centric architecture (Markdown + YAML)\n\nPlease provide comprehensive validation checklist covering:\n\n1. **Code Quality:**\n   - TypeScript best practices (strict mode, no ''any'', proper typing)\n   - ESLint rules for Node.js + Express\n   - Code organization patterns (controllers, services, models)\n   - Error handling patterns\n   - Logging best practices (Pino, Winston)\n\n2. **API Design:**\n   - RESTful conventions (status codes, response formats)\n   - Input validation (express-validator patterns)\n   - Rate limiting strategies\n   - API versioning (/api/v1)\n   - Error response standards\n\n3. **Database:**\n   - PostgreSQL query optimization\n   - Index strategy validation\n   - Connection pool configuration\n   - Migration best practices\n   - Data integrity constraints\n\n4. **Security:**\n   - OWASP Top 10 compliance\n   - SQL injection prevention\n   - XSS prevention\n   - Rate limiting\n   - Authentication/authorization (JWT, RBAC)\n   - Secrets management\n\n5. **Performance:**\n   - Response time targets (p95 <200ms)\n   - Caching hit rate (>80%)\n   - Database query performance (<50ms)\n   - WebSocket latency (<50ms)\n   - Memory leak detection\n\n6. **Testing:**\n   - Test coverage targets (>75%)\n   - Unit test patterns\n   - Integration test strategies\n   - E2E test scenarios\n   - WebSocket testing approaches\n\n7. **Production Readiness:**\n   - Environment configuration\n   - Graceful shutdown\n   - Health check endpoints\n   - Monitoring setup (Prometheus, DataDog)\n   - Error tracking (Sentry)\n   - Logging infrastructure\n\n8. **Deployment (Render specific):**\n   - Static file serving validation\n   - Environment variable checks\n   - Build process verification\n   - Path resolution correctness\n   - 404 prevention strategies\n\nProvide specific validation commands, test cases, and checklists for each category.\"\n```\n\n### Step 3: Check for AI-Powered Validation Tools\n\n**Use gemini-research-analyst agent** to find modern validation tools:\n\n```markdown\nInvoke Task tool with subagent_type=\"gemini-research-analyst\"\n\nPrompt:\n\"Research if Google''s Gemini AI provides any code validation, quality analysis, or automated testing tools that could benefit Project Conductor.\n\nSpecifically investigate:\n1. Gemini-powered code review tools\n2. Automated test generation\n3. Security vulnerability scanning\n4. Performance profiling\n5. API contract testing\n6. TypeScript type safety analysis\n7. Database query optimization suggestions\n8. Real-time monitoring and anomaly detection\n\nIf Gemini has relevant tools:\n- How to integrate with TypeScript + Express.js\n- Cost implications\n- Accuracy/reliability compared to traditional tools\n- Production-ready status\n- Examples of companies using these tools\n\nAlso research Google Cloud tools that could enhance validation:\n- Cloud Build (CI/CD)\n- Error Reporting\n- Cloud Monitoring\n- Cloud Profiler\n- Security Command Center\"\n```\n\n### Step 4: Execute Comprehensive Validation\n\nAfter research agents return, run this complete validation suite:\n\n#### 4A. Code Quality Validation\n\n```bash\n#!/bin/bash\n# comprehensive-validation.sh\n\necho \"📊 Project Conductor Validation Suite\"\necho \"======================================\"\n\n# 1. TypeScript Compilation\necho \"\\n1️⃣ TypeScript Compilation...\"\nnpm run build\nif [ $? -ne 0 ]; then\n  echo \"❌ TypeScript compilation failed\"\n  exit 1\nfi\necho \"✅ TypeScript compilation passed\"\n\n# 2. Type Checking (strict mode)\necho \"\\n2️⃣ TypeScript Strict Checks...\"\nnpx tsc --noEmit --strict\nif [ $? -ne 0 ]; then\n  echo \"❌ Type checking failed\"\n  exit 1\nfi\necho \"✅ Type checking passed\"\n\n# 3. Linting\necho \"\\n3️⃣ ESLint...\"\nnpm run lint\nif [ $? -ne 0 ]; then\n  echo \"⚠️  Linting issues found\"\nfi\n\n# 4. Find ''any'' types (anti-pattern)\necho \"\\n4️⃣ Checking for ''any'' types...\"\nANY_COUNT=$(grep -r \": any\" src/ --include=\"*.ts\" | wc -l)\necho \"Found $ANY_COUNT instances of ''any'' type\"\nif [ $ANY_COUNT -gt 10 ]; then\n  echo \"⚠️  Consider reducing ''any'' usage (found $ANY_COUNT, target <10)\"\nfi\n\n# 5. Find console.log (should use logger)\necho \"\\n5️⃣ Checking for console.log...\"\nCONSOLE_COUNT=$(grep -r \"console\\.\" src/ --include=\"*.ts\" | grep -v \"// \" | wc -l)\necho \"Found $CONSOLE_COUNT console statements\"\nif [ $CONSOLE_COUNT -gt 0 ]; then\n  echo \"⚠️  Replace console.log with logger (found $CONSOLE_COUNT)\"\nfi\n\n# 6. Check for hardcoded secrets\necho \"\\n6️⃣ Checking for hardcoded secrets...\"\nif grep -r \"password\\s*=\\s*[''\\\"]\" src/ --include=\"*.ts\" | grep -v \"process.env\"; then\n  echo \"❌ Hardcoded passwords found!\"\n  exit 1\nfi\necho \"✅ No hardcoded secrets detected\"\n\n# 7. Test Suite\necho \"\\n7️⃣ Running Test Suite...\"\nnpm test -- --coverage\nif [ $? -ne 0 ]; then\n  echo \"❌ Tests failed\"\n  exit 1\nfi\necho \"✅ Tests passed\"\n\n# 8. Test Coverage Check\necho \"\\n8️⃣ Checking Test Coverage...\"\nCOVERAGE=$(npm test -- --coverage --silent | grep \"All files\" | awk ''{print $10}'' | sed ''s/%//'')\nif (( $(echo \"$COVERAGE < 75\" | bc -l) )); then\n  echo \"⚠️  Test coverage is $COVERAGE% (target: 75%)\"\nelse\n  echo \"✅ Test coverage is $COVERAGE%\"\nfi\n```\n\n#### 4B. API Validation\n\n```typescript\n// tests/validation/api-validation.test.ts\nimport request from ''supertest'';\nimport { app } from ''../../src/index'';\n\ndescribe(''API Validation'', () => {\n  describe(''Response Format Standards'', () => {\n    it(''should return consistent JSON structure'', async () => {\n      const res = await request(app).get(''/api/v1/health'');\n\n      expect(res.status).toBe(200);\n      expect(res.body).toHaveProperty(''success'');\n      expect(res.body).toHaveProperty(''data'');\n      expect(typeof res.body.success).toBe(''boolean'');\n    });\n\n    it(''should handle errors with proper format'', async () => {\n      const res = await request(app).get(''/api/v1/requirements/invalid-id'');\n\n      expect(res.status).toBeGreaterThanOrEqual(400);\n      expect(res.body).toHaveProperty(''success'', false);\n      expect(res.body).toHaveProperty(''message'');\n    });\n  });\n\n  describe(''API Versioning'', () => {\n    it(''all endpoints should be under /api/v1'', async () => {\n      const res = await request(app).get(''/api/v1/health'');\n      expect(res.status).not.toBe(404);\n    });\n  });\n\n  describe(''Rate Limiting'', () => {\n    it(''should enforce rate limits'', async () => {\n      const requests = Array(100).fill(null).map(() =>\n        request(app).get(''/api/v1/requirements'')\n      );\n\n      const responses = await Promise.all(requests);\n      const rateLimited = responses.some(r => r.status === 429);\n\n      expect(rateLimited).toBe(true);\n    });\n  });\n\n  describe(''Input Validation'', () => {\n    it(''should reject invalid input'', async () => {\n      const res = await request(app)\n        .post(''/api/v1/requirements'')\n        .send({ title: '''', priority: ''invalid'' }); // Invalid data\n\n      expect(res.status).toBe(400);\n      expect(res.body.success).toBe(false);\n    });\n\n    it(''should sanitize SQL injection attempts'', async () => {\n      const res = await request(app)\n        .get(''/api/v1/requirements'')\n        .query({ sortBy: \"''; DROP TABLE requirements; --\" });\n\n      expect(res.status).not.toBe(500); // Should handle gracefully\n    });\n  });\n});\n```\n\n#### 4C. Database Validation\n\n```sql\n-- scripts/validate-database.sql\n-- Run this to validate database health\n\n-- 1. Check for missing indexes\nSELECT\n  schemaname,\n  tablename,\n  indexname\nFROM pg_indexes\nWHERE schemaname = ''public''\nORDER BY tablename;\n\n-- 2. Find slow queries (from pg_stat_statements)\nSELECT\n  query,\n  calls,\n  total_time,\n  mean_time,\n  max_time\nFROM pg_stat_statements\nWHERE mean_time > 100 -- Queries slower than 100ms\nORDER BY mean_time DESC\nLIMIT 20;\n\n-- 3. Check table sizes\nSELECT\n  schemaname,\n  tablename,\n  pg_size_pretty(pg_total_relation_size(schemaname||''.''||tablename)) AS size\nFROM pg_tables\nWHERE schemaname = ''public''\nORDER BY pg_total_relation_size(schemaname||''.''||tablename) DESC;\n\n-- 4. Check for unused indexes\nSELECT\n  schemaname,\n  tablename,\n  indexname,\n  idx_scan as index_scans\nFROM pg_stat_user_indexes\nWHERE idx_scan = 0\n  AND indexrelname NOT LIKE ''%_pkey''\nORDER BY pg_relation_size(indexrelid) DESC;\n\n-- 5. Connection pool health\nSELECT\n  count(*),\n  state\nFROM pg_stat_activity\nWHERE datname = current_database()\nGROUP BY state;\n```\n\n#### 4D. Security Validation\n\n```bash\n# scripts/security-audit.sh\n\necho \"🔒 Security Audit\"\necho \"================\"\n\n# 1. Check for known vulnerabilities\necho \"\\n1️⃣ Checking npm dependencies for vulnerabilities...\"\nnpm audit --audit-level=moderate\nif [ $? -ne 0 ]; then\n  echo \"⚠️  Vulnerabilities found in dependencies\"\nfi\n\n# 2. Check for exposed secrets\necho \"\\n2️⃣ Scanning for exposed secrets...\"\nif command -v gitleaks &> /dev/null; then\n  gitleaks detect --source . --verbose\nelse\n  echo \"⚠️  gitleaks not installed (recommended: brew install gitleaks)\"\nfi\n\n# 3. Check OWASP dependencies\necho \"\\n3️⃣ OWASP Dependency Check...\"\nif command -v dependency-check &> /dev/null; then\n  dependency-check --project \"Project Conductor\" --scan .\nelse\n  echo \"⚠️  OWASP dependency-check not installed\"\nfi\n\n# 4. Check environment variables\necho \"\\n4️⃣ Environment Variable Check...\"\nREQUIRED_ENVS=(\"DATABASE_URL\" \"REDIS_URL\" \"JWT_SECRET\" \"NODE_ENV\")\nfor env in \"${REQUIRED_ENVS[@]}\"; do\n  if [ -z \"${!env}\" ]; then\n    echo \"⚠️  Missing environment variable: $env\"\n  else\n    echo \"✅ $env is set\"\n  fi\ndone\n\n# 5. SSL/TLS Configuration\necho \"\\n5️⃣ Checking SSL/TLS...\"\nif [ \"$NODE_ENV\" = \"production\" ]; then\n  if [ -z \"$SSL_CERT\" ] || [ -z \"$SSL_KEY\" ]; then\n    echo \"⚠️  SSL certificates not configured for production\"\n  else\n    echo \"✅ SSL configured\"\n  fi\nfi\n```\n\n#### 4E. Performance Validation\n\n```typescript\n// tests/validation/performance.test.ts\nimport request from ''supertest'';\nimport { app } from ''../../src/index'';\n\ndescribe(''Performance Validation'', () => {\n  describe(''Response Times'', () => {\n    it(''API should respond in <200ms (p95)'', async () => {\n      const times: number[] = [];\n\n      // Make 100 requests\n      for (let i = 0; i < 100; i++) {\n        const start = Date.now();\n        await request(app).get(''/api/v1/requirements'');\n        times.push(Date.now() - start);\n      }\n\n      times.sort((a, b) => a - b);\n      const p95 = times[Math.floor(times.length * 0.95)];\n\n      console.log(`P95 response time: ${p95}ms`);\n      expect(p95).toBeLessThan(200);\n    });\n\n    it(''cached requests should be <50ms'', async () => {\n      // Prime cache\n      await request(app).get(''/api/v1/requirements?page=1'');\n\n      // Measure cached request\n      const start = Date.now();\n      await request(app).get(''/api/v1/requirements?page=1'');\n      const duration = Date.now() - start;\n\n      expect(duration).toBeLessThan(50);\n    });\n  });\n\n  describe(''Memory Leaks'', () => {\n    it(''should not leak memory over 1000 requests'', async () => {\n      const initialMemory = process.memoryUsage().heapUsed;\n\n      // Make 1000 requests\n      for (let i = 0; i < 1000; i++) {\n        await request(app).get(''/api/v1/health'');\n      }\n\n      // Force garbage collection if available\n      if (global.gc) {\n        global.gc();\n      }\n\n      const finalMemory = process.memoryUsage().heapUsed;\n      const memoryIncrease = finalMemory - initialMemory;\n\n      // Memory should not increase by more than 50MB\n      expect(memoryIncrease).toBeLessThan(50 * 1024 * 1024);\n    });\n  });\n});\n```\n\n#### 4F. Deployment Validation (Render Specific)\n\n```bash\n# scripts/render-deployment-validation.sh\n# Based on lessons learned from production deployment\n\necho \"🚀 Render Deployment Validation\"\necho \"===============================\"\n\n# 1. Check for files in /public\necho \"\\n1️⃣ Validating static files...\"\nPUBLIC_FILES=$(ls -la public/*.html 2>/dev/null | wc -l)\nif [ $PUBLIC_FILES -gt 0 ]; then\n  echo \"✅ Found $PUBLIC_FILES HTML files in /public\"\nelse\n  echo \"⚠️  No HTML files in /public directory\"\nfi\n\n# 2. Check for explicit routes that might override static middleware\necho \"\\n2️⃣ Checking for route conflicts...\"\nEXPLICIT_ROUTES=$(grep -n \"\\.sendFile.*publicDir\" src/index.ts | wc -l)\nif [ $EXPLICIT_ROUTES -gt 0 ]; then\n  echo \"⚠️  Found $EXPLICIT_ROUTES explicit routes for /public files\"\n  echo \"   These may override static middleware - review needed\"\n  grep -n \"\\.sendFile.*publicDir\" src/index.ts\nfi\n\n# 3. Check for hardcoded localhost URLs\necho \"\\n3️⃣ Checking for hardcoded URLs...\"\nif grep -r \"localhost:3000\" public/ src/ --include=\"*.ts\" --include=\"*.js\" --include=\"*.html\"; then\n  echo \"⚠️  Hardcoded localhost URLs found - will break on Render\"\nelse\n  echo \"✅ No hardcoded localhost URLs\"\nfi\n\n# 4. Verify environment variables are used\necho \"\\n4️⃣ Checking environment variable usage...\"\nif grep -r \"process.env.PORT\" src/index.ts > /dev/null; then\n  echo \"✅ PORT uses environment variable\"\nelse\n  echo \"❌ PORT is hardcoded - Render requires process.env.PORT\"\nfi\n\n# 5. Build test\necho \"\\n5️⃣ Testing production build...\"\nnpm run build\nif [ $? -eq 0 ]; then\n  echo \"✅ Production build successful\"\nelse\n  echo \"❌ Production build failed\"\n  exit 1\nfi\n\n# 6. Check git tracking\necho \"\\n6️⃣ Checking git status...\"\nUNTRACKED=$(git ls-files --others --exclude-standard public/ | wc -l)\nif [ $UNTRACKED -gt 0 ]; then\n  echo \"⚠️  Untracked files in /public:\"\n  git ls-files --others --exclude-standard public/\n  echo \"   These files won''t deploy to Render!\"\nelse\n  echo \"✅ All /public files are tracked in git\"\nfi\n```\n\n### Step 5: Generate Validation Report\n\n```markdown\n## Validation Report\n\n**Project**: Project Conductor\n**Date**: [ISO timestamp]\n**Validator**: validation-expert skill\n**Status**: [PASS/FAIL/WARNING]\n\n### Summary\n- **Code Quality**: [PASS/FAIL] - [details]\n- **API Design**: [PASS/FAIL] - [details]\n- **Database**: [PASS/FAIL] - [details]\n- **Security**: [PASS/FAIL] - [details]\n- **Performance**: [PASS/FAIL] - [details]\n- **Testing**: [PASS/FAIL] - [details]\n- **Deployment**: [PASS/FAIL] - [details]\n\n### Critical Issues (must fix before production)\n1. [Issue with severity]\n2. [Issue with severity]\n\n### Warnings (recommended to fix)\n1. [Warning with recommendation]\n2. [Warning with recommendation]\n\n### Passed Validations\n- ✅ [Check description]\n- ✅ [Check description]\n\n### Metrics\n- **Test Coverage**: [percentage]%\n- **TypeScript Strict**: [pass/fail]\n- **API Response Time (p95)**: [ms]\n- **Database Query Time (p95)**: [ms]\n- **Security Vulnerabilities**: [count]\n- **Linting Issues**: [count]\n\n### Next Steps\n1. Fix critical issues: [list]\n2. Address warnings: [list]\n3. Re-run validation: `npm run validate`\n4. If all pass: Ready for deployment ✅\n\n### Recommendations Based on Research\n[Insert findings from codex-deep-research agent]\n- Industry best practices not yet implemented\n- Tools to consider adding\n- Patterns to adopt\n```\n\n## Validation Commands\n\n```json\n// Add to package.json scripts\n{\n  \"scripts\": {\n    \"validate\": \"bash scripts/comprehensive-validation.sh\",\n    \"validate:security\": \"bash scripts/security-audit.sh\",\n    \"validate:deploy\": \"bash scripts/render-deployment-validation.sh\",\n    \"validate:db\": \"psql $DATABASE_URL -f scripts/validate-database.sql\",\n    \"validate:all\": \"npm run validate && npm run validate:security && npm run validate:deploy\"\n  }\n}\n```\n\n## Success Criteria\n\nValidation PASSES when:\n- ✅ All tests pass with >75% coverage\n- ✅ TypeScript compilation succeeds (strict mode)\n- ✅ No critical security vulnerabilities\n- ✅ API response times <200ms (p95)\n- ✅ Database queries <50ms (p95)\n- ✅ No hardcoded secrets or passwords\n- ✅ All /public files tracked in git\n- ✅ Production build succeeds\n- ✅ No route conflicts for static files\n\n## Integration with CI/CD\n\n```yaml\n# .github/workflows/validation.yml\nname: Validation Pipeline\n\non: [push, pull_request]\n\njobs:\n  validate:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v3\n      - uses: actions/setup-node@v3\n        with:\n          node-version: ''20''\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Run comprehensive validation\n        run: npm run validate:all\n\n      - name: Upload coverage\n        uses: codecov/codecov-action@v3\n        with:\n          files: ./coverage/lcov.info\n```\n\n## Example Invocation\n\nUser: \"Is Project Conductor ready for production deployment?\"\n\nThis skill will:\n1. Run all validation scripts\n2. Research best practices via codex-deep-research\n3. Check for AI-powered validation tools via gemini-research-analyst\n4. Generate comprehensive validation report\n5. Provide specific recommendations with fixes\n"},"lastSynced":"2026-03-08T02:02:49.418Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring in-depth validation for Node.js projects with TypeScript support.","zh":"适用于需要对 Node.js 项目进行深入验证的代码审查代理，支持 TypeScript。","ja":"Node.js プロジェクトの詳細な検証が必要なコードレビュー エージェントに適しています。TypeScript をサポートしています。","ko":"Node.js 프로젝트에 대한 심도 있는 검증이 필요한 코드 리뷰 에이전트에 적합합니다. TypeScript를 지원합니다.","es":"Ideal para agentes de revisión de código que requieren una validación en profundidad para proyectos de Node.js con soporte de TypeScript.","fr":"Idéal pour les agents de vérification de code nécessitant une validation approfondie pour les projets Node.js avec prise en charge de TypeScript.","de":"Ideal für Code-Review-Agents, die eine umfassende Überprüfung für Node.js-Projekte mit TypeScript-Unterstützung erfordern.","pt":"Ideal para Agentes de Revisão de Código que exigem validação aprofundada para projetos Node.js com suporte a TypeScript.","ru":"Идеально подходит для агентов проверки кода, требующих глубокой валидации для проектов Node.js с поддержкой TypeScript.","ar":"مثالي لعميل مراجعة الكود الذي يتطلب التحقق العميق لمشاريع Node.js مع دعم TypeScript."},"recommendation":{"en":"Empowers agents to perform deep research-driven validation for Project Conductor''s architecture, ensuring quality and production readiness with Node.js 20+ and TypeScript 5.2.2, and supports pre-deployment checks, major feature implementations, and quality issue detection.","zh":"赋予代理执行针对 Project Conductor 架构的深入研究驱动的验证，确保质量和生产就绪性，支持 Node.js 20+ 和 TypeScript 5.2.2，并支持预部署检查、主要功能实现和质量问题检测。","ja":"エージェントに、Project Conductor のアーキテクチャに対する深い研究に基づく検証を実行する力を与え、品質と本稼働の準備性を確保します。Node.js 20+ と TypeScript 5.2.2 をサポートし、事前デプロイ チェック、主な機能の実装、品質の問題の検出もサポートします。","ko":"에이전트가 프로젝트 컨덕터의 아키텍처에 대한 심도 있는 연구 기반의 검증을 수행할 수 있도록 하여 품질과 생산 준비성을 보장합니다. Node.js 20+ 및 TypeScript 5.2.2를 지원하며, 사전 배포 체크, 주요 기능 구현 및 품질 문제 탐지를 지원합니다.","es":"Habilita a los agentes a realizar una validación basada en investigaciones profundas para la arquitectura de Project Conductor, garantizando la calidad y la preparación para la producción con Node.js 20+ y TypeScript 5.2.2, y admite controles previos a la implementación, implementaciones de funciones principales y detección de problemas de calidad.","fr":"Permet aux agents d''effectuer une validation approfondie basée sur la recherche pour l''architecture de Project Conductor, garantissant la qualité et la préparation à la production avec Node.js 20+ et TypeScript 5.2.2, et prend en charge les vérifications préalables au déploiement, les mises en œuvre de fonctionnalités majeures et la détection des problèmes de qualité.","de":"Ermächtigt Agenten, eine tiefere forschungsbasierte Überprüfung für die Architektur von Project Conductor durchzuführen, um Qualität und Produktionsreife mit Node.js 20+ und TypeScript 5.2.2 sicherzustellen und unterstützt Prüfung vor der Bereitstellung, Umsetzung wichtiger Funktionen und Erkennung von Qualitätsproblemen.","pt":"Habilita os agentes a realizar uma validação aprofundada baseada em pesquisa para a arquitetura do Project Conductor, garantindo qualidade e prontidão para produção com Node.js 20+ e TypeScript 5.2.2, e suporta verificações pré-implementação, implementações de recursos importantes e detecção de problemas de qualidade.","ru":"Наделяет агентов возможностью проводить глубокую валидацию, основанную на исследованиях, для архитектуры Project Conductor, обеспечивая качество и готовность к производству с Node.js 20+ и TypeScript 5.2.2, и поддерживает предварительные проверки, реализацию основных функций и обнаружение проблем качества.","ar":"يمنح الوكلاء القدرة على إجراء التحقق العميق القائم على البحث لمعمارية Project Conductor، مما يضمن الجودة والجاهزية الإنتاجية مع Node.js 20+ وTypeScript 5.2.2، ودعم الفحوصات قبل النشر وتنفيذ الميزات الرئيسيةและการكشف عن مشاكل الجودة."},"useCases":{"en":["Validating project architecture before deployment to staging or production","Reviewing code quality after major feature implementations","Detecting potential quality issues in Node.js projects with TypeScript","Checking production readiness of Project Conductor''s architecture"],"zh":["在将项目部署到临时或生产环境之前验证项目架构","在主要功能实现后审查代码质量","在 Node.js 项目中使用 TypeScript 时检测潜在的质量问题","检查 Project Conductor 架构的生产就绪性"],"ja":["ステージングまたは本稼働環境にデプロイする前にプロジェクト アーキテクチャを検証する","主要な機能の実装後に行うコード品質のレビュー","Node.js プロジェクトで TypeScript を使用する場合の潜在的な品質の問題の検出","Project Conductor のアーキテクチャの本稼働の準備性を確認する"],"ko":["프로젝트를 스테이징 또는 프로덕션 환경에 배포하기 전에 프로젝트 아키텍처를 검증하는 것","메인 기능 구현 후 코드 품질을 검토하는 것","Node.js 프로젝트에서 TypeScript를 사용할 때 잠재적인 품질 문제를 탐지하는 것","프로젝트 컨덕터의 아키텍처의 프로덕션 준비성을 확인하는 것"],"es":["Validar la arquitectura del proyecto antes de la implementación en staging o producción","Revisar la calidad del código después de la implementación de funciones principales","Detectar posibles problemas de calidad en proyectos de Node.js con TypeScript","Comprobar la preparación para la producción de la arquitectura de Project Conductor"],"fr":["Valider l''architecture du projet avant le déploiement en staging ou en production","Réviser la qualité du code après la mise en œuvre de fonctionnalités majeures","Détecter les problèmes potentiels de qualité dans les projets Node.js avec TypeScript","Vérifier la préparation à la production de l''architecture de Project Conductor"],"de":["Validieren der Projektarchitektur vor der Bereitstellung in staging oder Produktion","Überprüfen der Codequalität nach der Umsetzung wichtiger Funktionen","Erkennen potenzieller Qualitätsprobleme in Node.js-Projekten mit TypeScript","Überprüfen der Produktionsreife der Architektur von Project Conductor"],"pt":["Validar a arquitetura do projeto antes do deploy para staging ou produção","Revisar a qualidade do código após implementações de recursos importantes","Detectar problemas de qualidade potenciais em projetos Node.js com TypeScript","Verificar a prontidão para produção da arquitetura do Project Conductor"],"ru":["Проверить архитектуру проекта перед развертыванием в staging или производство","Просмотреть качество кода после реализации основных функций","Обнаружить потенциальные проблемы качества в проектах Node.js с TypeScript","Проверить готовность к производству архитектуры Project Conductor"],"ar":["التحقق من معمارية المشروع قبل النشر إلى مرحلة التحرير أو الإنتاج","مراجعة جودة الكود بعد تنفيذ الميزات الرئيسية","الكشف عن مشاكل الجودة المحتملة في مشاريع Node.js مع دعم TypeScript","التحقق من جاهزية الإنتاج لمعمارية Project Conductor"]},"limitations":{"en":["Requires Node.js 20+","Specific to TypeScript 5.2.2","Limited to Project Conductor''s architecture"],"zh":["需要 Node.js 20+","特定于 TypeScript 5.2.2","仅限于 Project Conductor 的架构"],"ja":["Node.js 20+ が必要","TypeScript 5.2.2 に特有","Project Conductor のアーキテクチャに限定"],"ko":["Node.js 20+가 필요함","TypeScript 5.2.2에 특정함","프로젝트 컨덕터의 아키텍처에만 제한됨"],"es":["Requiere Node.js 20+","Específico para TypeScript 5.2.2","Limitado a la arquitectura de Project Conductor"],"fr":["Nécessite Node.js 20+","Spécifique à TypeScript 5.2.2","Limité à l''architecture de Project Conductor"],"de":["Benötigt Node.js 20+","Spezifisch für TypeScript 5.2.2","Begrenzt auf die Architektur von Project Conductor"],"pt":["Exige Node.js 20+","Específico para TypeScript 5.2.2","Limitado à arquitetura do Project Conductor"],"ru":["Требует Node.js 20+","Спецефичен для TypeScript 5.2.2","Ограничен архитектурой Project Conductor"],"ar":["يتطلب Node.js 20+","محدد لTypeScript 5.2.2","محدود بمعمارية Project Conductor"]},"version":4},"contentHash":"473410285e8ab972535d9dcb6cd815e54752673422d926712ed09b3ec936a057","qualityScore":65}');
