INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Foundup/Foundups-Agent/gemma_domain_trainer_prototype', 'gemma_domain_trainer_prototype', 'Foundup', 'Foundups-Agent', 'community', 'gemma_domain_trainer_prototype Foundup Foundups-Agent community The gemma_domain_trainer_prototype skill fine-tunes Gemma 270M on domain-specific training data extracted from 012.txt, benefiting developers working with AI agents like qwen and gemma. Gemma 域训练器原型是一种用于在特定领域数据上微调 Gemma 270M AI 模型的工具，实现高精度的文本生成 Gemma ドメイントレーナープロトタイプは、特定のドメインデータで Gemma 270M AI モデルを微調整するためのツールです Gemma 도메인 트레이너 프로토タイプ는 특정 도메인 데이터에서 Gemma 270M AI 모델을 微調整하여 높은 精度의 텍스트 생성을 실현하는 도구입니다 El prototipo de Gemma Domain Trainer permite fine-tunear Gemma 270M con datos de entrenamiento específicos del dominio extraídos de 012.txt. Le prototype de Gemma Domain Trainer permet de fine-tuner Gemma 270M avec des données d''entraînement spécifiques au domaine extraites de 012.txt. Der Prototyp von Gemma Domain Trainer ermöglicht die Feinjustierung von Gemma 270M mit domänspezifischen Trainingsdaten, die aus 012.txt extrahiert werden. O Treinador de Domínio Gemma é uma ferramenta de treinamento de modelo que permite fine-tuning do modelo Gemma 270M com dados específicos do domínio. Тренер Доменов Gemma — это инструмент для обучения модели, который позволяет дообучать модель Gemma 270M на данных конкретного домена. مدرب المجال جيما هو أداة لتدريب النموذج التي تمكن من ضبط دقيق لنموذج جيما 270M مع بيانات محددة للمجال. how to use gemma_domain_trainer_prototype gemma_domain_trainer_prototype setup guide fine-tuning Gemma 270M with 0102 gemma_domain_trainer_prototype vs qwen gemma_domain_trainer_prototype install what is gemma_domain_trainer_prototype gemma_domain_trainer_prototype alternative gemma_domain_trainer_prototype for AI agents 0102 artifact integration MCP Orchestration for gemma_domain_trainer_prototype Gemma 域训练器原型 AI 工具 Gemma 270M 微调 特定领域数据 文本生成 MCP 编排 模式保真度阈值 Fine-tunes Gemma 270M on domain-specific training data extracted from 012.txt Utilizes 0102 artifacts for recursive pattern generation Supports MCP Orchestration for seamless workflow integration Employs a primary agent, qwen, for intent-based generation Requires a pattern fidelity threshold of 0.90 for optimal performance Needs validation for test status completion gemma_domain_trainer_prototype is a skill that enables fine-tuning of Gemma 270M on domain-specific data using 0102 artifacts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nodnarbnitram/claude-code-extensions/esphome-config-helper', 'community', 'nodnarbnitram', 'claude-code-extensions', 'nodnarbnitram/claude-code-extensions', 'esphome-config-helper', 0, 0, 65, '2026-03-08T01:57:15.359Z', '2026-03-08T02:04:07.712Z', '8ef553f1dedc5249a2ca939f3b21196632b9732a9933a03ab7b8ed465881265e', '{"id":"nodnarbnitram/claude-code-extensions/esphome-config-helper","name":"esphome-config-helper","description":{"en":"The esphome-config-helper skill accelerates ESPHome device configuration for developers, providing quick-start templates, GPIO references, and validation utilities. It benefits developers working with ESPHome devices.","zh":"ESPHome 配置助手是一款用于快速生成和排除 ESPHome 设备配置故障的工具，提供模板、GPIO 引脚参考和验证工具","ja":"ESPHome 設定ヘルパーは、ESPHome デバイスの設定を迅速に生成してトラブルシューティングを行うためのツールです","ko":"ESPHome 설정 도우미는 ESPHome 장치 설정을 빠르게 생성하고 문제를 해결하기 위한 도구입니다","es":"esphome-config-helper es una colección de extensiones para Claude Code que facilitan la configuración de dispositivos ESPHome con plantillas y guías de referencia","fr":"esphome-config-helper est un ensemble d''extensions pour Claude Code qui facilitent la configuration des appareils ESPHome avec des modèles et des guides de référence","de":"esphome-config-helper ist eine Sammlung von Erweiterungen für Claude Code, die die Konfiguration von ESPHome-Geräten mit Vorlagen und Referenzhandbüchern erleichtern","pt":"O esphome-config-helper é uma coleção de extensões para Claude Code que acelera a configuração de dispositivos ESPHome.","ru":"esphome-config-helper - это коллекция расширений для Claude Code, ускоряющая настройку устройств ESPHome.","ar":"esphome-config-helper هي مجموعة من الامتدادات لمكتبة Claude Code التي تسريع عملية تشغيل أجهزة ESPHome"},"seo":{"title":{"en":"esphome-config-helper: Rapid ESPHome Configuration Setup ...","zh":"ESPHome 配置助手 Setup Guide - 快速配置和故障排除","ja":"ESPHome 設定ヘルパー AIエージェント - 設定とトラブルシューティングの最適化","ko":"ESPHome 설정 도우미 Setup Guide - 빠른 설정과 문제 해결","es":"Guía de configuración de esphome-config-helper para dispo...","fr":"Guide de configuration d''esphome-config-helper pour les a...","de":"Konfigurationsleitfaden für esphome-config-helper und IoT...","pt":"Guia de Configuração do esphome-config-helper: Ferramenta...","ru":"ИИ Агенты для ESPHome: esphome-config-helper Настройка","ar":"دليل إعداد esphome-config-helper: أدوات مساعدة للبرمجة"},"description":{"en":"Streamline your ESPHome device configuration with esphome-config-helper. Discover how to generate configurations, troubleshoot issues, and optimize your setu...","zh":"使用 ESPHome 配置助手快速生成和排除 ESPHome 设备配置故障，提供模板、GPIO 引脚参考和验证工具","ja":"ESPHome 設定ヘルパーを使用して、ESPHome デバイスの設定を迅速に生成してトラブルシューティングを行うことができます","ko":"ESPHome 설정 도우미를 사용하여 ESPHome 장치 설정을 빠르게 생성하고 문제를 해결할 수 있습니다","es":"Descubre cómo configurar dispositivos ESPHome con facilidad utilizando esphome-config-helper, con plantillas y guías de referencia para GPIO","fr":"Découvrez comment configurer facilement les appareils ESPHome avec esphome-config-helper, grâce à des modèles et des guides de référence pour GPIO","de":"Erfahren Sie, wie Sie ESPHome-Geräte mithilfe von esphome-config-helper leicht konfigurieren können, mit Vorlagen und Referenzhandbüchern für GPIO","pt":"Aprenda a configurar dispositivos ESPHome com o esphome-config-helper, com templates prontos para uso e guias de referência de GPIO.","ru":"Настройте устройства ESPHome с помощью esphome-config-helper, включая шаблоны и справочные материалы по GPIO.","ar":"تعلم كيفية تشغيل أجهزة ESPHome باستخدام esphome-config-helper، مع قوالب جاهزة ومراجع GPIO"},"definition":{"en":"esphome-config-helper is a collection of extensions for rapid ESPHome configuration generation and troubleshooting, offering templates, GPIO guides, and validation tools.","zh":"ESPHome 配置助手是一款用于辅助 ESPHome 设备配置的 AI 工具","ja":"ESPHome 設定ヘルパーは、ESPHome デバイスの設定を支援する AI エージェントです","ko":"ESPHome 설정 도우미는 ESPHome 장치 설정을 지원하는 AI 도구입니다","es":"esphome-config-helper es una herramienta de configuración para dispositivos ESPHome que proporciona plantillas y guías de referencia para GPIO","fr":"esphome-config-helper est un outil de configuration pour les appareils ESPHome qui fournit des modèles et des guides de référence pour GPIO","de":"esphome-config-helper ist ein Konfigurationstool für ESPHome-Geräte, das Vorlagen und Referenzhandbücher für GPIO bereitstellt","pt":"O que é esphome-config-helper? É uma ferramenta de auxílio para configuração de dispositivos ESPHome.","ru":"Что такое esphome-config-helper? Это инструмент для настройки устройств ESPHome.","ar":"ما هو esphome-config-helper؟ هو أداة مساعدة لتشغيل أجهزة ESPHome"},"features":{"en":["Provides quick-start templates for common ESPHome device types","Includes GPIO pinout references to prevent conflicts","Offers common sensor configurations with wiring diagrams","Features error message lookup and solutions","Includes a configuration validation workflow"],"zh":["快速启动模板","GPIO 引脚参考","常见传感器配置","错误消息查找和解决","配置验证工作流"],"ja":["クイックスタートテンプレート","GPIO ピンアウト参考","一般的なセンサーコンフィギュレーション","エラーメッセージの検索と解決","コンフィギュレーションの検証ワークフロー"],"ko":["빠른 시작 템플릿","GPIO 핀아웃 참조","일반 센서 구성","오류 메시지 찾기 및 해결","구성 검증 워크플로"],"es":["Plantillas de configuración para dispositivos comunes","Guías de referencia para GPIO para prevenir conflictos","Configuraciones de sensores comunes con diagramas de cableado","Búsqueda de mensajes de error y soluciones","Flujo de trabajo de validación de configuración"],"fr":["Modèles de configuration pour les appareils courants","Guides de référence pour GPIO pour éviter les conflits","Configurations de capteurs courantes avec des diagrammes de câblage","Recherche de messages d''erreur et solutions","Flux de travail de validation de configuration"],"de":["Konfigurationsvorlagen für gemeinsame Geräte","Referenzhandbücher für GPIO zur Vermeidung von Konflikten","Gemeinsame Sensor-Konfigurationen mit Verkabelungsdiagrammen","Fehlermeldungs-Suche und Lösungen","Konfigurations-Validierungs-Workflow"],"pt":["Templates prontos para uso para dispositivos comuns","Guia de referência de GPIO para prevenir conflitos","Configurações de sensores comuns com diagramas de fiação","Pesquisa de mensagens de erro e soluções","Fluxo de trabalho de validação de configuração"],"ru":["Готовые шаблоны для общих устройств","Справочная информация по GPIO для предотвращения конфликтов","Общие конфигурации датчиков с схемами подключения","Поиск ошибок и решения","Поток работы валидации конфигурации"],"ar":["قوالب جاهزة للاستخدام لأجهزة الشائعة","مرجع GPIO لمنع الصراعات","تكوين حساس مشترك مع مخططات التماس","بحث رسائل الخطأ والحلول","سير عمل التحقق من صحة التكوين"]},"keywords":{"en":["how to use esphome-config-helper","esphome-config-helper setup guide","ESPHome configuration generation","esphome-config-helper alternative","esphome-config-helper vs opencode","esphome-config-helper install","what is esphome-config-helper","esphome-config-helper troubleshooting","ESPHome device configuration"],"zh":["ESPHome 配置","ESPHome 故障排除","AI 配置助手","GPIO 引脚参考","ESPHome 设备配置","快速启动模板","错误消息查找"],"ja":["ESPHome 設定","ESPHome トラブルシューティング","AI 設定ヘルパー","GPIO ピンアウト参考","ESPHome デバイス設定","クイックスタートテンプレート","エラーメッセージの検索"],"ko":["ESPHome 설정","ESPHome 문제 해결","AI 설정 도우미","GPIO 핀아웃 참조","ESPHome 장치 설정","빠른 시작 템플릿","오류 메시지 찾기"],"es":["esphome-config-helper","configuración de ESPHome","herramientas de configuración de IoT","plantillas de configuración de dispositivos","guías de referencia para GPIO","solución de problemas de ESPHome"],"fr":["esphome-config-helper","configuration d''ESPHome","outils de configuration d''IoT","modèles de configuration d''appareils","guides de référence pour GPIO","dépannage d''ESPHome"],"de":["esphome-config-helper","Konfiguration von ESPHome","Konfigurationstools für IoT","Konfigurationsvorlagen für Geräte","Referenzhandbücher für GPIO","Fehlerbehebung von ESPHome"],"pt":["esphome-config-helper","configuração de dispositivos ESPHome","templates de configuração","guia de GPIO","configuração de sensores","validação de configuração"," Claude Code","opencode","AI Agents","ferramentas de auxílio"],"ru":["esphome-config-helper","настройка устройств ESPHome","шаблоны конфигурации","справочная информация по GPIO","конфигурация датчиков","валидация конфигурации"," Claude Code","opencode","ИИ Агенты","инструменты для настройки"],"ar":["esphome-config-helper","تشغيل أجهزة ESPHome","قوالب التكوين","مرجع GPIO","تكوين الحساسات","التحقق من صحة التكوين"," Claude Code","opencode","أدوات الذكاء الاصطناعي","أدوات المساعدة"]}},"owner":"nodnarbnitram","repo":"claude-code-extensions","repoPath":"nodnarbnitram/claude-code-extensions","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.359Z","topics":[],"category":"community","skillMd":{"name":"esphome-config-helper","description":"This skill should be used when the user asks to create an esphome config, set up an esp32 device, configure esphome yaml, add a sensor to esphome, fix esphome compile error, or mentions gpio pin assignment, wifi setup, ota update, or error messages like Unknown platform, GPIO already in use, Could not compile, or WiFi connection failed. Provides rapid ESPHome configuration generation, troubleshooting, and validation.","version":"0.1.0","bodyPreview":"# ESPHome Configuration Helper\n\nRapid ESPHome configuration generation and troubleshooting skill with ready-to-use templates, GPIO reference guides, and validation utilities.\n\n## Purpose\n\nThis skill accelerates ESPHome device configuration by providing:\n- Quick-start templates for common device types\n- GPIO pinout references to prevent conflicts\n- Common sensor configurations with wiring diagrams\n- Error message lookup and solutions\n- Configuration validation workflow\n\nUse this skill for general","body":"# ESPHome Configuration Helper\n\nRapid ESPHome configuration generation and troubleshooting skill with ready-to-use templates, GPIO reference guides, and validation utilities.\n\n## Purpose\n\nThis skill accelerates ESPHome device configuration by providing:\n- Quick-start templates for common device types\n- GPIO pinout references to prevent conflicts\n- Common sensor configurations with wiring diagrams\n- Error message lookup and solutions\n- Configuration validation workflow\n\nUse this skill for general ESPHome configuration tasks. For ESP32-S3-BOX-3 specific implementations, use the esphome-box3-builder skill instead.\n\n## When to Use This Skill\n\nUse this skill when:\n- Starting a new ESPHome device configuration\n- Adding sensors, switches, or displays to existing configs\n- Troubleshooting compilation or runtime errors\n- Determining safe GPIO pins for components\n- Validating configuration before flashing\n\nDelegate to specialized ESPHome agents for:\n- Deep technical questions (esphome-core, esphome-components, etc.)\n- Complex automation logic (esphome-automations agent)\n- Network troubleshooting (esphome-networking agent)\n- ESP32-S3-BOX-3 projects (esphome-box3 agent)\n\n## Configuration Templates\n\n### Available Templates\n\nLocated in `templates/` directory:\n\n1. **`basic-device.yaml`** - Minimal ESP32 starter\n   - ESP32 platform with WiFi and API\n   - OTA updates enabled\n   - Logger and web server\n   - Use as foundation for custom projects\n\n2. **`sensor-node.yaml`** - Temperature/humidity sensor node\n   - DHT22 sensor on GPIO4\n   - WiFi with fallback AP\n   - Home Assistant integration\n   - Use for environmental monitoring\n\n3. **`relay-switch.yaml`** - 4-channel relay controller\n   - GPIO control for 4 relays (GPIO23, GPIO22, GPIO21, GPIO19)\n   - Physical button inputs with interlocks\n   - Switch entities for Home Assistant\n   - Use for home automation switching\n\n4. **`display-node.yaml`** - Display with sensors\n   - SSD1306 OLED display (128x64, I²C)\n   - DHT22 temperature/humidity\n   - Display lambda showing sensor readings\n   - Use for visual sensor displays\n\n### Using Templates\n\nTo use a template:\n1. Read the appropriate template file\n2. Customize device name, WiFi credentials, GPIO pins\n3. Add or remove components as needed\n4. Validate configuration (see Validation Workflow below)\n\n**Template Workflow:**\n```yaml\n# 1. Read template\ncat .claude/skills/esphome-config-helper/templates/sensor-node.yaml\n\n# 2. Copy to project\ncp .claude/skills/esphome-config-helper/templates/sensor-node.yaml my-device.yaml\n\n# 3. Edit with device-specific values\n# - Update device name\n# - Set WiFi credentials (use secrets.yaml)\n# - Adjust GPIO pins if needed\n# - Customize sensor names\n\n# 4. Validate (see Validation Workflow)\n```\n\n## GPIO Pin Reference\n\n### Quick GPIO Lookup\n\nFor detailed GPIO pinouts and safe pin selection, consult:\n- **`references/gpio-pinouts.md`** - Complete ESP32 and ESP8266 GPIO reference\n  - Safe pins for each platform\n  - Strapping pins to avoid\n  - I²C/SPI/UART default pins\n  - Input-only vs output-capable pins\n  - Boot failure pins (GPIO0, GPIO2, GPIO15)\n\n**Quick Safe Pins:**\n- **ESP32**: GPIO4, GPIO5, GPIO12, GPIO13, GPIO14, GPIO16, GPIO17, GPIO18, GPIO19, GPIO21, GPIO22, GPIO23, GPIO25-27, GPIO32, GPIO33\n- **ESP8266**: GPIO4 (D2), GPIO5 (D1), GPIO12 (D6), GPIO13 (D7), GPIO14 (D5)\n\n**Avoid (strapping/boot pins):**\n- **ESP32**: GPIO0, GPIO2, GPIO5, GPIO12, GPIO15 (use with caution)\n- **ESP8266**: GPIO0, GPIO2, GPIO15\n\n## Common Sensor Configurations\n\n### Sensor Selection Guide\n\nFor detailed sensor configurations with wiring diagrams, consult:\n- **`references/common-sensors.md`** - Top 20 sensor configurations\n  - Temperature/humidity sensors (DHT22, BME280, SHT3x)\n  - Motion sensors (PIR, mmWave)\n  - Light sensors (BH1750, TSL2561)\n  - Distance sensors (HC-SR04, VL53L0X)\n  - Gas sensors (MQ-series, SGP30)\n  - Complete wiring diagrams and platform selection\n\n**Quick Sensor Recommendations:**\n- **Temperature/Humidity**: BME280 (I²C, more reliable than DHT22)\n- **Motion**: HC-SR501 PIR (GPIO binary sensor)\n- **Light**: BH1750 (I²C, accurate lux measurements)\n- **Distance**: HC-SR04 (ultrasonic, 2-400cm range)\n- **Air Quality**: BME680 (I²C, temp/humidity/pressure/gas)\n\n### Basic Sensor Patterns\n\n**I²C Sensor** (BME280 example):\n```yaml\ni2c:\n  sda: GPIO21\n  scl: GPIO22\n  scan: true\n\nsensor:\n  - platform: bme280\n    temperature:\n      name: \"Temperature\"\n    humidity:\n      name: \"Humidity\"\n    pressure:\n      name: \"Pressure\"\n    address: 0x76\n    update_interval: 60s\n```\n\n**GPIO Sensor** (DHT22 example):\n```yaml\nsensor:\n  - platform: dht\n    pin: GPIO4\n    model: DHT22\n    temperature:\n      name: \"Temperature\"\n    humidity:\n      name: \"Humidity\"\n    update_interval: 60s\n```\n\n**Binary Sensor** (PIR motion):\n```yaml\nbinary_sensor:\n  - platform: gpio\n    pin: GPIO14\n    name: \"Motion Sensor\"\n    device_class: motion\n```\n\n## Troubleshooting Guide\n\n### Error Lookup\n\nFor complete error message lookup table and solutions, consult:\n- **`references/troubleshooting.md`** - Comprehensive error message reference\n  - Compilation errors (unknown platform, GPIO conflicts, dependency issues)\n  - Runtime errors (WiFi failures, sensor timeouts, OTA problems)\n  - Configuration errors (YAML syntax, invalid pins, missing components)\n  - Hardware issues (sensor not detected, relay not switching)\n\n**Common Error Quick Reference:**\n\n| Error Message | Quick Fix |\n|---------------|-----------|\n| \"Unknown platform\" | Check component name spelling, ensure platform supported |\n| \"GPIO already in use\" | Check GPIO pin assignments, avoid duplicates |\n| \"Could not compile\" | Check YAML syntax, verify indentation (2 spaces) |\n| \"WiFi connection failed\" | Verify SSID/password, check signal strength, use static IP |\n| \"Sensor not found\" | Check I²C address (use scan: true), verify wiring |\n| \"OTA upload failed\" | Check device reachable, verify OTA password, restart device |\n\n### Troubleshooting Workflow\n\nWhen encountering errors:\n\n1. **Check YAML syntax**: Verify indentation (2 spaces, no tabs)\n2. **Validate GPIO pins**: Ensure no conflicts, use safe pins\n3. **Check component platform**: Verify platform name and configuration\n4. **Review logs**: Use `esphome logs device.yaml` to see runtime errors\n5. **Consult references**: Check `references/troubleshooting.md` for specific error\n6. **Validate config**: Run validation workflow (see below)\n\n## Validation Workflow\n\n### Using the Validation Script\n\nThe validation utility provides quick configuration checks:\n\n**Script**: `scripts/validate-config.sh`\n\n**Usage:**\n```bash\n# Validate configuration\n./.claude/skills/esphome-config-helper/scripts/validate-config.sh my-device.yaml\n\n# The script runs:\n# 1. esphome config my-device.yaml  (syntax check)\n# 2. esphome compile my-device.yaml (compilation test)\n```\n\n**Validation Steps:**\n\n1. **Syntax validation**: `esphome config my-device.yaml`\n   - Checks YAML syntax\n   - Validates component configuration\n   - Reports missing requirements\n   - Shows final configuration\n\n2. **Compilation test**: `esphome compile my-device.yaml`\n   - Downloads required libraries\n   - Compiles firmware\n   - Reports errors and warnings\n   - Confirms configuration works\n\n3. **Fix errors**: If validation fails:\n   - Review error messages\n   - Check GPIO conflicts\n   - Verify component platforms\n   - Consult `references/troubleshooting.md`\n   - Re-validate after fixes\n\n### Pre-Flash Checklist\n\nBefore flashing device:\n- [ ] Configuration validates without errors\n- [ ] WiFi credentials correct (use secrets.yaml)\n- [ ] Device name unique on network\n- [ ] GPIO pins verified safe\n- [ ] OTA password set (for future updates)\n- [ ] API encryption key configured (2026.1.0+)\n\n## Configuration Best Practices\n\n### YAML Structure\n\nOrganize configuration in logical sections:\n```yaml\n# 1. Core platform\nesphome:\n  name: device-name\n  friendly_name: Device Name\n\nesp32:\n  board: esp32dev\n  framework:\n    type: arduino\n\n# 2. Network\nwifi:\n  ssid: !secret wifi_ssid\n  password: !secret wifi_password\n\napi:\n  encryption:\n    key: !secret api_encryption_key\n\nota:\n  - platform: esphome\n    password: !secret ota_password\n\n# 3. Logging\nlogger:\nweb_server:\n\n# 4. Components (sensors, switches, etc.)\nsensor:\n  # ...\n\nbinary_sensor:\n  # ...\n```\n\n### Secrets Management\n\nUse `secrets.yaml` for sensitive data:\n\n**secrets.yaml:**\n```yaml\nwifi_ssid: \"MyNetwork\"\nwifi_password: \"MyPassword123\"\napi_encryption_key: \"base64-generated-key\"\nota_password: \"SecureOTAPassword\"\n```\n\n**Reference in config:**\n```yaml\nwifi:\n  ssid: !secret wifi_ssid\n  password: !secret wifi_password\n```\n\n### Naming Conventions\n\nFollow consistent naming:\n- **Device names**: lowercase-with-hyphens (e.g., `bedroom-sensor`)\n- **Entity names**: Title Case with Spaces (e.g., `\"Bedroom Temperature\"`)\n- **IDs**: lowercase_with_underscores (e.g., `temp_sensor`)\n\n**Example:**\n```yaml\nsensor:\n  - platform: dht\n    pin: GPIO4\n    temperature:\n      name: \"Living Room Temperature\"\n      id: living_room_temp\n    humidity:\n      name: \"Living Room Humidity\"\n      id: living_room_humidity\n```\n\n## Integration with Other Skills and Agents\n\n### When to Use Other Resources\n\n- **ESP32-S3-BOX-3 projects**: Use esphome-box3-builder skill\n  - Audio pipeline (I²S, ES7210, ES8311)\n  - Display lambda rendering (ILI9xxx)\n  - Touch interaction (GT911)\n  - Voice assistant integration\n\n- **Deep technical questions**: Delegate to ESPHome agents\n  - Core concepts → esphome-core agent\n  - Component selection → esphome-components agent\n  - Automation logic → esphome-automations agent\n  - Network issues → esphome-networking agent\n  - HA integration → esphome-homeassistant agent\n\n- **Complex projects**: Combine resources\n  - Start with template (this skill)\n  - Customize with agent guidance\n  - Validate with scripts (this skill)\n  - Deploy and troubleshoot (this skill + agents)\n\n## Additional Resources\n\n### Reference Files\n\nFor detailed information, consult:\n- **`references/gpio-pinouts.md`** - Complete ESP32/ESP8266 GPIO reference with safe pins, strapping pins, and pin capabilities\n- **`references/common-sensors.md`** - Top 20 sensor configurations with wiring diagrams, platform selection, and usage examples\n- **`references/troubleshooting.md`** - Comprehensive error message lookup table with solutions for compilation, runtime, and hardware issues\n\n### Template Files\n\nWorking configuration examples in `templates/`:\n- **`basic-device.yaml`** - Minimal ESP32 foundation\n- **`sensor-node.yaml`** - DHT22 temperature/humidity node\n- **`relay-switch.yaml`** - 4-channel relay controller\n- **`display-node.yaml`** - OLED display with sensors\n\n### Utility Scripts\n\nValidation and testing tools in `scripts/`:\n- **`validate-config.sh`** - ESPHome configuration validation wrapper\n\n## Quick Start Workflow\n\nFor new ESPHome device:\n\n1. **Select template** based on device type (sensor, switch, display, or basic)\n2. **Copy template** to project directory\n3. **Customize configuration**:\n   - Update device name\n   - Set WiFi credentials in secrets.yaml\n   - Adjust GPIO pins using `references/gpio-pinouts.md`\n   - Add/remove components as needed\n4. **Validate configuration** using `scripts/validate-config.sh`\n5. **Fix any errors** using `references/troubleshooting.md`\n6. **Flash device** with validated configuration\n7. **Monitor logs** and troubleshoot if needed\n\nFor adding to existing config:\n1. **Consult references** for component configuration\n2. **Check GPIO availability** in `references/gpio-pinouts.md`\n3. **Add component** to configuration\n4. **Validate** before flashing\n5. **Update and monitor**\n\nThis skill provides rapid configuration generation for common ESPHome use cases. For specialized hardware (ESP32-S3-BOX-3) or deep technical questions, use the appropriate specialist skills and agents.\n"},"lastSynced":"2026-03-08T02:04:07.712Z","agentAnalysis":{"suitability":{"en":"Perfect for IoT Automation Agents needing streamlined ESPHome device configuration and troubleshooting capabilities.","zh":"非常适合需要简化ESPHome设备配置和故障排除能力的IoT自动化代理。","ja":"IoT自動化エージェントがESPHomeデバイスの構成とトラブルシューティングの機能を簡素化する必要がある場合に最適です。","ko":"IoT 자동화 에이전트가 ESPHome 디바이스 구성 및 문제 해결 기능을 간소화해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Automatización de IoT que necesitan una configuración y capacidades de solución de problemas de dispositivos ESPHome simplificadas.","fr":"Parfait pour les Agents d''Automatisation IoT qui ont besoin d''une configuration et de capacités de dépannage de périphériques ESPHome simplifiées.","de":"Perfekt für IoT-Automatisierungsagenten, die eine vereinfachte Konfiguration und Fehlerbehebungsfunktionen für ESPHome-Geräte benötigen.","pt":"Perfeito para Agentes de Automação de IoT que necessitam de configuração de dispositivos ESPHome simplificada e capacidades de solução de problemas.","ru":"Идеально подходит для агентов автоматизации IoT, которым необходима упрощенная настройка устройств ESPHome и возможности устранения неполадок.","ar":"مثالي للوكلاء الآليين في إنترنت الأشياء الذين يحتاجون إلى تكوين جهاز ESPHome مبسط وقدرات فحص للأخطاء."},"recommendation":{"en":"Empowers agents to rapidly generate and validate ESPHome configurations using quick-start templates, GPIO references, and error message lookup utilities, streamlining the development process for ESPHome devices with features like configuration validation workflow and common sensor configurations.","zh":"赋予代理快速生成和验证ESPHome配置的能力，使用快速入门模板、GPIO参考和错误消息查找实用程序，简化具有配置验证工作流和常见传感器配置等功能的ESPHome设备的开发过程。","ja":"クイックスタートテンプレート、GPIOリファレンス、エラーメッセージの検索ユーティリティを使用して、ESPHome構成の迅速な生成と検証を可能にし、構成の検証ワークフローや一般的なセンサー構成などの機能を持つESPHomeデバイスの開発プロセスを合理化します。","ko":"快速 시작 템플릿, GPIO 참조 및 오류 메시지 조회 유틸리티를 사용하여 ESPHome 구성의 빠른 생성 및 검증을 가능하게 하여 구성 유효성 검사 워크플로 및 일반적인 센서 구성 등과 같은 기능을 갖춘 ESPHome 디바이스의 개발 프로세스를 간소화합니다.","es":"Permite a los agentes generar y validar rápidamente configuraciones de ESPHome utilizando plantillas de inicio rápido, referencias de GPIO y utilidades de búsqueda de mensajes de error, simplificando el proceso de desarrollo para dispositivos ESPHome con características como el flujo de trabajo de validación de configuración y configuraciones de sensores comunes.","fr":"Permet aux agents de générer et de valider rapidement des configurations ESPHome en utilisant des modèles de démarrage rapide, des références de GPIO et des utilitaires de recherche de messages d''erreur, simplifiant le processus de développement pour les périphériques ESPHome avec des fonctionnalités comme le flux de travail de validation de configuration et des configurations de capteurs courants.","de":"Ermöglicht es Agenten, ESPHome-Konfigurationen schnell mit Hilfe von Schnellstartvorlagen, GPIO-Referenzen und Fehlermeldungs-Suchwerkzeugen zu generieren und zu validieren, wodurch der Entwicklungsprozess für ESPHome-Geräte mit Funktionen wie Konfigurationsvalidierungs-Workflow und gängigen Sensor-Konfigurationen vereinfacht wird.","pt":"Habilita os agentes a gerar e validar rapidamente configurações ESPHome usando modelos de início rápido, referências GPIO e utilitários de pesquisa de mensagens de erro, simplificando o processo de desenvolvimento para dispositivos ESPHome com recursos como fluxo de trabalho de validação de configuração e configurações de sensores comuns.","ru":"Наделяет агентов возможностью быстро генерировать и проверять конфигурации ESPHome с помощью шаблонов быстрого запуска, справочников GPIO и утилит поиска сообщений об ошибках, упрощая процесс разработки для устройств ESPHome с функциями, такими как рабочий процесс проверки конфигурации и общие конфигурации датчиков.","ar":"تمكّن الوكلاء من توليد وتنقيح-configurações ESPHome بسرعة باستخدام قوالب البداية السريعة ومراجع GPIO وبرامج البحث عن رسائل الخطأ، مبسطًا عملية التطوير لأجهزة ESPHome مع ميزات مثل تدفق عمل التحقق من الصحة وتكوينات المستشعرات الشائعة."},"useCases":{"en":["Generating ESPHome configurations for common device types","Troubleshooting ESPHome device issues using error message lookup and solutions","Validating ESPHome configurations to prevent errors and conflicts","Creating wiring diagrams for common sensor configurations"],"zh":["为常见设备类型生成ESPHome配置","使用错误消息查找和解决方案排除ESPHome设备问题","验证ESPHome配置以防止错误和冲突","为常见传感器配置创建接线图"],"ja":["一般的なデバイスの種類のためのESPHome構成を生成する","エラーメッセージの検索と解決策を使用してESPHomeデバイスの問題をトラブルシューティングする","エラーやコンフリクトを防ぐためにESPHome構成を検証する","一般的なセンサー構成のための配線図を作成する"],"ko":["일반적인 디바이스 유형에 대한 ESPHome 구성 생성","오류 메시지 조회 및 해결책을 사용하여 ESPHome 디바이스 문제 해결","오류 및 충돌 방지를 위해 ESPHome 구성 검증","일반적인 센서 구성에 대한 배선도 생성"],"es":["Generación de configuraciones de ESPHome para tipos de dispositivos comunes","Solución de problemas de dispositivos ESPHome mediante la búsqueda de mensajes de error y soluciones","Validación de configuraciones de ESPHome para prevenir errores y conflictos","Creación de diagramas de cableado para configuraciones de sensores comunes"],"fr":["Génération de configurations ESPHome pour des types de périphériques courants","Dépannage de problèmes de périphériques ESPHome à l''aide de la recherche de messages d''erreur et de solutions","Validation de configurations ESPHome pour prévenir les erreurs et les conflits","Création de diagrammes de câblage pour des configurations de capteurs courants"],"de":["Generierung von ESPHome-Konfigurationen für gängige Gerätetypen","Fehlerbehebung bei ESPHome-Geräten mithilfe der Fehlermeldungs-Suche und Lösungen","Validierung von ESPHome-Konfigurationen, um Fehler und Konflikte zu vermeiden","Erstellung von Verkabelungsdiagrammen für gängige Sensor-Konfigurationen"],"pt":["Geração de configurações ESPHome para tipos de dispositivos comuns","Solução de problemas de dispositivos ESPHome usando pesquisa de mensagens de erro e soluções","Validação de configurações ESPHome para prevenir erros e conflitos","Criação de diagramas de fiação para configurações de sensores comuns"],"ru":["Генерация конфигураций ESPHome для распространенных типов устройств","Устранение неполадок устройств ESPHome с помощью поиска сообщений об ошибках и решений","Проверка конфигураций ESPHome для предотвращения ошибок и конфликтов","Создание схем подключения для общих конфигураций датчиков"],"ar":["توليد-configurações ESPHome لأنواع الأجهزة الشائعة","فحص أخطاء أجهزة ESPHome باستخدام بحث رسائل الأخطاء والحلول"," التحقق من صحة-configurações ESPHome لمنع الأخطاء والصراعات","إنشاء رسومات التماسك ل-tipo configurações الشائعة للمستشعرات"]},"limitations":{"en":["Requires ESPHome device and configuration knowledge","Limited to ESPHome ecosystem","GPIO pinout references may require manual updates for custom devices"],"zh":["需要ESPHome设备和配置知识","仅限ESPHome生态系统","GPIO引脚排列参考可能需要手动更新以适应自定义设备"],"ja":["ESPHomeデバイスおよび構成の知識が必要","ESPHomeエコシステムに限定される","GPIOピンアウトリファレンスは、カスタムデバイスに対応するために手動で更新する必要がある場合がある"],"ko":["ESPHome 디바이스 및 구성에 대한 지식이 필요","ESPHome 생태계에만 제한","GPIO 핀 아웃 참조는 사용자 지정 디바이스에 대한 지원을 위해 수동으로 업데이트해야 할 수 있음"],"es":["Requiere conocimientos de dispositivos y configuración de ESPHome","Limitado al ecosistema de ESPHome","Las referencias de pinout de GPIO pueden requerir actualizaciones manuales para dispositivos personalizados"],"fr":["Nécessite des connaissances en périphériques et en configuration ESPHome","Limité à l''écosystème ESPHome","Les références de pinout de GPIO peuvent nécessiter des mises à jour manuelles pour les périphériques personnalisés"],"de":["Benötigt Kenntnisse von ESPHome-Geräten und -Konfiguration","Begrenzt auf das ESPHome-Ökosystem","Die GPIO-Pinout-Referenzen können für benutzerdefinierte Geräte manuelle Updates erfordern"],"pt":["Exige conhecimento de dispositivos e configuração ESPHome","Limitado ao ecossistema ESPHome","Referências de pinout GPIO podem exigir atualizações manuais para dispositivos personalizados"],"ru":["Требует знания устройств и конфигурации ESPHome","Ограничен экосистемой ESPHome","Справочники разводки GPIO могут требовать ручных обновлений для пользовательских устройств"],"ar":["يتطلب معرفة بأجهزة و-tipo configuração ESPHome","محدود بنظام بيئي ESPHome","مراجع مخطط GPIO قد تتطلب تحديثات يدوية لأجهزة مخصصة"]},"version":4},"contentHash":"8ef553f1dedc5249a2ca939f3b21196632b9732a9933a03ab7b8ed465881265e","qualityScore":65}');
