INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nodnarbnitram/claude-code-extensions/esphome-config-helper', 'esphome-config-helper', 'nodnarbnitram', 'claude-code-extensions', 'community', 'esphome-config-helper nodnarbnitram claude-code-extensions community The esphome-config-helper skill accelerates ESPHome device configuration for developers, providing quick-start templates, GPIO references, and validation utilities. It benefits developers working with ESPHome devices. ESPHome 配置助手是一款用于快速生成和排除 ESPHome 设备配置故障的工具，提供模板、GPIO 引脚参考和验证工具 ESPHome 設定ヘルパーは、ESPHome デバイスの設定を迅速に生成してトラブルシューティングを行うためのツールです ESPHome 설정 도우미는 ESPHome 장치 설정을 빠르게 생성하고 문제를 해결하기 위한 도구입니다 esphome-config-helper es una colección de extensiones para Claude Code que facilitan la configuración de dispositivos ESPHome con plantillas y guías de referencia esphome-config-helper est un ensemble d''extensions pour Claude Code qui facilitent la configuration des appareils ESPHome avec des modèles et des guides de référence esphome-config-helper ist eine Sammlung von Erweiterungen für Claude Code, die die Konfiguration von ESPHome-Geräten mit Vorlagen und Referenzhandbüchern erleichtern O esphome-config-helper é uma coleção de extensões para Claude Code que acelera a configuração de dispositivos ESPHome. esphome-config-helper - это коллекция расширений для Claude Code, ускоряющая настройку устройств ESPHome. esphome-config-helper هي مجموعة من الامتدادات لمكتبة Claude Code التي تسريع عملية تشغيل أجهزة ESPHome how to use esphome-config-helper esphome-config-helper setup guide ESPHome configuration generation esphome-config-helper alternative esphome-config-helper vs opencode esphome-config-helper install what is esphome-config-helper esphome-config-helper troubleshooting ESPHome device configuration ESPHome 配置 ESPHome 故障排除 AI 配置助手 GPIO 引脚参考 ESPHome 设备配置 快速启动模板 错误消息查找 Provides quick-start templates for common ESPHome device types Includes GPIO pinout references to prevent conflicts Offers common sensor configurations with wiring diagrams Features error message lookup and solutions Includes a configuration validation workflow esphome-config-helper is a collection of extensions for rapid ESPHome configuration generation and troubleshooting, offering templates, GPIO guides, and validation tools.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stharrold/finder/bmad-planner', 'community', 'stharrold', 'finder', 'stharrold/finder', 'bmad-planner', 0, 0, 65, '2026-03-08T01:57:15.370Z', '2026-03-08T02:04:26.522Z', 'a5ffb1f00ca6c2cdb8fbc3b2d0afd8dfd6901fcd8cec5787c2ba715d23c1f168', '{"id":"stharrold/finder/bmad-planner","name":"bmad-planner","description":{"en":"The bmad-planner skill enables developers to perform web searches and create Business Model, Architecture, and Design documentation. It benefits developers working in the planning phase.","zh":"bmad-planner是一个交互式的Python脚本，用于创建业务模型、架构和设计文档，节省约2,000-2,700个令牌","ja":"bmad-plannerは、ビジネスモデル、アーキテクチャ、デザイン文書を作成するためのインタラクティブなPythonスクリプトです。約2,000-2,700トークンを節約","ko":"bmad-planner는 비즈니스 모델, 아키텍처 및 디자인 문서를 생성하기 위한 상호 작용 Python 스크립트로, 약 2,000-2,700 토큰을 절약합니다","es":"bmad-planner es una herramienta interactiva y callable en Python que facilita la planificación de modelos de negocio y arquitectura, ahorrando ~2,000-2,700 tokens por característica","fr":"bmad-planner est un outil interactif et appelable en Python qui facilite la planification de modèles d''entreprise et d''architecture, économisant ~2,000-2,700 jetons par fonctionnalité","de":"bmad-planner ist ein interaktives und aufrufbares Python-Tool, das die Planung von Geschäftsmodellen und Architekturen erleichtert und ~2,000-2,700 Token pro Funktion spart","pt":"O bmad-planner é uma ferramenta de planejamento de modelos de negócios que executa uma busca web para encontrar recursos, economizando ~2,000-2,700 tokens por recurso","ru":"bmad-planner - это инструмент планирования бизнес-моделей, который выполняет поиск в Интернете для нахождения ресурсов, экономя ~2,000-2,700 токенов на функцию","ar":"bmad-planner هو أداة تخطيط نماذج الأعمال التي تنفذ بحثًا على شبكة الإنترنت للعثور على الموارد، مما يوفر ~2,000-2,700 رمزًا لكل ميزة"},"seo":{"title":{"en":"bmad-planner: Setup Guide for AI Agents | AI Agent Skill","zh":"bmad-planner_SETUP GUIDE：使用Python脚本进行交互式业务模型规划","ja":"bmad-planner_Setupガイド：Pythonスクリプトによるインタラクティブビジネスモデル設計","ko":"bmad-planner_SETUP GUIDE: Python 스크립트를 사용한 상호 작용 비즈니스 모델 계획","es":"Guía de configuración de bmad-planner: Herramienta de pla...","fr":"Guide de configuration de bmad-planner: Outil de planific...","de":"Einrichtungsanleitung für bmad-planner: Geschäftsmodell- ...","pt":"Guia de Configuração do bmad-planner: Ferramenta de Plane...","ru":"Настройка bmad-planner: Инструмент планирования бизнес-мо...","ar":"دليل إعداد bmad-planner: أداة تخطيط نماذج الأعمال الإلكتر..."},"description":{"en":"Streamline your planning phase with bmad-planner, an interactive callable Python script that saves ~2,000-2,700 tokens per feature. Learn how to use it now!","zh":"使用bmad-planner进行业务模型、架构和设计文档创建，节省手动复制的代价，提高开发效率，了解更多","ja":"bmad-plannerを使用してビジネスモデル、アーキテクチャ、デザイン文書を作成し、手動複製のコストを削減して開発効率を向上させる","ko":"bmad-planner를 사용하여 비즈니스 모델, 아키텍처 및 디자인 문서를 생성하고 수동 복제의 비용을 절감하여 개발 효율성을 향상시키는 방법","es":"Descubre cómo utilizar bmad-planner para agilizar el proceso de planificación de modelos de negocio y arquitectura con su herramienta interactiva y callable ...","fr":"Découvrez comment utiliser bmad-planner pour accélérer le processus de planification de modèles d''entreprise et d''architecture avec son outil interactif et a...","de":"Erfahren Sie, wie Sie bmad-planner verwenden können, um den Prozess der Planung von Geschäftsmodellen und Architekturen mit seinem interaktiven und aufrufbar...","pt":"Aprenda a configurar o bmad-planner, uma ferramenta de planejamento de modelos de negócios que economiza tokens e melhora a eficiência do desenvolvimento de ...","ru":"Узнайте, как настроить bmad-planner, инструмент планирования бизнес-моделей, который экономит токены и улучшает эффективность разработки функций ИИ Агентов","ar":"تعلم كيفية إعداد bmad-planner، أداة تخطيط نماذج الأعمال التي توفر الرموز وتحسن كفاءة تطوير الميزات الإلكترونية"},"definition":{"en":"bmad-planner is an interactive callable Python script that facilitates Business Model, Architecture, and Design documentation creation.","zh":"bmad-planner是一种用于创建业务模型、架构和设计文档的交互式Python脚本工具","ja":"bmad-plannerは、ビジネスモデル、アーキテクチャ、デザイン文書を作成するためのインタラクティブなPythonスクリプトツール","ko":"bmad-planner는 비즈니스 모델, 아키텍처 및 디자인 문서를 생성하기 위한 상호 작용 Python 스크립트 도구입니다","es":"bmad-planner es una herramienta de planificación de modelo de negocio y arquitectura que utiliza un script de Python interactivo y callable","fr":"bmad-planner est un outil de planification de modèle d''entreprise et d''architecture qui utilise un script Python interactif et appelable","de":"bmad-planner ist ein Tool für die Planung von Geschäftsmodellen und Architekturen, das ein interaktives und aufrufbares Python-Skript verwendet","pt":"O bmad-planner é uma ferramenta de planejamento de modelos de negócios que utiliza busca web para encontrar recursos","ru":"bmad-planner - это инструмент планирования бизнес-моделей, который использует поиск в Интернете для нахождения ресурсов","ar":"bmad-planner هو أداة تخطيط نماذج الأعمال التي تستخدم بحثًا على شبكة الإنترنت للعثور على الموارد"},"features":{"en":["Runs as an interactive callable Python script","Saves ~2,000-2,700 tokens per feature compared to manual reproduction","Operates in the main repository, not worktree","Functions in the contrib/<gh-user> branch","Active during the Planning phase (Phase 1)"],"zh":["交互式Python脚本","业务模型、架构和设计文档创建","节省约2,000-2,700个令牌","支持主仓库和contrib分支","规划阶段（Phase 1）"],"ja":["インタラクティブなPythonスクリプト","ビジネスモデル、アーキテクチャ、デザイン文書の作成","約2,000-2,700トークンの節約","メインリポジトリとcontribブランチのサポート","計画段階（Phase 1）"],"ko":["상호 작용 Python 스크립트","비즈니스 모델, 아키텍처 및 디자인 문서 생성","약 2,000-2,700 토큰 절약","메인 저장소 및 contrib 분기 지원","계획 단계 (Phase 1)"],"es":["Herramienta interactiva y callable en Python","Ahorrador de ~2,000-2,700 tokens por característica","Se utiliza en la fase de planificación (Fase 1)","Se ejecuta en el directorio principal del repositorio","Se utiliza en la rama ''contrib/<gh-user>''"],"fr":["Outil interactif et appelable en Python","Économiseur de ~2,000-2,700 jetons par fonctionnalité","Utilisé dans la phase de planification (Phase 1)","Exécuté dans le répertoire principal du référentiel","Utilisé dans la branche ''contrib/<gh-user>''"],"de":["Interaktives und aufrufbares Python-Tool","Spart ~2,000-2,700 Token pro Funktion","Wird in der Planungsphase (Phase 1) verwendet","Wird im Hauptverzeichnis des Repositorys ausgeführt","Wird in der Zweig ''contrib/<gh-user>'' verwendet"],"pt":["Executa busca web para encontrar recursos","Economiza ~2,000-2,700 tokens por recurso","Ferramenta interativa e chamável em Python","Otimizado para fase de planejamento (Fase 1)","Funciona no diretório principal do repositório","Suporta branch ''contrib/<gh-user>''"],"ru":["Выполняет поиск в Интернете для нахождения ресурсов","Экономит ~2,000-2,700 токенов на функцию","Интерактивный и вызываемый инструмент на Python","Оптимизирован для фазы планирования (Фаза 1)","Работает в основной директории репозитория","Поддерживает ветку ''contrib/<gh-user>''"],"ar":["تنفذ بحثًا على شبكة الإنترنت للعثور على الموارد","يوفر ~2,000-2,700 رمزًا لكل ميزة","أداة تفاعلية وقابلة لل呼و في بيثون","مختصر لمرحلة التخطيط (المرحلة 1)","تعمل في الدليل الرئيسي للمستودع","تدعم الفرع ''contrib/<gh-user>''"]},"keywords":{"en":["how to use bmad-planner","bmad-planner setup guide","bmad-planner alternative","bmad-planner vs manual planning","bmad-planner install","what is bmad-planner","bmad-planner for AI agents","bmad-planner tutorial","bmad-planner documentation"],"zh":["bmad-planner","Python脚本","业务模型","架构","设计文档","交互式工具","AIエージェント","开发效率"],"ja":["bmad-planner","Pythonスクリプト","ビジネスモデル","アーキテクチャ","デザイン文書","インタラクティブツール","AIエージェント","開発効率"],"ko":["bmad-planner","Python 스크립트","비즈니스 모델","아키텍처","디자인 문서","상호 작용 도구","AI 에이전트","개발 효율성"],"es":["herramientas de planificación de modelo de negocio","herramientas de arquitectura de software","script de Python interactivo","ahorrador de tokens","planificación de características","desarrollo de software ágil"],"fr":["outils de planification de modèle d''entreprise","outils d''architecture de logiciel","script Python interactif","économiseur de jetons","planification de fonctionnalités","développement de logiciel agile"],"de":["Tools für die Planung von Geschäftsmodellen","Tools für die Architektur von Software","interaktives Python-Skript","Token-Spar-Tool","Planung von Funktionen","Agiles Software-Entwickeln"],"pt":["bmad-planner","ferramenta de planejamento de modelos de negócios","busca web","economia de tokens","desenvolvimento de recursos","python","planejamento de recursos","ferramentas de desenvolvimento","otimização de desenvolvimento"],"ru":["bmad-planner","инструмент планирования бизнес-моделей","поиск в Интернете","экономия токенов","разработка функций","python","планирование функций","инструменты разработки","оптимизация разработки"],"ar":["bmad-planner","أداة تخطيط نماذج الأعمال","بحث على شبكة الإنترنت","توفير الرموز","تطوير الميزات","بيثون","تخطيط الميزات","أدوات تطوير","تحسين التطوير"]}},"owner":"stharrold","repo":"finder","repoPath":"stharrold/finder","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.370Z","topics":[],"category":"community","skillMd":{"name":"bmad-planner","description":"|","version":"5.1.0","bodyPreview":"# BMAD Planner\n\n## Purpose\n\nBusiness Model, Architecture, and Design documentation created in main\nrepository before feature development begins.\n\n**Now available as an interactive callable Python script** - saves ~2,000-2,700 tokens per feature compared to manual reproduction.\n\n## When to Use\n\n- Current directory: main repository (not worktree)\n- Current branch: `contrib/<gh-user>`\n- Phase: Planning (Phase 1)\n\n## Interactive Callable Tool\n\nBMAD is now an **interactive callable tool** that runs a","body":"# BMAD Planner\n\n## Purpose\n\nBusiness Model, Architecture, and Design documentation created in main\nrepository before feature development begins.\n\n**Now available as an interactive callable Python script** - saves ~2,000-2,700 tokens per feature compared to manual reproduction.\n\n## When to Use\n\n- Current directory: main repository (not worktree)\n- Current branch: `contrib/<gh-user>`\n- Phase: Planning (Phase 1)\n\n## Interactive Callable Tool\n\nBMAD is now an **interactive callable tool** that runs as a Python script in the main repository.\n\n### Invocation\n\n**Command:**\n```bash\npython .claude/skills/bmad-planner/scripts/create_planning.py \\\n  <slug> <gh_user>\n```\n\n**Arguments:**\n- `slug`: Feature slug (e.g., my-feature)\n- `gh_user`: GitHub username\n- `--no-commit`: Optional flag to skip git commit (for testing)\n\n**Example:**\n```bash\n# In main repo on contrib branch\npython .claude/skills/bmad-planner/scripts/create_planning.py \\\n  my-feature stharrold\n```\n\n### Interactive Session Flow\n\n**Session output:**\n```\nWorking in main repository...\nBranch: contrib/stharrold\n\n======================================================================\nBMAD Interactive Planning Tool\n======================================================================\n\nCreating planning documents for: my-feature\nGitHub user: stharrold\nOutput directory: planning/my-feature\n\n======================================================================\n🧠 BMAD Analyst Persona - Requirements Gathering\n======================================================================\n\nI''ll help create the requirements document through interactive Q&A.\n----------------------------------------------------------------------\n\nWhat problem does this feature solve?\n> Add German vocabulary search by part of speech\n\nWho are the primary users of this feature?\n> German language learners\n\n[... continues with 5-10 questions ...]\n\n✓ Requirements gathering complete!\n\n======================================================================\n🏗️ BMAD Architect Persona - Technical Architecture Design\n======================================================================\n\nBased on the requirements, I''ll design the technical architecture.\n----------------------------------------------------------------------\n\nTechnology Stack:\n\nWeb framework (if applicable)?\n  1) FastAPI\n  2) Flask\n  3) Django\n  4) None\n  [default: None]\n> 4\n\n[... continues with 5-8 questions ...]\n\n✓ Architecture design complete!\n\n======================================================================\n📋 BMAD PM Persona - Epic Breakdown\n======================================================================\n\nAnalyzing requirements and architecture to create epic breakdown...\n----------------------------------------------------------------------\n\n✓ Identified 3 epics:\n  - E-001: Data Layer Foundation (Priority: P0, Medium complexity)\n  - E-002: Core Business Logic (Priority: P0, High complexity)\n  - E-003: Testing & Quality Assurance (Priority: P1, Medium complexity)\n\n✓ Epic breakdown complete!\n\n======================================================================\nGenerating Planning Documents\n======================================================================\n  ✓ Created planning/my-feature/CLAUDE.md\n  ✓ Created planning/my-feature/README.md\n  ✓ Created planning/my-feature/ARCHIVED/CLAUDE.md\n  ✓ Created planning/my-feature/ARCHIVED/README.md\n  ✓ Created planning/my-feature/requirements.md\n  ✓ Created planning/my-feature/architecture.md\n  ✓ Created planning/my-feature/epics.md\n\nCommitting planning documents...\n✓ Committed planning documents for my-feature\n\n======================================================================\n✓ BMAD Planning Documents Created Successfully!\n======================================================================\n\nFiles created in planning/my-feature:\n  - requirements.md (Business requirements and acceptance criteria)\n  - architecture.md (Technical architecture and design)\n  - epics.md (Epic breakdown and planning)\n  - CLAUDE.md (Context for Claude Code)\n  - README.md (Human-readable overview)\n  - ARCHIVED/ (Directory for deprecated planning docs)\n\nNext steps:\n  1. Review planning documents in planning/my-feature\n  2. Create feature worktree\n  3. SpecKit will auto-detect and use these planning documents\n  4. Token savings: ~1,700-2,700 tokens by reusing planning context\n```\n\n**What happens:**\n1. Script validates location (main repo, contrib branch)\n2. Conducts 🧠 Analyst Q&A (5-10 questions)\n3. Generates requirements.md from template + Q&A responses\n4. Conducts 🏗️ Architect Q&A (5-8 questions)\n5. Generates architecture.md from template + Q&A responses\n6. Automatically analyzes requirements + architecture (📋 PM)\n7. Generates epics.md with epic breakdown\n8. Creates compliant planning/<slug>/ directory structure\n9. Commits changes to contrib branch\n\n**Token Efficiency:**\n\n| Approach | Token Usage | Savings |\n|----------|-------------|---------|\n| **Before (manual):** Claude Code reproduces BMAD each time | ~2,500 tokens | - |\n| **After (callable tool):** Claude Code calls script | ~200 tokens | ~2,300 tokens (92%) |\n\n### Script Architecture\n\n**Location:** `.claude/skills/bmad-planner/scripts/create_planning.py`\n\n**Key functions:**\n- `detect_context()` - Verify main repo, contrib branch\n- `interactive_qa_analyst()` - 🧠 Requirements Q&A\n- `interactive_qa_architect()` - 🏗️ Architecture Q&A\n- `generate_epic_breakdown()` - 📋 Auto-generate epics\n- `process_*_template()` - Replace placeholders, inject Q&A responses\n- `create_directory_structure()` - CLAUDE.md, README.md, ARCHIVED/\n- `commit_planning_docs()` - Git commit\n\n## Document Templates\n\nTemplates are located in `templates/`:\n- `requirements.md.template` - Business requirements and acceptance criteria (170 lines)\n- `architecture.md.template` - System architecture and design decisions (418 lines)\n- `epics.md.template` - Epic breakdown with priorities and dependencies (245 lines)\n\n## Interactive Planning Approach\n\nBMAD uses a three-persona method to gather comprehensive planning information through interactive Q&A sessions with the user.\n\n### 🧠 Persona 1: BMAD Analyst (Requirements)\n\n**Role:** Business Analyst creating Product Requirements Document\n\n**Process:**\n1. Ask user about problem statement and business context\n2. Identify target users and stakeholders\n3. Define success criteria and measurable outcomes\n4. Gather functional and non-functional requirements\n5. Document user stories with scenarios\n6. Identify risks and constraints\n\n**Interactive Q&A Example:**\n```\nI''ll help create the requirements document using the BMAD Analyst persona.\n\nWhat problem does this feature solve?\n> [User describes the problem]\n\nWho are the primary users of this feature?\n> [User identifies user types]\n\nHow will we measure success for this feature?\n> [User defines success metrics]\n\nWhat are the must-have capabilities? (functional requirements)\n> [User lists key capabilities]\n\nAny performance, security, or scalability requirements? (non-functional)\n> [User specifies NFRs]\n```\n\n**Generates:** `planning/<feature>/requirements.md` using comprehensive template\n\n### 🏗️ Persona 2: BMAD Architect (Architecture)\n\n**Role:** Technical Architect designing system architecture\n\n**Process:**\n1. Read requirements.md for business context\n2. Ask user about technology preferences and constraints\n3. Design system components and data models\n4. Define API contracts and integration points\n5. Specify security, error handling, testing strategies\n6. Document deployment and observability approach\n\n**Interactive Q&A Example:**\n```\nBased on the requirements, I''ll design the technical architecture.\n\nTechnology preferences?\n- Web framework: FastAPI / Flask / Django?\n> [User chooses framework]\n\nDatabase requirements?\n- Development: SQLite\n- Production: PostgreSQL / MySQL?\n> [User chooses database]\n\nPerformance targets?\n- Response time: < 200ms?\n- Concurrent users: How many?\n> [User specifies targets]\n\nContainer strategy?\n- Using Podman (default for this project)\n- Multi-container setup needed?\n> [User confirms approach]\n```\n\n**Generates:** `planning/<feature>/architecture.md` using comprehensive template\n\n### 📋 Persona 3: BMAD PM (Epic Breakdown)\n\n**Role:** Project Manager breaking down work into epics\n\n**Process:**\n1. Read requirements.md + architecture.md for full context\n2. Identify major work streams (epics)\n3. Define scope, complexity, and dependencies for each epic\n4. Prioritize epics (P0/P1/P2)\n5. Create implementation timeline\n6. Estimate effort and identify risks\n\n**Analysis:**\n```\nAnalyzing requirements and architecture to create epic breakdown...\n\nIdentified 3 major epics:\n1. E-001: Data Layer (Foundation) - P0, High complexity\n2. E-002: API Layer (Core functionality) - P0, Medium complexity\n3. E-003: Testing & Quality - P1, Medium complexity\n\nDependencies detected:\n  E-001 → E-002 (API needs data layer)\n  E-002 → E-003 (tests need API)\n\nCreating epic breakdown document...\n```\n\n**Generates:** `planning/<feature>/epics.md` with epic definitions, priorities, timeline\n\n## How to Invoke BMAD\n\nWhen workflow-orchestrator loads bmad-planner during Phase 1, it calls the create_planning.py script.\n\n**Workflow Orchestrator Code:**\n```python\n# In workflow orchestrator - Phase 1.1\nif current_phase == 1 and current_step == ''1.1'':\n    import subprocess\n\n    result = subprocess.run([\n        ''python'',\n        ''.claude/skills/bmad-planner/scripts/create_planning.py'',\n        slug,       # my-feature\n        gh_user,    # stharrold\n    ], check=True)\n\n    # Script handles:\n    # - 🧠 Analyst Q&A with user\n    # - 🏗️ Architect Q&A with user\n    # - 📋 PM epic breakdown (automatic)\n    # - requirements.md, architecture.md, epics.md generation\n    # - Directory structure creation\n    # - Git commit\n\n    print(f\"✓ BMAD planning created in planning/{slug}/\")\n    print(\"  Next: Create feature worktree (Phase 2)\")\n```\n\n**User Experience:**\n```\nPhase 1: BMAD Planning Session\n\nWorkflow calls:\n  python .claude/skills/bmad-planner/scripts/create_planning.py my-feature stharrold\n\nScript conducts interactive session:\n  🧠 BMAD Analyst: Requirements gathering [5-10 questions]\n  🏗️ BMAD Architect: Architecture design [5-8 questions]\n  📋 BMAD PM: Epic breakdown [automatic analysis]\n\n✓ Generated: planning/my-feature/requirements.md\n✓ Generated: planning/my-feature/architecture.md\n✓ Generated: planning/my-feature/epics.md\n✓ Committed to contrib branch\n\n✓ BMAD planning complete!\n  Next: Create feature worktree (Phase 2 will use these docs)\n  Token savings: ~2,300 tokens vs manual approach\n```\n\n## Integration with Workflow\n\nThe workflow-orchestrator calls the create_planning.py script during Phase 1:\n\n```python\n# In workflow orchestrator\nif current_phase == 1 and current_step == ''1.1'':\n    import subprocess\n\n    result = subprocess.run([\n        ''python'',\n        ''.claude/skills/bmad-planner/scripts/create_planning.py'',\n        slug,\n        gh_user,\n    ], check=True)\n\n    print(f\"✓ BMAD planning created: planning/{slug}/\")\n```\n\n## Output Files\n\nBMAD generates three planning documents that become input context for SpecKit:\n\n```\nplanning/<feature-name>/\n├── requirements.md    # Business requirements (170 lines from template)\n│   ├─ Problem statement, stakeholders\n│   ├─ Functional requirements (FR-001, FR-002...)\n│   ├─ Non-functional requirements (performance, security...)\n│   ├─ User stories with scenarios\n│   └─ Risks, assumptions, success criteria\n│\n├── architecture.md    # Technical architecture (418 lines from template)\n│   ├─ System overview, components\n│   ├─ Technology stack with justifications\n│   ├─ Data models, API endpoints\n│   ├─ Container architecture (Containerfile, podman-compose.yml)\n│   ├─ Security, error handling, testing strategies\n│   └─ Deployment, observability, disaster recovery\n│\n├── epics.md          # Epic breakdown (245 lines from template)\n│   ├─ Epic definitions (scope, complexity, priority)\n│   ├─ Dependencies and critical path\n│   ├─ Implementation timeline\n│   └─ Resource requirements and risks\n│\n├── CLAUDE.md         # Context for this planning directory\n├── README.md         # Human-readable overview\n└── ARCHIVED/         # Deprecated planning documents\n```\n\n**These files become input context for SpecKit in Phase 2.**\n\n## Integration with SpecKit\n\nBMAD documents are used as context when creating SpecKit specifications:\n\n### Data Flow: BMAD → SpecKit\n\n**Phase 1 (Main Repo, contrib branch):**\n```\nBMAD Interactive Session\n  ↓\nplanning/<feature>/\n├── requirements.md\n├── architecture.md\n└── epics.md\n```\n\n**Create Worktree:**\n```bash\n# Worktree creation preserves link to main repo\ngit worktree add ../repo_feature_<slug> feature/<timestamp>_<slug>\n```\n\n**Phase 2 (Worktree):**\n```\nSpecKit reads from main repo:\n../planning/<feature>/requirements.md → Business context\n../planning/<feature>/architecture.md → Technical design\n../planning/<feature>/epics.md        → Epic priorities\n\nSpecKit generates (informed by BMAD):\nspecs/<feature>/spec.md  ← Detailed specification\nspecs/<feature>/plan.md  ← Implementation tasks\n```\n\n### Why This Connection Matters\n\n**Consistency:**\n- Technology choices in spec.md match architecture.md stack\n- spec.md acceptance criteria cover requirements.md success criteria\n- plan.md tasks align with epics.md breakdown\n\n**Completeness:**\n- All functional requirements from requirements.md appear in spec.md\n- Non-functional requirements (performance, security) included\n- Epic dependencies reflected in plan.md task ordering\n\n**Traceability:**\n- spec.md sections reference FR-001, FR-002... from requirements.md\n- plan.md tasks map to E-001, E-002... from epics.md\n- Architecture decisions from architecture.md justify implementation choices\n\n**Less Rework:**\n- Planning clarifies requirements before coding\n- Design decisions made explicit\n- Reduces ambiguity and prevents scope creep\n\n## Integration with Workflow\n\nThe workflow-orchestrator calls this skill during Phase 1:\n\n```python\n# In workflow orchestrator\nif current_phase == 1 and current_step == ''1.1'':\n    load_skill(''bmad-planner'')\n    create_planning_docs(feature_name, gh_user)\n    commit_changes(''docs: add BMAD planning for '' + feature_name)\n```\n\n## Template Placeholders\n\nBoth templates use these placeholders:\n- `{{TITLE}}` - Feature name (title case)\n- `{{DATE}}` - Creation date (YYYY-MM-DD)\n- `{{GH_USER}}` - GitHub username\n\n## Best Practices\n\n- **Requirements first**: Define business needs before technical design\n- **Acceptance criteria**: Make success measurable\n- **Architecture clarity**: Explain design decisions and trade-offs\n- **Technology justification**: Document why specific tools/frameworks chosen\n- **Non-functional requirements**: Don''t forget performance, security, scalability\n"},"lastSynced":"2026-03-08T02:04:26.522Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated Business Model, Architecture, and Design documentation creation.","zh":"非常适合需要自动创建业务模型、架构和设计文档的开发代理。","ja":"ビジネスモデル、建築、設計のドキュメント作成を自動化する必要がある開発エージェントに最適です。","ko":"자동으로 비즈니스 모델, 아키텍처 및 디자인 문서를 생성해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una creación automatizada de documentación de modelo de negocio, arquitectura y diseño.","fr":"Parfait pour les agents de développement ayant besoin d''une création automatique de documentation de modèle commercial, d''architecture et de conception.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Erstellung von Geschäftsmodell-, Architektur- und Design-Dokumentation benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de criação automatizada de documentação de Modelo de Negócios, Arquitetura e Design.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированная создание документации бизнес-модели, архитектуры и дизайна.","ar":"مثالي للوكلاء التطوير الذين يحتاجون إلى إنشاء تلقائي لوثائق نموذج الأعمال والهيكلة والتصميم."},"recommendation":{"en":"Empowers agents to perform web searches and generate comprehensive BMAD documentation using interactive callable Python scripts, saving ~2,000-2,700 tokens per feature and supporting feature development in the planning phase with protocols like Git branching.","zh":"赋予代理执行网页搜索并使用交互式可调用Python脚本生成全面的BMAD文档的能力，每个功能可节省约2,000-2,700个令牌，并支持使用Git分支等协议的规划阶段功能开发。","ja":"エージェントがWeb検索を実行し、インタラクティブなcallable Pythonスクリプトを使用して包括的なBMADドキュメントを生成する機能を付与し、約2,000-2,700トークンを節約し、Gitブランチングなどのプロトコルを使用した計画段階の機能開発をサポートします。","ko":"에이전트가 웹 검색을 수행하고 상호 작용 가능한 callable Python 스크립트를 사용하여 포괄적인 BMAD 문서를 생성하여 기능당 약 2,000-2,700개의 토큰을 절약하고 Git 브랜칭 등의 프로토콜을 사용한 계획 단계 기능 개발을 지원하는 기능을 부여합니다.","es":"Habilita a los agentes a realizar búsquedas web y generar documentación de BMAD completa utilizando scripts de Python interactivos llamables, ahorrando ~2,000-2,700 tokens por función y apoyando el desarrollo de funciones en la fase de planificación con protocolos como Git branching.","fr":"Permet aux agents d''effectuer des recherches web et de générer une documentation de BMAD complète en utilisant des scripts Python interactifs appelables, économisant ~2,000-2,700 jetons par fonction et soutenant le développement de fonctions dans la phase de planification avec des protocoles comme Git branching.","de":"Ermöglicht es Agenten, Web-Suchen durchzuführen und umfassende BMAD-Dokumentation mithilfe interaktiver, aufrufbarer Python-Skripte zu generieren, wodurch ~2,000-2,700 Token pro Funktion eingespart werden und die Funktionsentwicklung in der Planungsphase mit Protokollen wie Git-Branching unterstützt wird.","pt":"Habilita os agentes a realizar pesquisas na web e gerar documentação de BMAD abrangente usando scripts Python interativos chamáveis, economizando ~2.000-2.700 tokens por recurso e apoiando o desenvolvimento de recursos na fase de planejamento com protocolos como branching do Git.","ru":"Наделяет агентов возможностью выполнять веб-поиски и генерировать всестороннюю документацию BMAD с помощью интерактивных вызываемых скриптов Python, экономя ~2 000-2 700 токенов на функцию и поддерживая разработку функций на этапе планирования с протоколами như ветвление Git.","ar":"يمنح الوكلاء القدرة على إجراء عمليات بحث على الويب وإنشاء وثائق شاملة لBMAD باستخدام سكريبتات بايثون تفاعلية قابلة للاتصال، وتوفير ~2،000-2،700 رمز لكل ميزة ودعم تطوير الميزات في مرحلة التخطيط ببروتوكولات مثل فرع Git."},"useCases":{"en":["Automating BMAD documentation creation","Generating Business Model reports","Creating Architecture and Design documentation"],"zh":["自动创建BMAD文档","生成业务模型报告","创建架构和设计文档"],"ja":["BMADドキュメントの自動作成","ビジネスモデルレポートの生成","アーキテクチャと設計のドキュメント作成"],"ko":["BMAD 문서 자동 생성","비즈니스 모델 보고서 생성","아키텍처 및 디자인 문서 생성"],"es":["Automatización de la creación de documentación de BMAD","Generación de informes de modelo de negocio","Creación de documentación de arquitectura y diseño"],"fr":["Automatisation de la création de documentation de BMAD","Génération de rapports de modèle commercial","Création de documentation d''architecture et de conception"],"de":["Automatisierung der Erstellung von BMAD-Dokumentation","Generierung von Geschäftsmodell-Berichten","Erstellung von Architektur- und Design-Dokumentation"],"pt":["Automatizar a criação de documentação de BMAD","Gerar relatórios de Modelo de Negócios","Criar documentação de Arquitetura e Design"],"ru":["Автоматизировать создание документации BMAD","Генерировать отчеты бизнес-модели","Создавать документацию архитектуры и дизайна"],"ar":["أتمتة إنشاء وثائق BMAD","توليد تقارير نموذج الأعمال","إنشاء وثائق هيكلية وتصميم"]},"limitations":{"en":["Requires main repository access","Limited to planning phase (Phase 1)","Must be run from ''contrib/<gh-user>'' branch"],"zh":["需要主存储库访问权","仅限规划阶段（第1阶段）","必须从''contrib/<gh-user>''分支运行"],"ja":["主リポジトリへのアクセスが必要","計画段階（フェーズ1）のみ","''contrib/<gh-user>''ブランチから実行する必要がある"],"ko":["주 저장소 액세스가 필요함","계획 단계(1단계)로 제한됨","''contrib/<gh-user>'' 브랜치에서 실행해야 함"],"es":["Requiere acceso al repositorio principal","Limitado a la fase de planificación (Fase 1)","Debe ejecutarse desde la rama ''contrib/<gh-user>''"],"fr":["Nécessite un accès au référentiel principal","Limité à la phase de planification (Phase 1)","Doit être exécuté à partir de la branche ''contrib/<gh-user>''"],"de":["Erfordert Zugriff auf das Hauptrepository","Begrenzt auf die Planungsphase (Phase 1)","Muss von dem Branch ''contrib/<gh-user>'' aus ausgeführt werden"],"pt":["Exige acesso ao repositório principal","Limitado à fase de planejamento (Fase 1)","Deve ser executado a partir da branch ''contrib/<gh-user>''"],"ru":["Требуется доступ к основному репозиторию","Ограничен этапом планирования (Этап 1)","Должно быть выполнено из ветки ''contrib/<gh-user>''"],"ar":["يتطلب الوصول إلى المستودع الرئيسي","محدود بمرحلة التخطيط (المرحلة 1)","يجب تشغيله من الفرع ''contrib/<gh-user>''"]},"version":4},"contentHash":"a5ffb1f00ca6c2cdb8fbc3b2d0afd8dfd6901fcd8cec5787c2ba715d23c1f168","qualityScore":65}');
