INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stharrold/finder/bmad-planner', 'bmad-planner', 'stharrold', 'finder', 'community', 'bmad-planner stharrold finder community The bmad-planner skill enables developers to perform web searches and create Business Model, Architecture, and Design documentation. It benefits developers working in the planning phase. bmad-planner是一个交互式的Python脚本，用于创建业务模型、架构和设计文档，节省约2,000-2,700个令牌 bmad-plannerは、ビジネスモデル、アーキテクチャ、デザイン文書を作成するためのインタラクティブなPythonスクリプトです。約2,000-2,700トークンを節約 bmad-planner는 비즈니스 모델, 아키텍처 및 디자인 문서를 생성하기 위한 상호 작용 Python 스크립트로, 약 2,000-2,700 토큰을 절약합니다 bmad-planner es una herramienta interactiva y callable en Python que facilita la planificación de modelos de negocio y arquitectura, ahorrando ~2,000-2,700 tokens por característica bmad-planner est un outil interactif et appelable en Python qui facilite la planification de modèles d''entreprise et d''architecture, économisant ~2,000-2,700 jetons par fonctionnalité bmad-planner ist ein interaktives und aufrufbares Python-Tool, das die Planung von Geschäftsmodellen und Architekturen erleichtert und ~2,000-2,700 Token pro Funktion spart O bmad-planner é uma ferramenta de planejamento de modelos de negócios que executa uma busca web para encontrar recursos, economizando ~2,000-2,700 tokens por recurso bmad-planner - это инструмент планирования бизнес-моделей, который выполняет поиск в Интернете для нахождения ресурсов, экономя ~2,000-2,700 токенов на функцию bmad-planner هو أداة تخطيط نماذج الأعمال التي تنفذ بحثًا على شبكة الإنترنت للعثور على الموارد، مما يوفر ~2,000-2,700 رمزًا لكل ميزة how to use bmad-planner bmad-planner setup guide bmad-planner alternative bmad-planner vs manual planning bmad-planner install what is bmad-planner bmad-planner for AI agents bmad-planner tutorial bmad-planner documentation bmad-planner Python脚本 业务模型 架构 设计文档 交互式工具 AIエージェント 开发效率 Runs as an interactive callable Python script Saves ~2,000-2,700 tokens per feature compared to manual reproduction Operates in the main repository, not worktree Functions in the contrib/<gh-user> branch Active during the Planning phase (Phase 1) bmad-planner is an interactive callable Python script that facilitates Business Model, Architecture, and Design documentation creation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('frmoretto/clarity-gate/clarity-gate', 'community', 'frmoretto', 'clarity-gate', 'frmoretto/clarity-gate', 'clarity-gate', 0, 0, 65, '2026-03-08T01:57:15.371Z', '2026-03-08T02:04:28.690Z', 'd6e812f6c76fda1bd2cbb480b08ad0ef1ac8302f1fd10ab94654c2528b89b072', '{"id":"frmoretto/clarity-gate/clarity-gate","name":"clarity-gate","description":{"en":"clarity-gate is a verification protocol that stops LLMs from mistaking assumptions for facts. It benefits developers working with RAG systems and LLMs by ensuring epistemic quality in their documents.","zh":"Clarity Gate是一种验证协议，确保LLM和RAG系统中的文档准确性","ja":"Clarity Gateは、LLMとRAGシステムで使用される文書の精度を確保するための検証プロトコルです","ko":"Clarity Gate는 LLM과 RAG 시스템에서 사용되는 문서의 정확성을 보장하는 검증 프로토콜입니다","es":"Clarity Gate es un protocolo de verificación para documentos que se proporcionarán a LLM o sistemas RAG, que coloca automáticamente marcadores de incertidumbre para evitar alucinaciones confiadas","fr":"Clarity Gate est un protocole de vérification pour les documents qui seront fournis à des LLM ou des systèmes RAG, qui place automatiquement des marqueurs d''incertitude pour éviter les hallucinations confiantes","de":"Clarity Gate ist ein Verifizierungsprotokoll für Dokumente, die an LLM oder RAG-Systeme geliefert werden, das automatisch Unsicherheitsmarker setzt, um selbstsichere Halluzinationen zu vermeiden","pt":"O Clarity Gate é um protocolo de verificação para documentos que serão fornecidos a LLMs ou sistemas RAG, adicionando marcadores de incerteza para evitar hallucinações confiantes","ru":"Clarity Gate - это протокол проверки документов, которые будут предоставлены LLM или системам RAG, добавляющий маркеры неопределенности для предотвращения уверенных галлюцинаций","ar":"Clarity Gate هو بروتوكول التحقق من الوثائق التي سيتم تقديمها إلى LLMs أو أنظمة RAG، بإضافة علامات الشك لمنع الخيال الموثوق"},"seo":{"title":{"en":"clarity-gate: Pre-Ingestion Verification Setup Guide | AI...","zh":"Clarity Gate Setup Guide: AI智能工具防歪曲","ja":"Clarity Gateベストプラクティス: AIエージェントの誤認を防ぐ","ko":"Clarity Gate 구현 방법: AI 에이전트의 오차 방지","es":"Configuración de Clarity Gate: Guía para evitar alucinaci...","fr":"Mise en place de Clarity Gate : Guide pour éviter les hal...","de":"Einrichtung von Clarity Gate: Anleitung zur Vermeidung vo...","pt":"Guia de Configuração do Clarity Gate para Prevenção de Ha...","ru":"Руководство по настройке Clarity Gate для предотвращения ...","ar":"دليل إعدادClarity Gate لمنع الخيال في وكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how clarity-gate prevents LLM hallucinations by enforcing epistemic quality. Learn to setup and use this verification protocol for your documents to...","zh":"了解Clarity Gate如何帮助防止LLM将猜测作为事实，通过自动添加不确定性标记","ja":"Clarity Gateを使用して、LLMが推測を事実として認識しないようにする方法","ko":"Clarity Gate를 통해 LLM이 추측을 사실로 인식하지 않도록 하는 방법에 대해 알아보세요","es":"Aprende a implementar Clarity Gate para verificar la calidad epistémica de tus documentos y evitar que los LLM confundan suposiciones con hechos","fr":"Découvrez comment mettre en place Clarity Gate pour vérifier la qualité épistémique de vos documents et éviter que les LLM confondent les suppositions avec l...","de":"Erfahren Sie, wie Sie Clarity Gate implementieren, um die epistemische Qualität Ihrer Dokumente zu überprüfen und zu verhindern, dass LLM Annahmen mit Tatsac...","pt":"Aprenda a implementar o Clarity Gate para evitar que LLMs confundam suposições com fatos, melhorando a qualidade epistêmica dos documentos","ru":"Узнайте, как реализовать Clarity Gate, чтобы предотвратить ошибочное принятие предположений за факты в ИИ Агентах","ar":"تعرف على كيفية تطبيق Clarity Gate لمنع خلط الافتراضات بالحقائق في وكلاء الذكاء الاصطناعي"},"definition":{"en":"clarity-gate is a pre-ingestion verification system that enforces epistemic quality before documents enter RAG knowledge bases, producing Clarity-Gated Documents (CGD) compliant with the Clarity Gate Format Specification v2.1","zh":"Clarity Gate是一种防止LLM将猜测作为事实的验证协议","ja":"Clarity Gateは、LLMが推測を事実として認識しないようにする検証プロトコルです","ko":"Clarity Gate는 LLM이 추측을 사실로 인식하지 않도록 하는 검증 프로토콜입니다","es":"Clarity Gate es un protocolo de verificación que garantiza la calidad epistémica de los documentos antes de que entren en las bases de conocimiento de RAG","fr":"Clarity Gate est un protocole de vérification qui garantit la qualité épistémique des documents avant qu''ils n''entrent dans les bases de connaissances de RAG","de":"Clarity Gate ist ein Verifizierungsprotokoll, das die epistemische Qualität von Dokumenten vor ihrem Eintritt in die RAG-Wissensbasen sicherstellt","pt":"Clarity Gate é um protocolo de verificação que garante a qualidade epistêmica dos documentos antes que sejam ingestados por LLMs ou sistemas RAG","ru":"Clarity Gate - это протокол проверки, обеспечивающий эпистемологическое качество документов до их ингестии LLM или системами RAG","ar":"Clarity Gate هو بروتوكول التحقق الذي يضمن جودة المعرفة للوثائق قبل أن يتم استيعابها بواسطة LLMs أو أنظمة RAG"},"features":{"en":["Automatically places missing uncertainty markers to avoid confident hallucinations","Produces Clarity-Gated Documents (CGD) compliant with the Clarity Gate Format Specification v2.1","Enforces epistemic quality before documents enter RAG knowledge bases","Supports Human-in-the-Loop (HITL) for non-directly verifiable claims","Detects and enforces what should be in documents to prevent LLM mistakes","Complies with the Clarity Gate Format Specification v2.1 for consistency"],"zh":["自动添加不确定性标记","防止LLM将猜测作为事实","支持RAG知识库","符合Clarity Gate Format Specification v2.1","HITL（人机交互学习）支持","提高LLM文档的准确性"],"ja":["不確実性マーカーの自動追加","LLMが推測を事実として認識しないようにする","RAGナレッジベースのサポート","Clarity Gate Format Specification v2.1への準拠","HITL（ヒューマン・イン・ザ・ループ）サポート","LLMドキュメントの精度の向上"],"ko":["불확실성 마커의 자동 추가","LLM이 추측을 사실로 인식하지 않도록 하는 기능","RAG 지식베이스 지원","Clarity Gate Format Specification v2.1 규격 준수","HITL（인간 및 루프）지원","LLM 문서의 정확성 향상"],"es":["Protocolo de verificación para documentos de LLM y RAG","Colocación automática de marcadores de incertidumbre","Cumplimiento con la especificación de formato de Clarity Gate v2.1","Producción de documentos con calidad epistémica verificada","Detección de suposiciones y hechos en documentos","Integración con sistemas de revisión humana para reclamos no verificables directamente"],"fr":["Protocole de vérification pour les documents de LLM et RAG","Placement automatique de marqueurs d''incertitude","Conformité à la spécification de format de Clarity Gate v2.1","Production de documents avec une qualité épistémique vérifiée","Détection des suppositions et des faits dans les documents","Intégration avec les systèmes de révision humaine pour les réclamations non vérifiables directement"],"de":["Verifizierungsprotokoll für LLM- und RAG-Dokumente","Automatische Platzierung von Unsicherheitsmarkern","Konformität mit der Clarity-Gate-Format-Spezifikation v2.1","Erzeugung von Dokumenten mit überprüfter epistemischer Qualität","Erkennung von Annahmen und Tatsachen in Dokumenten","Integration mit menschlicher Überprüfung für nicht direkt überprüfbare Ansprüche"],"pt":["Adiciona marcadores de incerteza automaticamente para evitar hallucinações confiantes","Garante a qualidade epistêmica dos documentos antes da ingestão por LLMs ou sistemas RAG","Compatível com o formato de especificação Clarity Gate v2.1","Suporta HITL para reivindicações não diretamente verificáveis","Pre-ingestão de verificação para evitar erros de LLMs","Produz documentos Clarity-Gated (CGD) conformes com a especificação"],"ru":["Автоматически добавляет маркеры неопределенности для предотвращения уверенных галлюцинаций","Гарантирует эпистемологическое качество документов до их ингестии LLM или системами RAG","Совместим с форматом спецификации Clarity Gate v2.1","Поддерживает HITL для непрямых проверяемых утверждений","Предварительная проверка для предотвращения ошибок LLM","Производит документы Clarity-Gated (CGD), соответствующие спецификации"],"ar":["يضيف علامات الشك تلقائيا لمنع الخيال الموثوق","يضمن جودة المعرفة للوثائق قبل استيعابها بواسطة LLMs أو أنظمة RAG","متوافق مع مواصفات تنسيق Clarity Gate v2.1","يدعم HITL لادعاءات غير قابلة للتحقق المباشر","التحقق المسبق لمنع أخطاء LLMs","ينتج وثائق Clarity-Gated (CGD) متوافقة مع المواصفات"]},"keywords":{"en":["how to use clarity-gate","clarity-gate setup guide","clarity-gate alternative","clarity-gate vs RAG systems","what is clarity-gate","clarity-gate install","pre-ingestion verification protocol","LLM hallucination prevention","epistemic quality enforcement","Clarity Gate Format Specification v2.1"],"zh":["Clarity Gate","AI智能工具","LLM","RAG","文档验证","不确定性标记","HITL","Clarity Gate Format Specification v2.1"],"ja":["Clarity Gate","AIエージェント","LLM","RAG","ドキュメント検証","不確実性マーカー","HITL","Clarity Gate Format Specification v2.1"],"ko":["Clarity Gate","AI 에이전트","LLM","RAG","문서 검증","불확실성 마커","HITL","Clarity Gate Format Specification v2.1"],"es":["Clarity Gate","LLM","RAG","verificación de documentos","calidad epistémica","marcadores de incertidumbre","formato de Clarity Gate v2.1","revisión humana","suposiciones y hechos"],"fr":["Clarity Gate","LLM","RAG","vérification de documents","qualité épistémique","marqueurs d''incertitude","spécification de format de Clarity Gate v2.1","révision humaine","suppositions et faits"],"de":["Clarity Gate","LLM","RAG","Dokumentenverifizierung","epistemische Qualität","Unsicherheitsmarker","Clarity-Gate-Format-Spezifikation v2.1","menschliche Überprüfung","Annahmen und Tatsachen"],"pt":["Clarity Gate","LLMs","sistemas RAG","marcadores de incerteza","qualidade epistêmica","HITL","verificação de documentos","prevenção de hallucinações","formato de especificação Clarity Gate v2.1"],"ru":["Clarity Gate","ИИ Агенты","системы RAG","маркеры неопределенности","эпистемологическое качество","HITL","проверка документов","предотвращение галлюцинаций","формат спецификации Clarity Gate v2.1"],"ar":["Clarity Gate","وكلاء الذكاء الاصطناعي","أنظمة RAG","علامات الشك","جودة المعرفة","HITL","تحقق الوثائق","منع الخيال","تنسيق مواصفات Clarity Gate v2.1"]}},"owner":"frmoretto","repo":"clarity-gate","repoPath":"frmoretto/clarity-gate","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.371Z","topics":[],"category":"community","skillMd":{"name":"clarity-gate","description":">","version":"2.1.3","bodyPreview":"# Clarity Gate v2.1\n\n**Purpose:** Pre-ingestion verification system that enforces epistemic quality before documents enter RAG knowledge bases. Produces Clarity-Gated Documents (CGD) compliant with the Clarity Gate Format Specification v2.1.\n\n**Core Question:** \"If another LLM reads this document, will it mistake assumptions for facts?\"\n\n**Core Principle:** *\"Detection finds what is; enforcement ensures what should be. In practice: find the missing uncertainty markers before they become confiden","body":"# Clarity Gate v2.1\n\n**Purpose:** Pre-ingestion verification system that enforces epistemic quality before documents enter RAG knowledge bases. Produces Clarity-Gated Documents (CGD) compliant with the Clarity Gate Format Specification v2.1.\n\n**Core Question:** \"If another LLM reads this document, will it mistake assumptions for facts?\"\n\n**Core Principle:** *\"Detection finds what is; enforcement ensures what should be. In practice: find the missing uncertainty markers before they become confident hallucinations.\"*\n\n---\n\n## What''s New in v2.1\n\n| Feature | Description |\n|---------|-------------|\n| **Claim Completion Status** | PENDING/VERIFIED determined by field presence (no explicit status field) |\n| **Source Field Semantics** | Actionable source (PENDING) vs. what-was-found (VERIFIED) |\n| **Claim ID Format Guidance** | Hash-based IDs preferred, collision analysis for scale |\n| **Body Structure Requirements** | HITL Verification Record section mandatory when claims exist |\n| **New Validation Codes** | E-ST10, W-ST11, W-HC01, W-HC02, E-SC06 (FORMAT_SPEC); E-TB01-07 (SOT validation) |\n| **Bundled Scripts** | `claim_id.py` and `document_hash.py` for deterministic computations |\n\n---\n\n## Specifications\n\nThis skill implements and references:\n\n| Specification | Version | Location |\n|---------------|---------|----------|\n| Clarity Gate Format (Unified) | v2.1 | [docs/CLARITY_GATE_FORMAT_SPEC.md](../../docs/CLARITY_GATE_FORMAT_SPEC.md) |\n\n**Note:** v2.0 unifies CGD and SOT into a single `.cgd.md` format. SOT is now a CGD with an optional `tier:` block.\n\n---\n\n## Validation Codes\n\nClarity Gate defines validation codes for structural and semantic checks per FORMAT_SPEC v2.1:\n\n### HITL Claim Validation (§1.3.2-1.3.3)\n| Code | Check | Severity |\n|------|-------|----------|\n| **W-HC01** | Partial `confirmed-by`/`confirmed-date` fields | WARNING |\n| **W-HC02** | Vague source (e.g., \"industry reports\", \"TBD\") | WARNING |\n| **E-SC06** | Schema error in `hitl-claims` structure | ERROR |\n\n### Body Structure (§1.2.1)\n| Code | Check | Severity |\n|------|-------|----------|\n| **E-ST10** | Missing `## HITL Verification Record` when claims exist | ERROR |\n| **W-ST11** | Table rows don''t match `hitl-claims` count | WARNING |\n\n### SOT Table Validation (§3.1)\n| Code | Check | Severity |\n|------|-------|----------|\n| **E-TB01** | No `## Verified Claims` section | ERROR |\n| **E-TB02** | Table has no data rows | ERROR |\n| **E-TB03** | Required columns missing | ERROR |\n| **E-TB04** | Column order wrong | ERROR |\n| **E-TB05** | Empty cell in required column | ERROR |\n| **E-TB06** | Invalid date format in Verified column | ERROR |\n| **E-TB07** | Verified date in future (beyond 24h grace) | ERROR |\n\n**Note:** Additional validation codes may be defined in RFC-001 (clarification document) but are not part of the normative FORMAT_SPEC.\n\n---\n\n## Bundled Scripts\n\nThis skill includes Python scripts for deterministic computations per FORMAT_SPEC.\n\n### scripts/claim_id.py\n\nComputes stable, hash-based claim IDs for HITL tracking (per §1.3.4).\n\n```bash\n# Generate claim ID\npython scripts/claim_id.py \"Base price is $99/mo\" \"api-pricing/1\"\n# Output: claim-75fb137a\n\n# Run test vectors\npython scripts/claim_id.py --test\n```\n\n**Algorithm:**\n1. Normalize text (strip + collapse whitespace)\n2. Concatenate with location using pipe delimiter\n3. SHA-256 hash, take first 8 hex chars\n4. Prefix with \"claim-\"\n\n**Test vectors:**\n- `claim_id(\"Base price is $99/mo\", \"api-pricing/1\")` → `claim-75fb137a`\n- `claim_id(\"The API supports GraphQL\", \"features/1\")` → `claim-eb357742`\n\n### scripts/document_hash.py\n\nComputes document SHA-256 hash per FORMAT_SPEC §2.2-2.4 with full canonicalization.\n\n```bash\n# Compute hash\npython scripts/document_hash.py my-doc.cgd.md\n# Output: 7d865e959b2466918c9863afca942d0fb89d7c9ac0c99bafc3749504ded97730\n\n# Verify existing hash\npython scripts/document_hash.py --verify my-doc.cgd.md\n# Output: PASS: Hash verified: 7d865e...\n\n# Run normalization tests\npython scripts/document_hash.py --test\n```\n\n**Algorithm (per §2.2-2.4):**\n1. Extract content between opening `---\\n` and `<!-- CLARITY_GATE_END -->`\n2. Remove `document-sha256` line from YAML frontmatter ONLY (with multiline continuation support)\n3. Canonicalize:\n   - Strip trailing whitespace per line\n   - Collapse 3+ consecutive newlines to 2\n   - Normalize final newline (exactly 1 LF)\n   - UTF-8 NFC normalization\n4. Compute SHA-256\n\n**Cross-platform normalization:**\n- BOM removed if present\n- CRLF to LF (Windows)\n- CR to LF (old Mac)\n- Boundary detection (prevents hash computation on content outside CGD structure)\n- Whitespace variations produce identical hashes (deterministic across platforms)\n\n---\n\n## The Key Distinction\n\nExisting tools like UnScientify and HedgeHunter (CoNLL-2010) **detect** uncertainty markers already present in text (\"Is uncertainty expressed?\").\n\nClarity Gate **enforces** their presence where epistemically required (\"Should uncertainty be expressed but isn''t?\").\n\n| Tool Type | Question | Example |\n|-----------|----------|---------|\n| **Detection** | \"Does this text contain hedges?\" | UnScientify/HedgeHunter find \"may\", \"possibly\" |\n| **Enforcement** | \"Should this claim be hedged but isn''t?\" | Clarity Gate flags \"Revenue will be $50M\" |\n\n---\n\n## Critical Limitation\n\n> **Clarity Gate verifies FORM, not TRUTH.**\n>\n> This skill checks whether claims are properly marked as uncertain—it cannot verify if claims are actually true. \n>\n> **Risk:** An LLM can hallucinate facts INTO a document, then \"pass\" Clarity Gate by adding source markers to false claims.\n>\n> **Solution:** HITL (Human-In-The-Loop) verification is **MANDATORY** before declaring PASS.\n\n---\n\n## When to Use\n\n- Before ingesting documents into RAG systems\n- Before sharing documents with other AI systems\n- After writing specifications, state docs, or methodology descriptions\n- When a document contains projections, estimates, or hypotheses\n- Before publishing claims that haven''t been validated\n- When handing off documentation between LLM sessions\n\n---\n\n## The 9 Verification Points\n\n### Relationship to Spec Suite\n\nThe 9 Verification Points guide **semantic review** — content quality checks that require judgment (human or AI). They answer questions like \"Should this claim be hedged?\" and \"Are these numbers consistent?\"\n\nWhen review completes, output a CGD file conforming to [CLARITY_GATE_FORMAT_SPEC.md](../../docs/CLARITY_GATE_FORMAT_SPEC.md). The C/S rules in [CLARITY_GATE_FORMAT_SPEC.md](../../docs/CLARITY_GATE_FORMAT_SPEC.md) validate **file structure**, not semantic content.\n\n**The connection:**\n1. Semantic findings (9 points) determine what issues exist\n2. Issues are recorded in CGD state fields (`clarity-status`, `hitl-status`, `hitl-pending-count`)\n3. State consistency is enforced by structural rules (C7-C10)\n\n*Example: If Point 5 (Data Consistency) finds conflicting numbers, you''d mark `clarity-status: UNCLEAR` until resolved. Rule C7 then ensures you can''t claim `REVIEWED` while still `UNCLEAR`.*\n\n---\n\n### Epistemic Checks (Core Focus: Points 1-4)\n\n**1. HYPOTHESIS vs FACT LABELING**\nEvery claim must be clearly marked as validated or hypothetical.\n\n| Fails | Passes |\n|-------|--------|\n| \"Our architecture outperforms competitors\" | \"Our architecture outperforms competitors [benchmark data in Table 3]\" |\n| \"The model achieves 40% improvement\" | \"The model achieves 40% improvement [measured on dataset X]\" |\n\n**Fix:** Add markers: \"PROJECTED:\", \"HYPOTHESIS:\", \"UNTESTED:\", \"(estimated)\", \"~\", \"?\"\n\n---\n\n**2. UNCERTAINTY MARKER ENFORCEMENT**\nForward-looking statements require qualifiers.\n\n| Fails | Passes |\n|-------|--------|\n| \"Revenue will be $50M by Q4\" | \"Revenue is **projected** to be $50M by Q4\" |\n| \"The feature will reduce churn\" | \"The feature is **expected** to reduce churn\" |\n\n**Fix:** Add \"projected\", \"estimated\", \"expected\", \"designed to\", \"intended to\"\n\n---\n\n**3. ASSUMPTION VISIBILITY**\nImplicit assumptions that affect interpretation must be explicit.\n\n| Fails | Passes |\n|-------|--------|\n| \"The system scales linearly\" | \"The system scales linearly [assuming <1000 concurrent users]\" |\n| \"Response time is 50ms\" | \"Response time is 50ms [under standard load conditions]\" |\n\n**Fix:** Add bracketed conditions: \"[assuming X]\", \"[under conditions Y]\", \"[when Z]\"\n\n---\n\n**4. AUTHORITATIVE-LOOKING UNVALIDATED DATA**\nTables with specific percentages and checkmarks look like measured data.\n\n**Red flag:** Tables with specific numbers (89%, 95%, 100%) without sources\n\n**Fix:** Add \"(guess)\", \"(est.)\", \"?\" to numbers. Add explicit warning: \"PROJECTED VALUES - NOT MEASURED\"\n\n---\n\n### Data Quality Checks (Complementary: Points 5-7)\n\n**5. DATA CONSISTENCY**\nScan for conflicting numbers, dates, or facts within the document.\n\n**Red flag:** \"500 users\" in one section, \"750 users\" in another\n\n**Fix:** Reconcile conflicts or explicitly note the discrepancy with explanation.\n\n---\n\n**6. IMPLICIT CAUSATION**\nClaims that imply causation without evidence.\n\n**Red flag:** \"Shorter prompts improve response quality\" (plausible but unproven)\n\n**Fix:** Reframe as hypothesis: \"Shorter prompts MAY improve response quality (hypothesis, not validated)\"\n\n---\n\n**7. FUTURE STATE AS PRESENT**\nDescribing planned/hoped outcomes as if already achieved.\n\n**Red flag:** \"The system processes 10,000 requests per second\" (when it hasn''t been built)\n\n**Fix:** Use future/conditional: \"The system is DESIGNED TO process...\" or \"TARGET: 10,000 rps\"\n\n---\n\n### Verification Routing (Points 8-9)\n\n**8. TEMPORAL COHERENCE**\nDocument dates and timestamps must be internally consistent and plausible.\n\n| Fails | Passes |\n|-------|--------|\n| \"Last Updated: December 2024\" (when current is 2026) | \"Last Updated: January 2026\" |\n| v1.0.0 dated 2024-12-23, v1.1.0 dated 2024-12-20 | Versions in chronological order |\n\n**Sub-checks:**\n1. Document date vs current date\n2. Internal chronology (versions, events in order)\n3. Reference freshness (\"current\", \"now\", \"today\" claims)\n\n**Fix:** Update dates, add \"as of [date]\" qualifiers, flag stale claims\n\n---\n\n**9. EXTERNALLY VERIFIABLE CLAIMS**\nSpecific numbers that could be fact-checked should be flagged for verification.\n\n| Type | Example | Risk |\n|------|---------|------|\n| Pricing | \"Costs ~$0.005 per call\" | API pricing changes |\n| Statistics | \"Papers average 15-30 equations\" | May be wildly off |\n| Rates/ratios | \"40% of researchers use X\" | Needs citation |\n| Competitor claims | \"No competitor offers Y\" | May be outdated |\n\n**Fix options:**\n1. Add source with date\n2. Add uncertainty marker\n3. Route to HITL or external search\n4. Generalize (\"low cost\" instead of \"$0.005\")\n\n---\n\n## The Verification Hierarchy\n\n```\nClaim Extracted --> Does Source of Truth Exist?\n                           |\n           +---------------+---------------+\n           YES                             NO\n           |                               |\n   Tier 1: Automated              Tier 2: HITL\n   Consistency & Verification     Two-Round Verification\n           |                               |\n   PASS / BLOCK                   Round A → Round B → APPROVE / REJECT\n```\n\n### Tier 1: Automated Verification\n\n**A. Internal Consistency**\n- Figure vs. Text contradictions\n- Abstract vs. Body mismatches\n- Table vs. Prose conflicts\n- Numerical consistency\n\n**B. External Verification (Extension Interface)**\n- User-provided connectors to structured sources\n- Financial systems, Git commits, CRM, etc.\n\n### Tier 2: Two-Round HITL Verification — MANDATORY\n\n**Round A: Derived Data Confirmation**\n- Claims from sources found in session\n- Human confirms interpretation, not truth\n\n**Round B: True HITL Verification**\n- Claims needing actual verification\n- No source found, human''s own data, extrapolations\n\n---\n\n## CGD Output Format\n\nWhen producing a Clarity-Gated Document, use this format per [CLARITY_GATE_FORMAT_SPEC.md](../../docs/CLARITY_GATE_FORMAT_SPEC.md) v2.1:\n\n```yaml\n---\nclarity-gate-version: 2.1\nprocessed-date: 2026-01-12\nprocessed-by: Claude + Human Review\nclarity-status: CLEAR\nhitl-status: REVIEWED\nhitl-pending-count: 0\npoints-passed: 1-9\nrag-ingestable: true          # computed by validator - do not set manually\ndocument-sha256: 7d865e959b2466918c9863afca942d0fb89d7c9ac0c99bafc3749504ded97730\nhitl-claims:\n  - id: claim-75fb137a\n    text: \"Revenue projection is $50M\"\n    value: \"$50M\"\n    source: \"Q3 planning doc\"\n    location: \"revenue-projections/1\"\n    round: B\n    confirmed-by: Francesco\n    confirmed-date: 2026-01-12\n---\n\n# Document Title\n\n[Document body with epistemic markers applied]\n\nClaims like \"Revenue will be $50M\" become \"Revenue is **projected** to be $50M *(unverified projection)*\"\n\n---\n\n## HITL Verification Record\n\n### Round A: Derived Data Confirmation\n- Claim 1 (source) ✓\n- Claim 2 (source) ✓\n\n### Round B: True HITL Verification\n| # | Claim | Status | Verified By | Date |\n|---|-------|--------|-------------|------|\n| 1 | [claim] | ✓ Confirmed | [name] | [date] |\n\n<!-- CLARITY_GATE_END -->\nClarity Gate: CLEAR | REVIEWED\n```\n\n**Required CGD Elements (per spec):**\n- YAML frontmatter with all required fields:\n  - `clarity-gate-version` — Tool version (no \"v\" prefix)\n  - `processed-date` — YYYY-MM-DD format\n  - `processed-by` — Processor name\n  - `clarity-status` — CLEAR or UNCLEAR\n  - `hitl-status` — PENDING, REVIEWED, or REVIEWED_WITH_EXCEPTIONS\n  - `hitl-pending-count` — Integer ≥ 0\n  - `points-passed` — e.g., `1-9` or `1-4,7,9`\n  - `hitl-claims` — List of verified claims (may be empty `[]`)\n- End marker (HTML comment + status line):\n  ```\n  <!-- CLARITY_GATE_END -->\n  Clarity Gate: <clarity-status> | <hitl-status>\n  ```\n- HITL verification record (if status is REVIEWED)\n\n**Optional/Computed Fields:**\n- `rag-ingestable` — **Computed by validators**, not manually set. Shows `true` only when `CLEAR | REVIEWED` with no exclusion blocks.\n- `document-sha256` — Required. 64-char lowercase hex hash for integrity verification. See spec §2 for computation rules.\n- `exclusions-coverage` — Optional. Fraction of body inside exclusion blocks (0.0–1.0).\n\n**Escape Mechanism:** To write about markers like `*(estimated)*` without triggering parsing, wrap in backticks: `` `*(estimated)*` ``\n\n### Claim Completion Status (v2.1)\n\nClaim verification status is determined by field **presence**, not an explicit status field:\n\n| State | `confirmed-by` | `confirmed-date` | Meaning |\n|-------|----------------|------------------|----------|\n| **PENDING** | absent | absent | Awaiting human verification |\n| **VERIFIED** | present | present | Human has confirmed |\n| *(invalid)* | present | absent | W-HC01: partial fields |\n| *(invalid)* | absent | present | W-HC01: partial fields |\n\n**Why no explicit status field?** Field presence is self-enforcing—you can''t accidentally set status without providing who/when.\n\n### Source Field Semantics (v2.1)\n\nThe `source` field meaning changes based on claim state:\n\n| State | `source` Contains | Example |\n|-------|-------------------|----------|\n| **PENDING** | Where to verify (actionable) | `\"Check Q3 planning doc\"` |\n| **VERIFIED** | What was found (evidence) | `\"Q3 planning doc, page 12\"` |\n\n**Vague source detection (W-HC02):** Sources like `\"industry reports\"`, `\"research\"`, `\"TBD\"` trigger warnings.\n\n### Claim ID Format (v2.1)\n\n**General pattern:** `claim-[a-z0-9._-]{1,64}` (alphanumeric, dots, underscores, hyphens)\n\n| Approach | Pattern | Example | Use Case |\n|----------|---------|---------|----------|\n| **Hash-based** (preferred) | `claim-[a-f0-9]{8,}` | `claim-75fb137a` | Deterministic, collision-resistant |\n| **Sequential** | `claim-[0-9]+` | `claim-1`, `claim-2` | Simple documents |\n| **Semantic** | `claim-[a-z0-9-]+` | `claim-revenue-q3` | Human-friendly |\n\n**Collision probability:** At 1,000 claims with 8-char hex IDs: ~0.012%. For >1,000 claims, use 12+ hex characters.\n\n**Recommendation:** Use hash-based IDs generated by `scripts/claim_id.py` for consistency and collision resistance.\n\n---\n\n## Exclusion Blocks\n\nWhen content cannot be resolved (no SME available, legacy prose, etc.), mark it as excluded rather than leaving it ambiguous:\n\n```markdown\n<!-- CG-EXCLUSION:BEGIN id=auth-legacy-1 -->\nLegacy authentication details that require SME review...\n<!-- CG-EXCLUSION:END id=auth-legacy-1 -->\n```\n\n**Rules:**\n- IDs must match: `[A-Za-z0-9][A-Za-z0-9._-]{0,63}`\n- No nesting or overlapping blocks\n- Each ID used only once\n- Requires `hitl-status: REVIEWED_WITH_EXCEPTIONS`\n- Must document `exceptions-reason` and `exceptions-ids` in frontmatter\n\n**Important:** Documents with exclusion blocks are **not RAG-ingestable**. They''re rejected entirely (no partial ingestion).\n\nSee [CLARITY_GATE_FORMAT_SPEC.md §4](../../docs/CLARITY_GATE_FORMAT_SPEC.md) for complete rules.\n\n---\n\n## SOT Validation\n\nWhen validating a Source of Truth file, the skill checks both **format compliance** (per [CLARITY_GATE_FORMAT_SPEC.md](../../docs/CLARITY_GATE_FORMAT_SPEC.md)) and **content quality** (the 9 points).\n\n### Format Compliance (Structural Rules)\n\nSOT documents are CGDs with a `tier:` block. They require a `## Verified Claims` section with a valid table.\n\n| Code | Check | Severity |\n|------|-------|----------|\n| E-TB01 | No `## Verified Claims` section | ERROR |\n| E-TB02 | Table has no data rows | ERROR |\n| E-TB03 | Required columns missing (Claim, Value, Source, Verified) | ERROR |\n| E-TB04 | Column order wrong (Claim not first or Verified not last) | ERROR |\n| E-TB05 | Empty cell in required column | ERROR |\n| E-TB06 | Invalid date format in Verified column | ERROR |\n| E-TB07 | Verified date in future (beyond 24h grace) | ERROR |\n\n### Content Quality (9 Points)\n\nThe 9 Verification Points apply to SOT content:\n\n| Point | SOT Application |\n|-------|-----------------|\n| 1-4 | Check claims in `## Verified Claims` are actually verified |\n| 5 | Check for conflicting values across tables |\n| 6 | Check claims don''t imply unsupported causation |\n| 7 | Check table doesn''t state futures as present |\n| 8 | Check dates are chronologically consistent |\n| 9 | Flag specific numbers for external check |\n\n### SOT-Specific Requirements\n\n- **Tier block required:** SOT is a CGD with `tier:` block containing `level`, `owner`, `version`, `promoted-date`, `promoted-by`\n- **Structured claims table:** `## Verified Claims` section with columns: Claim, Value, Source, Verified\n- **Table outside exclusions:** The verified claims table must NOT be inside an exclusion block\n- **Staleness markers:** Use `[STABLE]`, `[CHECK]`, `[VOLATILE]`, `[SNAPSHOT]` in content\n  - `[STABLE]` — Safe to cite without rechecking\n  - `[CHECK]` — Verify before citing\n  - `[VOLATILE]` — Changes frequently; always verify\n  - `[SNAPSHOT]` — Point-in-time data; include date when citing\n\n---\n\n## Output Format\n\nAfter running Clarity Gate, report:\n\n```\n## Clarity Gate Results\n\n**Document:** [filename]\n**Issues Found:** [number]\n\n### Critical (will cause hallucination)\n- [issue + location + fix]\n\n### Warning (could cause equivocation)  \n- [issue + location + fix]\n\n### Temporal (date/time issues)\n- [issue + location + fix]\n\n### Externally Verifiable Claims\n| # | Claim | Type | Suggested Verification |\n|---|-------|------|------------------------|\n| 1 | [claim] | Pricing | [where to verify] |\n\n---\n\n## Round A: Derived Data Confirmation\n\n- [claim] ([source])\n\nReply \"confirmed\" or flag any I misread.\n\n---\n\n## Round B: HITL Verification Required\n\n| # | Claim | Why HITL Needed | Human Confirms |\n|---|-------|-----------------|----------------|\n| 1 | [claim] | [reason] | [ ] True / [ ] False |\n\n---\n\n**Would you like me to produce an annotated CGD version?**\n\n---\n\n**Verdict:** PENDING CONFIRMATION\n```\n\n---\n\n## Severity Levels\n\n| Level | Definition | Action |\n|-------|------------|--------|\n| **CRITICAL** | LLM will likely treat hypothesis as fact | Must fix before use |\n| **WARNING** | LLM might misinterpret | Should fix |\n| **TEMPORAL** | Date/time inconsistency detected | Verify and update |\n| **VERIFIABLE** | Specific claim that could be fact-checked | Route to HITL or external search |\n| **ROUND A** | Derived from witnessed source | Quick confirmation |\n| **ROUND B** | Requires true verification | Cannot pass without confirmation |\n| **PASS** | Clearly marked, no ambiguity, verified | No action needed |\n\n---\n\n## Quick Scan Checklist\n\n| Pattern | Action |\n|---------|--------|\n| Specific percentages (89%, 73%) | Add source or mark as estimate |\n| Comparison tables | Add \"PROJECTED\" header |\n| \"Achieves\", \"delivers\", \"provides\" | Use \"designed to\", \"intended to\" if not validated |\n| Checkmarks | Verify these are confirmed |\n| \"100%\" anything | Almost always needs qualification |\n| \"Last Updated: [date]\" | Check against current date |\n| Version numbers with dates | Verify chronological order |\n| \"$X.XX\" or \"~$X\" (pricing) | Flag for external verification |\n| \"averages\", \"typically\" | Flag for source/citation |\n| Competitor capability claims | Flag for external verification |\n\n---\n\n## What This Skill Does NOT Do\n\n- Does not classify document types (use Stream Coding for that)\n- Does not restructure documents \n- Does not add deep links or references\n- Does not evaluate writing quality\n- **Does not check factual accuracy autonomously** (requires HITL)\n\n---\n\n## Related Projects\n\n| Project | Purpose | URL |\n|---------|---------|-----|\n| Source of Truth Creator | Create epistemically calibrated docs | github.com/frmoretto/source-of-truth-creator |\n| Stream Coding | Documentation-first methodology | github.com/frmoretto/stream-coding |\n| ArXiParse | Scientific paper verification | arxiparse.org |\n\n---\n\n## Changelog\n\n### v2.1.3 (2026-03-02)\n- **FIXED:** `document_hash.py` now implements full FORMAT_SPEC §2.1-2.4 compliance\n- **FIXED:** Fence-aware end marker detection (Quine Protection per §2.3/§8.5)\n- **FIXED:** All 4 deployment copies converged to single canonical implementation\n- **ADDED:** `canonicalize()` function: trailing whitespace stripping, newline collapsing, NFC normalization\n- **ADDED:** YAML-aware `document-sha256` removal with multiline continuation support (§2.2)\n- **ADDED:** Fence-tracking test vectors (7 new tests, 15 total)\n\n### v2.1.0 (2026-01-27)\n- **ADDED:** Claim Completion Status semantics (PENDING/VERIFIED by field presence)\n- **ADDED:** Source Field Semantics (actionable vs. what-was-found)\n- **ADDED:** Claim ID Format guidance with collision analysis\n- **ADDED:** Body Structure Requirements (HITL Verification Record mandatory when claims exist)\n- **ADDED:** New validation codes: E-ST10, W-ST11, W-HC01, W-HC02, E-SC06 (FORMAT_SPEC §1.2-1.3)\n- **ADDED:** Bundled scripts: `claim_id.py`, `document_hash.py`\n- **UPDATED:** References to FORMAT_SPEC v2.1\n- **UPDATED:** CGD output example to version 2.1\n\n### v2.0.0 (2026-01-13)\n- **ADDED:** agentskills.io compliant YAML frontmatter\n- **ADDED:** Clarity Gate Format Specification v2.0 compliance (unified CGD/SOT)\n- **ADDED:** SOT validation support with E-TB* error codes\n- **ADDED:** Validation rules mapping (9 points → rule codes)\n- **ADDED:** CGD output format template with `<!-- CLARITY_GATE_END -->` markers\n- **ADDED:** Quine Protection note (§2.3 fence-aware marker detection)\n- **ADDED:** Redacted Export feature (§8.11)\n- **UPDATED:** `hitl-claims` format to v2.0 schema (id, text, value, source, location, round)\n- **UPDATED:** End marker format to HTML comment style\n- **UPDATED:** Unified format spec v2.0 (single `.cgd.md` extension)\n- **RESTRUCTURED:** For multi-platform skill discovery\n\n### v1.6 (2025-12-31)\n- Added Two-Round HITL verification system\n- Round A: Derived Data Confirmation\n- Round B: True HITL Verification\n\n### v1.5 (2025-12-28)\n- Added Point 8: Temporal Coherence\n- Added Point 9: Externally Verifiable Claims\n\n### v1.4 (2025-12-23)\n- Added CGD annotation output mode\n\n### v1.3 (2025-12-21)\n- Restructured points into Epistemic (1-4) and Data Quality (5-7)\n\n### v1.2 (2025-12-21)\n- Added Source of Truth request step\n\n### v1.1 (2025-12-21)\n- Added HITL Fact Verification (mandatory)\n\n### v1.0 (2025-11)\n- Initial release with 6-point verification\n\n---\n\n**Version:** 2.1.3\n**Spec Version:** 2.1\n**Author:** Francesco Marinoni Moretto\n**License:** CC-BY-4.0\n"},"lastSynced":"2026-03-08T02:04:28.690Z","agentAnalysis":{"suitability":{"en":"Ideal for Epistemically-Aware Agents requiring advanced verification protocols to ensure fact-based document ingestion.","zh":"适用于需要高级验证协议来确保基于事实的文档摄取的本体意识代理。","ja":"事実に基づいた文書のインジェストを確実にするために高度な検証プロトコルを必要とする認識アウェアエージェントに最適です。","ko":"사실 기반 문서 摂取을 보장하기 위해 고급 검증 프로토콜을 필요로 하는 인식 에이전트에 적합합니다.","es":"Ideal para Agentes Epistémicamente Conscientes que requieren protocolos de verificación avanzados para garantizar la ingesta de documentos basados en hechos.","fr":"Idéal pour les Agents Epistémiquement Conscients nécessitant des protocoles de vérification avancés pour assurer l''ingestion de documents basés sur des faits.","de":"Ideal für Epistemisch Bewusste Agenten, die erweiterte Überprüfungsprotokolle benötigen, um die faktengestützte Dokumenteneingabe zu gewährleisten.","pt":"Ideal para Agentes Epistemicamente Conscientes que requerem protocolos de verificação avançados para garantir a ingestão de documentos baseados em fatos.","ru":"Идеально для Эпистемически-Осведомленных Агентов, требующих передовых протоколов верификации для обеспечения факто-основанной ингестии документов.","ar":"مثالي لعميل متعلم القدرات المعرفية التي تتطلب بروتوكولات التحقق المتقدمة لضمان استهلاك الوثائق القائمة على الحقائق."},"recommendation":{"en":"Empowers agents to enforce epistemic quality in documents through the Clarity Gate Format Specification v2.1, detecting and preventing assumptions from being mistaken for facts, and producing Clarity-Gated Documents (CGD) compliant with RAG systems and LLMs.","zh":"通过Clarity Gate Format Specification v2.1，赋予代理人在文档中执行本体质量的能力，检测和防止假设被误认为是事实，并生成符合RAG系统和LLMs的Clarity-Gated Documents (CGD)。","ja":"Clarity Gate Format Specification v2.1を通じて、エージェントに文書内で認識の質を実施する能力を付与し、仮定が事実と誤認されるのを検知して防止し、RAGシステムやLLMsと互換性のあるClarity-Gated Documents (CGD)を生成します。","ko":"클라리티 게이트 형식 사양 v2.1을 통해 에이전트가 문서에서 인식 품질을 강제하는 능력을 부여하여 가정을 사실로 오인하는 것을 감지하고 방지하며, RAG 시스템 및 LLMs와 호환되는 클라리티 게이티드 문서(CGD)를 생성합니다.","es":"Habilita a los agentes a hacer cumplir la calidad epistémica en los documentos a través de la Especificación de Formato de Puerta de Claridad v2.1, detectando y previniendo que las suposiciones se confundan con hechos, y produciendo Documentos con Puerta de Claridad (CGD) compatibles con sistemas RAG y LLMs.","fr":"Permet aux agents de faire respecter la qualité épistémique dans les documents via la Spécification de Format de Porte de Clarté v2.1, en détectant et en prévenant que les suppositions soient prises pour des faits, et en produisant des Documents à Porte de Clarté (CGD) compatibles avec les systèmes RAG et LLMs.","de":"Ermächtigt Agenten, die epistemische Qualität in Dokumenten durch die Clarity Gate Format Specification v2.1 durchzusetzen, indem es die Erkennung und Verhinderung von Annahmen verhindert, die mit Tatsachen verwechselt werden, und Clarity-Gated Documents (CGD) produziert, die mit RAG-Systemen und LLMs kompatibel sind.","pt":"Habilita os agentes a impor a qualidade epistêmica nos documentos por meio da Especificação de Formato de Porta de Clareza v2.1, detectando e prevenindo que suposições sejam confundidas com fatos, e produzindo Documentos com Porta de Clareza (CGD) compatíveis com sistemas RAG e LLMs.","ru":"Наделяет агентов возможностью обеспечить эпистемическое качество документов посредством Спецификации Формата Четкой Записи v2.1, обнаруживая и предотвращая принятие предположений за факты, и производя Документы с Четкой Записью (CGD), совместимые с системами RAG и LLMs.","ar":"يمكن للوكلاء فرض الجودة المعرفية في الوثائق من خلال مواصفة تنسيق بوابة الوضوح v2.1 ، وتحديد ومنع افتراضات الخلط مع الحقائق ، وإنتاج وثائق بوابة الوضوح (CGD) متوافقة مع أنظمة RAG و LLMs."},"useCases":{"en":["Verifying document accuracy before ingestion into RAG knowledge bases","Enforcing epistemic quality standards in large document collections","Detecting missing uncertainty markers to prevent confident mistakes"],"zh":["在将文档摄取到RAG知识库之前验证文档的准确性","在大型文档集合中执行本体质量标准","检测缺失的不确定性标记以防止自信的错误"],"ja":["RAGナレッジベースにインジェストする前に文書の正確性を検証する","大規模な文書コレクションで認識の質の基準を実施する","自信を持ったミスの防止のために不確実性マーカーが欠けていることを検知する"],"ko":["RAG 지식 베이스에 摂取하기 전에 문서의 정확성을 검증하는 것","대규모 문서 컬렉션에서 인식 품질 표준을 강제하는 것","자신감 있는 오류를 방지하기 위해 불확실성 표시가 누락되어 있는 것을 감지하는 것"],"es":["Verificar la exactitud de los documentos antes de la ingesta en bases de conocimiento RAG","Hacer cumplir los estándares de calidad epistémica en grandes colecciones de documentos","Detectar marcadores de incertidumbre faltantes para prevenir errores confiados"],"fr":["Vérifier l''exactitude des documents avant l''ingestion dans les bases de connaissances RAG","Faire respecter les normes de qualité épistémique dans les grandes collections de documents","Détecter les marqueurs d''incertitude manquants pour prévenir les erreurs confiantes"],"de":["Überprüfen der Dokumentengenauigkeit vor der Eingabe in RAG-Wissensbasen","Durchsetzen der epistemischen Qualitätsstandards in großen Dokumentsammlungen","Erkennen fehlender Unsicherheitsmarker, um vertrauenswürdige Fehler zu verhindern"],"pt":["Verificar a precisão do documento antes da ingestão em bases de conhecimento RAG","Impor padrões de qualidade epistêmica em grandes coleções de documentos","Detectar marcadores de incerteza ausentes para prevenir erros confiantes"],"ru":["Проверка точности документа перед ингестией в базы знаний RAG","Обеспечение стандартов эпистемического качества в больших коллекциях документов","Обнаружение отсутствующих маркеров неопределенности для предотвращения уверенных ошибок"],"ar":["التحقق من دقة الوثيقة قبل الاستهلاك في قواعدمعرفة RAG","فرض معايير الجودة المعرفية في مجموعات وثائق كبيرة","اكتشاف علامات الشك الغائبة لمنع الأخطاء الثقة"]},"limitations":{"en":["Requires integration with RAG systems and LLMs","Dependent on Clarity Gate Format Specification v2.1 compliance"],"zh":["需要与RAG系统和LLMs集成","依赖于Clarity Gate Format Specification v2.1的兼容性"],"ja":["RAGシステムやLLMsとの統合が必要","Clarity Gate Format Specification v2.1の互換性に依存する"],"ko":["RAG 시스템 및 LLMs와의 통합이 필요","클라리티 게이트 형식 사양 v2.1의 호환성에 의존"],"es":["Requiere integración con sistemas RAG y LLMs","Dependiente del cumplimiento de la Especificación de Formato de Puerta de Claridad v2.1"],"fr":["Nécessite une intégration avec les systèmes RAG et LLMs","Dépendante du respect de la Spécification de Format de Porte de Clarté v2.1"],"de":["Benötigt Integration mit RAG-Systemen und LLMs","Abhängig vom Einhalten der Clarity Gate Format Specification v2.1"],"pt":["Requer integração com sistemas RAG e LLMs","Dependente do cumprimento da Especificação de Formato de Porta de Clareza v2.1"],"ru":["Требует интеграции с системами RAG и LLMs","Зависит от соблюдения Спецификации Формата Четкой Записи v2.1"],"ar":["يتطلب التكامل مع أنظمة RAG و LLMs","يعتمد على الامتثال لمواصفة تنسيق بوابة الوضوح v2.1"]},"version":4},"contentHash":"d6e812f6c76fda1bd2cbb480b08ad0ef1ac8302f1fd10ab94654c2528b89b072","qualityScore":65}');
DELETE FROM skills_fts WHERE id = 'frmoretto/clarity-gate/clarity-gate';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frmoretto/clarity-gate/clarity-gate', 'clarity-gate', 'frmoretto', 'clarity-gate', 'community', 'clarity-gate frmoretto clarity-gate community clarity-gate is a verification protocol that stops LLMs from mistaking assumptions for facts. It benefits developers working with RAG systems and LLMs by ensuring epistemic quality in their documents. Clarity Gate是一种验证协议，确保LLM和RAG系统中的文档准确性 Clarity Gateは、LLMとRAGシステムで使用される文書の精度を確保するための検証プロトコルです Clarity Gate는 LLM과 RAG 시스템에서 사용되는 문서의 정확성을 보장하는 검증 프로토콜입니다 Clarity Gate es un protocolo de verificación para documentos que se proporcionarán a LLM o sistemas RAG, que coloca automáticamente marcadores de incertidumbre para evitar alucinaciones confiadas Clarity Gate est un protocole de vérification pour les documents qui seront fournis à des LLM ou des systèmes RAG, qui place automatiquement des marqueurs d''incertitude pour éviter les hallucinations confiantes Clarity Gate ist ein Verifizierungsprotokoll für Dokumente, die an LLM oder RAG-Systeme geliefert werden, das automatisch Unsicherheitsmarker setzt, um selbstsichere Halluzinationen zu vermeiden O Clarity Gate é um protocolo de verificação para documentos que serão fornecidos a LLMs ou sistemas RAG, adicionando marcadores de incerteza para evitar hallucinações confiantes Clarity Gate - это протокол проверки документов, которые будут предоставлены LLM или системам RAG, добавляющий маркеры неопределенности для предотвращения уверенных галлюцинаций Clarity Gate هو بروتوكول التحقق من الوثائق التي سيتم تقديمها إلى LLMs أو أنظمة RAG، بإضافة علامات الشك لمنع الخيال الموثوق how to use clarity-gate clarity-gate setup guide clarity-gate alternative clarity-gate vs RAG systems what is clarity-gate clarity-gate install pre-ingestion verification protocol LLM hallucination prevention epistemic quality enforcement Clarity Gate Format Specification v2.1 Clarity Gate AI智能工具 LLM RAG 文档验证 不确定性标记 HITL Clarity Gate Format Specification v2.1 Automatically places missing uncertainty markers to avoid confident hallucinations Produces Clarity-Gated Documents (CGD) compliant with the Clarity Gate Format Specification v2.1 Enforces epistemic quality before documents enter RAG knowledge bases Supports Human-in-the-Loop (HITL) for non-directly verifiable claims Detects and enforces what should be in documents to prevent LLM mistakes Complies with the Clarity Gate Format Specification v2.1 for consistency clarity-gate is a pre-ingestion verification system that enforces epistemic quality before documents enter RAG knowledge bases, producing Clarity-Gated Documents (CGD) compliant with the Clarity Gate Format Specification v2.1');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('goodnight000/KittyCourt/book-sft-pipeline', 'community', 'goodnight000', 'KittyCourt', 'goodnight000/KittyCourt', 'book-sft-pipeline', 0, 0, 65, '2026-03-08T01:57:15.382Z', '2026-03-08T02:05:41.861Z', '4b20fbfaa162bcbf131f713707bd51808f01766d8139b6055466b8b3abb32b9e', '{"id":"goodnight000/KittyCourt/book-sft-pipeline","name":"book-sft-pipeline","description":{"en":"The book-sft-pipeline skill enables developers to convert raw ePub files into SFT datasets and train style-transfer models, ideal for building fine-tuning datasets and creating author-voice models.","zh":"Book SFT Pipeline是一个完整的系统，用于将书籍转换为SFT数据集和训练风格转换模型。它支持从raw ePub到模型训练的整个流程。","ja":"Book SFT Pipelineは、書籍をSFTデータセットに変換し、スタイル転送モデルをトレーニングするための完全なシステムです。raw ePubからモデルトレーニングまでの全プロセスをサポートします。","ko":"Book SFT Pipeline는 책을 SFT 데이터셋으로 변환하고 스타일 전환 모델을 학습하는 완벽한 시스템입니다. raw ePub에서 모델 학습까지의 전체 프로세스를 지원합니다.","es":"Book-sft-pipeline es un sistema completo para convertir libros en conjuntos de datos SFT y entrenar modelos de transferencia de estilo. Esta habilidad enseña el proceso desde un archivo ePub raw hasta un modelo que escribe en la voz de cualquier autor.","fr":"Book-sft-pipeline est un système complet pour convertir des livres en jeux de données SFT et entraîner des modèles de transfert de style. Cette compétence enseigne le processus depuis un fichier ePub brut jusqu''à un modèle qui écrit dans la voix de n''importe quel auteur.","de":"Book-sft-pipeline ist ein vollständiges System zur Konvertierung von Büchern in SFT-Datensätze und zum Trainieren von Stil-Transfer-Modellen. Diese Fähigkeit lehrt den Prozess von einer rohen ePub-Datei bis hin zu einem Modell, das in der Stimme jedes Autors schreibt.","pt":"O pipeline de livros SFT é um sistema completo para converter livros em datasets SFT e treinar modelos de transferência de estilo. Aprenda a criar datasets de fine-tuning e treinar modelos com este skill","ru":"Конвейер книг SFT - это полная система для преобразования книг в наборы данных SFT и обучения моделей передачи стиля. Научитесь создавать наборы данных для fine-tuning и обучать модели с помощью этого навыка и ИИ Агентов","ar":"خط أنابيب الكتاب SFT هو نظام كامل لتحويل الكتب إلى مجموعات بيانات SFT وتدريب نماذج نقل الأسلوب. تعلم كيفية إنشاء مجموعات بيانات للتعدين الدقيق وتدريب النماذج باستخدام هذا المهارة"},"seo":{"title":{"en":"book-sft-pipeline: Style-Transfer Model Setup Guide | AI ...","zh":"Book SFT Pipeline_SETUP GUIDE：从ePub到风格转换模型","ja":"Book SFT Pipeline セットアップガイド: ePubからスタイル転送モデルまで","ko":"Book SFT Pipeline 설정 가이드: ePub에서 스타일 전환 모델까지","es":"Guía de configuración de book-sft-pipeline para modelos d...","fr":"Guide de mise en place de book-sft-pipeline pour les modè...","de":"Einrichtungsleitfaden für book-sft-pipeline zur Erstellun...","pt":"Guia de Configuração do Pipeline de Livros SFT para Desen...","ru":"Настройка конвейера книг SFT: ИИ Агенты для Fine-Tuning","ar":"دليل إعداد خط أنابيب الكتاب SFT للطورين"},"description":{"en":"Unlock author-voice models with book-sft-pipeline. Learn how to convert eBooks to SFT datasets and train style-transfer models. Get started now!","zh":"使用Book SFT Pipeline，从ePub转换为SFT数据集并训练风格转换模型，AIエージェント","ja":"Book SFT Pipelineを使用して、ePubをSFTデータセットに変換し、スタイル転送モデルをトレーニングする、AIエージェント","ko":"Book SFT Pipeline를 사용하여 ePub를 SFT 데이터셋으로 변환하고 스타일 전환 모델을 학습하는 방법, AI 도구","es":"Aprende a configurar book-sft-pipeline para convertir libros en conjuntos de datos SFT y entrenar modelos de transferencia de estilo con esta guía paso a paso","fr":"Découvrez comment configurer book-sft-pipeline pour convertir des livres en jeux de données SFT et entraîner des modèles de transfert de style avec ce guide ...","de":"Erfahren Sie, wie Sie book-sft-pipeline einrichten, um Bücher in SFT-Datensätze umzuwandeln und Stil-Transfer-Modelle zu trainieren, mit diesem Schritt-für-S...","pt":"Aprenda a criar datasets de fine-tuning a partir de obras literárias e treinar modelos de transferência de estilo com o pipeline de livros SFT","ru":"Создайте наборы данных для fine-tuning из литературных произведений и обучите модели передачи стиля с помощью конвейера книг SFT и ИИ Агентов","ar":"تعلم كيفية إنشاء مجموعات بيانات للتعدين الدقيق من الأعمال الأدبية وتدريب نماذج نقل الأسلوب باستخدام خط أنابيب الكتاب SFT"},"definition":{"en":"book-sft-pipeline is a complete system for converting books into SFT datasets and training style-transfer models, supporting text segmentation pipelines for long-form content.","zh":"Book SFT Pipeline是一种用于将书籍转换为SFT数据集和训练风格转换模型的技术","ja":"Book SFT Pipelineは、書籍をSFTデータセットに変換し、スタイル転送モデルをトレーニングする技術です","ko":"Book SFT Pipeline는 책을 SFT 데이터셋으로 변환하고 스타일 전환 모델을 학습하는 기술입니다","es":"Book-sft-pipeline es una habilidad de AI que convierte libros en conjuntos de datos SFT para entrenar modelos de transferencia de estilo","fr":"Book-sft-pipeline est une compétence d''IA qui convertit des livres en jeux de données SFT pour entraîner des modèles de transfert de style","de":"Book-sft-pipeline ist eine KI-Fähigkeit, die Bücher in SFT-Datensätze umwandelt, um Stil-Transfer-Modelle zu trainieren","pt":"O pipeline de livros SFT é um sistema que converte livros em datasets SFT para treinar modelos de transferência de estilo","ru":"Конвейер книг SFT - это система, преобразующая книги в наборы данных SFT для обучения моделей передачи стиля","ar":"خط أنابيب الكتاب SFT هو نظام لتحويل الكتب إلى مجموعات بيانات SFT لتدريب نماذج نقل الأسلوب"},"features":{"en":["Converts raw ePub files to SFT datasets","Trains style-transfer models for author-voice replication","Supports text segmentation pipelines for long-form content","Prepares training data for Tinker or similar SFT platforms","Enables building fine-tuning datasets from literary works","Creates author-voice or style-transfer models"],"zh":["支持从raw ePub到模型训练的整个流程","用于创建作者声音或风格转换模型","用于准备Tinker或类似SFT平台的训练数据","支持文本分段管道用于长篇内容","用于训练小型模型"],"ja":["raw ePubからモデルトレーニングまでの全プロセスをサポート","著者音声またはスタイル転送モデルを作成するために使用","Tinkerまたは同様のSFTプラットフォームのトレーニングデータを準備するために使用","長文のコンテンツ用のテキスト分割パイプラインをサポート","小規模モデルをトレーニングするために使用"],"ko":["raw ePub에서 모델 학습까지의 전체 프로세스를 지원","작가 목소리 또는 스타일 전환 모델을 생성하는 데 사용","Tinker 또는 유사한 SFT 플랫폼의 학습 데이터를 준비하는 데 사용","긴 내용의 텍스트 분할 파이프라인을 지원","소규모 모델을 학습하는 데 사용"],"es":["Conversión de libros en conjuntos de datos SFT","Entrenamiento de modelos de transferencia de estilo","Procesamiento de archivos ePub raw","Creación de modelos que escriben en la voz de cualquier autor","Integración con plataformas de SFT como Tinker","Diseño de pipelines de segmentación de texto para contenido de larga forma"],"fr":["Conversion de livres en jeux de données SFT","Entraînement de modèles de transfert de style","Traitement de fichiers ePub bruts","Création de modèles qui écrivent dans la voix de n''importe quel auteur","Intégration avec des plateformes de SFT comme Tinker","Conception de pipelines de segmentation de texte pour du contenu de longue forme"],"de":["Konvertierung von Büchern in SFT-Datensätze","Trainieren von Stil-Transfer-Modellen","Verarbeitung von rohen ePub-Dateien","Erstellung von Modellen, die in der Stimme jedes Autors schreiben","Integration mit SFT-Plattformen wie Tinker","Entwurf von Textsegmentierungspipelines für Langform-Inhalte"],"pt":["Conversão de livros em datasets SFT","Treinamento de modelos de transferência de estilo","Criação de datasets de fine-tuning a partir de obras literárias","Preparação de dados de treinamento para plataformas de SFT","Desenvolvimento de pipelines de segmentação de texto para conteúdo de longa forma"],"ru":["Преобразование книг в наборы данных SFT","Обучение моделей передачи стиля","Создание наборов данных для fine-tuning из литературных произведений","Подготовка данных для обучения на платформах SFT и ИИ Агентов","Разработка конвейеров сегментации текста для контента большой формы"],"ar":["تحويل الكتب إلى مجموعات بيانات SFT","تدريب نماذج نقل الأسلوب","إنشاء مجموعات بيانات للتعدين الدقيق من الأعمال الأدبية","إعداد بيانات التدريب لمنصات SFT","تطوير خطوط أنابيب قاطع النص للconteúdo طويل الشكل"]},"keywords":{"en":["book-sft-pipeline setup guide","how to use book-sft-pipeline","what is book-sft-pipeline","book-sft-pipeline alternative","book-sft-pipeline vs style-transfer models","book-sft-pipeline install","training style-transfer models with book-sft-pipeline","converting eBooks to SFT datasets","author-voice model creation with book-sft-pipeline"],"zh":["Book SFT Pipeline","AIエージェント","ePub转换","SFT数据集","风格转换模型","Tinker","小型模型","文本分段"],"ja":["Book SFT Pipeline","AIエージェント","ePub変換","SFTデータセット","スタイル転送モデル","Tinker","小規模モデル","テキスト分割"],"ko":["Book SFT Pipeline","AI 도구","ePub 변환","SFT 데이터셋","스타일 전환 모델","Tinker","소규모 모델","텍스트 분할"],"es":["book-sft-pipeline","modelos de transferencia de estilo","conjuntos de datos SFT","entrenamiento de modelos","procesamiento de texto","plataformas de SFT","Tinker","Herramientas de IA para desarrolladores","Desarrollo de modelos de lenguaje natural"],"fr":["book-sft-pipeline","modèles de transfert de style","jeux de données SFT","entraînement de modèles","traitement de texte","plateformes de SFT","Tinker","Outils d''IA pour développeurs","Développement de modèles de langage naturel"],"de":["book-sft-pipeline","Stil-Transfer-Modelle","SFT-Datensätze","Modelltraining","Textverarbeitung","SFT-Plattformen","Tinker","KI-Tools für Entwickler","Entwicklung von Sprachmodellen"],"pt":["pipeline de livros SFT","datasets de fine-tuning","modelos de transferência de estilo","treinamento de modelos","plataformas de SFT","desenvolvimento de pipelines de segmentação de texto","livros em datasets SFT","conversão de livros em datasets"],"ru":["конвейер книг SFT","наборы данных для fine-tuning","модели передачи стиля","обучение моделей","платформы SFT","разработка конвейеров сегментации текста","книги в наборы данных SFT","преобразование книг в наборы данных","ИИ Агенты"],"ar":["خط أنابيب الكتاب SFT","مجموعات بيانات للتعدين الدقيق","نماذج نقل الأسلوب","تدريب النماذج","منصات SFT","تطوير خطوط أنابيب قاطع النص","كتب إلى مجموعات بيانات SFT","تحويل الكتب إلى مجموعات بيانات","أدوات الذكاء الاصطناعي"]}},"owner":"goodnight000","repo":"KittyCourt","repoPath":"goodnight000/KittyCourt","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.382Z","topics":[],"category":"community","skillMd":{"name":"book-sft-pipeline","description":"End-to-end system for creating supervised fine-tuning datasets from books and training style-transfer models. Covers text extraction, intelligent segmentation, synthetic instruction generation, Tinker-compatible output, LoRA training, and validation.","version":"2.0.0","bodyPreview":"# Book SFT Pipeline\n\nA complete system for converting books into SFT datasets and training style-transfer models. This skill teaches the pipeline from raw ePub to a model that writes in any author''s voice.\n\n## When to Activate\n\nActivate this skill when:\n- Building fine-tuning datasets from literary works\n- Creating author-voice or style-transfer models\n- Preparing training data for Tinker or similar SFT platforms\n- Designing text segmentation pipelines for long-form content\n- Training small mode","body":"# Book SFT Pipeline\n\nA complete system for converting books into SFT datasets and training style-transfer models. This skill teaches the pipeline from raw ePub to a model that writes in any author''s voice.\n\n## When to Activate\n\nActivate this skill when:\n- Building fine-tuning datasets from literary works\n- Creating author-voice or style-transfer models\n- Preparing training data for Tinker or similar SFT platforms\n- Designing text segmentation pipelines for long-form content\n- Training small models (8B or less) on limited data\n\n## Core Concepts\n\n### The Three Pillars of Book SFT\n\n**1. Intelligent Segmentation**\nText chunks must be semantically coherent. Breaking mid-sentence teaches the model to produce fragmented output. Target: 150-400 words per chunk, always at natural boundaries.\n\n**2. Diverse Instruction Generation**\nUse multiple prompt templates and system prompts to prevent overfitting. A single prompt style leads to memorization. Use 15+ prompt templates with 5+ system prompts.\n\n**3. Style Over Content**\nThe goal is learning the author''s rhythm and vocabulary patterns, not memorizing plots. Synthetic instructions describe what happens without quoting the text.\n\n## Pipeline Architecture\n\n```\n┌─────────────────────────────────────────────────────────────────┐\n│                    ORCHESTRATOR AGENT                           │\n│  Coordinates pipeline phases, manages state, handles failures   │\n└──────────────────────┬──────────────────────────────────────────┘\n                       │\n       ┌───────────────┼───────────────┬───────────────┐\n       ▼               ▼               ▼               ▼\n┌──────────────┐ ┌──────────────┐ ┌──────────────┐ ┌──────────────┐\n│  EXTRACTION  │ │ SEGMENTATION │ │  INSTRUCTION │ │   DATASET    │\n│    AGENT     │ │    AGENT     │ │    AGENT     │ │   BUILDER    │\n│ ePub → Text  │ │ Text → Chunks│ │ Chunks →     │ │ Pairs →      │\n│              │ │ 150-400 words│ │ Prompts      │ │ JSONL        │\n└──────────────┘ └──────────────┘ └──────────────┘ └──────────────┘\n                       │\n       ┌───────────────┴───────────────┐\n       ▼                               ▼\n┌──────────────┐               ┌──────────────┐\n│   TRAINING   │               │  VALIDATION  │\n│    AGENT     │               │    AGENT     │\n│ LoRA on      │               │ AI detector  │\n│ Tinker       │               │ Originality  │\n└──────────────┘               └──────────────┘\n```\n\n## Phase 1: Text Extraction\n\n### Critical Rules\n1. **Always source ePub over PDF** - OCR errors become learned patterns\n2. **Use paragraph-level extraction** - Extract from `<p>` tags to preserve breaks\n3. **Remove front/back matter** - Copyright and TOC pollute the dataset\n\n```python\n# Extract text from ePub paragraphs\nfrom epub2 import EPub\nfrom bs4 import BeautifulSoup\n\ndef extract_epub(path):\n    book = EPub(path)\n    chapters = []\n    for item in book.flow:\n        html = book.get_chapter(item.id)\n        soup = BeautifulSoup(html, ''html.parser'')\n        paragraphs = [p.get_text().strip() for p in soup.find_all(''p'')]\n        chapters.append(''\\n\\n''.join(p for p in paragraphs if p))\n    return ''\\n\\n''.join(chapters)\n```\n\n## Phase 2: Intelligent Segmentation\n\n### Smaller Chunks + Overlap\n\nSmaller chunks (150-400 words) produce more training examples and better style transfer than larger chunks (250-650).\n\n```python\ndef segment(text, min_words=150, max_words=400):\n    paragraphs = text.split(''\\n\\n'')\n    chunks, buffer, buffer_words = [], [], 0\n    \n    for para in paragraphs:\n        words = len(para.split())\n        if buffer_words + words > max_words and buffer_words >= min_words:\n            chunks.append(''\\n\\n''.join(buffer))\n            # Keep last paragraph for overlap\n            buffer = [buffer[-1], para] if buffer else [para]\n            buffer_words = sum(len(p.split()) for p in buffer)\n        else:\n            buffer.append(para)\n            buffer_words += words\n    \n    if buffer:\n        chunks.append(''\\n\\n''.join(buffer))\n    return chunks\n```\n\n### Expected Results\n\nFor an 86,000-word book:\n- Old method (250-650 words): ~150 chunks\n- New method (150-400 + overlap): ~300 chunks\n- With 2 variants per chunk: 600+ training examples\n\n## Phase 3: Diverse Instruction Generation\n\n### The Key Insight\n\nUsing a single prompt template causes memorization. Diverse templates teach the underlying style.\n\n```python\nSYSTEM_PROMPTS = [\n    \"You are an expert creative writer capable of emulating specific literary styles.\",\n    \"You are a literary writer with deep knowledge of classic prose styles.\",\n    \"You are a creative writer skilled at emulating distinctive authorial voices.\",\n    \"You write prose that captures the essence of modernist literature.\",\n    \"You are a talented writer who can channel classic American authors.\",\n]\n\nPROMPT_TEMPLATES = [\n    \"Write a passage in the style of {author}: {desc}\",\n    \"Channel {author}''s voice to write about: {desc}\",\n    \"In {author}''s distinctive prose style, describe: {desc}\",\n    \"Write this scene as {author} would have: {desc}\",\n    \"Using {author}''s repetitive technique, describe: {desc}\",\n    \"Capture the rhythm of {author} in this passage: {desc}\",\n    \"Write like {author}: {desc}\",\n    \"In the voice of {author}, write: {desc}\",\n    \"This is a literary exercise. Write like {author}: {desc}\",\n    \"Can you write in {author}''s style? {desc}\",\n]\n```\n\n### Instruction Generation\n\n```python\nINSTRUCTION_PROMPT = \"\"\"Describe what is happening in this excerpt in 2-3 sentences.\nFocus on: characters present, actions, emotions, setting.\nDo NOT quote the text directly.\n\nExcerpt:\n{text}\n\"\"\"\n\n# Use a fast, cheap LLM (e.g., Gemini Flash)\ninstruction = llm_call(INSTRUCTION_PROMPT.format(text=chunk))\n```\n\n## Phase 4: Dataset Construction\n\n### Message Format\n\n```json\n{\n    \"messages\": [\n        {\"role\": \"system\", \"content\": \"You are an expert creative writer...\"},\n        {\"role\": \"user\", \"content\": \"Write in the style of Author: Scene description...\"},\n        {\"role\": \"assistant\", \"content\": \"The actual book text from chunk...\"}\n    ]\n}\n```\n\n### Multiple Variants Per Chunk\n\n```python\ndef build_examples(chunk, instruction, author, variants=2):\n    examples = []\n    for i in range(variants):\n        system = SYSTEM_PROMPTS[i % len(SYSTEM_PROMPTS)]\n        template = PROMPT_TEMPLATES[(chunk.id + i) % len(PROMPT_TEMPLATES)]\n        user = template.format(author=author, desc=instruction)\n        examples.append({\"messages\": [\n            {\"role\": \"system\", \"content\": system},\n            {\"role\": \"user\", \"content\": user},\n            {\"role\": \"assistant\", \"content\": chunk.text}\n        ]})\n    return examples\n```\n\n## Phase 5: LoRA Training on Tinker\n\n### Configuration\n\n```python\nCONFIG = {\n    \"model_name\": \"Qwen/Qwen3-8B-Base\",  # Base, not instruct\n    \"lora_rank\": 32,                      # 352MB adapter\n    \"learning_rate\": 5e-4,                # Higher for LoRA\n    \"batch_size\": 4,\n    \"epochs\": 3,\n}\n```\n\n### Why Base Model?\n\nUse **base** (pretrained) models, not instruction-tuned versions:\n- Base models are more malleable for new styles\n- Instruct models have patterns that resist overwriting\n- Style is a low-level pattern that base models capture better\n\n### Training Loop\n\n```python\nimport tinker\nfrom tinker import types\n\ntraining_client = await service_client.create_lora_training_client_async(\n    base_model=\"Qwen/Qwen3-8B-Base\",\n    rank=32\n)\n\nfor epoch in range(3):\n    for batch in batches:\n        await training_client.forward_backward_async(batch, loss_fn=\"cross_entropy\")\n        await training_client.optim_step_async(types.AdamParams(learning_rate=5e-4))\n\nresult = await training_client.save_weights_for_sampler_async(name=\"final\")\n```\n\n## Phase 6: Validation\n\n### Modern Scenario Test\n\nTest with scenarios that couldn''t exist in the original book:\n\n```python\nTEST_PROMPTS = [\n    \"Write about a barista making lattes\",\n    \"Describe lovers communicating through text messages\",\n    \"Write about someone anxious about climate change\",\n]\n```\n\nIf the model applies style markers to modern scenarios, it learned **style**, not **content**.\n\n### Originality Verification\n\n```bash\n# Search training data for output phrases\ngrep \"specific phrase from output\" dataset.jsonl\n# Should return: No matches\n```\n\n### AI Detector Testing\n\nTest outputs with GPTZero, Pangram, or ZeroGPT.\n\n## Known Issues and Solutions\n\n### Character Name Leakage\n\n**Symptom**: Model uses original character names in new scenarios.\n**Cause**: Limited name diversity from one book.\n**Solution**: Train on multiple books or add synthetic examples.\n\n### Model Parrots Exact Phrases\n\n**Symptom**: Outputs contain exact sentences from training data.\n**Cause**: Too few prompt variations or too many epochs.\n**Solution**: Use 15+ templates, limit to 3 epochs.\n\n### Fragmented Outputs\n\n**Symptom**: Sentences feel incomplete.\n**Cause**: Poor segmentation breaking mid-thought.\n**Solution**: Always break at paragraph boundaries.\n\n## Guidelines\n\n1. **Always source ePub over PDF** - OCR errors become learned patterns\n2. **Never break mid-sentence** - Boundaries must be grammatically complete\n3. **Use diverse prompts** - 15+ templates, 5+ system prompts\n4. **Use base models** - Not instruct versions\n5. **Use smaller chunks** - 150-400 words for more examples\n6. **Reserve test set** - 50 examples minimum\n7. **Test on modern scenarios** - Proves style transfer vs memorization\n8. **Verify originality** - Grep training data for output phrases\n\n## Expected Results\n\n| Metric | Value |\n|--------|-------|\n| Training examples | 500-1000 per book |\n| Model | Qwen/Qwen3-8B-Base |\n| LoRA rank | 32 |\n| Adapter size | ~350 MB |\n| Training time | ~15 min |\n| Loss reduction | 90%+ |\n| Style transfer success | ~50% perfect |\n\n## Cost Estimate\n\n| Component | Cost |\n|-----------|------|\n| LLM (instruction generation) | ~$0.50 |\n| Tinker training (15 min) | ~$1.50 |\n| **Total** | **~$2.00** |\n\n## Integration with Context Engineering Skills\n\nThis example applies several skills from the Agent Skills for Context Engineering collection:\n\n### project-development\nThe pipeline follows the staged, idempotent architecture pattern:\n- **Acquire**: Extract text from ePub\n- **Prepare**: Segment into training chunks\n- **Process**: Generate synthetic instructions\n- **Parse**: Build message format\n- **Render**: Output Tinker-compatible JSONL\n- **Train**: LoRA fine-tuning\n- **Validate**: Modern scenario testing\n\nEach phase is resumable and produces intermediate artifacts for debugging.\n\n### context-compression\nSegmentation is a form of context compression for training. The core insight from context-compression applies: information density matters more than information quantity. Smaller, coherent chunks (150-400 words) produce better style transfer than larger, diluted chunks.\n\nThe two-tier strategy mirrors context compression evaluation:\n- Tier 1: Fast, deterministic compression\n- Tier 2: LLM-assisted for edge cases\n\n### multi-agent-patterns\nThe pipeline uses the **supervisor/orchestrator** pattern:\n- Orchestrator coordinates phases and manages state\n- Specialized agents (Extraction, Segmentation, Instruction, Builder) have isolated contexts\n- Each agent receives only the information needed for its task\n\nThis matches the principle that sub-agents exist primarily to isolate context rather than simulate roles.\n\n### evaluation\nValidation follows the **end-state evaluation** pattern:\n- Functional testing: Does output match expected style markers?\n- Originality verification: Is content genuinely generated?\n- External validation: AI detector scores\n\nThe \"modern scenario\" test is a form of out-of-distribution evaluation that proves generalization.\n\n### context-fundamentals\nPrompt diversity prevents attention collapse on single patterns. When training with identical prompt structures, the model memorizes the instruction-response mapping. Diverse templates force attention across the style patterns themselves.\n\n## References\n\nInternal references:\n- [Segmentation Strategies](./references/segmentation-strategies.md) - Text chunking patterns\n- [Tinker Format Specification](./references/tinker-format.md) - Datum structure\n- [Tinker API Documentation](./references/tinker.txt) - Full API reference\n\nRelated skills from Agent Skills for Context Engineering:\n- project-development - Pipeline architecture patterns\n- context-compression - Compression strategies  \n- multi-agent-patterns - Agent coordination\n- evaluation - Evaluation frameworks\n- context-fundamentals - Attention and information density\n\nExternal resources:\n- [Research Paper](https://arxiv.org/pdf/2510.13939) - Chakrabarty et al. 2025\n- [Dataset on Hugging Face](https://huggingface.co/datasets/MuratcanKoylan/gertrude-stein-style-sft)\n- [Gertrude Stein Case Study](./examples/gertrude-stein/) - Complete working example\n\n---\n\n## Skill Metadata\n\n**Created**: 2025-12-26\n**Last Updated**: 2025-12-28\n**Author**: Muratcan Koylan\n**Version**: 2.0.0\n**Standalone**: Yes (separate from main context-engineering collection)\n"},"lastSynced":"2026-03-08T02:05:41.861Z","agentAnalysis":{"suitability":{"en":"Perfect for NLP Agents needing advanced text analysis and style-transfer capabilities for literary works","zh":"非常适合需要高级文本分析和风格转换功能的NLP代理，特别是在文学作品中","ja":"NLPエージェントが文学作品の高度なテキスト分析とスタイル転送機能を必要とする場合に最適","ko":"문학 작품에서 고급 텍스트 분석 및 스타일 전환 기능이 필요한 NLP 에이전트에 적합","es":"Perfecto para agentes de NLP que necesitan análisis de texto avanzado y capacidades de transferencia de estilo para obras literarias","fr":"Parfait pour les agents NLP nécessitant une analyse de texte avancée et des capacités de transfert de style pour les œuvres littéraires","de":"Perfekt für NLP-Agents, die erweiterte Textanalyse und Stil-Transfer-Fähigkeiten für literarische Werke benötigen","pt":"Perfeito para Agentes de NLP que necessitam de análise de texto avançada e capacidades de transferência de estilo para obras literárias","ru":"Идеально для агентов NLP, которым необходимы продвинутые возможности анализа текста и передачи стиля для литературных произведений","ar":"مثالي للوكلاء NLP الذين يحتاجون إلى تحليل متقدم للنصوص وقدرات نقل الأسلوب للأعمال الأدبية"},"recommendation":{"en":"Empowers agents to convert raw ePub files into SFT datasets and train style-transfer models using protocols like fine-tuning datasets, enabling the creation of author-voice models and text segmentation pipelines for long-form content","zh":"能够使代理将原始ePub文件转换为SFT数据集，并使用诸如fine-tuning数据集的协议训练样式转换模型，从而实现作者声音模型和长篇内容的文本分段管道的创建","ja":"エージェントが生のePubファイルをSFTデータセットに変換し、fine-tuningデータセットなどのプロトコルを使用してスタイル転送モデルをトレーニングできるようにし、作者の声モデルや長文コンテンツのテキストセグメンテーションパイプラインの作成を可能にします","ko":"에이전트가 원시 ePub 파일을 SFT 데이터셋으로 변환하고, fine-tuning 데이터셋과 같은 프로토콜을 사용하여 스타일 전환 모델을 훈련할 수 있도록 해줌으로써, 저자 음성 모델 및 장문 콘텐츠의 텍스트 분할 파이프라인을 생성할 수 있습니다","es":"Habilita a los agentes a convertir archivos ePub sin procesar en conjuntos de datos SFT y entrenar modelos de transferencia de estilo utilizando protocolos como el ajuste fino de conjuntos de datos, lo que permite la creación de modelos de voz de autor y tuberías de segmentación de texto para contenido de larga forma","fr":"Permet aux agents de convertir des fichiers ePub bruts en jeux de données SFT et d''entraîner des modèles de transfert de style en utilisant des protocoles tels que le réglage fin des jeux de données, ce qui permet la création de modèles de voix d''auteur et de pipelines de segmentation de texte pour du contenu de longue forme","de":"Ermöglicht es Agenten, rohe ePub-Dateien in SFT-Datensätze zu konvertieren und Stil-Transfer-Modelle mit Protokollen wie dem Feinabstimmung von Datensätzen zu trainieren, was die Erstellung von Autor-Stimmen-Modellen und Text-Segmentierung-Pipelines für Langform-Inhalte ermöglicht","pt":"Habilita os agentes a converter arquivos ePub brutos em conjuntos de dados SFT e treinar modelos de transferência de estilo usando protocolos como conjuntos de dados de fine-tuning, permitindo a criação de modelos de voz de autor e pipelines de segmentação de texto para conteúdo de longa forma","ru":"Наделяет агентов возможностью конвертировать сырые файлы ePub в наборы данных SFT и обучать модели передачи стиля с использованием протоколов, таких как наборы данных для тонкой настройки, что позволяет создавать модели голоса автора и конвейеры сегментации текста для контента большой длины","ar":"يمنح الوكلاء القدرة على تحويل الملفات ePub الخام إلى مجموعات بيانات SFT وتدريب نماذج نقل الأسلوب باستخدام بروتوكولات مثل مجموعات البيانات للضبط الدقيق، مما يسمح بإنشاء نماذج صوت المؤلف وأنابيب اقتطاع النص لمحتوى الشكل الطويل"},"useCases":{"en":["Building fine-tuning datasets from literary works","Creating author-voice or style-transfer models","Preparing training data for Tinker or similar SFT platforms"],"zh":["从文学作品构建fine-tuning数据集","创建作者声音或样式转换模型","为Tinker或类似的SFT平台准备训练数据"],"ja":["文学作品からfine-tuningデータセットを構築する","作者の声またはスタイル転送モデルを作成する","Tinkerまたは同等のSFTプラットフォームのトレーニングデータを準備する"],"ko":["문학 작품에서 fine-tuning 데이터셋을 구축하는 것","저자 음성 또는 스타일 전환 모델을 생성하는 것","Tinker 또는 유사한 SFT 플랫폼의 훈련 데이터를 준비하는 것"],"es":["Construir conjuntos de datos de ajuste fino a partir de obras literarias","Crear modelos de voz de autor o de transferencia de estilo","Preparar datos de entrenamiento para Tinker o plataformas SFT similares"],"fr":["Construire des jeux de données de réglage fin à partir d''œuvres littéraires","Créer des modèles de voix d''auteur ou de transfert de style","Préparer des données de formation pour Tinker ou des plateformes SFT similaires"],"de":["Feinabstimmungs-Datensätze aus literarischen Werken aufbauen","Erstellen von Autor-Stimmen- oder Stil-Transfer-Modellen","Trainingsdaten für Tinker oder ähnliche SFT-Plattformen vorbereiten"],"pt":["Construir conjuntos de dados de fine-tuning a partir de obras literárias","Criar modelos de voz de autor ou modelos de transferência de estilo","Preparar dados de treinamento para Tinker ou plataformas SFT semelhantes"],"ru":["Создание наборов данных для тонкой настройки из литературных произведений","Создание моделей голоса автора или моделей передачи стиля","Подготовка данных для обучения для Tinker или аналогичных платформ SFT"],"ar":["بناء مجموعات بيانات الضبط الدقيق من الأعمال الأدبية","إنشاء نماذج صوت المؤلف أو نماذج نقل الأسلوب","تحضير بيانات التدريب لتينكر أو منصات SFT المماثلة"]},"limitations":{"en":["Requires raw ePub files as input","Limited to training small models","Specifically designed for SFT datasets and style-transfer models"],"zh":["需要原始ePub文件作为输入","仅限于训练小型模型","专门为SFT数据集和样式转换模型设计"],"ja":["生のePubファイルを入力として必要とする","小規模モデルしかトレーニングできない","SFTデータセットおよびスタイル転送モデル専用に設計"],"ko":["원시 ePub 파일을 입력으로 필요로 함","작은 모델만을 훈련할 수 있음","SFT 데이터셋 및 스타일 전환 모델을 위한 특수 설계"],"es":["Requiere archivos ePub sin procesar como entrada","Limitado a entrenar modelos pequeños","Diseñado específicamente para conjuntos de datos SFT y modelos de transferencia de estilo"],"fr":["Nécessite des fichiers ePub bruts comme entrée","Limité à l''entraînement de petits modèles","Conçu spécifiquement pour des jeux de données SFT et des modèles de transfert de style"],"de":["Benötigt rohe ePub-Dateien als Eingabe","Begrenzt auf das Trainieren kleiner Modelle","Speziell für SFT-Datensätze und Stil-Transfer-Modelle konzipiert"],"pt":["Requer arquivos ePub brutos como entrada","Limitado ao treinamento de modelos pequenos","Especificamente projetado para conjuntos de dados SFT e modelos de transferência de estilo"],"ru":["Требует сырых файлов ePub в качестве входных данных","Ограничен обучением небольших моделей","Специально разработан для наборов данных SFT и моделей передачи стиля"],"ar":["يتطلب ملفات ePub خام كمدخلات","محدود بتدريب نماذج صغيرة","مصمم خصيصًا لمجموعات بيانات SFT ونماذج نقل الأسلوب"]},"version":4},"contentHash":"4b20fbfaa162bcbf131f713707bd51808f01766d8139b6055466b8b3abb32b9e","qualityScore":65}');
