INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('goodnight000/KittyCourt/book-sft-pipeline', 'book-sft-pipeline', 'goodnight000', 'KittyCourt', 'community', 'book-sft-pipeline goodnight000 KittyCourt community The book-sft-pipeline skill enables developers to convert raw ePub files into SFT datasets and train style-transfer models, ideal for building fine-tuning datasets and creating author-voice models. Book SFT Pipeline是一个完整的系统，用于将书籍转换为SFT数据集和训练风格转换模型。它支持从raw ePub到模型训练的整个流程。 Book SFT Pipelineは、書籍をSFTデータセットに変換し、スタイル転送モデルをトレーニングするための完全なシステムです。raw ePubからモデルトレーニングまでの全プロセスをサポートします。 Book SFT Pipeline는 책을 SFT 데이터셋으로 변환하고 스타일 전환 모델을 학습하는 완벽한 시스템입니다. raw ePub에서 모델 학습까지의 전체 프로세스를 지원합니다. Book-sft-pipeline es un sistema completo para convertir libros en conjuntos de datos SFT y entrenar modelos de transferencia de estilo. Esta habilidad enseña el proceso desde un archivo ePub raw hasta un modelo que escribe en la voz de cualquier autor. Book-sft-pipeline est un système complet pour convertir des livres en jeux de données SFT et entraîner des modèles de transfert de style. Cette compétence enseigne le processus depuis un fichier ePub brut jusqu''à un modèle qui écrit dans la voix de n''importe quel auteur. Book-sft-pipeline ist ein vollständiges System zur Konvertierung von Büchern in SFT-Datensätze und zum Trainieren von Stil-Transfer-Modellen. Diese Fähigkeit lehrt den Prozess von einer rohen ePub-Datei bis hin zu einem Modell, das in der Stimme jedes Autors schreibt. O pipeline de livros SFT é um sistema completo para converter livros em datasets SFT e treinar modelos de transferência de estilo. Aprenda a criar datasets de fine-tuning e treinar modelos com este skill Конвейер книг SFT - это полная система для преобразования книг в наборы данных SFT и обучения моделей передачи стиля. Научитесь создавать наборы данных для fine-tuning и обучать модели с помощью этого навыка и ИИ Агентов خط أنابيب الكتاب SFT هو نظام كامل لتحويل الكتب إلى مجموعات بيانات SFT وتدريب نماذج نقل الأسلوب. تعلم كيفية إنشاء مجموعات بيانات للتعدين الدقيق وتدريب النماذج باستخدام هذا المهارة book-sft-pipeline setup guide how to use book-sft-pipeline what is book-sft-pipeline book-sft-pipeline alternative book-sft-pipeline vs style-transfer models book-sft-pipeline install training style-transfer models with book-sft-pipeline converting eBooks to SFT datasets author-voice model creation with book-sft-pipeline Book SFT Pipeline AIエージェント ePub转换 SFT数据集 风格转换模型 Tinker 小型模型 文本分段 Converts raw ePub files to SFT datasets Trains style-transfer models for author-voice replication Supports text segmentation pipelines for long-form content Prepares training data for Tinker or similar SFT platforms Enables building fine-tuning datasets from literary works Creates author-voice or style-transfer models book-sft-pipeline is a complete system for converting books into SFT datasets and training style-transfer models, supporting text segmentation pipelines for long-form content.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kanyun-inc/reskill/reskill-usage', 'community', 'kanyun-inc', 'reskill', 'kanyun-inc/reskill', 'reskill-usage', 0, 0, 65, '2026-03-08T01:57:15.404Z', '2026-03-08T02:06:51.322Z', 'f3e4ef76960bdf5e5d458ab836f161c571a5905f6fc119b755209687a2a76c1f', '{"id":"kanyun-inc/reskill/reskill-usage","name":"reskill-usage","description":{"en":"reskill-usage brings the npm experience to AI agent skills, providing declarative configuration and flexible versioning for seamless skill management. It benefits developers and teams working with AI agents.","zh":"reskill-usage 是一个 Git 基础的 AI 工具包管理器，提供声明式配置和灵活的版本管理","ja":"reskill-usage は Git ベースの AI エージェントスキルマネージャーで、宣言型の構成と柔軟なバージョン管理を提供する","ko":"reskill-usage 는 Git 기반의 AI 에이전트 技能 관리자로, 선언적 구성 및 유연한 버전 관리를 제공합니다","es":"reskill-usage es una herramienta de gestión de habilidades para agentes de inteligencia artificial basada en Git, que ofrece configuración declarativa y soporte para múltiples agentes","fr":"reskill-usage est un outil de gestion de compétences pour les agents d''intelligence artificielle basé sur Git, qui propose une configuration déclarative et un support pour les agents multiples","de":"reskill-usage ist ein Tool für die Verwaltung von Fähigkeiten für künstliche Intelligenz-Agenten basierend auf Git, das eine deklarative Konfiguration und Unterstützung für mehrere Agenten bietet","pt":"O reskill-usage é um gerenciador de pacotes baseado em Git para habilidades de agentes de IA, oferecendo configuração declarativa e versão flexível","ru":"Reskill-usage - это менеджер пакетов на основе Git для навыков ИИ Агентов, предоставляющий декларативную конфигурацию и гибкую версию","ar":"reskill-usage هو مدير حزم قائم على Git لمهارات أدوات الذكاء الاصطناعي، يوفر تكوين إعلاني وتأطير مرن"},"seo":{"title":{"en":"reskill-usage: Setup Guide for AI Agents","zh":"reskill-usage 安装指南：