INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kanyun-inc/reskill/reskill-usage', 'reskill-usage', 'kanyun-inc', 'reskill', 'community', 'reskill-usage kanyun-inc reskill community reskill-usage brings the npm experience to AI agent skills, providing declarative configuration and flexible versioning for seamless skill management. It benefits developers and teams working with AI agents. reskill-usage 是一个 Git 基础的 AI 工具包管理器，提供声明式配置和灵活的版本管理 reskill-usage は Git ベースの AI エージェントスキルマネージャーで、宣言型の構成と柔軟なバージョン管理を提供する reskill-usage 는 Git 기반의 AI 에이전트 技能 관리자로, 선언적 구성 및 유연한 버전 관리를 제공합니다 reskill-usage es una herramienta de gestión de habilidades para agentes de inteligencia artificial basada en Git, que ofrece configuración declarativa y soporte para múltiples agentes reskill-usage est un outil de gestion de compétences pour les agents d''intelligence artificielle basé sur Git, qui propose une configuration déclarative et un support pour les agents multiples reskill-usage ist ein Tool für die Verwaltung von Fähigkeiten für künstliche Intelligenz-Agenten basierend auf Git, das eine deklarative Konfiguration und Unterstützung für mehrere Agenten bietet O reskill-usage é um gerenciador de pacotes baseado em Git para habilidades de agentes de IA, oferecendo configuração declarativa e versão flexível Reskill-usage - это менеджер пакетов на основе Git для навыков ИИ Агентов, предоставляющий декларативную конфигурацию и гибкую версию reskill-usage هو مدير حزم قائم على Git لمهارات أدوات الذكاء الاصطناعي، يوفر تكوين إعلاني وتأطير مرن how to use reskill-usage reskill-usage setup guide reskill-usage alternative reskill-usage vs npm reskill-usage install what is reskill-usage reskill-usage for AI agents reskill-usage package manager reskill-usage skills management reskill-usage AI 工具包管理 Git 基础包管理 声明式配置 灵活的版本管理 Node.js AI 工具包安装 AI 工具包管理器 Declarative configuration via skills.json and skills.lock files Flexible versioning for precise skill management Multi-agent support for streamlined skill installation CLI usage via npm install -g reskill or npx reskill@latest Support for Node.js versions >= 18.0.0 reskill-usage is a Git-based package manager for AI agent skills, enabling efficient installation, management, and sharing of skills across projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('arbgjr/sdlc_agentico/skill-name', 'community', 'arbgjr', 'sdlc_agentico', 'arbgjr/sdlc_agentico', 'skill-name', 0, 0, 65, '2026-03-08T01:57:15.412Z', '2026-03-08T02:07:05.117Z', '88afaf50005db576d7ae7e7c0b0e8f172fbc29da144f969bf5d4725b908160d9', '{"id":"arbgjr/sdlc_agentico/skill-name","name":"skill-name","description":{"en":"skill-name automates and coordinates the software development lifecycle. It benefits developers by streamlining processes and improving efficiency.","zh":"技能-name是一个AI驱动的软件开发系统，自动化整个开发周期","ja":"スキル名は、AIによって駆動されるソフトウェア開発システムであり、開発全体を自動化","ko":"스킬-이름은 AI에 의해 구동되는 소프트웨어 개발 시스템으로 개발 전반을 자동화","es":"Skill-name es un sistema de desarrollo de software orientado por agentes de IA que automatiza y coordina todo el ciclo de vida del desarrollo","fr":"Skill-name est un système de développement de logiciels piloté par des agents d''IA qui automatisent et coordonnent tout le cycle de vie du développement","de":"Skill-name ist ein Software-Entwicklungssystem, das von KI-Agenten gesteuert wird und den gesamten Entwicklungszyklus automatisiert und koordiniert","pt":"O sistema de desenvolvimento de software orientado por agentes de IA automatiza e coordena todo o ciclo de vida do desenvolvimento, utilizando scripts apenas para operações determinísticas, I/O complexas ou integração com APIs externas.","ru":"Система разработки программного обеспечения, ориентированная на ИИ Агентов, автоматизирует и координирует весь жизненный цикл разработки, используя скрипты только для детерминированных операций, сложных вводов/выводов или интеграции с внешними API.","ar":"نظام تطوير البرمجيات الموجه بواسطة وكلاء الذكاء الاصطناعي ي自動ي ويتوافق مع جميع مراحل التطوير، باستخدام البرامج النصية فقط للعمليات الحتمية أو الإدخال/الإخراج المعقد أو التكامل مع واجهات برمجة التطبيقات الخارجية."},"seo":{"title":{"en":"skill-name: Automated Software Development Setup Guide | ...","zh":"AIエージェント技能-name快速入门指南","ja":"AIエージェントスキル名の設定ガイド","ko":"AI 에이전트 스킬-이름 설정 가이드","es":"Guía de configuración de skill-name para agentes de IA","fr":"Guide de démarrage rapide pour skill-name et les outils d''IA","de":"Einrichtungsleitfaden für skill-name mit KI-Agenten","pt":"Guia de Configuração do Sistema de Desenvolvimento de Sof...","ru":"Настройка ИИ Агентов для Автоматизации Жизненного Цикла Р...","ar":"دليل إعداد نظام تطوير البرمجيات الموجه بواسطة وكلاء الذكا..."},"description":{"en":"Unlock efficient software development with skill-name. Discover how to automate your workflow and coordinate development cycles with this AI-powered tool. Ge...","zh":"了解AIエージェント技能-name的工作原理，自动化软件开发周期","ja":"AIエージェントスキル名を使用してソフトウェア開発を自動化","ko":"AI 에이전트 스킬-이름을 사용하여 소프트웨어 개발 자동화","es":"Automatice el ciclo de vida del desarrollo con skill-name, un sistema orientado por agentes de IA para desarrolladores","fr":"Accélérez votre développement avec skill-name, un système piloté par des agents d''IA pour les développeurs","de":"Automatisieren Sie den Entwicklungszyklus mit skill-name, einem KI-Agenten-System für Entwickler","pt":"Aprenda a configurar o sistema de desenvolvimento de software orientado por agentes de IA para automatizar todo o ciclo de vida do desenvolvimento","ru":"Узнайте, как настроить ИИ Агенты для автоматизации жизненного цикла разработки программного обеспечения","ar":"تعلم كيفية إعداد نظام تطوير البرمجيات الموجه بواسطة وكلاء الذكاء الاصطناعي لتحقيق الت 자동يز للجميع مراحل التطوير"},"definition":{"en":"skill-name is a software development system oriented by AI agents that automates and coordinates the entire development lifecycle.","zh":"技能-name是一种AI驱动的软件开发工具，使用自然语言处理","ja":"スキル名は、自然言語を使用するAI駆動のソフトウェア開発ツール","ko":"스킬-이름은 자연어를 사용하는 AI 구동 소프트웨어 개발 도구","es":"Un sistema de desarrollo de software que utiliza agentes de IA para automatizar y coordinar el ciclo de vida del desarrollo","fr":"Un système de développement de logiciels qui utilise des agents d''IA pour automatiser et coordonner le cycle de vie du développement","de":"Ein Software-Entwicklungssystem, das KI-Agenten verwendet, um den Entwicklungszyklus zu automatisieren und zu koordinieren","pt":"Sistema de desenvolvimento de software que utiliza agentes de IA para automatizar e coordenar todo o ciclo de vida do desenvolvimento","ru":"Система разработки программного обеспечения, которая использует ИИ Агентов для автоматизации и координации всего жизненного цикла разработки","ar":"نظام تطوير البرمجيات الذي يستخدم وكلاء الذكاء الاصطناعي لتحقيق الت自動ي و التكامل مع جميع مراحل التطوير"},"features":{"en":["Automates software development lifecycle using natural language","Utilizes scripts for deterministic operations and complex I/O","Supports external API integration for expanded functionality","Processes documents with commands like python3 scripts/process.py","Generates output files in formats like result.txt","Coordinates development cycles for improved efficiency"],"zh":["使用自然语言处理","自动化软件开发周期","支持脚本语言（Python）","集成外部API","支持CLI命令"],"ja":["自然言語処理を使用","ソフトウェア開発サイクルを自動化","スクリプト言語（Python）をサポート","外部APIを統合","CLIコマンドをサポート"],"ko":["자연어 처리 사용","소프트웨어 개발 주기를 자동화","스크립트 언어（Python） 지원","외부 API 통합","CLI 명령어 지원"],"es":["Automatización del ciclo de vida del desarrollo","Uso de scripts solo para operaciones determinísticas, I/O complejas o integración de API externas","Procesamiento de documentos con Python","Integración con CLI para ejecutar comandos","Soporte para operaciones de entrada y salida complejas"],"fr":["Automatisation du cycle de vie du développement","Utilisation de scripts uniquement pour les opérations déterministes, les I/O complexes ou l''intégration d''API externes","Traitement de documents avec Python","Intégration avec CLI pour exécuter des commandes","Prise en charge des opérations de saisie et de sortie complexes"],"de":["Automatisierung des Entwicklungszyklus","Verwendung von Skripten nur für deterministische Operationen, komplexe I/O oder externe API-Integration","Dokumentenverarbeitung mit Python","Integration mit CLI zum Ausführen von Befehlen","Unterstützung für komplexe Ein- und Ausgabevorgänge"],"pt":["Utiliza scripts apenas para operações determinísticas, I/O complexas ou integração com APIs externas","Automatiza e coordena todo o ciclo de vida do desenvolvimento","Suporta processamento de documentos com scripts em Python","Permite integração com APIs externas para expansão das funcionalidades"],"ru":["Использует скрипты только для детерминированных операций, сложных вводов/выводов или интеграции с внешними API","Автоматизирует и координирует весь жизненный цикл разработки","Поддерживает обработку документов с помощью скриптов на Python","Позволяет интегрироваться с внешними API для расширения функциональности"],"ar":["يستخدم البرامج النصية فقط للعمليات الحتمية أو الإدخال/الإخراج المعقد أو التكامل مع واجهات برمجة التطبيقات الخارجية","ي自動ي ويتوافق مع جميع مراحل التطوير","يدعم معالجة الوثائق باستخدام البرامج النصية بالغة بايثون","يسمح بالتكامل مع واجهات برمجة التطبيقات الخارجية لتوسيع الوظائف"]},"keywords":{"en":["how to use skill-name","what is skill-name","skill-name alternative","skill-name vs competitor","skill-name install","skill-name setup guide","automated software development","AI-powered development tools","software development lifecycle management"],"zh":["AIエージェント","软件开发自动化","自然语言处理","Python脚本","CLI命令","AI驱动开发","软件开发工具","自动化测试"],"ja":["AIエージェント","ソフトウェア開発自動化","自然言語処理","Pythonスクリプト","CLIコマンド","AI駆動開発","ソフトウェア開発ツール","自動化テスト"],"ko":["AI 에이전트","소프트웨어 개발 자동화","자연어 처리","Python 스크립트","CLI 명령어","AI 구동 개발","소프트웨어 개발 도구","자동화 테스트"],"es":["agentes de IA para desarrollo","sistemas de desarrollo de software","automatización del ciclo de vida del desarrollo","desarrollo de software con Python","integración de API externas","CLI para desarrollo","procesamiento de documentos","desarrollo de software con KI-Agenten","agentes de IA para programación"],"fr":["agents d''IA pour le déve