INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arbgjr/sdlc_agentico/skill-name', 'skill-name', 'arbgjr', 'sdlc_agentico', 'community', 'skill-name arbgjr sdlc_agentico community skill-name automates and coordinates the software development lifecycle. It benefits developers by streamlining processes and improving efficiency. 技能-name是一个AI驱动的软件开发系统，自动化整个开发周期 スキル名は、AIによって駆動されるソフトウェア開発システムであり、開発全体を自動化 스킬-이름은 AI에 의해 구동되는 소프트웨어 개발 시스템으로 개발 전반을 자동화 Skill-name es un sistema de desarrollo de software orientado por agentes de IA que automatiza y coordina todo el ciclo de vida del desarrollo Skill-name est un système de développement de logiciels piloté par des agents d''IA qui automatisent et coordonnent tout le cycle de vie du développement Skill-name ist ein Software-Entwicklungssystem, das von KI-Agenten gesteuert wird und den gesamten Entwicklungszyklus automatisiert und koordiniert O sistema de desenvolvimento de software orientado por agentes de IA automatiza e coordena todo o ciclo de vida do desenvolvimento, utilizando scripts apenas para operações determinísticas, I/O complexas ou integração com APIs externas. Система разработки программного обеспечения, ориентированная на ИИ Агентов, автоматизирует и координирует весь жизненный цикл разработки, используя скрипты только для детерминированных операций, сложных вводов/выводов или интеграции с внешними API. نظام تطوير البرمجيات الموجه بواسطة وكلاء الذكاء الاصطناعي ي自動ي ويتوافق مع جميع مراحل التطوير، باستخدام البرامج النصية فقط للعمليات الحتمية أو الإدخال/الإخراج المعقد أو التكامل مع واجهات برمجة التطبيقات الخارجية. how to use skill-name what is skill-name skill-name alternative skill-name vs competitor skill-name install skill-name setup guide automated software development AI-powered development tools software development lifecycle management AIエージェント 软件开发自动化 自然语言处理 Python脚本 CLI命令 AI驱动开发 软件开发工具 自动化测试 Automates software development lifecycle using natural language Utilizes scripts for deterministic operations and complex I/O Supports external API integration for expanded functionality Processes documents with commands like python3 scripts/process.py Generates output files in formats like result.txt Coordinates development cycles for improved efficiency skill-name is a software development system oriented by AI agents that automates and coordinates the entire development lifecycle.');
